[Proposition 9 (Laurent integrality of the dual coefficients) of arXiv:2608.29585, '2608.29585'] For every zero-framed knot $K$, every $n\ge2$, and every partition
$\lambda$ with at most $n$ parts, the coefficient defined in
\textup{(BG3)} satisfies
\begin{equation}
 a_\lambda(K;q^2)\in R_{\mathrm{ev}}=\Z[q^{\pm2}].
\end{equation}

[Lemma 51 of arXiv:2512.04807, 'Existence and uniqueness of the canonical Brownian motion in non-simple conformal loop ens'] Almost surely, there exists a countable set $\{z_m\}_{m \in \N} \subseteq \Upsilon_\Gamma$ that is dense with respect to $\dpathY$ and such that the following holds. Suppose that $V \in \metregions$ is separated from $\Upsilon_\Gamma \setminus \ol{V}$ by a finite set of points $Z$ contained in $\{z_m\}_{m \in \N}$. Then the following holds for sufficiently large $m \in \N$. Let $A = \{z_1,\ldots,z_m\}$ and $A_V = A \cap \ol{V}$, let $w$ (resp.\ $w_V$) be the weight function associated with $\rmet{\cdot}{\cdot}{\Gamma}|_{A}$ (resp.\ $\rmetres{V}{\cdot}{\cdot}{\Gamma}|_{A_V}$). Then
 \begin{itemize}
  \item $w(x,y) = w_V(x,y)$ for each $x,y \in A_V$,
  \item $w(x,y) = 0$ for each $x \in A_V \setminus Z$, $y \in A \setminus \ol{V}$,
  \item $w(x,y) = 0$ for $x,y \in Z$.
 \end{itemize}

[Theorem 24 (Comparison theorems) of arXiv:2605.04359, 'Well-posedness of reflected BSDEs with default time and irregular barrier: An application '] Assume that:
	\begin{itemize}
		\item $\xi^1 \leq \xi^2$.
		\item $
		f^1\left(t, Y_t^2, Z_t^2,U^2_t\right) \leq f^2\left(t, Y_t^2, Z_t^2,U^2_t\right),~t \in [0,T],~d\mathbb{P}\otimes dt\text{-a.e.}
		$
	\end{itemize}
	Then, we have
	\begin{itemize}
		\item[(i)] Comparison theorem: $Y^1_t \leq Y^2_t$, $\forall t \in [0,T]$ a.s.
		\item[(ii)] Strict comparison theorem: Suppose moreover, that $\psi>-1$ a.s., and $Y^1_{t_0}=Y^2_{t_0}$ a.s. for some $t_0 \in [0,T]$. Then $\xi_1=\xi_2$ a.s., and $Y^1=Y^2$ on $[t_0,T]$. 
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 10 of arXiv:2606.03661, '2606.03661'] Let $\mathscr{L}_t[f(t);z]$ be the Laplace transform of the function $f(t)$ with conjugate variable $z$. Here $t$ denotes the time variable and $z$ is the Laplace dual variable. Then 
\begin{equation}

\begin{split} 
& \mathscr{L}_t[t^\mu \Psi_\alpha^\nu(-\kappa t);z] \\[1ex]
& \quad = 
\frac{1}{z^{1+\mu}} \frac{G(1+\nu)}{G(2+\nu-\alpha)} \frac{1}{2\pi i} 
\int_{c-\infty}^{c+\infty} \left(\frac{\kappa}{z}\right)^{-s} \Gamma(1+\mu-s) 
\Gamma(s) \frac{G(2+\nu-\alpha-s)}{G(1+\nu-s)} \, ds 
\end{split}
\end{equation}
with $\mu > -1$.

