body:
[Theorem thm:disk+QT of arXiv:2411.19810, 'Radial conformal welding in Liouville quantum gravity'] Fix $W,W_1,W_2,W_3>0$ such that $W_2+W_3=W_1+2$ or $W_1+W_3=W_2+\gamma^2-2$. There exists some constant $c:=c_{W,W_1,W_2,W_3}\in (0,
	\infty)$ such that
	\begin{equation}
	    \mathrm{QT}(W+W_1,W+W_2,W_3)\otimes \mathrm{SLE}_\kappa(W-2;W_2-2,W_1-W_2) = c\int_0^\infty {\mathcal{M}}^\mathrm{disk}_{0,2}(W;\ell)\times\mathrm{QT}(W_1,W_2,W_3;\ell)d\ell.
	\end{equation}
	That is, if we draw an independent $\mathrm{SLE}_\kappa(W-2;W_1-2,W_2-W_1)$ curve $\eta$ on a sample from $\mathrm{QT}(W+W_1,W+W_2,W_3)$ embedded as $(D,\phi,a_1,a_2,a_3)$, then the quantum surfaces to the left and right of $\eta$ are corresponding independent quantum disks and triangles conditioned on having the same interface quantum length. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:1* of arXiv:2512.09219, 'Strong confluence of geodesics in Liouville quantum gravity'] For distinct points $u_+,v_+,u_-,v_-\in \mathbb{C}$, we say that $\mathscr{X}^{u_+,v_+}_{u_-,v_-}$ occurs if the following hold.
  \begin{enumerate}
  \item  The $D_h$-geodesics $P_+,P_-$ from $u_+$ to $v_+$ and $u_-$ to $v_-$ are unique. Further, $P_+\cap P_-$ is non-empty and is a non-trivial simple path, whose (distinct) starting and ending points we call $u$ and $v$ respectively.
  \item  There is a unique $D_h$-geodesic $\Gamma_{u_+,v_-}$ (resp.\ $\Gamma_{u_-,v_+}$) and this is equal to the concatenation of $\Gamma_{u_+,u}, \Gamma_{u,v}, \Gamma_{v,v_-}$ (resp.\ $\Gamma_{u_-,u}, \Gamma_{u,v}, \Gamma_{v,v_+}$).
  \item  The geodesics $\Gamma_{u_-,u}, \Gamma_{v,v_-}$ lie to the right of $P_+$ and the geodesics $\Gamma_{u_+,u},\Gamma_{v,v_+}$ lie to the left of $P_-$.
  \end{enumerate}

[Lemma 10 of arXiv:2608.29984, 'On Cauchy Problems for Parabolic Equations with Rough Coefficients'] Let the multi-variable Fourier multiplier $\sigma(\xi,\eta)\in C^{\infty}(\R^{d}\times\R^{d}\setminus (0,0))$ satisfies
\begin{equation}
\begin{split}
&|\p_{\xi}^{\alpha}\p_{\eta}^{\beta}\sigma(\xi,\eta)|\lesssim_{\alpha,\beta}(|\xi|+|\eta|)^{-|\alpha|+|\beta|},\ \forall (\alpha,\beta),\ \forall (\xi,\eta)\neq (0,0);\\
&\sigma(\xi,0)\equiv 0.
\end{split}
\end{equation}
Define the bilinear Fourier integral operator
\begin{equation}
B_{\sigma}(f,g)(x):=\int_{\R^{2d}}e^{ix\cdot(\xi+\eta)}\sigma(\xi,\eta)\hat{f}(\xi)\hat{g}(\eta)d\xi d\eta,\ x\in\R^{d}.
\end{equation}
Then for all $1<p<\infty$, we have
\begin{equation}
\|B_{\sigma}(f,g)\|_{L^{p}(\R^{d})}\lesssim_{p,\sigma}\|f\|_{L^{p}(\R^{d})}\cdot [g]_{BMO(\R^{d})}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:matchingbord of arXiv:2601.20502, 'Optimal matching under size priority'] Let $(G,o,w)$ be a finite weighted graph with a unique optimal matching $M_{\mathrm{opt}}$. Let $H>0$ and assume that $G^H:=B_H(G,o)$ is a tree. 
    Define the decorated graph $(G^H,o, (i_M,Z_M))$ as follows:
    \begin{enumerate}
        \item Set $(i_M,Z_M)(u,v)=(0,0)$ if $v$ is on the boundary and not matched by $M_{\mathrm{opt}}$ to the exterior of $G^H$. In other words, $(i_M,Z_M)(u,v)=(0,0)$ if $d(v,o)=H+1$ and $(v,u') \notin M_{\mathrm{opt}}$ for $u' \sim v, u' \neq u$.
        \item Set $(i_M,Z_M)(u,v)=(1,+\infty)$  if $v$ is on the boundary and matched by $M_{\mathrm{opt}}$ to the exterior of $G^H$.
        \item Use Recursion~(equation eq:systemrecursionzoombis of the paper) to define $(i_M,Z_M)$ on the remainder of $(G^H,o)$.
    \end{enumerate}
    Then an edge $(u,v)\in G^H$ is in $M_{\mathrm{opt}}$ if and only if
     \begin{align*}
         (i_M,Z_M)(u,v)+(i_M,Z_M)(v,u)\overset{\lex}{<} (1,w(u,v)).
     \end{align*}

[Lem 31 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d\geq 2$, $\beta\geq 0$, and $n\geq 1$. Then, for every $e\in E(\Lambda_n)$, one has
\begin{equation}
	\phi^1_{\Lambda_{2n},\beta}[\omega_e]-\phi^0_{\Lambda_{2n},\beta}[\omega_e]\leq \big(\langle \sigma_0\rangle_{\Lambda_{n},\beta}^+\big)^2.
\end{equation}

