[Proposition 13 (Proposition 4.1 in \cite{Streets-Ustinovskiy22}) of arXiv:2608.30638, 'On compact steady pluriclosed soliton surfaces'] Consider the vector field
    \begin{equation}
        V\coloneqq\frac12(\theta^\#-\nabla f).
    \end{equation}
    Then it satisfies
    \begin{equation}
            \mathcal L_VJ=0,
            \quad \mathcal L_{JV}g=0,\quad
            \mathcal L_V\omega=\rho_B^{1,1}.
    \end{equation}
    In particular, $JV$ is holomorphic and Killing. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 8 of arXiv:2609.01296, 'Asymptotic safety regions for Gabor frames generated by Hermite functions'] Let $0< \delta < \eta < \frac{1}{3}$. Then there exists $n_{\eta,\delta}\in\N$ such that, for every $n\geq n_{\eta,\delta}$, the region
    \begin{equation}
           S_n(\delta,\eta) := \left\{ (a,b) \in \R^2_+ : \min\{a,b\}\geq n^{-\frac12-\delta}, ab \leq n^{-\frac{2}{3}-\eta} \right\} 
        \end{equation}
is contained in the frame set of the $n$-th Hermite function. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop: estimates 1 of arXiv:2411.05924, 'Non-negative Martingale Solutions to the Stochastic Porous Medium Equation with Sticky Beh'] Let $p\in[1,\infty)$. (1) Then
    \[
        \begin{aligned}
        \sup_{n\in\mathbb N} \mathbb E\left[\sup_{r\in[0,T]} \left\|\mathbf u_n^{(\alpha+1)/2}(r) \right\|_{\mathbf H^0_n}^p\right] &< \infty.
        \end{aligned}
    \]
    (2) Moreover, for $0 \leq s < t \leq T$,
    \[
        \begin{aligned}
        \sup_{n\in\mathbb N} \mathbb E\left[\left(\int_{s \wedge \tau_n}^{t \wedge \tau_n} \left\|\mathbf u_n^\alpha(r)\right\|_{\mathbf H^1_n}^2 \mathrm d r\right)^p\right] &\lesssim (t-s)^p + (t-s)^{\frac p2}.
        \end{aligned}
    \]

