[Lemma lem_gamma.from.K of arXiv:2411.07113, '\begin{LARGE}On differentiability and mass distributions of topologically typical multivar'] Consider $C \in \mathcal{C}_{ar}^d$ and let $\psi$, $\gamma$, and $F_K^d$ denote the 
corresponding generator, Williamson measure and Kendall distribution function, respectively. 
Then the following identity holds for all $z \in [0,\infty)$:
      \begin{equation}
     \gamma([0,z]) = \begin{cases}
        F_K^d(\psi(\frac{1}{z})),& \text{ if } z \in [\frac{1}{\varphi(0)},\infty)\\ 
        0,& \text{ if } z \in [0,\frac{1}{\varphi(0)}). 
     \end{cases}
    \end{equation}
Moreover, the non-decreasing transformation $h: [0,\infty] \rightarrow \mathbb{I}$, defined by $h(z)=\psi(\frac{1}{z})$ 
fulfills $h(0)=0$ and is non-singular in the sense that for every $F \in \mathcal{B}([0,\infty))$ we have that 
$\lambda(F)=0$ implies $\lambda^h(F)=0$.

[Lemma lem:bounds_h_2_multidim of arXiv:2411.03609, 'Asymptotically optimal Wasserstein couplings for the small-time stable domain of attractio'] Under Assumption~(\nameref{asm:C}), there exists a function $\widetilde{h}:(0,\infty)\times \mathbb{S}^{d-1}\to(-1,\infty)$ and a constant $K_{\widetilde{h}} \geqslant 0$, such that, for all $x>0$ and $\bm{v} \in \mathbb{S}^{d-1}$, 
\begin{equation}

\rho_{\bm{X}}^{\mathsf{c}\leftarrow}(x,\bm{v})=\left( c_\alpha/c\right)^{1/\alpha}x^{-1/\alpha}G(1/x)(1+\widetilde{h}(x,\bm{v})) \quad \text{and}\quad 
|\widetilde{h}(x,\bm{v})|\leqslant K_{\widetilde{h}}\big(1\wedge (x^{-p/\alpha}G(1/x)^p+x^{-\delta})\big).
\end{equation}

[Lem lem7d of arXiv:2505.11700, 'Distribution of the cokernels of determinantal row-sparse matrices'] For every $1 \le r \le n-1$, we have
\begin{equation*}
p \left ( \bigcup_{i_1 < \cdots < i_r} (T_{n, i_1} \cap \cdots \cap T_{n, i_r}) \right ) 
\ge \sum_{i_1 < \cdots < i_r} p(T_{n, i_1} \cap \cdots \cap T_{n, i_r}) - r \sum_{i_1 < \cdots < i_{r+1}} p(T_{n, i_1} \cap \cdots \cap T_{n, i_{r+1}})
\end{equation*}

[Theorem 18 of arXiv:2506.10522, 'On the Law of the Iterated Logarithm for $m$-dependent stationary random variables under s'] Let $\{X_n;n=1,2,\cdots\}$ be a sequence of independent random variables under $\sles$. Denote $s_n^2=\sum_{i=1}^n\mbE[X_i^2]$, $\underline{s}_n^2=\sum_{i=1}^n\mbe[X_i^2]$, $t_n=\sqrt{2\log\log s_n^2}$ and $a_n=s_nt_n$. Suppose that condition (CC) is satisfied. Assume that 
    \begin{equation}
        \frac{\underline{s}_n^2}{s_n^2}\to r > 0,

    \end{equation}
    \begin{equation}
        s_n^2\to\infty, \quad |X_n|\leq \alpha_n\frac{s_n}{t_n} \text{ with } \alpha_n\to 0

    \end{equation}
    and
    \begin{equation}
        \frac{\sum_{j=1}^n|\mbE[X_j]|+|\mbe[X_j]|}{a_n}\to0.

    \end{equation}
     are satisfied, then for $V = \V^{\mathcal{P}}, \mathbb{C}^*$ or $\Vstar$,
    \begin{equation}
        V\left(C\left\{\frac{\sum_{i=1}^n X_i}{\sqrt{2s_n^2\log\log s_n^2}}\right\}=[-\sqrt{t},\sqrt{t}]\right)=
        \begin{cases}
            1 & \text{ if } t\in[r, 1],\\
            0 & \text{ if } t\notin[r,1].
        \end{cases}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 of arXiv:2607.22416, 'A multi-player optimal stopping game based on a spider Brownian bridge'] \begin{enumerate}
\item $M^\phi= (M^{\phi}_t)_{0 \leq t \leq 1}$ given by $M^{\phi}_t = \sqrt{1-t} \phi\left( \frac{R_t}{\sqrt{1-t}} \right)$ is a non-negative local martingale. 
\item For $j \in \{ 1,2, \ldots , N \}$, $M^{\psi,j} =  (M^{\psi,j}_t)_{0 \leq t \leq 1}$ given by $$M^{\psi,j}_t = \sqrt{1-t} \psi\left( \frac{R_t}{\sqrt{1-t}} \right) \left( \mathbb{I}_{ \{ \Theta_t = \theta_j \} } - p_j \right)$$ is a local martingale. 
\item Suppose $C \in \RR$ and $D \in \RR^N$ is such that $\sum_{j=1}^N p_j D_{j}=0$. Then $M = (M^{C,D}_t)_{0 \leq t \leq 1}$ given by
\[ M^{C,D}_t = C \sqrt{1-t} \phi\left( \frac{R_t}{\sqrt{1-t}} \right) + \sum_{j=1}^N D_j \sqrt{1-t} \psi\left( \frac{R_t}{\sqrt{1-t}} \right) \mathbb{I}_{ \{ \Theta_t = \theta_j \} }
 \]
is a local martingale.
\end{enumerate}

[Lemma lm:fifth_bd of arXiv:2608.27828, 'Scaling limit of the 3D abelian Yang--Mills Langevin dynamics'] Under Assumptions (asmpt:v of the paper) and  (as:models_abstract of the paper),
there exists $C_M>0$ such that 
 \begin{equ}

 \norm{\varepsilon^{-2} \mathop{}\!\mathrm{d}_\varepsilon^*\widehat{\mathfrak{R}}(\varepsilon^2 \mathop{}\!\mathrm{d}_\varepsilon \widehat\theta^\varepsilon(t)) }_{\CC^{-1}_{\varepsilon}}
 \leq 
 C_M 
 \varepsilon^\kappa 
  (1+r + R_v)^5\,
  (1\wedge t)^{
 \frac{1+\eta-5\kappa}{2} \wedge \frac{5 \eta+3 -\kappa }{2} \wedge 0}.
\end{equ}

