body:
[Theo Substitute-Feller of arXiv:2411.19543, 'Feller property and convergence for semigroups of time-changed processes'] Assume that $F$ is closed. Then
\begin{enumerate}
\item[\rm(1)] The space $P_F(C_0(X))$ is  $\check{R}_\alpha$-invariant for all $\alpha>0$ and $\lim_{\alpha\to\infty} \|\alpha\check{R}_\alpha u - u\|_\infty = 0$ for all $u\in P_F(C_0(X))$. 
\item[\rm(2)] The space $P_F(C_0(X))$ is $\check{\bf P}_t$-invariant for all $t>0$ and $\lim_{t\to 0}\| \check{\bf P}_t u - u \|_\infty = 0$ for all $u\in P_F(C_0(X))$.
\item[\rm(3)] For all $t\geq 0$ the semigroup $\check{\bf P}_t$ maps continuously $C_0(X)$ into itself. Moreover, it is continuous, i.e., for all $u\in C_0(X)$, the map: $t\in[0,\infty)\to C_0(X),\; t\mapsto \check{\bf P}_t u$ is continuous.
\end{enumerate}

[Defi 9 (Diagonal negative dependence) of arXiv:2608.30357, 'Mean convergence for Banach space-valued random elements indexed in measure spaces'] \mbox{ }
\begin{enumerate}[(i)]
\item Two $\cX$-valued random elements $X, Y$ are said to be \textit{diagonally negatively dependent} if 
\begin{align}
\bP(X \in A, Y \in A) \le \bP(X \in A)\,\bP(Y \in A), \quad \forall A \in \cB(\cX),
\end{align}
or equivalently,
$\Cov(\1_{\{X \in A\}}, \1_{\{Y \in A\}}) \le 0$ for all $A \in \cB(\cX)$.

\item Let $\varnothing \neq I \subseteq \bR$ and $M \in \bN \cup \{0\}$.
A family $\{Y_i : i \in I\}$ of $\cX$-valued random elements is \textit{$M$-pairwise diagonally negatively dependent} if $Y_i, Y_j$ are diagonally negatively dependent for all $i, j \in I$ with $|i-j|>M$.
When $M=0$, we then simply call $\{Y_i : i \in I\}$ \textit{pairwise diagonally negatively dependent}.

\end{enumerate}

[Proposition 7 of arXiv:2609.03954, 'Galois representations ramified at one prime via relative deformation theory'] For every $m\in\Z$ there is a natural isomorphism
\begin{equation}
 H^2\!\left(G_{\{p\}},(\Qp/\Zp)(m)\right)^\vee
 \simeq e_mX[f_m].
\end{equation}

[Lem theo: decoupling ineq of arXiv:2604.21663, 'Large deviations for non-irreducible Markov chains on Euclidean spaces'] Let $n,$ $T$ and $N$ be as in Corollary~(coro: advanced geographic ineq coupling map of the paper). Let 
	\begin{align*}
		A_n^{(1)}(\delta)&=\{u\in \widetilde{\mathcal{W}}_n\ |\ d_{\mathrm{LP}}(L[u],\mu_1)\leqslant \delta\},\\
		A_n^{(2)}(\delta)&=\{u\in \widetilde{\mathcal{W}}_n\ |\ d_{\mathrm{LP}}(L[u],\mu_2)\leqslant \delta\},\\
		B_T(\varepsilon, \delta)&=\{w\in \mathcal W_T\ |\ d_{\mathrm{LP}}(L[w],\mu)\leqslant f(\varepsilon, \delta)\}.
	\end{align*}
	Then,
	\begin{equation}
		\begin{split}

		\mathbb P(A_n^{(1)}(\delta))^{\lceil N/2\rceil}\mathbb P(A_n^{(2)}(\delta))^{\lfloor N/2\rfloor}&\leqslant C_{n,T} \mathbb P(B_T(\varepsilon,\delta)),
		\\ C_{n,T}&= \big(c_K^r(\tau_K+1)^{r}(n+1)^{2r+1}\big)^{N}.
		\end{split}
	\end{equation}

