[Lemma 25 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the same notation as in Definition \ref{Def.IPGP}. Then, for any $\{ B_i \in \Omega(T,y_i) \}_{i = 1}^{2k}$
\begin{equation}
{\bf 1}_{A} \cdot \mathbb{P}\left( L_{i}\llbracket 0,T \rrbracket = B_{i} \mbox{ for $i \in \llbracket 1, 2k \rrbracket$} \, \vert  \mathcal{F}_{\mathrm{ext}}^{\mathrm{odd}} \right) \overset{a.s.}{=} {\bf 1}_{A} \cdot  \mathbb{P}^{T, \vec{y}, g}_{\ice; q,c} \left( \cap_{i = 1}^{2k} \{Q_i = B_i\} \right),
\end{equation}
where $\mathcal{F}_{\mathrm{ext}}^{\mathrm{odd}} = \sigma\left\{L_i(j): (i,j) \in \llbracket1,2\lfloor(N-1)/2\rfloor+1\rrbracket \times \llbracket 0, T_1 \rrbracket \setminus \llbracket 1, 2k \rrbracket \times \llbracket 0, T-1 \rrbracket\right\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 1 (Geometry and path-space discretization) of arXiv:2609.02196, 'Schr\"odinger Bridges on Lie Group Manifolds for Probabilistic Intrinsic Generation'] Assume the Ornstein--Uhlenbeck specialization \(\bm b(t,g,\bm\xi)=-\gamma\bm\xi\) with \(\gamma>0\). For \(\G=SO(3)\) or \(\G=U(n)\), take the metric \(d_\G\) used in the bounded-Lipschitz path distance to be the standard bi-invariant Riemannian distance induced by an \(\operatorname{Ad}\)-invariant inner product on \(\g\). Let the feedback control \(\bm u:[0,T]\times\G\times\g\to\g\) satisfy, for constants \(L_u,K_u<\infty\),
\begin{align*}
\norm{\bm u(t,g,\bm\xi)-\bm u(s,g',\bm\eta)}
&\le L_u\bigl(|t-s|+d_\G(g,g')+\norm{\bm\xi-\bm\eta}\bigr),\\
\norm{\bm u(t,g,\bm\xi)}
&\le K_u\bigl(1+\norm{\bm\xi}\bigr),
\end{align*}
and assume \(\E\norm{\bm\xi_0}^4<\infty\). Then the update above preserves \(SO(3)\) for skew-symmetric algebra coordinates and \(U(n)\) for skew-Hermitian coordinates, and the velocity update is exact for the frozen-control OU substep. If \(P_{\Delta t}^{\bm u}\) denotes the law of the continuous piecewise OU/exponential interpolation defined in the proof and \(P^{\bm u}\) is the exact controlled path law with the same initial law, then
\begin{equation}
d_{\rm BL}(P_{\Delta t}^{\bm u},P^{\bm u})
\leq C_T\Delta t^{1/2}.
\end{equation}
The constant \(C_T\) depends only on \(T,\gamma,\alpha,L_u,K_u\), the fourth moment of the initial velocity, and the fixed group metric. In particular, it is uniform over any control sieve with common Lipschitz and linear-growth bounds. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 10 of arXiv:2608.06038, 'Efron type identities\\ for stopping sets and Poisson hulls'] Let $Z$ be a Markov set. Then
  \begin{equation}
    \BE \eta_Z(B)=\BE \lambda_Z(B),\quad B\in\cX.
  \end{equation}

[Thm 17 (Main Theorem for $n=1$ and $p>0$) of arXiv:2609.00974, 'On Algebraic Integrability\\ of Vector Fields \\ with Rational Function Coefficients\\ tha'] We follow the assumptions and notations from Theorem \ref{Main Formula}. In particular, the prime $p$ is assumed to be big enough. The following are equivalent:
    \begin{enumerate}
        \item $\frac{\overline{L}}{P^p+L^p+H^p}=\mu \in \overline{k}$,
        \item One of the following is true:
        \begin{enumerate}
            \item $L=0$. In this case: $\mu=0$.
            \item $P=H=0$ and there exists $\eta\in \overline{k}$, $\eta \ne 0$ such that each $c_i$ satisfies $(\eta x)^{p}=(\eta x)$. 

            In this case: $\mu \ne 0$ and $\eta^{p-1}=\mu$.
        \end{enumerate}
    \end{enumerate}

[Prop TVS-meas of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] {dim-TVS}}] 
    Fix $a\geq\lambda$, $u\in\mathbb R$. Denote $\mathds A=\mathds A_{-a,a}^u$. For $\eta>0$, define the random measures
    \begin{equation}
        \mu_\eta(dz) = \eta\mathrm{CR}(z, D\setminus\mathds A)^{-(\alpha_c-\eta)^2/2}dz.
    \end{equation}
    Then, for any $f\in C_c^\infty(D)$, 
    \begin{equation}
        \lim_{\eta\to0}(\mu_\eta, f) = (\mu, f)\in[0, \infty)
    \end{equation}
   exists as a limit in $L^1(\mathbb P)$ and
    \begin{equation}
       a(\mu, f) = \mathbb E[(:\! \cos(\alpha_c\phi) \!: , f)\mid\mathcal F_\mathds A].
   \end{equation}
   In particular, $(\mu_\eta)_{\eta>0}$ converge in law with respect to the weak topology of measures to a random measure $\mu$, which is measurable with respect to $\mathds A$ and supported in $\mathds A$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:ward of arXiv:2608.23742, 'Second-order fusion asymptotics for $\Sine_\beta$ correlation functions'] Let $\delta>1/2$, $\beta>0$, and let expectation $\mathbb E_{N,\delta}$ be with respect to $\mathsf{CJ}_{N,\beta,\delta}$. With $r_N$ as in (equation eq:rN of the paper),
\begin{equation}
\mathbb E_{N,\delta}\left[r_N''(0)+(2\delta-1)r_N'(0)^2\right]=0.
\end{equation}
Consequently, if $h_N(t):=\mathbb E_{N,\delta}r_N(t)^\beta$, then
\begin{equation}
h_N''(0)=\beta(\beta-2\delta)\mathbb E_{N,\delta}r_N'(0)^2.
\end{equation}

[Cor 38 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] For $N$ sufficiently large, there are constants $C, \tilde{C} > 0$ such that

$$\sul{k=1}{N} |V(\lambda_k^+) - V(\lambda_k^-)|  \leq \frac{C}{N} \sul{k=1}{N}

\big\{ {V}(\lambda_k^+) + V(\lambda_k^-) \big\} + \tilde{C} \, .$$

[Theorem 4 (Mixed operator convergence with deterministic diagonal resolution) of arXiv:2606.16662, '2606.16662'] Fix \(\eps>0\), \(0<T_0\le1\), a finite color set \(\cC\), a finite family \(\cM\) of mixed triples, and a fixed Bony aperture \(c_{\rm ap}\).  Assume the Fourier-diagonal time covariance model \eqref{eq:conv-cov}--\eqref{eq:cov-decay} and the coefficient bounds of Assumption~\ref{ass:coeff}.  Let \((s,\sigma)\) be \((\tau,\eps)\)-centered admissible in the sense of Definition~\ref{def:admissible} for every \(\tau\in\cM\).

Choose a dyadically admissible deterministic diagonal resolution
\(\mathfrak P=\{(\Ret^\tau_\Lambda,\Ctr^\tau_\Lambda)\}_{\tau\in\cM}\)
in the sense of Definition~\ref{def:contraction-resolution}.  Assume that
every nonzero retained diagonal has gain \(\delta_\tau>20\eps\) and that
\(s<\delta_\tau-10\eps\) for those labels.

For each \(\tau=(i;j,k)\), define the finite \(\mathfrak P\)-resolved operator
\begin{equation}
        T_{\Lambda}^{\tau,\mathfrak P}:=T_{\Lambda}^{\tau}-\Ctr^\tau_\Lambda .
\end{equation}
Then, for every \(0<T\le T_0\), the following assertions hold.
The full-probability event below may be chosen for \(T_0\) and therefore
works simultaneously for every \(T\le T_0\).

\begin{enumerate}[label=(\roman*),leftmargin=2.4em]
\item \textup{Finite Wick split.}  The cutoff operator admits the exact finite-cutoff Wick decomposition
\begin{equation}
        T_{\Lambda}^{\tau}=D_{\Lambda}^{\tau}+B_{\Lambda}^{\tau}.
\end{equation}
The diagonal part \(D_{\Lambda}^{\tau}\) is deterministic and supported by \(n=q\) in the external variables.  The centered part \(B_{\Lambda}^{\tau}\) is a finite sum of second homogeneous Gaussian chaoses and preserves the incidence
\begin{equation}
        n=q+\ell+r.
\end{equation}
Consequently,
\begin{equation}
        T_{\Lambda}^{\tau,\mathfrak P}=\Ret^\tau_\Lambda+B^\tau_\Lambda.
\end{equation}

\item \textup{Centered operator component.}  For every finite \(p\ge2\), the centered operators \(B^\tau_\Lambda\) converge in \(L^p(\Omega)\) and almost surely in the centered operator topology
\begin{equation}
        \cL(X_T^\sigma,C_TH^{s-\lambda_i})
        \cap
        \cL(X_T^\sigma,L_T^1B^{\sigma-\lambda_i}_{2,\infty}).
\end{equation}
The limit \(B^\tau\) satisfies the operator-norm estimates
\begin{align}
        \|B^\tau\|_{L^p(\Omega;\cL(X_T^\sigma,C_TH^{s-\lambda_i}))}
        &\le C_p,\\
        \|B^\tau\|_{L^p(\Omega;\cL(X_T^\sigma,L_T^1B^{\sigma-\lambda_i}_{2,\infty}))}
        &\le C_p.
\end{align}
There is a full-probability event, independent of \(\tau\in\cM\), on which all centered cutoff sequences are Cauchy in the pathwise operator norm \eqref{eq:centered-op-topology}.  The centered estimate is an \(X_T^\sigma\)-estimate; the derivative components of \(E_{T,\cM}^{2,\sigma}\) are needed only when a retained diagonal is present.

\item \textup{Retained deterministic component.}  The retained diagonals converge to deterministic operators \(\Ret^\tau\) satisfying
\begin{equation}
        \|\Ret^\tau w\|_{C_TH^{s-\lambda_i}}
        +\|\Ret^\tau w\|_{L_T^1B^{\sigma-\lambda_i}_{2,\infty}}
        \le C\|w\|_{E_{T,\cM}^{2,\sigma}} .
\end{equation}

\item \textup{Assembled operator.}  On the same full-probability event,
\begin{equation}
        T_{\Lambda}^{\tau,\mathfrak P}
        \longrightarrow
        T^{\tau,\mathfrak P}:=\Ret^\tau+B^\tau
\end{equation}
in the assembled topology
\begin{equation}
        \cL(E_{T,\cM}^{2,\sigma},C_TH^{s-\lambda_i})
        \cap
        \cL(E_{T,\cM}^{2,\sigma},L_T^1B^{\sigma-\lambda_i}_{2,\infty}),
\end{equation}
for every \(\tau\in\cM\).  The convergence also holds in \(L^p(\Omega)\) for every finite \(p\ge2\).
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 4 (Control-law relative entropy) of arXiv:2609.02196, 'Schr\"odinger Bridges on Lie Group Manifolds for Probabilistic Intrinsic Generation'] For controlled laws with the same initial law and diffusion coefficient,
\begin{equation*}
\KL(P^{\bm u}\|P^{\bm v})
=\frac12\E_{P^{\bm u}}\int_0^T\norm{\bm u_t-\bm v_t}^2\,\dd t
\end{equation*}
whenever the Girsanov exponentials are true martingales. In particular,
\begin{equation*}
\norm{P_t^{\bm u}-P_t^{\bm v}}_{\rm TV}
\leq\frac12\left(\E_{P^{\bm u}}\int_0^T\norm{\bm u_s-\bm v_s}^2\,\dd s\right)^{1/2}.
\end{equation*}
The proof is given in \cref{app:proof-control-kl}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Ppn 169 (quenched second moment bounds for $\vX$, $\vX^\trunc$, and $\vX^\frozen$) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Let $\hat{a}$, $\hat{a}^\frozen$,
$\hat{\iota}$, and $\hat{\iota}^\frozen$
be sampled uniformly at random from 
$[M]$, $[M^\frozen]$,
$[N]$, and $[N^\frozen]$, independently of the gaussian disorder and of one another. 
Recall that $\bE$ denotes expectation over $\hat{a}$, $\hat{a}^\frozen$, $\hat{\iota}$, and $\hat{\iota}^\frozen$, as applicable.
Then for 
all $0\le d\le \dmax-1$ we have
	\[\max\bigg\{
	\frac{\bE[\Delta X^{\RomI}(q_d,\hat{a})^2]}
		{(\delta_d)^2 p'(q_d)},
	\frac{\bE[\Delta X^{\RomII}(q_d,\hat{a})^2]}
		{\delta_d  p(q_d)},
	\frac{\bE[\Delta X^{\RomIII}(q_d,\hat{a})^2]}
		{\delta_d  q_d p'(q_d)},
	\frac{\bE[\Delta X^{\Ising}(q_d,{\hat{\iota}})^2]}
		{\delta_d}
	\bigg\}
    \le (\MAX_N)^2\,,\]
where $\MAX_N$ is defined by \eqref{e:MAX.N}. The same bound holds with $\vX^\trunc$ or $\vX^\frozen$ in place of $\vX$
(using $(\hat{a}^\frozen,\hat{\iota}^\frozen)$ in place of $(\hat{a},\hat{\iota})$ for the case of $\vX^\frozen$).

\begin{proof}
Recall the notation introduced in \eqref{e:normalized.vectors.g}--\eqref{e:normalized.vectors.y}. From \eqref{e:X.decomp}, we have
	\begin{align*}
	\frac{\Delta X^{\RomI}(q_d,a)}{\delta_dp'(q_d)^{1/2}}
	&= 
	\frac{(\bmeta^a(q_{d+1}),
	\by(q_{d+1}))}{N^{1/2}}\,,\\
	\frac{\Delta X^{\RomII}(q_d,a)}{(\delta_d p_d)^{1/2}}
	&= \frac{(\bar{\bg}^a(q_d),\by(q_{d+1}))}{N^{1/2}}\,,\\
	\frac{\Delta X^{\RomIII}(q_d,a)}{[\delta_d q_d p'(q_d)]^{1/2}}
	&= 
	\frac{(\bmeta^a(q_{d+1}),\bar{\bx}(q_d))}{N^{1/2}}\,,\\
	\frac{\Delta X^{\Ising}(q_d,
		{i})}{(\delta_d)^{1/2}}
	&=(\be_i,\by(q_{d+1}))\,,
	\end{align*}
where $a\in[M]$ and $i\in[N]$.
We therefore have the (quenched) second moment bounds
	\begin{align*}
	\frac{\bE[\Delta X^{\RomI}(q_d,
		\hat{a})^2]}
		{(\delta_d)^2 p'(q_d)}
	&=\frac{1}{M}
	\sum_{a=1}^M \frac{(
	\bmeta^a(q_{d+1}),
		\by(q_{d+1}))^2}{N}
	\le \frac{
	\|\bXi(q_{d+1})\|^2
	\|\by(q_{d+1})\|^2}
		{MN}
	\le (\MAX_N)^2\,,\\
	\frac{\bE[\Delta X^{\RomII}(q_d,\hat{a})^2]}
		{\delta_d p_d}
	&=
	\frac{1}{M}
	\sum_{a=1}^M 
	\frac{(\bar{\bg}^a(q_d),\by(q_{d+1}))^2}{N}
	\le
	\frac{\|\bar{\bG}(q_d)\|^2
	\|\by(q_{d+1})\|^2}{MN}
	\le (\MAX_N)^2\,,\\
	\frac{\bE[\Delta X^{\RomIII}(q_d,
		\hat{a})^2]}{\delta_d q_d p'(q_d)}
	&=\frac{1}{M}
	\sum_{a=1}^M
	\frac{(\bmeta^a(q_{d+1}),\bar{\bx}(q_d))^2}{N}
	\le \frac{\|\bXi(q_{d+1})\|^2 \|\bar{\bx}(q_d)\|^2}{MN}
	\le (\MAX_N)^2\,,\\
	\frac{\bE[\Delta X^{\Ising}
	(q_d,{\hat{\iota}})^2]}{\delta_d}
	&=
	\sum_{i=1}^N \frac{(\be_i,\by(q_{d+1}))^2}{N}
	= \frac{\|\by(q_{d+1})\|^2}{N}
	\le \MAX_N\,.
	\end{align*}
This proves the claim for $\vX$.
Then note that $\Delta X^{\trunc,\RomI}(q_d,a)$ equals either $\Delta X^{\RomI}(q_d,a)$ or zero, where the latter case corresponds to scenarios where the trajectory has exited $[-\trK,\trK)^3$ (Definition~\ref{d:trunc}) or has landed in a small bucket (Definition~\ref{d:buckets}). 
Likewise, $\Delta X^{\frozen,\RomI}(q_d,a)$ equals either $\Delta X^{\trunc,\RomI}(q_d,a)$ or zero, 
where the latter case corresponds to the same scenarios mentioned above for $X^{\trunc,\RomI}$, or to the scenario where $a$ is the index of one of the frozen particles added in Definition~\ref{d:froze}. It follows that
	\[
	\bE\Big[\Delta X^{\frozen,\RomI}(q_d,\hat{a}^\frozen)^2\Big]
	\le 
	\bE\Big[\Delta X^{\trunc,\RomI}(q_d,\hat{a})^2\Big]
	\le \bE\Big[
		\Delta X^{\RomI}(q_d,\hat{a})^2\Big]\,,\]
and similarly for $X^{\RomII}$, $X^{\RomIII}$, and $X^{\Ising}$. The claim then follows for $\vX^\trunc$ and $\vX^\frozen$.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem bigggg-lemma of arXiv:2510.18856, 'Evolution of recursive trees with limited memory'] \textcolor{black}{Let $\mathcal{C}$ be a bounded subset in $R_{+}^{K^2+K}$. Then we have 
\begin{align*}
    \sup_{i=0,1,2} \, \sup_{\boldsymbol{x} \in \mathcal{C}}\left|\mathbf{P}_{i,n}(\boldsymbol{x}) - \mathbf{P}_{i+1,n}(\boldsymbol{x}) \right|\leqslant  \frac{C}{n}
\end{align*}for some constant $C \geqslant 0$ depending of the set $\mathcal{C}$ and $K$.} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 74 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $q \in (0,1)$, $c \in [0,1)$, and set $p = \frac{q}{1-q}$, $\sigma = \sqrt{p(1+p)}$. Let $\{d_n \}_{n \geq 1}$ be a sequence of positive reals, such that $d_n \rightarrow \infty$ as $n \rightarrow \infty$. Fix $b > 0$, put $T_n = \lceil b d_n \rceil$, and let $Y^n \in \mathfrak{W}_2$ be a sequence, such that 
\begin{equation}
\lim_{n \rightarrow \infty}\sigma^{-1} d_n^{-1/2} (Y_1^n -Y_2^n) = \alpha > 0.
\end{equation}
Finally, fix $s, t \in \mathbb{R}$, and let $\hat{q}, \hat{c}$ be as in (\ref{Eq.qchatsA}). Then, we have 
\begin{equation}
\lim_{n \rightarrow \infty} \sigma^2 d_n (1-q)^{2T_n} e^{2\im p T_n s \sigma^{-1} d_n^{-1/2} } Z(T_n, Y^n; \hat{q},\hat{c}) = e^{-bs^2} \cdot \frac{1}{(1 - \hat{c})^2} \cdot e^{-\alpha^2/4b} \cdot \frac{\alpha}{b \sqrt{4\pi b}}.
\end{equation}

