body:
[Lemma 27 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb$, $f\in \Sob^k(\Rbb^n,\gamma_n)$, $q\in [1,2)$ and $t\geq 0$,
\begin{equation}
    \Vop^k(\Pop_t f) \leq \upe^{-2kt} \Vop^k(f)^{1-\vartheta} \min\left\{\Vop^k(f),\,\left\|\left|\grad^k f\right|\right\|_{\Leb^q}^{2},\, \sum_{\kappa\in \Nbb^n:|\kappa|=k}\left\|\Dop^\kappa f\right\|_{\Leb^q}^2\right\}^{\vartheta},
\end{equation}
and further for all $\kappa\in \Nbb^n$ with $|\kappa|=k$,
\begin{equation}
    \Vop^\kappa(\Pop_t f) \leq \upe^{-2kt} \Vop^\kappa(f)^{1-\vartheta} \min\left\{\Vop^\kappa(f),\,\left\|\Dop^\kappa f\right\|_{\Leb^q}^2\right\}^{\vartheta},
\end{equation}
where $\vartheta=\vartheta(q,t) := \min\left\{\frac{q}{2-q}\tanh(t), 1\right\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition ContainerTheoremE of arXiv:2411.12522, 'Canonical insurance models: stochastic equations and comparison theorems'] For $Y \in \mathbb{Y}$, the processes  $Y^i$, $i \in \mathcal{Z}$, defined by 
	\begin{align}
		Y^i(t)(\omega):=Y(t)(\omega_t^i), \quad t \geq 0,\, \omega \in \Omega,
	\end{align}
	are 
	$\mathcal{F}^-$-adapted and jointly measurable, and the paths of $I^i(t-) Y^i(\mathrm{d} t)$ are   càdlàg  and of  finite variation on finite intervals. 
		It holds that
		\begin{align}
			 Y(\mathrm{d} t) = \sum_{i} I^i(t-)  Y^i(\mathrm{d} t) + \sum_{i,j:i \neq j} (Y^j(t)-Y^i(t)) N^{ij}(\mathrm{d} t). 
		\end{align}

[Lemma lem:local-arithmetic of arXiv:2609.00777, 'Universal murmuration and Hecke augmentation'] Let $D,M\geq1$ and $1\leq r<2\sqrt Q/\sqrt{X+Y}$ with $P\nmid r$.
The series
\[
\sum_{\substack{d,n\geq1\\ (r,d)\ {\rm admissible}}}
\frac{\Gamma_{r,Q}(d,n)}{nd}
\]
is absolutely convergent, and
\begin{equation}
\sum_{\substack{d\leq D,\ n\leq M\\ (r,d)\ {\rm admissible}}}
\frac{\Gamma_{r,Q}(d,n)}{nd}
=BC(r)+O(P^{-2})
+O_\varepsilon\left(
(QDM)^\varepsilon\left(D^{-2}+M^{-1/5}\right)
\right).
\end{equation}
The constants and tail bounds are uniform in the displayed range of $r$; $k$ remains fixed.

