[Thm 5.8 of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Let $X$ be a Borel right process on $(E,d)$ that satisfies (AC) and the following short-time heat kernel lower bound at a fixed point $x\in E$: For some $T>0, \alpha>0$ and $\beta>1$, there exist constants $C_1,C_2>0$ such that
\begin{equation}
p(t,x,y)\ge \frac{C_1}{t^{\alpha/\beta}}\exp\left\{-C_2\left(\frac{d(x,y)}{t^{1/\beta}}\right)^{\beta/(\beta -1)}\right\}, \quad \forall t\in (0, T], \, y\in E.
\end{equation}
Let $B\in \mathscr{B}^n(E)$ be a nearly Borel set.
\begin{itemize}
    \item[(1)] If $X$ satsifies (H3) and $p^{(\lambda)}_B\in {\mathcal{F}}$ for some $\lambda>0$, then for any $\delta,\rho>0$,
 \[
        \mathbb{P}^x[\sigma_B\leq t]\geq \frac{\nu^{(\lambda)}_{B_{x,\delta}}(\overline{B}_{x,\delta})}{\mathrm{e}^{\lambda T}}\cdot \frac{C_1 C_3}{ t^{(\alpha-\beta)/\beta}}\exp\left\{-(1+\rho)C_2\left( \frac{\widetilde{d}(x,B)+\delta}{t^{1/\beta}}\right)^{\beta/(\beta-1)}\right\},\quad 0<t\leq T,
    \]
    where  $B_{x,\delta}:=\{y\in B:d(y,x)\leq \widetilde{d}(x,B)+\delta\}$, $\nu^{(\lambda)}_{B_{x,\delta}}$ is the measure obtained in Corollary~(COR55 of the paper), $C_1$ and $C_2$ are as in (equation eq:511-2 of the paper), and $C_3=(\beta-1)\rho\cdot \min\{(1+\rho)^{\alpha-\beta-\alpha/\beta}, 1\}>0$ is a constant depending on $\alpha, \beta,\rho$.
\item[(2)] If $X$ is transient and satisfies (H3'), and $p_B\in {\mathcal{F}}_\mathrm{e}$, then the same conclusion as in the first statement holds with $\lambda=0$ and $\nu^{(0)}_{B_{x,\delta}}=\nu_{B_{x,\delta}}$, where $\nu_{B_{x,\delta}}$ is the measure obtained in Lemma~(LM53 of the paper). 
\end{itemize}

[Theorem 13 of arXiv:2506.11918, 'Central limit theorems for the Euler characteristic in the Random Connection Model for hig'] [CLT for increasing observation window] 
Let $(W_n)_{n\in\N}$ be a sequence of observation windows with $|W_n|\rightarrow\infty$ for $n\rightarrow\infty$, such that there is a constant $C>0$ with
\begin{align} 
\E{ f_\alpha(\Delta_{W_n}) } \,\geq\, C |W_n| \qquad \text{for all sufficiently large } n\in\N.
\end{align}
Moreover, assume that the condition (\ref{Integrabilitaet}) holds.
Then for $a=(a_0,\dots,a_\alpha) \in \R^{\alpha+1}$ with $a_\alpha\neq 0$ it is true that
\begin{align*}
\frac{\chi_a\big(\Delta_{W_n}\big)-\E{ \chi_a\big(\Delta_{W_n}\big) }}{\sqrt{\V{\chi_a\big(\Delta_{W_n}\big) }}} \xrightarrow{d} \mathcal{N}(0,1) \qquad \text{for } n \rightarrow \infty.
\end{align*}
Concretely, the quantities from Theorem \ref{Th:myRCM} applied to $\tilde{\chi}_a\big(\Delta_{W_n}\big)$ satisfy
\begin{align*}
\gamma_1,\gamma_2,\gamma_3,\gamma_4,\gamma_5,\gamma_6 \,=\, \mathcal{O}\left(|W_n|^{-\frac{1}{2}}\right).
\end{align*}

