[Definition 7 (resolvent) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] \label[definition]{def:resolvent}
Let $X$ be a regular diffusion with generator $\mathcal L$ and speed measure $m$.  For $\alpha>0$, the \emph{resolvent} is the operator $R_\alpha\coloneqq\alpha(\alpha-\mathcal L)^{-1}$, which averages a function over an independent $\operatorname{Exp}(\alpha)$ time:
\begin{equation}
  R_\alpha f(x)\;=\;\mathbb E\bigl[f(X_{T_\alpha})\mid X_0=x\bigr]\;=\;\alpha\!\int_0^\infty G_\alpha(x,y)\,f(y)\,m(dy),
\end{equation}
with \emph{resolvent kernel} $G_\alpha$.

[Mylem Lem_Moments_2 of arXiv:2411.08430, 'The Restricted Isometry Property of Block Diagonal Matrices Generated by $\varphi$-Sub-Gau'] Assume that a random variable $\xi$ satisfies for $p\ge p_{0}$
	\begin{align}
		\Vert \xi\Vert_{L_p}\le \sum_{k=1}^{m}C_{k}p^{\beta_{k}}+C_{m+1},\nonumber
	\end{align}
	where $C_{1},\cdots, C_{m+1}> 0$ and $\beta_{1},\cdots, \beta_{m}>0$. Then we have for any $t>0$,
	\begin{align}
		\textsf{P}\big\{ \vert \xi\vert>e(mt+C_{m+1}) \big\}\le e^{p_{0}}\exp\Big(-\min\big\{\big(\frac{t}{C_{1}}\big)^{1/\beta_{1}},\cdots, \big(\frac{t}{C_{m}}\big)^{1/\beta_{m}}\big\}\Big)\nonumber
	\end{align}
	and
	\begin{align}
		\textsf{P}\Big\{\vert \xi\vert>e \big(\sum_{k=1}^{m}C_{k}t^{\beta_{k}}+C_{m+1}\big)  \Big\}\le e^{p_{0}}e^{-t}.\nonumber
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

