[Thm th:2.2 of arXiv:2412.03370, 'TASEP with a general initial condition and a deterministically moving wall'] Suppose $\xi = g_\alpha < 1-2\sqrt{\alpha}$. Then, it holds
	\begin{equation}
	\begin{aligned}
	\lim_{T \to \infty} \mathbb{P}(x^f_{\alpha T}(T) > \xi T - S T^{1/3}) 
	&= \lim_{T \to \infty} \mathbb{P}(x_{\alpha T}(t) > \xi T - f(T-t)-ST^{1/3} \ \forall t \in [0,T]) \\
	&\hphantom{= } \times \lim_{T \to \infty} \mathbb{P}(\tilde{x}_{\alpha T}(T) > \xi T - S T^{1/3}). 
	\end{aligned} 
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary coro_1 of arXiv:2412.03774, '{ Refining Concentration for \\Gaussian Quadratic Chaos with\\ Applications in Sonar and C'] Let $A$ be a symmetric matrix. For every $\epsilon>0$ and integer $m\geq2$, 
\begin{eqnarray}

\Pr(\boldsymbol{\Delta}>t)\leq \inf_{0<b<1}e^{\Lambda_m(t,b)}\leq (1+\epsilon)\exp\bigg(-\tilde{\kappa}_{m}\min\bigg\{\frac{t^{1+\frac{1}{m}}}{\|A\|_{m+1}^{1+\frac{1}{m}}}, \frac{t}{\|A\|}\bigg\}\bigg),
\end{eqnarray} 
where $\tilde{\kappa}_{m}>0$ is a constant that depends only on $m, n$ and $\epsilon$.

