[Prop 12 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Recall from \eqref{defPgamH} the definition of $\mathcal{P}^{ \gamma} H$. It holds
\begin{align} 
  \forall 0 \leq s \leq t \leq T, \quad \lim_{n \rightarrow \infty} E_{\nu_{\rho}} \big[ \langle \mathcal{M}^n(H) \rangle_t - \langle \mathcal{M}^n(H) \rangle_s \big] = (t-s) D_3  \mathcal{P}^{ \gamma} H.
\end{align}	
Furthermore, if $H \in C_c^1(\mathbb{R})$, it holds
	\begin{align} 
\forall n \in \mathbb{N}_+, \; \forall 0 \leq s \leq t \leq T, \quad		\ E_{\nu_{\rho}} \big[ \langle \mathcal{M}^n(H) \rangle_t - \langle \mathcal{M}^n(H) \rangle_s \big] \leq   C(H)(t-s).
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 47 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Using the above conventions, set $M(A,B)=\sup_{x\in A, y\in B} -c(x,y)$ for non-empty $A,B\subset Q_n$. Then, 
    \begin{equation} 
        \sqrt{\mu_n(A)\mu_n(B)}\leq F_n\left( M(A,B) \right).
    \end{equation}
    It is sharp in the sense that, if $j<n$, then 
\begin{equation}
   F_n(j)=\max\{\sqrt{\mu_n(A)\mu_n(B)}: d_H(A,B)\geq n-j\}.
\end{equation}

[Thm 14 of arXiv:2604.24189, 'Malliavin calculus and densities for chaos-driven stochastic differential equations'] Let $F=\{F_t=(I_q(f_t^1),\ldots,I_q(f_t^m))\,,\;t\in \R_+\}$ be an $\R^m$-valued chaos process on an abstract Wiener space $(\Omega,\mathcal{F},\P,\mathfrak{H})$.  Assume that, $F$ verifies the hypotheses $\mathbf{(H_2)}$ with $H\in (\frac{1}{2},1)$. Let us also assume  that the coefficients $(b_k)_{1 \leq k \leq d}$ and $(\sigma_{k,\ell})_{1 \leq k \leq d, 1 \leq \ell \leq m}$ of the stochastic differential equation \eqref{eq:SDEsDrivenF} satisfy  the hypotheses $\mathbf{(H_1)}$.
	Then, the unique solution to \eqref{eq:SDEsDrivenF}, $(X_t)_{t \in [0,T]}$, is such that for any $t\in(0,T]$, $X_t\in (\D^{1,\infty})^d$, and, for any $h\in\HHH$ and $1 \leq k \leq d$, we have
	\begin{align}
		\left<D X_t^k, h\right>_{\HHH}=  \sum_{\ell=1}^{m} \int_{0}^{t} \Theta_{t}^{k,\ell}(s) \mathrm{d} \left<DF^{\ell}(s), h\right>_{\HHH},
	\end{align}
where 	for $1 \leq k \leq d$, $1 \leq \ell \leq m, \, 0 \leq s \leq t \leq T, s \mapsto \Theta_{t}^{k,\ell}(s)$ satisfies
\begin{align}
	\Theta_{t}^{k,\ell}(s)=\sigma_{k,\ell}\left(X_s\right) &+ \sum_{p=1}^{d} \int_{s}^{t} \partial_{p} b_{k}\left(X_u\right) \Theta_{u}^{p, \ell}(s) \mathrm{d} u \nonumber \\
	&+ \sum_{p=1}^{d} \sum_{q=1}^{m} \int_{s}^{t} \partial_{p} \sigma_{k,q}\left(X_u\right) \Theta_{u}^{p, \ell}(s) \mathrm{d} F^{q}_u,
\end{align}
and $\Theta_{t}^{k, \ell}(s)=0$ if $s>t$.

