[Defin of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] An $\mathbb{X}$-\textit{shuffling rule} is a mapping $\psi\colon\trees^{\bullet}[\mathbb{X}]\to\mathfrak{S}$ such that for every $(T,{\boldsymbol{x}},\mathtt{u})\in\trees^{\bullet}[\mathbb{X}]$, its image $\psi(T,{\boldsymbol{x}},\mathtt{u})$ is an element of $\mathfrak{S}_{k_\mathtt{u}(T)}$.
	Given an $\mathbb{X}$-shuffling rule, for every  $T\in\trees$ and every ${\boldsymbol{x}}\in\mathbb{X}^T$, we set:
	\begin{align*}
	{\boldsymbol{\sigma}}^\psi_{T,{\boldsymbol{x}}}=\bigl(\psi(T,{\boldsymbol{x}},\mathtt{u})\bigr)_{\mathtt{u}\inT},
	\end{align*}
	which defines an element of $\mathfrak{S}_T$

[Definition 10 (Thick quantum disk) of arXiv:2608.27630, 'Oriented planar maps and \\ annular mating of trees'] Fix a weight parameter $W\ge\frac{\gamma^2}{2}$ and let $\beta = \gamma+ \frac{2-W}{\gamma}\le Q$. 
		Let $(B_s)_{s\ge0}$ and $(\wt{B}_s)_{s\ge0}$ be independent standard one-dimensional Brownian motions conditioned on  $B_{2t}-(Q-\beta)t<0$ and  $ \wt{B}_{2t} - (Q-\beta)t<0$ for all $t>0$.   Let $\mathbf{c}$ be sampled from the infinite measure $\frac{\gamma}{2}e^{(\beta-Q)c}dc$ on $\bbR$ independently from $(B_s)_{s\ge0}$ and $(\wt{B}_s)_{s\ge0}$.
			Let 	
			\begin{equation*}
				Y_t=\left\{ \begin{array}{rcl} 
					B_{2t}+\beta t+\mathbf{c} & \mbox{for} & t\ge 0,\\
					\wt{B}_{-2t} +(2Q-\beta) t+\mathbf{c} & \mbox{for} & t<0.
				\end{array} 
				\right.
			\end{equation*}
			 Let $h$ be a free boundary  GFF on $\mathbb{H}$ independent of $(Y_t)_{t\in\bbR}$ with projection onto $H_2(\mathbb{H})$ given by $h_2$. Consider the random distribution
			\begin{equation*}
				\psi(\cdot)=Y_{-\log|\cdot|} + h_2(\cdot) \, .
		\end{equation*}
		Let the infinite measure $\mathcal{M}_{2}^{\mathrm{disk}}(W)$ be the law of $({\mathbb{H}}, \psi,0,\infty)/\mathord\sim_\gamma $. 
		We call a sample from $\mathcal{M}_{2}^{\textup{disk}}(W)$ a \emph{quantum disk} of weight $W$ with two marked points.

		We call $\nu_\psi((-\infty,0))$ and $\nu_\psi((0,\infty))$ the left and right{, respectively,} quantum   {boundary} length of the quantum disk  $(\mathbb{H}, \psi, 0, \infty)/{\sim_\gamma}$.

[Theorem 7 of arXiv:2606.31528, 'Well-posedness and stationary distribution of free stochastic differential equations'] Suppose that the free SDE \eqref{eq:fSDE} admits weak uniqueness, and for any free Brownian motion $\{W_t\}_{t \geq 0}$ and initial value $U_0 \in \mathscr{A}_{sa}$ that is free from $\{W_t\}_{t\geq 0},$ there exists a unique strong solution $\{U_t\}_{t\ge 0}$ to \eqref{eq:fSDE} such that $U_t \in \mathscr{A}_{\le t}$ and $\sup_{t\geq 0} \|U_t\|< \infty$. Assume further that Assumption \hyperlink{assumption:ass3}{(B-1)} holds. If 
\begin{equation}
L'_\alpha < -\frac{1}{2}(\sum_{i=1}^{l} (L_{\beta^i} K_{\gamma^i}+ L_{\gamma^i} K_{\beta^i}))^2,
\end{equation}
then the solution $\{U_t\}_{t\ge 0}$ admits a unique stationary distribution $\mu$. Moreover, for any initial value, the distribution of $U_t$ converges to $\mu$ in $W_2$ as $t \to \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:FaceIntegralAsymptotic of arXiv:2609.01825, 'On everywhere locally soluble varieties \\ in families over toric bases'] Let $\vec\ell$ be of convergent type for the face $\cal F$ and assume that $\cal F$ is not contained in a coordinate hyperplane. Then there exists $\epsilon >0$ such that we have

\begin{align*}
\int_{\cal F(\log B)} \prod_{i=1}^s (t_i+1)^{\ell_i} d\mu = (\log B)^{d+\ell} \int_{\cal F} \prod_{i=1}^s t_i^{\ell_i} d\mu \left(1+O_\epsilon\!\left((\log B)^{-\epsilon}\right)\right).
\end{align*}

[Lemma lem:distinct-pair of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] If $L_w(\ell)\ge\tfrac12$, then
\begin{equation}
  s^{\times}(S)
  \le
  \frac{M_w+\binom{\ell}{2}}{2}
  -\frac{L_w(\ell)^2-L_w(\ell)}4.
\end{equation}

[Lemma Lem local asymp cut disks expect CR 1 8 of arXiv:2604.15146, 'Renormalised two-point functions of CLE$_4$ gaskets'] As $\max(\varepsilon_1,\varepsilon_2)\to 0$, we have that
\begin{multline*}
\mathbb{P}(E_{\varepsilon_1,\varepsilon_2}^{v,\rm{holes}})
