body:
[Proposition eq:cf_tempered of arXiv:2412.06374, 'Stable and tempered stable distributions and processes: an overview toward trajectory simu'] Let $(X_t)_{t\in \mathbb{R}}$ be a CTS Lévy process with Lévy triplet $\left(b_\nu, 0,\nu\right)$ where $\nu$ defined as in (equation eq:levy_measure_tempered_stable of the paper) and $b_\nu=\int_{|x|>1}x \nu(dx)$. For $t\in \mathbb{R}_+$, the characteristic function exponent can be expressed for $u\in \mathbb{R}$ as 
\begin{align}
\log(\phi_{X_t}(u))= \begin{cases} 
tP\Gamma(-\alpha)\left((A-iu)^\alpha - A^\alpha + iu\alpha A^{\alpha-1} \right) + tQ\Gamma(-\alpha)\left((B+iu)^\alpha - B^\alpha + iu\alpha B^{\alpha-1}  \right) & \alpha \neq 1,\\
iut(P-Q) + tP(A-iu)\log\left(1-\frac{iu}{A}\right) + tQ(B-iu)\log\left(1-\frac{iu}{B}\right)& \alpha = 1.
\end{cases}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:covreperror of arXiv:2411.16366, 'Connections between sequential Bayesian inference and evolutionary dynamics'] Assume the system properties described by (equation eq:realhidden of the paper) for the true hidden state, (equation eq:asshidden of the paper) for the assumed hidden state and (equation eq:obs of the paper) for the observation model.  Given $r,s$ such that $r <s, r >0$, we have the following evolution equations for the  error covariance $P_t$ and expected squared error $\tilde{P}_t$,
\begin{align}

	\frac{dP_t}{dt} &= (G -(r-s)K_tH) P_t  + P_t (G -(r-s)K_tH)^\top  + \Sigma   + (r-s)^2 K_t \Xi K_t^\top   \\

	\frac{d\tilde{P}_t}{dt} &= (G -(r-s)K_tH)\tilde{P}_t  + \tilde{P}_t(G -(r-s)K_tH)^\top  + \Sigma  + (r-s)^2 K_t \Xi K_t^\top   - \mathbb{E}[\varepsilon_t]b^\top  - b \mathbb{E}[\varepsilon_t^\top]  
\end{align}
where $K_t$ is the continuous time Kalman gain matrix as defined in (equation eq:kalmangain of the paper).  For the special case $s=0,r=1$, it holds that $P_t = C_t, \enskip \forall \enskip t > 0$ if $P_0 = C_0$ where $C_t$ is the solution of the covariance equation of the replicator-mutator.\\
\\
Furthermore, for any p.d. $C_0$,  the evolution of the mean squared error $E_t$ satisfies the following inequality 
\begin{align}


	\frac{dE_t}{dt} \leq \alpha(A_t(r,s) + A_t(r,s)^\top)E_t - 2\text{Tr}[\mathbb{E}[\varepsilon_t]b^\top] + \text{Tr}[\Sigma] + (r-s)^2 \alpha(H^\top \Xi^{-1}H) \|C_t\|_F
\end{align}
where $A_t$ is defined in (equation eq:defnAt of the paper) and $\alpha(A)$ denotes the largest eigenvalue of $A$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition th:lin_FP of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] Let $s\in [0,T)$, $\nu\in\mathcal{P}(\mathbb{R}^d)$ and let ${\boldsymbol\mu}:[s,T)\to \mathcal{M}_{+}(\mathbb{R}^d)$ (continuous, with ${\boldsymbol\mu}_{s} = \nu$) be such that
\begin{equation}
b,\sigma \in L^{1}_{\text{loc}}([s,T) \times \mathbb{R}^d , \overline{\boldsymbol\mu}),
\end{equation}

with $\overline{\boldsymbol\mu}$ as in Notation (not:measure_dt_dx of the paper).

Then:

\begin{itemize}
\item[(i)] If $X$ is a solution to SDE$(b,\sigma;s,\nu)$, with $[X_t]={\boldsymbol\mu}_t $ for $t\in [s,T)$, then ${\boldsymbol\mu}$ is a weak solution to FP$(b,\sigma;s,\nu)$.
\item[(ii)] [Superposition] Under the additional assumption that 
\begin{equation}
\Big[ t \mapsto \int_{\mathbb{R}^d} \Big( |b(t,x)| + \| \sigma\sigma^\top(t,x) \| \Big) {\boldsymbol\mu}_t (d x)\Big], \  \big[ t \mapsto {\boldsymbol\mu}_{t} (\mathbb{R}^d) \big]  \in L^{\infty}_{\text{loc}}([s,T) ,
\end{equation}

if ${\boldsymbol\mu}$ is a (weak) solution to FP$(b,\sigma;s,\nu)$, 
 then there exists a solution $X$ to SDE$(b,\sigma;s,\nu)$ such that $ [X_t] = {\boldsymbol\mu}_t $.

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $p\geq 2$ and let $(X_N = I_p(f_N), N\geq 1)$ with $f_N\in H^{\odot p}$ 
	for all $N\geq 1$. Assume \eqref{c1}. Then, for every $Y\in L^2(\Omega)$,
	\begin{equation*}
		(X_N, Y) \xrightarrow[N\to\infty]{(d)} (Z, Y),
	\end{equation*}
	where $Z\sim N(0,\sigma^2)$ and $Z$, $Y$ are independent. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 68 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Let $z \in \mathfrak{L}_q$ be any point in the liquid region with
$\mathfrak{d}_{z} = \mathfrak{d}_{w_0}=\md$ and $\ell_z = \ell_{w_0}$. In the case $\md=\bd$, assume furthermore that
\begin{equation}

\omega \le  (\mathfrak{d}_{w_0} \mathfrak{e}_{w_0; q})^{-1/2}.
          \end{equation}
Then, if $L$ in \Cref{yy} is large enough, $z \in \mathcal{Y}^-$.

[Lemma le:neg_mom_1 of arXiv:2608.30382, 'Convergence rates for the RMSprop optimizer with full control of the hyperparameters'] Let $c,q,\rho\in(0,\infty)$, $p\in[1,\infty)$, $\beta \in (0, 1) $, $ n, n_0 \in {\mathbb N} $ satisfy
\begin{align}\begin{split} 
q+p\ln\beta\ge \rho
 \end{split}\end{align}
and $n> n_0$. 
Let $V_n^*$ be a non-negative random variable which satisfies for all $ \lambda \in [0,\infty) $ that
\bas{
  - \ln \mathbb{E}\bigl[ e^{-\lambda V_n^*} \bigr]
  \ge \sum_{k=n_0+1}^n \left( c \frac{1-\beta}{1-\beta^n} \beta^{n-k} \lambda \right) \wedge q + c \frac{1-\beta^{n_0}}{1-\beta^n} \beta^{n-n_0} \lambda.
}
Then \bas{
{\mathbb E}[(V_n^*)^{-p}]&\le \frac1{c^p} D_{\rho,p},
}
where
\bas{

  D_{\rho,p}:=\sum_{r=0}^\infty (r+1)^p e^{-\rho r}<\infty.
}

