[Corollary cor:bernstein_current_1 of arXiv:2609.01581, 'Concentration of additive functionals of Stratonovich-type'] Under the assumptions of Theorem~(thm:explicit_current_1 of the paper), for all $t>0$ and
$a>0$,
\begin{align}
  \mathbb{P}^\nu\left(\overline{J}_t(U) - \E^\mu[\overline{J}_t] \geq a\right)
  \leq
  \left\|\frac{\mathrm{d}\nu}{\mathrm{d}\mu}\right\|_{L^2(\mu)}
  \exp\left(-\frac{ta^2}{2\bigl(\tilde\sigma_{J,1}^2 + c_{J,1}a\bigr)}\right).

\end{align}

[Corollary A025 of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] Let $\kappa \in (8/3, 4)$ and $\beta \in [-1, 1]$. Let $\rho^\prime$, $\rho_\BR$, and $\rho_\rL$ be as in~(A021 of the paper) such that $\beta = \beta(\kappa^\prime, \rho^\prime)$. Consider the following algorithm:
	\begin{itemize}
		\item One samples a $\cwBCLE_{\kappa^\prime}(\rho^\prime)$ in $\BH$. Then, inside each connected component of each true (resp.\ false) loop of this $\cwBCLE_{\kappa^\prime}(\rho^\prime)$, one samples an independent $\ccwBCLE_\kappa(\rho_\BR)$ (resp.\ $\cwBCLE_\kappa(\rho_\rL)$).
		\item Inside each (both true and false) loop of the $\ccwBCLE_\kappa(\rho_\BR)$'s and $\cwBCLE_\kappa(\rho_\rL)$'s of the previous step, one samples an independent $\cwBCLE_{\kappa^\prime}(\rho^\prime)$. Then, inside each connected component of each true (resp.\ false) loop of these $\cwBCLE_{\kappa^\prime}(\rho^\prime)$'s, one samples an independent $\ccwBCLE_\kappa(\rho_\BR)$ (resp.\ $\cwBCLE_\kappa(\rho_\rL)$). Then, we iterate this step.
	\end{itemize}
	Then the collection of all the true loops of all the simple BCLEs has the law of a nested $\CLE_\kappa^\beta$ in $\BH$.

[Lemma lem:Lem45 of arXiv:2411.07157, 'Rough differential equations in the flow approach'] Pick $\varsigma\in(0,1)$ satisfying\footnote{Note the $4$ appearing below stems from (equation eq:fix_kernel of the paper).}  
\begin{equs}
    (2/\varsigma-1)^4\leqslant2\,. 
\end{equs}
Then, there exists $\tilde{T} = \tilde{T}_{\Xi} \in(0,1]$, such that, for any $T \in (0,\tilde{T}]$, $\eta > 0$,  $p\in\N$, and $\eps \in (0,1]$, 
    \begin{equs}
         \norm{K_{\varsigma^pT}\big( F_{\eps,T}[0]+R_{\eps,T}\big)}_{L^\infty_{0;T}}\leqslant 2 C_F(\varsigma^pT)^{-1+H-\eta}\mathcal{G}_{\tt u}(1)\,,
    \end{equs}
where $C_F$ is as per Corollary~(coro:1 of the paper). Consequently, by interpolation, we have that 
\begin{equs}
     \norm{K_{\mu}\big( F_{\eps,T}[0]+R_{\eps,T}\big)}_{L^\infty_{0;T}}\lesssim C_F \mathcal{G}_{\tt u}(1)\mu^{-1+H-\eta}
\end{equs}
uniformly in $\mu\in(0,1]$.

