[Lemma lem:error 1 part of arXiv:2412.06452, 'Time-dependent queue length distribution in queues fed by $K$ customers in a finite interv'] \red{
Suppose that for a given $\epsilon_0 \in (0,1]$,
the truncation points $M_n$ ($n=1,2,\ldots,N$) are chosen such that

\begin{align}
\sum_{m=0}^{M_n-K}
\mathrm{Poi}\bigl(\theta_n(T_n-T_{n-1}),m\bigr)
> 1-\epsilon_0,
\quad 
n = 1,2,\ldots,N.

\end{align}

We then have}

\begin{align}
&
(1-\epsilon_0)^n \Pr[\widehat{A}(t)=k] 
< 
\hat{p}_k^{\mathrm{trunc}}(t) 
\leq
\Pr[\widehat{A}(t)=k],
\nonumber
\\
&\hspace{10em}
k=0,1,\ldots,K,\ t \in (T_{n-1},T_n],\ n=1,2,\ldots,N.

\end{align}

[Lemma 11 of arXiv:2606.01742, 'Large deviation principles for SPDEs with locally Lipschitz coefficients'] Assume that Hypotheses \ref{cond-initial}, \ref{cond-dif}  and  \ref{3} hold. If $L_\sigma>0$, then
\begin{align}
\sup_{N>0}\sup_{x\in \R}\E\left[\left|u_N^{ \varepsilon,h_ \varepsilon}(t,x)\right|^k\right]\leq 4^k\left(\|u_0\|_{L^\infty(\R)}+1\right)^ke^{8(2\sqrt{k\varepsilon}L_{\sigma}+ML_{\sigma})^4kt}
\end{align}
uniformly for all $t>0$, $\e>0$, $k\geq 2$ and for every $M\geq L_b^{1/4}L_{\sigma}^{-1}$.

