[Theorem 5 (Kac, Pleijel) of arXiv:2507.06186, '2507.06186'] If $\partial D$ is sufficiently regular (e.g., smooth), then
\begin{align}

\msf T_0(t)=\tfrac{\msf{A}(D)}{2\pi}t^{-1}
-\tfrac{\msf{L}(\partial D)}{4\sqrt{2\pi}}t^{-1/2}+O(1)\qquad\text{as }t\to0,
\end{align}
where $\msf L(\partial D)$ is the length of the curve
$\partial D$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2608.31008, 'Stability of gravitational instantons with a bounded Killing vector field'] Assume the geometric hypotheses of \cref{thm:intro-bounded} and
normalize $K$ as above.  For every $0<\varepsilon<\tfrac12$ there is
a solution of
\begin{equation}
 \Delta u=V+2, \text{ with}
\end{equation}
\begin{equation}
 u=-\tfrac{r^2}{2}+w,\qquad
 |\nabla_b^jw|=\mathcal{O}(r^{1+\varepsilon-j}),
\end{equation}
and the tensor $k_K$ of \eqref{eq:k-def} satisfies
\begin{equation}
 |\nabla^jk_K|=\mathcal{O}(r^{-1+\varepsilon-j}),\qquad j=0,1,2.
\end{equation}
In particular, it satisfies the decay assumptions for dynamical destabilizations of ALF metrics from \cite[Definition 5.1]{KO}.

[Lem Wiener:caterpillar of arXiv:2606.09228, 'On topological indices of random caterpillar graphs'] In the case of a caterpillar, we have
    \begin{align*}
    \begin{split}
        W_n=&\sum_{i<j} (j-i+2)I_i^{(n)}I_j^{(n)}+\sum_{i,j=1}^m (\vert j-i\vert+1)I_j^{(n)}\\
        &+\sum_{i=1}^m I_i^{(n)}(I_i^{(n)}-1)+\frac{(m-1)m(m+1)}{6}.
    \end{split}
    \end{align*}

[Theorem 9 (Hard Edge) of arXiv:2511.12623, 'The eigenvector bead process'] We recall Convention~\ref{conv:inverse-stieltjes-branches}, and use the same convention for the inverse branches of the Stieltjes transform appearing below. 
Let $\alpha = T - N \ge 0$ denote the rectangularity parameter of the Wishart ensemble.
For $u, v \in \mathbb{N}$, the overlaps satisfy
\begin{equation}
\Omega^{(N)}_{u,v}
\;\mathrel{\underset{N \to \infty}{\overset{d}{\sim}}}\;
\frac{g_v \, \sqrt{\xi_v}}{\,D_{g^2, \xi, \alpha}^{-1}(0)_u - \xi_v\,}
\left(
    \sum_{v' \in \mathbb{N}} 
    \frac{(g_{v'})^2\xi_{v'}}{\bigl(D_{g^2, \xi, \alpha}^{-1}(0)_u - \xi_{v'}\bigr)^2}
\right)^{-1/2}.
\end{equation}

\noindent
Here $(\xi_u)_{u \in \mathbb{N}}$ follow the Bessel point process associated with the parameter $\alpha$, 
and $(g_u)_{u \in \mathbb{N}}$ are i.i.d.~standard Gaussian random variables 
$\mathcal{N}(0,1)$, independent of $(\xi_u)$.

\medskip
\noindent
The function $D_{g^2, \xi, \alpha}(z)$ is defined by
\begin{equation}
D_{g^2, \xi, \alpha}(z)
= \sum_{i \in \mathbb{N}} \frac{g_i^2}{ \xi_i-z}
- \frac{\chi_{\alpha}}{z},
\end{equation}
where $\chi_{\alpha}$ denotes a chi-square random variable with $\alpha$ degrees of freedom. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary eq:zero-rate-localized-complement of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[corollary]{cor:nonnegative-bulk}
\leavevmode\par\noindent
In the setting of (thm:conditional-transfer of the paper), suppose that both
de-regularization defects vanish and \(\Phi\ge0\).  If
\begin{equation}
 \overline\Lambda_L^J(V)\le0,
\end{equation}
then the full exact-complexity limit exists and equals \(\Phi\).

[Conjecture conj:perc of arXiv:2412.05503, 'Critical scaling profile for trees and connected subgraphs \\ on the complete graph'] For $s\in \mathbb{R}$, let
\begin{equation}

f_{\rm perc}(s) = \int_0^\infty x^2 \mathrm d\sigma_s, \qquad
\mathrm d \sigma_s =
	\frac 1 { \sqrt{2\pi} } x^{-5/2} \Psi(x^{3/2})
    e^{-\frac 1 6 x^3 + \frac s 2 x^2 - \frac{ s^2} 2 x}
    \mathrm dx
    .
\end{equation}
Then, for some $a,b>0$, as $V\to\infty$ we have
\begin{equation} 
\begin{aligned}
    \tau_{V,01}(1+sV^{-1/3}) & \sim b V^{-2/3} f_{\rm perc}(as),
    \\
    \chi_{V} ^{\rm {perc}}(1+sV^{-1/3}) & \sim b V^{1/3} f_{\rm perc}(as).
\end{aligned}
\end{equation} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Corollary cor:bc-fidelity of arXiv:2608.01253, 'The pseudo-quantum representation of \\finite reversible Markov chains'] For all $t_1,t_2\ge0$,

\begin{equation}
\mathrm{BC}(\pi_{t_1},\pi_{t_2})=\braket{\sqrt{\pi_{t_1}}}{\sqrt{\pi_{t_2}}}
=\braket{\psi_{\theta(t_1)}}{\psi_{\theta(t_2)}}
=\cos^{n}\!\Bigl(\tfrac{\theta(t_2)-\theta(t_1)}2\Bigr).

\end{equation}

The Bhattacharyya overlap of the laws at two times equals the fidelity
overlap of the corresponding register states, and it depends only on the
clock increment.

[Lemma Feller's lemma of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] Let $X_t,X$ be a family of $[0,\infty]$-valued random variables such that $\mathbb{P}\left(X <\infty\right) = 1$. Assume that for all $\rho>0$,
    \begin{equation}
        \mathbb{E}[e^{-\rho X_t}] \longrightarrow \mathbb{E}[e^{-\rho X}] \quad \text{as} \quad t\to\infty.
    \end{equation}
    Then, 
    \begin{equation}
        \mathbb{P}\left(X_{t} = +\infty\right) \to 0 \quad \text{as} \quad t\to\infty,
    \end{equation} 
    and conditioned on the event $\{X_{t}<\infty \}$, $X_{t}$ converges weakly to $X$. In particular, for all $x \in [0,\infty)$ which is a point of continuity for  $\mathbb{P}(X\leq x)$, $\mathbb{P}\left(X_{t}\le x\right) \to \mathbb{P}\left(X\le x\right)$ as $t\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

For a finite system of $N$ particles with states $(\bm{X}_i)_{i \in [N]}$ and weights $(\bm{W}_{i, j})_{i, j \in [N]}$, its empirical structure $\bm{\mathcal{Y}}_N = (\mathsf{X}_N, \mathsf{W}_N)$ is represented on $\Omega = [0, 1]$ equipped with Lebesgue measure by partitioning $[0, 1]$ into $N$ equal intervals $I_i = [\frac{i-1}{N}, \frac{i}{N})$ and setting $\mathsf{X}_N(\xi) = \sum_{i=1}^N \bm{X}_i \mathbf{1}_{I_i}(\xi)$ and $\mathsf{W}_N(\xi, \zeta) = \sum_{i, j = 1}^N \bm{W}_{i, j} \mathbf{1}_{I_i \times I_j}(\xi, \zeta)$.
N \in \mathbb{N}
I_i are equipartition intervals of [0, 1]

[Lemma 11 (Caccioppoli inequality) of arXiv:2608.26834, 'Small-time annealed large deviations principle for one-dimensional diffusions in a random '] Let $u\ge0$ be a bounded weak sub-solution to equation~\eqref{02} on $(s_1,s_2)\times I$, where $I$ is a bounded interval. Let $p\ge2$, $\zeta\in C_c^1(I)$, and $\chi\in C_c^1((s_1,s_2))$ satisfy $0\le\zeta,\chi\le1$. Then
		\begin{align}
			&\operatorname*{ess\,sup}_{s\in[s_1,s_2]}
			\chi(s)^2\int_I\zeta^2u(s)^p\,\dd\mu_W
			+\int_{s_1}^{s_2}\!\chi^2\int_I\zeta^2
			\left|\partial_y(u^{p/2})\right|^2e^{a}\,\dd y\,\dd s\\
			&\quad\le Cp^2\left(\|\chi'\|_{L^\infty(s_1,s_2)}+
			\left\|2e^{a-\rho}(\zeta')^2\right\|_{L^\infty(I)}\right)
			\int_{s_1}^{s_2}\!\int_{\operatorname{supp}\zeta}u^p\,\dd\mu_W\,\dd s.\nonumber
		\end{align}

