[Corollary 8 of arXiv:2608.09419, 'Left-tail expansions for Schr\"oder branching processes with explicit convergence rates'] \lb{C1}
 Under assumptions of Theorem \ref{T1}, suppose also that 
\[\lb{c001}
 1-\{re^{i\vp}:\ \vp\in(-\vp_0,\vp_0),\ r\in(0,r_0)\}\ss\mJ_P(0).
\]
Then $\Pi(z)$ can be analytically extended to the sector $S_{\vp_0}:=\{z:\ |\arg z|<\vp_0\}$. The image of this sector satisfies $\Pi(S_{\vp_0})\ss\mJ_P(0)\cup\{1\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop CM UT LB of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] There exists a deterministic constant $c_3 \in (0,\infty)$ such that, 
  for any $x_0 \in M$, $r \in (0, 1 \wedge r_*)$, and $n, N \in \mathbb{N}$ with $4n \leq N$ and $c_1 Nr^{d^{\mathrm{min}}_\mathrm{w}} < 1 \wedge t_*$,
  \begin{equation}
    \inf_{\bm{x} \in \hat{B}_*(x_0, r)}
    \hat{P}_{\bm{x}}\!\left(\Pi_{c_1 N r^{d^{\mathrm{min}}_\mathrm{w}}}(B(x_0,r)) \geq c_3 n r^{d_{\mathrm{cp}}}\right) 
    \geq 
    \tilde{c}_1 e^{-\tilde{c}_2 n},
    \qquad 
    \text{if}\quad \hat{d}_{\mathrm{s}} > 2,
  \end{equation}
  and 
  \begin{equation}
    \inf_{\bm{x} \in \hat{B}_*(x_0, r)}
    \hat{P}_{\bm{x}}\!\left(\Pi_{c_1 N r^{d^{\mathrm{min}}_\mathrm{w}}}(B(x_0,r)) \geq c_3 n r^{d_{\mathrm{f}}} \log (N/n)\right) 
    \geq 
    \tilde{c}_1 e^{-\tilde{c}_2 n},
    \qquad 
    \text{if}\quad \hat{d}_{\mathrm{s}} = 2.
  \end{equation}

[Lemma lem:boundaryboxes of arXiv:2609.01825, 'On everywhere locally soluble varieties \\ in families over toric bases'] Let $\vec W = (\log (B/X_1), \dots, \log (B/X_k))$ as in the previous lemma, $\vec U_{\!\pm}$ be defined as in (lem:decomposition into boxes of the paper), and $1< \theta \leq 2$. Let $\gamma > \max_{1\leq l\leq k} \sum_{i=1}^s \frac{\varpi_{li}}{\alpha_i}$. Then
	\begin{multline*}
		\sum_{\substack{\vec j \in \cal P(\vec U_{\!+}) \\ \vec j \notin \cal P(\vec U_{\!-})}} \sum_{\vec x \in \cal B_{\vec j}} |f(\vec x)| \ll
		C_f \int_{\Xi} \prod_{i=1}^s \mathrm e^{t_i} (1 + t_i)^{\ell_i} \,\mathrm d\vec t\\
