[Lemma 17 (consistency: one-step weighted defect) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] \label[lemma]{lem:boundary-charge}
  Assume $G'\in C^2_{\mathrm b}([0,\infty))$ and $\delta \in (1,2)$.  There exist $C_{\mathrm b}<\infty$ and $h_0>0$ such that, for all $h\in(0,h_0]$, the one-step defect of the clamped kernel \eqref{eq:clamped-kernel} satisfies
  \begin{equation}
    \|\nu_h\|_{V}=|\nu_h(\{0\})|+\int_0^\infty(1+x^2)|r(x)|\,dx\le C_{\mathrm b}\,h^{\delta}.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma dir_E[multi_edges]_asymp of arXiv:2604.05921, 'Simplicity of random hypergraphs'] If $\forall e \in E: \delta_e^{\textnormal{tail}} = \delta^{\textnormal{tail}}\in O(1)$ and $\delta_e^{\textnormal{head}} = \delta^{\textnormal{head}}\in O(1)$ and
\begin{enumerate}
    \item $\mathds{E}[(d_U^{\textnormal{out}})^{2\delta^{\textnormal{tail}}}], \mathds{E}[(d_U^{\textnormal{in}})^{2\delta^{\textnormal{head}}}] \in o(n)$
    \item $\exists c>0: \mathds{P}(d_U^{\textnormal{out}} \geq 2\delta^{\textnormal{tail}}),\mathds{P}(d_U^{\textnormal{in}} \geq 2\delta^{\textnormal{head}}) \geq c$ 
\end{enumerate}
then
\begin{align*}
    \mathds{E}[M_n] &= \frac{(\delta^{\textnormal{tail}}-1)!(\delta^{\textnormal{head}}-1)!}{2} n^2 \mathds{E}[d_U^{\textnormal{out}}] \mathds{E}[d_U^{\textnormal{in}}] \\
    &\hspace{0.5cm} \times \Big( \frac{\mathds{E}[(d_U^{\textnormal{out}})^2] - \mathds{E}[d_U^{\textnormal{out}}]}{n \mathds{E}[d_U^{\textnormal{out}}]^2} \Big)^{\delta^{\textnormal{tail}}} \Big(  \frac{\mathds{E}[(d_U^{\textnormal{in}})^2] - \mathds{E}[d_U^{\textnormal{in}}]}{n \mathds{E}[d_U^{\textnormal{in}}]^2} \Big)^{\delta^{\textnormal{head}}} (1+o(1)).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma thm:u=F of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] For all integers $n_j\ge 1, j=1,\ldots,s$, we have    
\begin{equation}
    \kappa_X\big(n_1,\cdots,n_s\big)=\sum_{\Gamma\in \mathscr{D}_{s;\beta}^*} F_{\Gamma}(\{n_j\}_{j=1}^s).
\end{equation}

[Theorem TheoremCanoncialSpace of arXiv:2411.12522, 'Canonical insurance models: stochastic equations and comparison theorems'] There exist unique $\mathcal{F}_{s-}$-measurable  probability kernels $\mathbb{P}_{s}^i$, $s \in [0,\infty)$, $i\in\mathcal{Z}$,  on $(\Omega, \mathcal{F}_{\infty})$   such that 
\begin{enumerate}
    \item[(i)]  For $s \in [0,\infty)$, $\omega \in \Omega$  and $i,j \in \mathcal{Z}$ with $j \neq i$, it holds that
\begin{align*}
 \Lambda^{ij}(\mathrm{d} t)(\omega) = \frac{\mathbb{E}_s^i[\mathds{1}_{\{\tau(s) \geq t\}} N^{ij}(\mathrm{d} t )](\omega)}{\mathbb{E}_s^i[\mathds{1}_{\{\tau(s) \geq t\}}](\omega)} 
\end{align*}
for those $t \in (s,\infty)$ such that neither $Z(\cdot )(\omega)$ has a jump in $(s,t)$ nor $\Lambda^{i \raisebox{-0.25ex}{\scalebox{1.4}{$\cdot$}}}(\cdot)(\omega)$ has a pole or a jump of size $+1$ in $(s,t{]}$. 
\end{enumerate}
    Further, there exists a unique probability measure $\mathbb{P}$ on $(\Omega, \mathcal{F}_{\infty})$ such that
    \begin{enumerate}
\item[(ii)] Equation~(equation DefOfProbKernel of the paper) holds almost surely for $A \in \mathcal{F}_{\infty}$, $s \in [0,\infty)$,
	\item[(iii)] {f}or  $i \in \mathcal{Z}$, it holds that  
   \begin{align*}
   	 \alpha(i) =\mathbb{P}[Z(0) = i  ].
   \end{align*}
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:on-bank-truth-validity of arXiv:2608.20295, 'Physical-Support Confidence Sets for Highly Coherent Dictionaries'] Suppose the reported truth-level assertion $\widehat g$ is emitted only when
its predicate satisfies Equation~(equation eq:universal-truth-predicate of the paper), and
suppose the data-generating explanation $e_\star$ belongs to the bank.
Under Equation~(equation eq:on-bank-truth-retention of the paper),
\begin{equation}
    \sup_{e_\star\in\mathcal B}
    \mathbb P_{e_\star}
    \left\{
        \widehat g
        \text{ is reported and }
        q_{\widehat g}(e_\star)=0
    \right\}
    \le
    \alpha_{\mathcal B}.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition thm_rel_en_bound of arXiv:2603.26307, '\LARGE The incompressible Navier--Stokes--Fourier system with thermal noise'] Under the assumptions of Theorem (thm_WS_main of the paper), we have, $\mathbb{P}$-a.s.,
	\begin{equation}
		\mathcal{E}( u_t,\psi^+_t | V_t,\Phi_t ) \,\le\, \exp \Bigl( \bigl( 2 \| \nabla_\mathrm{sym} V \|_{C([0,t]\times \mathbb{T}^3; \mathbb{R}^{3\times 3})} \,+\,   \| \nabla \Phi \|_{C([0,t]\times \mathbb{T}^3; \mathbb{R}^{3})}  \bigr)\cdot  t \Bigr) \mathcal{E}( u_0,\psi_0 | V_0,\Phi_0 ),
	\end{equation}
	for $t\in [0,T\wedge \tau)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:group-exponent-dichotomy of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] Let $G$ be an abelian group and fix $k\geq4$.
\begin{enumerate}[label=\textup{(\roman*)}]
\item If $G$ has unbounded exponent, then
\begin{equation}
 |\mathcal R_G(h,k)|=h^{k-1+o_k(1)}
 \qquad(h\to\infty).
\end{equation}
\item If $mG=0$ for some positive integer $m$, then
\begin{equation}
 |\mathcal R_G(h,k)|\leq m^{k-1}
 \qquad(h\geq1).
\end{equation}
\end{enumerate}
 Consequently, when $|G|\geq k$, the spectrum sizes are bounded in $h$ if
 and only if $G$ has bounded exponent.  The bounded-exponent case has
 logarithmic growth exponent $0$, while the unbounded-exponent case has
 exponent $k-1$.

