[Cor corollary:exitPx of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] For every  non-negative measurable functions $F,G$ on $\mathbb{D}(\mathbb{R}_+, \mathcal{M}_f(\mathbb{R}_+)\times \mathcal{W}_{\overline{E}}) \times \mathbb{R}$ and $\mathbb{D}(\mathbb{R}_+, \mathcal{M}_f(\mathbb{R}_+)\times \mathcal{W}_{\overline{E}})$ we have 
\begin{equation}
    \mathbb{E}_{0,x,0}\Big[   \sum_{u \in \mathcal{D}} F\big( \,  \emph{\texttt{T}}_u (\rho,\overline{W}), \mathfrak{g}(u) \big) G(\rho^u , \overline{W}^u) \Big]  = 
    \mathbb{E}_{0,x,0}\Big[ \int_0^\infty \mathrm{d} A_s  ~F(\rho,\overline{W}, s ) \mathbf{N}_{x, \widehat{\Lambda}_s}\big(G(\rho,\overline{W})\big)\Big].
\end{equation}

[Proposition prop:moments of arXiv:2608.23742, 'Second-order fusion asymptotics for $\Sine_\beta$ correlation functions'] Let $m\ge2$, $\beta>0$, $m\beta>1$, and put $\delta=m\beta/2$. Then
\begin{align}
\mathbb E S_1^2&=\frac{1}{4(m\beta-1)(2m+1)},\\
\mathbb E S_2&=\frac{m\beta}{4(m\beta-1)(2m+1)}.
\end{align}
Moreover,
\begin{equation}
\mathbb E\xi''(0)=-(2\delta-1)\mathbb E\xi'(0)^2.
\end{equation}

[Lemma 22 of arXiv:2605.30560, 'Projected McKean--Vlasov Dynamics for Entropic Weak Optimal Transport'] Let $\mu\in \Pc_{1+\varepsilon}(\Xc)$ for some $\varepsilon>0$.
Then, for all $0\le \varepsilon'<\varepsilon$,
\[
\lim_{\delta\to0}
\sup_{\substack{
\gamma\in\Pi(\mu,\mu)\\
\E^\gamma[d_\Xc(X,X')]\le\delta
}}
\E^\gamma\big[d_\Xc(X,X')^{1 + \varepsilon'} \big]
=0.
\]

[Lemma 55 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] Fix \(K<\infty\) and \(\kappa\in(0,H)\).  There is
\(C_{K,\kappa}<\infty\) with the following property.  For parameters
\(h,u,L\) satisfying \eqref{eq:block-repulsion-component-range}, under
\(\widehat Q_{h,u,L}\), and for every dyadic \(r=2^j\geq2\) whose
displayed interval is nonempty,
\begin{equation}
\begin{split}
  &\widehat Q_{h,u,L}\left(
    \inf_{r\leq s\leq\min(2r,L)}G_s<r^{H-\kappa}
  \right)\\
  &\qquad\leq
  C_{K,\kappa}\left[
    r^{-\kappa}
    +(1+\sqrt{\log r})r^{-(H-\kappa)}
  \right].
\end{split}

\end{equation}

