[Corollary cor:local_hajek_norho of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Define
\begin{equation}
    \widehat{\mathsf{N}}_G^v(x) \coloneqq \mathsf{N}_G^v(x) - 2 \mathsf{e} p^{\mathsf{e}-1} n^{\mathsf{v}-2} \mathsf{deg}_v(x).
\end{equation}
Then for all $\zeta \in (0,\frac{3}{4})$, there is some $c > 0$ such that
\begin{equation}
    \mathbb{P} \mleft[
        \mleft|
            \widehat{\mathsf{N}}_G^v(X) - \mathbb{E}\mleft[\widehat{\mathsf{N}}_G^v(X)\mright]
        \mright| > n^{\mathsf{v}-1.75+\zeta}
    \mright] \leq \Exp{-c n^{\frac{4}{3}\zeta}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 28 of arXiv:2606.21111, 'On Elephant Random Walk with Delayed Amnesia'] Let $0\le p<(4a-1)/4a$ and $\{Z_n\}_{n\ge1}$ be uniformly bounded. Then,
\begin{equation}
\frac{W_n}{\sqrt{n}}\xrightarrow{d}\mathcal{N}\Big(0,\sigma^2+\frac{\mu^2K}{(2a(1-p)-1)^2}\Big),
\end{equation}
where $K$ is as given in \eqref{K}.

