[Theorem 25 of arXiv:2609.03070, 'Variants of order semicontinuity in Banach lattices'] The following conditions are equivalent:
\item[(i)] $F$ is monotonically bounded;
\item[(ii)] $F$ is $r$-monotonically bounded, for some $r\ge 1$;
\item[(iii)] Every directed dominable subset of $\Ba_{F_{+}}$ is order bounded.

[Definition 22 of arXiv:2607.18104, '2607.18104'] Let $(\omega_v)_{v \in \Z^2}$ be an $(N,k)$-periodic environment for some $N \in \N$ and with $k=k(N)\in \lbr N -1\rbr$. 
We define the \textbf{periodic last passage time} $\Tper_{u,v}$ between $u$ and $v$ as
\begin{equation}
\Tper_{u,v}:=  \sup_{i \in \Z} T_{u+i(N-k,-k),v} . 
\end{equation}

[Prop 8 of arXiv:2608.01419, 'A model of opinion dynamics evolving via a preferential attachment mechanism involving mul'] _unique_root_examples}
Recall $f$ and $g$ from \eqref{X_{n+1}_conditional_distribution} and \eqref{g_defn} respectively. The function $g$ is monotonically increasing, and the function $\hat{G}$, defined in \eqref{hat{G}_defn}, has a unique root in $[0,1]$, whenever
\begin{enumerate}

\item $f(x)=x$ for all $x\in[0,1]$, with $p\in(1/2,1)$ and
\begin{equation}
\alpha\geqslant\frac{(2p-1)}{4(1-p)},
\end{equation}
\item $f(x)=x$ for all $x\in[0,1]$, with $p\in(1/2,1)$, when \eqref{alpha_inequality} fails to hold but we have 
\begin{equation}
\text{either }\hat{G}\left(\frac{1}{2}-\frac{\sqrt{3}}{6}\sqrt{1-\frac{4\alpha(1-p)}{2p-1}}\right)>0 \text{ or } \hat{G}\left(\frac{1}{2}+\frac{\sqrt{3}}{6}\sqrt{1-\frac{4\alpha(1-p)}{2p-1}}\right)<0.}
\end{equation}
\item $f(x)=e^{x-1}$ for all $x\in[0,1]$, $p\in(1/2,1)$ and $\alpha>0.15218(2p-1)/(1-p)$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 36 of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] Given any~$\sigma\in(0,1/10)$, $a\ge0$ and with $\gamma_{n,a}$ as in \eqref{E:6.34ii}, for $k\le n$ let
\begin{equation}

G_{n,k}:=\bigl\{X_k\in[k^{\sigma},k^{1-\sigma}]\bigr\}\cap\bigcap_{j=k}^{n-k}\bigl\{X_j\ge\gamma_{n,a}(j)\bigr\},
\end{equation}
where~$X$ is related to~$h$ via \eqref{E:sub}. For each~$\epsilon>0$ and $\lambda>0$ there exist~$a\in\R$ and $k_0\ge1$ such that for all~$s\ge 1$ and all $u\le s$ with $s-u\le\lambda$,
\begin{equation}

Q_{n,s,u}(G_{n,k}^\cc)\le\epsilon\frac {1+u_+} n
\end{equation}
holds once $n^\sigma\ge k\ge k_0$ and $n^{1-\sigma}\ge s$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 7 of arXiv:2608.23462, '2608.23462'] Let $p \geq 2$ and $\beta > 0$. We say that the frozen variable $(\hat Y_t^x)_{t \ge 0}$ is (uniformly) $p$-dissipative (with constant $\beta$), if for all $x\in \R^{d_1}$ and $y_1,y_2 \in \R^{d_2}$
\begin{align*}
    \langle y_1 - y_2, g(x,y_1)-g(x,y_2) \rangle + \frac{p-1}{2} |\sigma(x,y_1)-\sigma(x,y_2)|_F^2 \leq -\beta|y_1-y_2|^2.
\end{align*}

[Lemma 4 of arXiv:2608.09419, 'Left-tail expansions for Schr\"oder branching processes with explicit convergence rates'] \lb{L1}
	Let $\mP_E$ be a set of polynomial probability generating functions with the expectation $P'(1)=E$. Denote $N=\lfloor E\rfloor$ the number which rounds $E$
	down to the nearest integer less than or equal to $E$. Then, the unique minimizer of the second derivative at $z=1$ is
	\[\lb{100}
	 {\rm argmin}_{P\in\mP_E}P''(1)=(N+1-E)z^N+(E-N)z^{N+1}.
	\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 26 of arXiv:2608.02103, '$p$-Adic Diffusion and Random Walks on $[0,1]$'] The entries of the average-transition-rate matrix $W_n^a$ attached to $(A_n,w)$ satisfy 
\begin{equation}

    w(x,y)=\lim_{n\rightarrow \infty} w_{I_n(x),J_n(y)}^{(n),a}
\end{equation}
\begin{comment}
\begin{equation}

    w(y|x)=\lim_{n\rightarrow \infty} w_{J_n(y),I_n(x)}^{(n),a}
\end{equation}
\end{comment}
almost everywhere.

[Theorem 8 of arXiv:2608.24675, 'Towards Liouville Quantum Gravity on fractals'] \begin{enumerate}[wide=0em,label={\rm (\roman*)},itemsep=.5em]
\item
 The sequence $\{h_{\ell}\}_{\ell\geq 1}$ converges both in $L^2(\Omega)$ and $\mathbb{P}$-a.s. to the FGFF $h$ on $K$. In particular,
 \begin{equation*}
    h\stackrel{d}{=}\sum_{k=1}^\infty\xi_{k}\lambda_{k}^{-\frac{d_S}{4}}\varphi_k
 \end{equation*}
and, $\mathbb{P}$-a.s., it holds that $h\in {H}^{-\varepsilon}(K)$ for any $\varepsilon>0$ and $h\notin L^2(K)$.
\item
    For every $u\in{H}^{-d_S/2}(K)$, the sequence $\{\langle h_{\ell},u\rangle\}_{\ell\geq 1}$ is a centered, $L^2$-bounded martingale with respect to the filtration $\{\mathcal F_\ell\}_{\ell\geq1}$, where
    \begin{equation*}
        \mathcal{F}_{\ell}:=\sigma(\{\xi_1,\ldots,\xi_{N_\ell}\}).
    \end{equation*}
    Moreover, the sequence converges in $L^2(\Omega)$ and $\mathbb{P}$-a.s. to a centered Gaussian random variable, denoted by $h\cdot u$. In particular, $\P$-a.s.
    \begin{equation*}
    h\cdot u=\sum_{k=1}^{\infty}\xi_{k}\lambda_{k}^{-\frac{d_S}{4}}\langle \varphi_k,u\rangle
    \end{equation*}
    and
    \begin{equation*}
        \E[(h\cdot u)^2]=\|u\|_{H^{-d_S/2}}^2.
    \end{equation*}

\end{enumerate}

