body:
[Thm resolvealeph of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] Suppose $\Phi$ is $\aleph$-unobstructed. With the previous notation, there exists $\varepsilon > 0$ such that
\begin{align} 
    U^\varepsilon_\flat \times U^\varepsilon_\sharp \times U^\varepsilon_- \times U^\varepsilon_+ \times \{(w_1, \dots, w_{k_\circ})\} \times \mathbb{R}^{k_\aleph} \subset \mathcal{Z}(\Phi).
\end{align}

[Mainthm 1 of arXiv:2609.02576, 'Sharp estimates for the Jacobi and trigonometric Dunkl heat kernels'] Let $k_1,k_2\geq 0$ be such that $k_1+k_2>0$. The $W$-invariant Opdam--Cherednik heat kernel satisfies the bound
	\begin{equation*}
		\hOC_t(x,y)\simeq t^{-1/2} e^{-\frac{(x-y)^2}{4t}} e^{-\rho^2 t} e^{-\rho(x+y)} (1+x)(1+y) \frac{(t+1+x+y+xy)^{k_1+k_2-1}}{(t+xy)^{k_1+k_2}},
	\end{equation*}
	uniformly in $t>0$ and $x,y>0$, where $\rho=k_1/2+k_2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 41 of arXiv:2607.18104, '2607.18104'] The function $(y,t) \mapsto \hfixp(\hfixp_0;y,t)$ in Definition~\ref{def:PeriodicKPZfixed} is (up to scaling the spatial coordinate) a periodic KPZ fixed point from Theorem ~\ref{thm:BaikPKPZ}  with initial data $\hfixp_0 \in \UCp$, i.e. 
\begin{equation}
      \hfixp\big(\hfixp_0;y,\tau\big) \overset{(d)}{=} \mathcal{H}^{\per}_2(\hfixpt_0;2y,\tau)
\end{equation}
jointly over $y\in \mathbb{T}$ and $\tau\geq 0$.
Here, we set $\hfixpt_0(x) := \hfixp_0(2x)$ for all $x\in \mathbb{T}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Phasethm t:2b of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Uniformly in $s \in \mathbb{R}$ on compacts, $(r_n, n-r_n)$-clustered sets ${\rm A} \subset {\rm D}^\circ_n$ and subsets ${\rm W} \subseteq {\rm D}$,
\begin{equation}

\bigg| \mathbb{P} \big( \widecheck{T}_{\rm A} \leq t_n^B + sn\,,\,\, \widecheck{X}_{\rm A} \in {\rm e}^{n} {\rm W} \big) -
	\exp \Big(-{\rm e}^{-(s-\log \frac{1}{\sqrt{n}} \|{\bf \Xi}_{{\rm A}, r_ n}\|)}\Big){\bf \Xi}^\circ_{{\rm A}, r_n}({\rm W}) \bigg| \underset{n \to \infty} \longrightarrow 0 \,.
\end{equation}
Moreover, for any fixed $s \in \mathbb{R}$, if $n$ is large enough, then, uniformly in all ${\rm A} \subset {\rm D}_n$ (not necessarily clustered),
\begin{equation}

\mathbb{P} \big( \widecheck{T}_{{\rm A}} > t_n^{B} + sn \big) \leq 2 {\rm e}^{-s}\frac{|{\rm A}|}{\sqrt{n}} \,.
\end{equation}
Lastly, for any fixed $s \in \mathbb{R}$,
\begin{equation}
	\frac{{\mathbf T}_{n,t_n^B+sn}/|{\rm D}_n| - (t_n^B+s n)}{n} \overset{\mathbb{P}}{\underset{n \to \infty}\longrightarrow} 0 \,.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn 9 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] We define $BS_\xi$ as the set of functions $p:\R^{2d}\to \C$ such that:
    \begin{enumerate}
        \item for all $x\in \R^d$, $p(x,\cdot)\in \mathscr{C}^\infty(\R^d)$ satisfies: for all $\gamma\in \N^d$, there exists $C_\gamma>0$ (independent of $h$ and $x$) such that
        \begin{equation*}
            \bb{\partial^\gamma_\xi p(x,\xi)}\leq C_\gamma,
        \end{equation*} 
        \item for all $x\in \R^d$, $p(x,\cdot)$ is $\Z^d$ periodic in the sense of \eqref{Def Z^d-périodicité en xi}.
    \end{enumerate}

[Proposition 2 of arXiv:2607.11608, '2607.11608'] Let $p > 2$ if $d=1,2 $, or  $2 < p < \frac{2 d}{d - 2 }$ if $d \ge 3$. Then, 
\begin{align}
\|u\|^p_{L^p(\R^d)}\le \textup{C}_{\textup{GNS}}(p,d)\|u\|^{\frac{(p-2)d}{2}}_{\dot{H}^{1}(\R^d)}\|u\|^{2+\frac{p-2}{2}(2-d)}_{L^2(\R^d)}. 

\end{align}
Moreover, the optimal constant $\textup{C}_{\textup{GNS}}$ is achieved by a function in $H^1(\R^d)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem12 of arXiv:2609.02795, 'Global smooth behavior in Kuznetsov and Westervelt type\\ viscous wave equations:\\ A unif'] Let $H^{(1)}$ and $H^{(2)}$ be as in Lemma (lem11 of the paper). Then
  \begin{eqnarray}\label{12.1}
	& & \hspace*{-20mm}
	\frac{d}{dt} \bigg\{ \frac{1}{2} \int_\Omega |\nabla u|^2
	+ \int_\Omega H^{(1)}(u,u_t) \bigg\} + a \int_\Omega |\nabla u|^2 \nonumber\\
	&=& \int_\Omega f(u,u_t,\nabla u,\nabla u_t) u
	+ \int_\Omega H^{(1)}_\xi(u,u_t) u_t
  \end{eqnarray}
  and
  \begin{eqnarray}\label{12.2}
	& & \hspace*{-20mm}
	\frac{d}{dt} \bigg\{ \int_\Omega H^{(2)}(u,u_t) + \frac{a}{2} \int_\Omega |\nabla u|^2 \bigg\}
	+ \int_\Omega |\nabla u_t|^2 \nonumber\\
	&=& \int_\Omega H^{(2)}_\xi(u,u_t) u_t
	+ \int_\Omega f(u,u_t,\nabla u,\nabla u_t) u_t
  \end{eqnarray}
  for all $t\in (0,T_{max})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq: first variation closed of arXiv:2609.02073, 'Existence of closed non-planar $p$-elasticae'] For $p\in (1,\infty)$, the immersed curve $\gamma \in W^{2,p}(\R/\Z;\R^n)$ is called a \textit{closed $p$-elastica} if there exists $\lambda \in \R$ such that 
  \begin{equation}

    \frac{d}{d\varepsilon} \left( \mathcal{B}_p[\gamma+\varepsilon \eta] + \lambda \mathcal{L}[\gamma + \varepsilon \eta] \right) \bigg|_{\varepsilon=0} = 0 \qquad \forall \eta \in C^\infty(\R/\Z;\R^n).
  \end{equation}

[Proposition 36 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] There is \(C_H<\infty\) such that, for \(T>R\geq1\) and \(x>0\),
\begin{equation}
  \mathbb P_{T,x}(\sigma_T>R)
  \leq C_HxR^{-H}.

\end{equation}

