[Defi 11 of arXiv:2608.28148, 'Flows and homotopies of Banach Lie algebroids'] ${}$
Let $N$ be a Banach manifold which we identify with the zero section in $p_N\colon TN\to N$. A local addition on $N$ is a smooth map $\Sigma\colon \mathcal{U}\subset TN\to N$  where $\mathcal{U}$ is an open neighbourhood of $N\subset TN$ such that:
\begin{itemize}
\item[1.] the map $\theta = (p_N, \Sigma) \colon  TN \to N\times N$ is a diffeomorphism from  $\mathcal{U}$ onto an open neighbourhood $\mathcal{V}$ of the diagonal;
\item[2.]  $\Sigma(x,0)=x$ for all $x\in N$.
\end{itemize}

[Proposition 5 of arXiv:2506.11799, 'Quenched limit for diffusive biased random walks in random environment'] Let $f, g, h$ be bounded function measurable, respectively, with respect to $\mathcal{A}, \mathcal{B}, \Sigma_k$, then, for all $x, y \in \mathbb{Z}^d$
	\begin{equation*}
		\mathbb{E}_{x, y} \left[ f\left(X_{\mu^{(1)}_k + \cdot}^{(1)}, X_{\mu^{(2)}_k + \cdot}^{(2)}\right) g \circ \theta_{\mu^{(1)}_k, \mu^{(2)}_k} h \right] = \mathbb{E}_{x, y} \left[ h \mathbb{E}_{X^{(1)}_{\mu_k}, X^{(2)}_{\mu_k}} \left[ f\left(X_{\cdot}^{(1)}, X_{\cdot}^{(2)} \right) g \mid \mathcal{D}^\bullet = \infty\right] \right].
	\end{equation*}

