[Theorem thm:heat_content of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] Let $\Omega$ be a bounded set in $\mathbb{G}$ whose $C^\infty$ boundary $\partial \Omega$ does contain no characteristic points. Then,  the following holds.
     \begin{enumerate}[leftmargin=*]
     \item For $1<\alpha< 2$,
     \begin{align*}
         \lim_{t\to 0} \frac{\operatorname{Vol}(\Omega) - H^{(\alpha)}_\Omega(t)}{t^{\frac{1}{\alpha}}}=\frac{1}{\pi}\Gamma\left(1-\frac{1}{\alpha}\right)\operatorname{Per}_\mathcal{H}(\Omega).
     \end{align*}
     \item When $\alpha=1$,
     \begin{align*}
         \lim_{t\to 0} \frac{\operatorname{Vol}(\Omega) - H^{(\alpha)}_\Omega(t)}{t\log(1/t)}=\frac{1}{\pi}\operatorname{Per}_\mathcal{H}(\Omega).
     \end{align*}
     \end{enumerate}
    For $0<\alpha<1$ and for any bounded open set $\Omega$ satisfying $\operatorname{Per}^{(\alpha)}_{\mathcal H}(\Omega)<\infty$ we have
    \begin{align*}
        \lim_{t\to 0} \frac{\operatorname{Vol}(\Omega) - H^{(\alpha)}_\Omega(t)}{t}=\operatorname{Per}^{(\alpha)}_{\mathcal H}(\Omega).
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 12 of arXiv:2609.01166, 'Nonparametric inference for density-dependent McKean--Vlasov diffusions'] Under the same assumptions as in Lemma~\ref{lem:primitive-kl}, there exists a constant \(C_\mathrm{risk}\) depending on \(I,J,\beta,H,\kappa,K,\xi_\star,d\) and \(V\), but not on \(n\), such that
\begin{equation}
  \inf_{\wh\Xi_n}
  \sup_{\xi\in\mathfrak X_\beta(J)}
  \E_\xi\norm{\wh\Xi_n-\xi}_{L^2(I)}^2
  \geq C_\mathrm{risk} n^{-2\beta/(2\beta+3)}.
\end{equation}
Moreover, for constants 
\(C_\mathrm{sep}>0\) and \(p\in(0,1)\)
depending on the same variables as \(C_\mathrm{risk}\),
\begin{equation}
  \inf_{\wh\Xi_n}
  \sup_{\xi\in\mathfrak X_\beta(J)}
  \Pi_\xi^{\otimes n}\!\biggl(
    \norm{\wh\Xi_n-\xi}_{L^2(I)}
    \geq C_\mathrm{sep} n^{-\beta/(2\beta+3)}
  \biggr)
  \geq p.
\end{equation}
The infimum is over all measurable estimators based on \(X_1,\ldots,X_n\sim \Pi_\xi\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 11 of arXiv:2609.02050, '2609.02050'] Let $D$ be a diagram that avoids the configurations in Figure~\ref{fig-upper} and let $C^{(1)},\ldots,C^{(m)}$ be all the diagrams $C=(C_1,C_2,\ldots,C_n)$ with $|C_j|=|D_j|$ for $j\in[n]$ and ${\bf x}^{C}={\bf x}^a$, where ${\bf x}^a$ is a monomial in $\chi_{D}({\bf x})$. For simplicity, write ${\bf y}^{(a)}={y}^{F_{led}^{C^{(a)}}}$  Then we have the following results:
		\begin{enumerate}
			\item[(a)] For $1\leq a \leq m$, the leading monomial ${\bf y}^{(a)}$ appears in the polynomial $\det\left(Y_D^{C^{(a)}}\right)$.

			\item[(b)] The leading monomials $\{{\bf y}^{(a)}\}$ are distinct.
		\end{enumerate}

[Defn 3 of arXiv:2608.12804, 'Scaling Limits for Ising Models on Inhomogeneous Random Graphs and Applications'] Let $T$ be a trace--class operator with eigenvalues $\lambda_i$, counted with algebraic multiplicity. Then the \emph{Fredholm determinant} of $I+T$ ($I$ being the identity operator) is defined as,
    \begin{equation*}
        \det(I+T) = \prod_i(1+\lambda_i)
    \end{equation*}

[Proposition 108 of arXiv:2608.26084, 'Localic Esakia Duality\\via Conic Frames'] There are functors
	\begin{align*}
		\patch_\mode
		\colon
		\Heyt_\mode
		&\longrightarrow
		\EFrm_\mode;
		\\
		A&\longmapsto (E_A,\dc{A});
		\\
		g &\longmapsto \idl(\bool{g}).
	\end{align*}

[Corollary LM of arXiv:2605.10452, 'A secretary for Messrs. Luce and Mallows'] When the weights for the Luce distribution are given by $\theta_j=q^j$, for $q\in(0,\infty)$, one has
\begin{equation}
P_n^{\mathcal{L}_\text{inv};\{q^j\}_{j=1}^n}(\mathcal{S}^\downarrow(n,M))=P_n^{\mathcal{M};q}(\mathcal{S}^\downarrow(n,M)).
\end{equation}

[Definition 5 (Stationary distribution) of arXiv:2606.31528, 'Well-posedness and stationary distribution of free stochastic differential equations'] Suppose that $\{U_t\}_{t\ge 0}$ is a solution to the free SDE \eqref{eq:fSDE}. A probability measure $\mu\in\mathcal P(\mathbb R)$ is called a \textit{stationary distribution} for the solution (or the equation) if, for every $t\ge0$, 
\begin{equation}
\tau(f(U_t))=\int_{\mathbb R} f(x)\,\mu({\rm d} x),
\qquad \forall f\in B_b(\mathbb R).
\end{equation}

[Theorem 6 of arXiv:2606.15843, 'Long-time behaviour of DLRA for SDEs'] Suppose Assumptions~(H1)--(H6) hold. Moreover,
		suppose Assumption~\ref{AS:relation1} holds. Then, there exists a constant $C(\mu,\nu,b,\sigma)>0$ such that, for all $t\in[0,\infty)$,
		\begin{equation}
			\bb W_2^2(\mu_t,\nu_t)\le \rrm e^{\delta t}\bb W_2^2(\mu,\nu)+\frac{C(\mu,\nu,b,\sigma)}{|\delta|}(d-r).
		\end{equation}

