[Theorem 12 (Rigidity of eigenvalues) of arXiv:2608.29872, 'Local Laws and Outlier Eigenvalues for Spiked Separable Covariance Matrices'] Suppose the assumptions of Theorem \ref{local_law} hold. Then, outside the spectrum, we have the following stronger averaged local law:
\begin{equation}
|m_1(z)-m_{1c}(z)|+|m_2(z)-m_{2c}(z)|+|m(z)-m_c(z)|\prec
\frac{1}{N(\kappa+\eta)}
+\frac{1}{(N\eta)^2\sqrt{\kappa+\eta}},
\end{equation}
uniformly in
\(
z\in S(c_0,C_0,\varepsilon)
\cap \{z=E+\ii\eta:E\geq \lambda_+,\, N\eta\sqrt{\kappa+\eta}\geq N^\varepsilon\}
\)
for any fixed $\varepsilon>0$. 

The local laws \eqref{average} and \eqref{eq:averaged_outside} imply the following rigidity estimate for any constant $0<c_1<c_0$. Define the classical location $\gamma_j$ of the $j$-th eigenvalue of $\mathcal Q_1$ by
\begin{equation*}
\gamma_j:=\sup_x\left\{\int_x^{+\infty}\rho_c(x)\dd x>\frac{j-1}{p}\right\}.
\end{equation*}
In particular, $\gamma_1=\lambda_+$. Then, for any $j$ such that $\lambda_+-c_1\leq \gamma_j\leq \lambda_+$, we have
\begin{equation}
|\lambda_j(\cal Q_1)-\gamma_j|\prec j^{-1/3}n^{-2/3}.
\end{equation}

[Lemma eq:Haar-entry-tail of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:Haar-incoherent}
There are universal constants \(c,C>0\) such that, for Haar \(O\in\mathbb O(N)\),
\begin{equation}
 \mathbb P(\abs{O_{ij}}>t)\le C e^{-cNt^2},
 \qquad 0<t<1.
\end{equation}
Consequently, if \(L>L_0:=\sqrt{3/c}\), then
\begin{equation}
 \nu_N(\mathcal O_{N,L})\longrightarrow1,
 \qquad
 \frac1N\log\nu_N(\mathcal O_{N,L})\longrightarrow0.
\end{equation}
For the point cutoff, however, every fixed \(L>0\) has zero
exponential cost:
\begin{equation}
 \frac1N\log\overline\sigma_{N-1}(D_{N,L})
 \longrightarrow0.
\end{equation}

[Lemma 33 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Let $k, b, \vec{y}, g$ be as in Definition \ref{Def.PinnedBM}. Suppose that $d_n$ is a sequence of positive reals such that $d_n \rightarrow \infty$, and set $T_n = \lceil b d_n \rceil$. Let $g_n: [0, T_n/d_n] \rightarrow [-\infty, \infty)$ be continuous functions such that $g_n \rightarrow g$ uniformly on $[0,b]$. In the case when $g = -\infty$, the last statement means that $g_n = -\infty$ for all large $n$. We also suppose that 
\begin{equation}
\lim_{n \rightarrow \infty} |g_n(T_n/d_n) - g_n(b)| = 0 \mbox{ if } g \neq -\infty.
\end{equation}

Fix $q\in (0,1)$, $c \in [0,1)$, and put $p = \frac{q}{1-q}$, $\sigma = \sqrt{p(1+p)}$. Define $G_n: [0, T_n] \rightarrow [-\infty, \infty)$ through
$$G_n(s) = \sigma d_n^{1/2} \cdot g_n(s/d_n) + p s,$$
and suppose that $Y^n \in \mathfrak{W}_{2k}$ is a sequence such that 
\begin{equation}
 \lim_{n \rightarrow \infty} \sigma^{-1} d_n^{-1/2} \cdot (Y_i^n - p T_n)   = y_i \mbox{ for } i \in \llbracket 1, 2k \rrbracket.
\end{equation}

Then, we have the following statements.
\begin{enumerate}
\item[(a)] There exists $N_0 \in \mathbb{N}$ such that for $n \geq N_0$ the laws $\mathbb{P}_{\ice;q ,c}^{T_n, Y^n,G_n}$ are well-defined, i.e. for some $(\mathfrak{B}^1, \dots, \mathfrak{B}^k) \in  \Omega_{\ice}(T_n, Y^n, G_n)$, we have $\prod_{i = 1}^k W(\mathfrak{B}^i; q,c) > 0$.
\item[(b)] If $\mathfrak{Q}^n = \{Q_i^n\}_{i = 1}^{2k}$ has law $\mathbb{P}_{\ice;q ,c}^{T_n, Y^n,G_n}$, then the sequence of $\llbracket 1,2k \rrbracket$-indexed line ensembles $\mathcal{Q}^n$ on $[0,b]$ defined by
\begin{equation}
\mathcal{Q}_i^n(t) = \sigma^{-1} d_n^{-1/2} \cdot \left( Q^n_i(t d_n) - ptd_n\right) \mbox{ for } n \geq N_0, \hspace{2mm} t \in [0,b] \mbox{ and } i \in \llbracket 1, 2k \rrbracket,
\end{equation}
converges weakly to $\mathbb{P}_{\mathrm{pin}}^{b,\vec{y},g}$ from Definition \ref{Def.PinnedBM} as $n \rightarrow \infty$.
\end{enumerate}

