[Lemme 24 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] Let $\mu\in \mathcal{G}_{\kappa}$ for some $\kappa > 0$, and also $\int x \, \dd\mu(x)=0$. Then

\begin{align}

\lim_{\delta \searrow   0}  \liminf_{N \to +\infty} \frac{1}{N}\ln \overline{\Pi}_{N,\mathsf{c}}[B_{\mathsf{c}}(\mu,\delta)] \geq - I[\mu] \;,

\end{align}

with $B_{\mathsf{c}}(\mu,\delta)$ as given in the statement of Proposition \ref{lowerboundonballs}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:stable-suspended-chart of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] Uniformly in the prime tuple,
\begin{equation}
 |\mathcal P_h(\boldsymbol\ell)|\gg_t h^4.
\end{equation}
Every $A_t$ in (equation eq:iterated-prime-suspension of the paper) is a primitive
$(4+t)$-set with
\begin{equation}
 r_h(A_t)=t+2,\qquad
 \operatorname{ndiam}(A_t)=\left(\prod_{i=1}^t\ell_i\right)(ps+qr)
 \asymp_t h^{t+2}.
\end{equation}
If
$p_1(A_t)\leq\cdots\leq p_{t+2}(A_t)$ are its successive relation-birth
degrees, then
\begin{equation}
 p_j(A_t)\asymp_t h\quad(1\leq j\leq t+2),
 \qquad
 \operatorname{ndiam}(A_t)\asymp_t\prod_{j=1}^{t+2}p_j(A_t).
\end{equation}
Its projective coordinate ring is arithmetically Cohen--Macaulay of type two.
Moreover, if
\begin{equation}
 R=\prod_{i=1}^t\ell_i,\qquad
 J=j_1+\cdots+j_t,\qquad 0\leq j_i<\ell_i,
\end{equation}
then
\begin{equation}
 |hA_t|=
 \sum_{0\leq j_i<\ell_i}
 \bigl(M_{h-J}-M_{u-J}+M_{v-J}-M_{b-J}-M_{c-J}\bigr),
\end{equation}
where $M_x=\binom{x+3}{3}$ for $x\geq0$ and $M_x=0$ for $x<0$.

[Lemma lem: prop of arXiv:2411.04157, 'Stochastic homogenization of dynamical discrete optimal transport'] Assume (equation path of the paper) and (equation ball of the paper) in Assumption (ass: graph of the paper).
The following assertions hold:

\begin{enumerate}
    \item $\sum_{y\sim x}\mathcal J^\varepsilon_v(x,y)=0$ $\forall x\in{\mathcal X_{\varepsilon}}$;
        \item $|\iota{\mathcal J}^\varepsilon_v|(A)\leq C |v| \mathcal{L}^n(A)$ for every orthotope (hyperbox) $A\subset \mathbb{R}^n$ of side length at least $\varepsilon$ in all directions, where $C=C(R,n)$;
    \item $\iota {\mathcal J}^\varepsilon_v\stackrel{*}{\rightharpoonup} v\mathcal{L}^n$ vaguely.
 \end{enumerate}

