[Definition 7 of arXiv:2608.30875, 'A Decomposition Theorem for Topological Semi-small Maps'] Let $Y = \bigsqcup_{\eta} W_{\eta}$ and $R = \bigsqcup_{\alpha} S_{\alpha}$ be topologically stratified spaces such that $R \subseteq Y$. An inclusion $R \hookrightarrow Y$ is said to be \textbf{locally flat at a point $r \in R$} if the following holds. Suppose $r \in W_{\eta} \cap S_{\alpha}$ and $\dim(W_{\eta}) \leq \dim(S_{\alpha})$. Then there exist distinguished neighborhoods $U \subset R$ and $U^{\prime} \subset Y$ of $r$ such that $U \subset U^{\prime}$ and the topological pair $(U \cap S_{\alpha},\, U^{\prime} \cap W_{\eta})$ is homeomorphic to the topological pair $(\mathbb{R}^{\dim S_{\alpha}},\, \mathbb{R}^{\dim W_{\eta}})$ with the standard inclusion $\mathbb{R}^{\dim W_{\eta}} \hookrightarrow \mathbb{R}^{\dim S_{\alpha}}$. In other words, there exist homeomorphisms $U^{\prime} \cap W_{\eta} \longrightarrow \mathbb{R}^{\dim W_{\eta}}$ and $U \cap S_{\alpha} \longrightarrow \mathbb{R}^{\dim S_{\alpha}} $ making the following diagram commute:
	\begin{align*}		
		\begin{tikzcd}[ampersand replacement=\&]
			U^{\prime} \cap W_{\eta} \arrow[r,  hookrightarrow] \arrow[d] \& U \cap S_{\alpha} \arrow[d]   \\
			\mathbb{R}^{\dim W_{\eta}} \arrow[r, hookrightarrow]  \& \mathbb{R}^{\dim S_{\alpha} }  
		\end{tikzcd}.
	\end{align*}
	The inclusion $R \hookrightarrow Y$ is locally flat if it is locally flat at each point $r \in R$. If $\dim(W_{\eta}) \geq \dim(S_{\alpha})$, we define local flatness similarly.

[Thm 10 of arXiv:2506.18834, '\large\bf On the random-time and finite-time ruin probability for widely dependent claim s'] (1) Under the assumptions of Theorem \ref{thm104} but without requiring condition (\ref{110}),
for any positive function $g(\cdot)$ on $[0,\infty)$ satisfying $g(x)\downarrow0$ sufficiently slowly such that
\begin{eqnarray}
x^{-1}g^{-1}(x)\ln x\downarrow0,
\end{eqnarray}
it holds that
\begin{eqnarray}
\lim\sup_{0<t\le xg(x)}\big|\psi(x;t)E^{-1}N(t)\overline{G}^{-1}(x)-1\big|=0.
\end{eqnarray}

(2) Similarly, under the assumptions of Theorem \ref{thm105} without requiring condition (\ref{110}),
the corresponding asymptotic relation (\ref{1127}) also holds. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma martingales of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $X_t$ denote the Auffinger--Chen process (equation eq:AuffingerChen of the paper). Then:
		\begin{enumerate}[label=(\roman*)]
			\item Define
			\begin{equation*}
				Y_t:=\Phi_\zeta(t,X_t)-\Phi_\zeta(0,X_0)-\frac12\int_0^t \xi''(s)\,\zeta([0,s])(\partial_x\Phi_\zeta(s,X_s))^2\,\mathrm{d} s-\int_0^t \partial_x\Phi_\zeta(s,X_s)\sqrt{\xi''(s)}\,\mathrm{d} B_s .
			\end{equation*}
			Then $\mathrm{d} Y_t=0$, i.e.\ $Y_t$ is a.s.\ constant in $t$.

			\item The process $\bigl(\partial_x\Phi_\zeta(t,X_t)\bigr)_{t\in[0,1]}$ is a martingale.

			\item The second derivative along the optimal trajectory satisfies
			\begin{equation*}
				\mathrm{d}\bigl(\partial_{xx}\Phi_\zeta(t,X_t)\bigr)
				=-\zeta([0,t])\,\xi''(t)\bigl(\partial_{xx}\Phi_\zeta(t,X_t)\bigr)^2\,\mathrm{d} t
				+\sqrt{\xi''(t)}\,\partial_{xxx}\Phi_\zeta(t,X_t)\,\mathrm{d} B_t.
			\end{equation*}

			\item Moreover,
			\begin{equation*}
				\mathrm{d}\bigl(\partial_x\Phi_\zeta(t,X_t)\bigr)^2
				=2\sqrt{\xi''(t)}\,\partial_x\Phi_\zeta(t,X_t)\,\partial_{xx}\Phi_\zeta(t,X_t)\,\mathrm{d} B_t
				+\xi''(t)\bigl(\partial_{xx}\Phi_\zeta(t,X_t)\bigr)^2\,\mathrm{d} t .
			\end{equation*}
		\end{enumerate}

[Lem 5. lem: sub-aging fucntion, smaller parts of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] Fix $l \in \mathbb{N}$.
  The following statements hold.
  \begin{enumerate} [label = (\roman*)]
    \item 
      For every $r>0$,
      \begin{equation}
        \lim_{\eta \to 0} 
        \limsup_{n \to \infty}
        \limsup_{(s,t) \in T_{3}(l)}
        \int_{D_{R_{n}}(\rho_{n}, r) \times \mathbb{R}_{\geq 0} \times (0, \eta]} 
          e^{-ws/v} P_{\rho_{n}}^{\nu_{n}}(X_{n}^{\nu_{n}}(t) = x)\, 
        \dot{\pi}_{n}(dx dw dv) 
        = 0.
      \end{equation}
    \item 
      It holds that 
      \begin{equation}
        \lim_{r \to \infty} 
        \limsup_{n \to \infty}
        \limsup_{(s,t) \in T_{3}(l)}
        \int_{D_{R_{n}}(\rho_{n}, r)^{c} \times \mathbb{R}_{\geq 0} \times \mathbb{R}_{>0}} 
          e^{-ws/v} P_{\rho_{n}}^{\nu_{n}}(X_{n}^{\nu_{n}}(t) = x)\, 
        \dot{\pi}_{n}(dx dw dv) 
        = 0.
      \end{equation}
    \item 
      For every $r, \eta>0$,
      it holds that  
      \begin{equation}
        \lim_{W \to \infty} 
        \limsup_{n \to \infty}
        \sup_{(s,t) \in T_{3}(l)}
        \int_{D_{R_{n}}(\rho_{n}, r)^{c} \times [W, \infty) \times [\eta, \infty)} 
          e^{-ws/v} P_{\rho_{n}}^{\nu_{n}}(X_{n}^{\nu_{n}}(t) = x)\, 
        \dot{\pi}_{n}(dx dw dv) 
        = 0.
      \end{equation}
  \end{enumerate}

