[Lem exs thP of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] There exists a constant $a_4 \in (0,1)$ such that, 
  for any $x \in M$, $R > 0$, and $\delta > 0$,
  \begin{equation}
    \lim_{r \downarrow 0}
    \hat{P}_{\diag(x)}\!\left(\sigma^{\mathrm{G}}(x, R, r; a_4) \leq \delta\right) = 1.
  \end{equation}

[Lemma S42L of arXiv:2410.23899, 'Tightness for interlacing geometric random walk bridges'] Fix $p, \epsilon, \eta, M^{\mathsf{bot}}, M^{\mathsf{side}}, A^{\mathsf{sep}}, A^{\mathsf{gap}}\in (0, \infty)$, $\Delta^{\mathsf{gap}}  \in (0,1/2)$, $k \in \mathbb{N}$, $\sigma = \sqrt{p(1+p)}$. There exist $N_6 \in \mathbb{N}$ and $\delta > 0 $, depending on $p, \epsilon, \eta, M^{\mathsf{bot}}, M^{\mathsf{side}}, A^{\mathsf{sep}}, A^{\mathsf{gap}}, \Delta^{\mathsf{gap}}, k$, such that the following holds for all $n \geq N_6$. If we assume:
\begin{itemize}
\item $\vec{x}, \vec{y}\in \mathfrak{W}_k$ as in ((DefSig of the paper)), and $|x_i| \leq M^{\mathsf{side}} \cdot n^{1/2}$, $|y_i - pn| \leq M^{\mathsf{side}} \cdot n^{1/2}$ for $i \in \llbracket 1, k \rrbracket$;
\item $x_i - x_{i+1} \geq A^{\mathsf{sep}} \cdot n^{1/2}$ and $y_i - y_{i+1} \geq A^{\mathsf{sep}} \cdot n^{1/2}$ for $i \in \llbracket 1, k -1 \rrbracket$;
\item $g: \llbracket 0, n \rrbracket \rightarrow [-\infty, \infty)$ is such that $g(s) - ps\leq  M^{\mathsf{bot}} \cdot n^{1/2} $ for all $s \in \llbracket 0, n \rrbracket$;
\item $x_k \geq g(s) - ps + A^{\mathsf{gap}} \cdot n^{1/2} $ for all $s \in \llbracket 0, n\rrbracket$ with $s \leq \Delta^{\mathsf{gap}} \cdot n$;
\item $y_k -pn \geq g(s) - ps + A^{\mathsf{gap}} \cdot n^{1/2} $ for all $s \in \llbracket 0, n\rrbracket$ with $s \geq n - \Delta^{\mathsf{gap}} \cdot n$;
\item the set $\Omega_{\mathsf{Inter}}(0,n,\vec{x},\vec{y}, \infty, g)$ is non-empty;
\item for $Q_i \in \Omega(0,n, x,y)$, we set $\mathcal{Q}_i(t)= \sigma^{-1}n^{-1/2}(Q_i(tn) - ptn)$ for $t \in [0,1]$;
\end{itemize}
then the following inequality holds for each $i \in \llbracket 1, k \rrbracket$
\begin{equation}
\mathbb{P}_{\mathsf{Inter}, \operatorname{Geom}}^{0, n, \vec{x}, \vec{y}, \infty, g}\left( w(\mathcal{Q}_i, \delta) > \epsilon \right) < \eta.
\end{equation}
We recall that $w(f,\delta)$ is the modulus of continuity from ((S33E1 of the paper)). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem l:8.2 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] For all $n$ large enough, $x \in {\rm D}_n^\circ$ and $y \in \partial {\rm B}(x; r_n)$, 
	\begin{equation}
		\mathbb{P}_y \big(\tau_{\partial} < \widecheck{{\mathbf T}}_{{\rm B}(x;r_n)} \big) \leq n^{-\eta_0/3}\,,
	\end{equation}
	where $\eta_0$ is as in~(equation e:2.3 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 18 of arXiv:2604.01978, 'Homogenized Transformers'] Let $X^n = §(x^{n}_1,\ldots, x^{n}_1)$ solve 
\begin{equation*}
\de x^{n}_i(t)=\int_{\Uptheta}G_{\mu^{n}(t)}(x_{i}^n(t);\bm{\theta})\mathsf{W}(\de \bm{\theta}, \de t),
\end{equation*}
with $\mu^n = \mu_{X^n}$. 
Let $(\bar x_1,\ldots,\bar x_n)$ be conditionally i.i.d., given $(\mathscr{F}^{\mathsf W}_t)_{t\geq0}$, copies of the unique solution $x$ of \eqref{eq:non_linear_SDE_common}, driven by the same common noise $\mathsf{W}$, and let $\bar\mu$ be their empirical measure. Then for every $T>0$ there exists $C_T>0$ such that 
\begin{align*}
    \max_{i\in[n]} \E \sup_{t\in[0, T]} \left\|x^{n}_i(t)-\bar x_i(t)\right\|^2 &+ \E \sup_{t\in[0, T]} W_2^2(\mu^n(t), \bar\mu^n(t)) \\
    &\leq  \frac{C_T}{n} \sum_{i=1}^n \E \left\|x^{n,i}(0)-\bar x^i(0)\right\|^2.
\end{align*}
In particular, after choosing an optimal coupling of the initial data, the right hand side may be written as $C_T \E W_2^2(\mu^n(0), \bar \mu^n(0))$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor unshuffling-cor of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Let $\mathbb{X}$ be a set and let $\psi$ be an $\mathbb{X}$-shuffling rule.
	If $\psi$ is $\mathfrak{S}$-equivariant, then for every $T,T'\in\trees$, ${\boldsymbol{x}}\in\mathbb{X}^T$, and ${\boldsymbol{\uppi}}\in\mathfrak{S}_{T'}$, we have
	\begin{align}
	\begin{cases}
	{\boldsymbol{\sigma}}^\psi_{T,{\boldsymbol{x}}}\cdotT=T',\\
	{\boldsymbol{\sigma}}^\psi_{T,{\boldsymbol{x}}}={\boldsymbol{\uppi}}^{-1}
	\end{cases}
	\qquad\iff\qquad
	\begin{cases}
	T={\boldsymbol{\uppi}}\cdotT',\\
	{\boldsymbol{\sigma}}^\psi_{T',{\boldsymbol{\uppi}}^{-1}_*{\boldsymbol{x}}}=\overline{\boldsymbol{\uppi}}.
	\end{cases}
	\end{align}

