[Defn Stationary Radial Ornstein Uhlenbeck process SDE of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] The normalized stationary radial Ornstein--Uhlenbeck process $\mathrm{ROU}_d(m)$, is the unique solution to 
    \begin{equation}
    \begin{split}
        &dR(t)=\bigg(\frac{m(d-1)}{R(t)}-mR(t)\bigg)\mathop{}\!\mathrm{d}{t} +m \mathop{}\!\mathrm{d}{W(t)} \\
        &R(0) \sim \chi_d
    \end{split}
\end{equation}
for a standard one dimensional Brownian motion $W(t)$.

[Theorem 26 of arXiv:2605.04359, 'Well-posedness of reflected BSDEs with default time and irregular barrier: An application '] Let $Y=\left(Y^1,Y^2,\cdots,Y^n\right)$ be an adapted $n$-dimensional process with regulated trajectories of the form
	\begin{equation}
		Y_t=Y^{\ast}_t+\sum_{0 \leq s <t} \Delta_{+} Y_s,\quad \forall t \in [0,T],

	\end{equation}
	where $Y^{\ast}=\left(Y^{\ast,1},Y^{\ast,2},\cdots,Y^{\ast,n}\right)$ is an RCLL adapted $n$-dimensional semimartingale and $\sum_{s <t} \left|\Delta_{+}  Y_s\right|  <\infty$  a.s. Let $F$ be
	a twice continuously differentiable function on $\mathbb{R}^n$. Then the process
	$\left(F\left(Y_t\right)\right)_{t \leq T}$ also has the form \eqref{form of the process for Ito}. Moreover, almost surely, for each $n \geq 1$ and all $t \leq T$,
	\begin{equation*}
		\begin{split}
			F\left(Y_t\right)
			&=F\left(Y_0\right)+\sum_{k=1}^n \int_{0}^{t} D^k F\left(Y_{s-}\right)dY^{\ast,k}_s+\dfrac{1}{2}\sum_{k,l=1}^n  \int_{0}^{t} D^k D^l F\left(Y_{s-}\right) d\left[Y^{\ast,k},Y^{\ast,l}\right]^c_s\\
			& \quad+\sum_{0 < s \leq t}\left\{ F\left(Y_s\right)-F\left(Y_{s-}\right)-\sum_{k=1}^n  D^k F\left(Y_{s-}\right)\Delta_{-}Y^{\ast,k}_s\right\}\\
			&\quad+\sum_{0 \leq s < t} \left\{F\left(Y_{s+}\right)-F\left(Y_{s}\right)\right\},
		\end{split}
	\end{equation*}
	where $D^k$ denotes the differentiation operator with respect to the $k$-th coordinate,and $\left[\cdot,\cdot\right]^c$ denotes the continuous part of the quadratic variation $\left[\cdot,\cdot\right]$.

[Lemma 8 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] Let $(X_{t})_{0 \le t \le T}$ be the Poisson F\"ollmer process. Then, we have
    \begin{enumerate}
        \item $X_{t} \sim P_{T-t}f \dd \pi_{t}$ for all $0 \le t \le T.$
        \item Denote the compensated process $(\tilde{X_{t}})_{0 \le t \le T}$ as 
        \begin{displaymath}
            \tilde{X_{t}} := X_{t} - \int_{0}^{t} \lambda_{s} \dd s.
        \end{displaymath}
        Then, $(\tilde{X_{t}})_{0 \le t \le T}$ is a martingale.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

