[Proposition prop:results:energyBound of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Suppose $(U, W)$ satisfy Assumption (as:results:invMeasure of the paper). 


Then, with $R_q$ as in (equation eq:results:fPartitionFunction of the paper), we have
\begin{equation}
   \mathbb{H}_\kappa^* :=  \inf_{\nu\in \mathcal{Q}_{\kappa, d}} \mathbb{H}_\kappa(\nu) \geq - \log R_q,

\end{equation} and $\mathbb H_\kappa$ is lower semicontinuous on $\mathcal{Q}_{\kappa, d}$. If $(U, W)$ additionally satisfy Assumption (as:results:strongCoercivity of the paper), then for all $M \in \ensuremath{\mathbb{R}}$ we have
    \begin{equation}
            \mathcal{R}(M):=\{\nu \in {\mathcal{M}_{\kappa, d}}: \mathbb{H}_\kappa(\nu) \leq M\} \subset \mathcal{Q}_{\kappa, d},

    \end{equation}
and $\mathcal{R}(M)$ is compact in the weak topology. Moreover there exists $C_{q,M} \in (0, \infty)$ such that
     \begin{equation}
        \sup_{\nu \in \mathcal{R}(M)}\bigg\{  \int_{(\ensuremath{\mathbb{R}}^d)^{1 + \kappa}} |\mathbf{x}|^2 \nu(d\mathbf{x}) \bigg\} \leq C_{q, M}.

    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem LM53 of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Assume that the Borel right process $X$ satisifes (AC) and (H3'), and that $X$ is transient.  Let $B\in \mathscr{B}^n(E)$ be a nearly Borel set such that $p_B\in {\mathcal{F}}_\mathrm{e}$. Then there exists a unique measure $\nu_B\in \mathscr{M}$ such that ${\mathcal{F}}_\mathrm{e}\subset L^1(E,\nu_B)$ and
    \begin{equation}
        {\mathcal{E}}(g,p_B)=\int_E g(x)\nu_B(\mathrm{d} x),\quad \forall g\in {\mathcal{F}}_\mathrm{e}. 
    \end{equation}
    In particular, 
    \begin{equation}
        p_B(x)=\int_E u(x,y)\nu_B(\mathrm{d} y),\quad \forall x\in E,
    \end{equation}
    and $\nu_B$ is a finite measure concentrated on $\overline{B}$ with $\nu_B(\overline{B})={\mathcal{E}}(p_B,p_B)$.

[Lemma 18 (Score regularity) of arXiv:2607.29560, 'Tractable Relaxations of Multivariate Stochastic Dominance via Optimal Transport and CVaR'] The functions in \eqref{Eq:AggregateScore}--\eqref{Eq:ScoreDecreaseCost}
are finite and continuous. Moreover,
\begin{equation}

|S(x)-S(y)|\le d_s(x,y),
\qquad
0\le\ell_s(x,y)\le d_s(x,y)
\le\overline L_s\|x-y\|_1.
\end{equation}

[Thmd 6 of arXiv:2606.08115, '2606.08115'] Let $K = \mathbb{R}^{+} \times \mathbb{R}^{+}$, a two-dimensional random walk $\left\{\ov{S}_n\right\}$ satisfies the condition (C). Let $\tau(\ov{x})$ be the exit time of a random walk from the cone $K$ with starting point $\ov{x} \in K$, as defined in (\ref{tauDef}). Then the following statements hold.
\begin{enumerate}
\item Uniformly in $\ov{x} \in K$ such that $\left|\ov{x}\right| \le \sqrt{n}/\ln n$
\begin{equation}

\pr \left( \tau(\ov{x}) > n \right) \sim \frac{\varkappa V\left(M\ov{x}\right)}{n^{p/2}}, \;\; n \to \infty,
\end{equation}
where $\varkappa$ is some real positive number which does not depend on $\ov{x}$.
\item There exists a real positive number $C$ and a vector $\ov{x}_0 \in MK$ such that for every $\ov{x} \in K$, we have inequality
\begin{equation}

\pr \left( \tau(\ov{x}) > n \right) \le C \frac{u \left( M\ov{x} + \ov{x}_0\right)}{n^{p/2}}.
\end{equation}
\end{enumerate}
In this case the function $V$ for every $\ov{x} \in K$ defined as follows
\begin{equation}

V\left(M\ov{x}\right):= \lim_{n \to \infty} \ex u\left(M\left(\ov{x} + \ov{S}_n\right)\right) I\left\{ \tau(\ov{x}) > n\right\}.
\end{equation}
Moreover:
\begin{itemize}
\item for every vector $\ov{x} \in K$ and every natural number $n$
\begin{equation}

V\left(M\ov{x}\right)= \ex V\left(M\left(\ov{x} + \ov{S}_n\right)\right) I\left\{ \tau(\ov{x}) > n\right\};
\end{equation}
\item the following asymptotic relation holds
\begin{equation}

V(M\ov{x}) \sim u(M\ov{x}), \;\; \mathrm{dist}\left( \ov{x}, \partial K\right) \to \infty.
\end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition pr:coupling of arXiv:2504.11107, 'An Invariance Principle for some\\% Reaction-Diffusion Equations with a Multiplicative Ran'] There exists a number
	$A=A(f\,,g)>1$ such that
	\begin{align*}
		&\mathrm{P}\left\{ u(s)\neq v(s)\text{ for all $s\in(0\,,t]$}\right\}\\
		&\hskip.5in\leqslant A\, \left( \frac{\|u_0 - v_0\|_{C(\mathbb{T})}}{
			\alpha t \min\left( \inf_{z\in \mathbb{T}} u_0(z)  \,, \inf_{z\in \mathbb{T}} v_0(z) \right)}\right)^{1/2}
			+ A\, \exp\left( -\frac{1}{A\sqrt{t}}\right),
	\end{align*}
	uniformly for all $t>0$ and all bounded, measurable, and non-zero 
	respective initial profiles $u_0,v_0:\mathbb{T}\to\mathbb{R}_+$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 32 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $3\le d\le 5$, there exist $\cl,\cl>0$ such that for any $r\ge 1$, 
 	 \begin{equation}
 	 	\mathbb{P}\big( \exists x \in B(r)\ \text{such that}\ \mathrm{cap}\big( \mathcal{C}_x^{\partial B(r)} \big) \ge \cref{const_lemma_lowd_cluster_capacity1}r^{d-2} \big) \ge \cref{const_lemma_lowd_cluster_capacity2}.
 	 \end{equation}

