body:
[Definition Locally Feller definition of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $x_0 \in E$ be a given reference point and define the strong closed ball
		\begin{equation}
			B^{d_E}_R(x_0) \triangleq \big\{x \in E : d_E(x, x_0) \le R\big\}.
		\end{equation}
		A Markov semigroup $\{\mathscr{P}_t\}_{t\ge 0}$ on $E$ satisfies the \textbf{restricted Feller property under mismatched metrics} (with respect to $\widetilde{d}_E$ and $d_E$, anchored at $x_0$) if the following two conditions hold:
		\begin{enumerate}[label={\rm(\roman*)}, leftmargin=0.79cm]\setlength\itemsep{0.2em}
			\item for every bounded Borel-measurable function $\phi \in \mathscr{M}_B(E)$ and $x \in E$, the map $t \mapsto [\mathscr{P}_t \phi](x)$ is Borel measurable on $[0, \infty)$;
			\item for any $t\ge 0$, $R>0$, and $\varphi \in C_B(E_{\widetilde{d}_E})$, the restriction 
			$\mathscr{P}_{t}\varphi\big|_{B^{d_E}_R(x_0)}$
			is continuous with respect to the metric $\widetilde{d}_E$.
		\end{enumerate}

[Lemma 14 (Compact embedding of paths) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Let $r\in(1,+\infty]$, and let $(q_n)_{n\in\N}$ be a sequence in $\mcl Q_r^\sS$ such that
\begin{align*}
    \sup_{n\in\N} \Ll|q_n\Rr|_{L^r}<+\infty.
\end{align*}
There exists a subsequence $\Ll(q_{n_k}\Rr)_{k\in\N}$ and some $q\in\mcl Q_r^\sS$ such that, for every $r'\in [1,r)$, this subsequence converges almost everywhere on $[0,1]$ and in $L^{r'}$ to $q$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] Given $\gamma\in{\mathcalboondox M}_{ac}$, let $\Pi_\gamma$ be the set of paths $\pi(t,dx)=\rho_t(x)dx$ in $\mathcal{D}([0,T],{\mathcalboondox M}_{ac})$ such that
    \begin{enumerate}
        \item There exists a $t_0>0$ such that $\rho$ follows the hydrodynamic equation (equation PDEproblem of the paper) in the interval $[0,t_0]$.
        \item For every $0<\delta\leq T,\;\exists\;\varepsilon>0$ such that $\varepsilon\leq\rho_t(x)\leq1-\varepsilon$ for all $(t,x)\in  {[\delta,T]}\times[0,1].$
        \item $\rho$ is smooth in $(0,T]\times[0,1].$
    \end{enumerate}

[Lemma 37 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Adopt the notation and assumptions of Theorem \ref{Thm.Tightness} and fix any $b\in (0,\beta)$. For any $\varepsilon \in (0,1)$, there exist $R_1 > 0$ and $N_1\in \mathbb{N}$, depending on $b$ and $\varepsilon$, such that for all $n\ge N_1$
\begin{equation}
\begin{split}
   &\mathbb{P}\left(\max_{s\in [0, \lfloor bd_n \rfloor ]}(L_{1}^n(s) -ps) \ge R_1 d_n^{1/2}\right)  < \varepsilon.
\end{split}
\end{equation}

