[Lem 17 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $f\in S_{\eta_1,\eta_2}(m,\A{1},\A{2})$ and let $t\in [0,1]$. Then, the matrix coefficients of $f_{N,\A{1},\A{2}}^t$ in the basis $\mc{B}^{\alpha_1}$ given by \eqref{Def de la base de l'espace d'intérêt} are
    \begin{equation}
        F^t_{s,j}=\sum_{n,r\in \Z^d}c_{n,j-s+rN}(f)e^{\frac{2i\pi}{N}(1-t)\ps{n}{j}+\frac{2i\pi}{N}t\ps{n}{s-rN}},\m\m\m\m  s,j\in \disc{1}{N}^d,
    \end{equation}
    where for all $n,k\in \Z^d$,
    \begin{equation}
        c_{n,k}(f)=(\A{1}\A{2})^d\int_{\mc{T}_{\A{1},\A{2}}}f(x,\xi)e^{-2i\pi(\alpha_1^{1/2}\ps{x}{n}+\alpha_2^{1/2}\ps{\xi}{k})}dxd\xi.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 38 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma \geq 3/2$, $\lambda  \in (0, \; 1)$ and $0 \leq s \leq t \leq T$. For every $n \in \mathbb{N}_+$, it holds 
	\begin{align} 
		\mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{  \frac{\Theta(n) K_n}{n \sqrt{n} }  \int_s^t \dd r \sum_{x}   \nabla H ( \tfrac{ \lfloor x - r v_n \rfloor }{n}  )   \Psi_{x, \ell_n}^{\alpha,\beta}(\eta_r^n)  \Bigg\}^{2} \Bigg] \leq \widetilde{C} {\| \nabla H \|^{2}_{2,n}} (t-s)^{\frac{2\gamma-1}{\gamma}} \frac{ \big[ \Theta(n) K_n \big]^{2} }{n^{2} [\Theta(n)]^{1/\gamma}}, 
	\end{align}
	where $\ell_n:=n^{1 - \lambda}$.

