[Proposition prop:tail_inequality of arXiv:2605.30999, 'Functional central limit theorems for $U$-statistics of $\beta$-mixing data'] For each $m\geqslant 2$, there exists a constant $\kappa_m$ such that if  $\pr{S,\mathcal{S}}$ is a measurable space, $\left(X_i\right)_{i\in\mathbb Z}$ is a strictly stationary sequence taking values in $S$,   $h\colon S^m\to \mathbb R$ is a canonical kernel, $a\geqslant 0$ and $N\geqslant m$, the following inequalities hold for each positive $R,t$: 
 \begin{multline}
 \mathbb P\pr{\abs{U_{m,N+a}\left(h\right)-U_{m,a}\left(h\right)}> t}
  \\ 
     \leqslant R^2\frac{\kappa_{m}}{t^2} N\left(N+a\right)^{2m-3}  \pr{1+\sum_{k=1}^{N+a }k
      \beta\left(k\right)}+\frac{\kappa_m}{t} \frac{\left(N+a\right)^{m-1}}{N^{m-3/2}} 
      \sup_{\bm{i}\in\operatorname{Inc}^m}\E{ 
      \abs{h\pr{X_{\bm{i}}}}\mathbf{1}_{\abs{h\pr{X_{\bm{i}}}}>R}
      },
 \end{multline}
 \begin{multline}
     \mathbb P\pr{\max_{m\leqslant n\leqslant N}\abs{U_{m,n}\left(h\right)   }>N^{m-1/2}t    } \\
     \leqslant     \frac{\kappa_{m}}{t^2} \left(\log N\right)^2\frac{R^2}N \pr{1+\sum_{k=1}^{N }k
      \beta\left(k\right)}+\frac{\kappa_m}{t} \sqrt{N} 
      \sup_{\bm{i}\in\operatorname{Inc}^m}\E{ 
      \abs{h\pr{X_{\bm{i}}}}\mathbf{1}_{\abs{h\pr{X_{\bm{i}}}}>R}
      }.
 \end{multline}

