body:
[Defn eq:rip of arXiv:2608.29018, 'Sharp Restricted Isometry Thresholds for\\ Global Minima of Rank-Restricted Matrix LASSO'] For $\delta\ge0$ and an integer $k\ge1$, we write $\mathcal{A}\in\operatorname{RIP}(\delta,k)$
if 
\begin{equation}
(1-\delta)\normF E^{2}\le\normtwo{\mathcal{A}(E)}^{2}\le(1+\delta)\normF E^{2}
\end{equation}
holds for every $E$ with $\operatorname{rank}(E)\le k$.

[Lemma 34 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] For every dyadic parent interval $[a,c]$ with midpoint $b$, the residuals produced by the dyadic recursion satisfy
\begin{equation}

R^{\mathsf s}_{ca}=R^{\mathsf s}_{cb}+S_{c-b}R^{\mathsf s}_{ba}+H_{cba}.
\end{equation}
Consequently, $\hdd R^{\mathsf s}=H$ on dyadic triples.

[Theorem 159 of arXiv:2601.16377, '2601.16377'] Consider a discrete ensemble satisfying Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit} and \ref{Assumptions_analyticity}. Let $L \in \amsmathbb{Z}_{> 0}$ and a $L$-tuple of integers $\boldsymbol{h} \in [H]^L$ both independent of $\N$, let a (possibly $\N$-dependent) $L$-tuple of functions $\boldsymbol{f}(z)$ such that $f_l(z)$ is twice continuously differentiable in $\amsmathbb{A}_{h_l}^{\mathfrak{m}}$ and is a holomorphic function of $z$ in a $\N$-independent complex neighborhood $\amsmathbb{K}_h$ of $\bigcup_{k = k^-(h_l)}^{k^+(h_l)} [\overline{\alpha}_k,\overline{\beta}_k]$. Assume there exists a constant $C > 0$ such that $\max_{l} \sup_{z \in \amsmathbb{K}_h} |f_l(z)| \leq C$.

Let $\textnormal{\textsf{\textbf{Gau\ss{}}}}[\boldsymbol{f}]$ be a $L$-dimensional random Gaussian vector independent of the $K$-dimensional discrete Gaussian vector $\textnormal{\textsf{\textbf{Gau\ss{}}}}_{\amsmathbb{Z}}$ appearing in Theorem~\ref{Theorem_CLT_for_filling_fractions_saturation}, having covariance
\begin{equation}

\textnormal{\textsf{Cov}}_{l_1,l_2}[\boldsymbol{f}] = \sum_{k_1=k^-(h_{l_1})}^{k^+(h_{l_1})} \, \sum_{k_2=k^-(h_{l_2})}^{k^+(h_{l_2})} \oint_{\gamma_{l_1}} \oint_{\gamma_{l_2}}
 f_{l_1}(z_1) f_{l_2}(z_2)
\,\mathcal{F}_{k_1,k_2}(z_1,z_2)\,\frac{\dd z_1 \dd z_2}{(2\ii\pi)^2}.
\end{equation}
and $l$-th component of the mean equal to the sum of $\mathbbm{Rest}[f_l]$ in \eqref{Elink1} and $\mathbbm{Rest}'[f_l]$ in \eqref{Elinkm2} below.
Then, we have as $\N \rightarrow \infty$
\begin{equation}

\left(\sum_{i = 1}^{N} \mathbbm{1}_{[a_{h_l},b_{h_l}]}(\ell_i) f_l\bigg(\frac{\ell_i}{\N}\bigg) - \N \int_{\hat{a}'_{h_l}}^{\hat{b}'_{h_l}} f_l(x)\,\mu_{h_l}(x)\,\dd x\right)_{l = 1}^{L} \,\,\mathop{\sim}^{\textnormal{d}} \,\,\textnormal{\textsf{\textbf{Gau\ss{}}}}[\boldsymbol{f}] + \big(\mathsf{Shift}_{h_l}[f_l]\big)_{l = 1}^{L}.
\end{equation}
The convergence in Definition~\ref{Definition_asymptotic_equivalence} is uniform for fixed constants in the assumptions. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, uniformly for $z\in\mb D(\tau,\eta_0)$,
        \begin{align}
                \|\Pi^{-1}(z)\|\lesssim1,\qquad \|\Pi(z)\|\lesssim\frac1{\Im m(z)}. \nonumber
        \end{align}
        Moreover,
        \begin{align}
                \|\Pi_{11}(z)\|\lesssim\frac1{\Im m(z)+\dist(z,\supp\bnu_1)},\qquad \|\Pi_{22}(z)\|\lesssim\frac1{\Im m(z)+\dist(z,\supp\bnu_2)}. \nonumber
        \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] We have 

\begin{equation}
g_{\text{{\tiny $\delta$}}} (\tilde{v}_m) \longrightarrow g_{\text{{\tiny $\delta$}}} (\tilde{v}) \quad \text{in} \quad L^2(0,T\,;L^2(\Omega)) \quad 
\text{as} \quad m \to \infty 
\end{equation}

whenever a sequence $\{\tilde{v}_m\}_{m\,\in\,\mathbb{N}} \subset \mathcal{V}_R(v_0,\nu)$ and a function $\tilde{v} \in \mathcal{V}(v_0)$ satisfy the following 
convergences as $m \to \infty$:

\begin{equation}
\tilde{v}_m \longrightarrow \tilde{v} \quad \left\{
\begin{array}{l}
\text{in} \quad C([0,T]\,;L^2(\Omega)),\\[0.1cm]
\text{weakly in} \quad W^{1,2}(0,T\,;L^2(\Omega)),\\[0.1cm]
\text{weakly$^*$ in} \quad L^\infty (0,T\,;H^1(\Omega)).
\end{array}
\right.
\end{equation}

\indent
Moreover, there exists a constant $C_9>0$, which is independent of the approximate parameters $\delta \in (1,\infty)$ and $\nu \in (0,1)$, 
such that the following uniform estimate holds:

\begin{equation*}
\sup_{\nu\,\in\,(0,1)} \left\{ \sup_{\tilde{v}\,\in\,\mathcal{V}_R(v_0,\nu)} 
\left( \sup_{0 \le t \le T} \|(g_{\text{{\tiny $\delta$}}} (\tilde{v}))(t)\|_{L^2(\Omega)} \right) \right\} \le \delta C_9 R^{\frac{1}{2}}.
\end{equation*}

[Lemma 15 of arXiv:2608.06646, 'Three-dimensional stochastic wave equation with non-Lipschitz coefficients'] For all $r\ge 0$ and $\alpha\in (-2,0)$, it holds for all $v\in \R^3$ that
    \begin{align*}
        \int_{|u|\le r}\frac{|u+v|^{\alpha}}{|u|}\ud u\le \int_{|u|\le r}|u|^{\alpha-1}\ud u \,.
    \end{align*}

