[Thm 9 of arXiv:2605.05986, '\bf Convergence rate of the occupation measure of { classes of ergodic processes toward th'] Assume that $d=d'$, that $b$ and $\sigma$ are locally Lipschitz functions, that $\sigma$ is bounded and that $\sigma$ is uniformly elliptic\footnote{In fact, the ellipticity assumption must be uniform only on compact sets.}:
\begin{equation}
\exists\,\ve_0>0,\,\forall x\in\ER^d,\quad  \s\s^{\top}(x)\ge \ve_0I_d\quad\textnormal{(in the sense of symmetric matrices)}.
\end{equation}
 Assume that $\mu_0$ has {finite} moments of any orders. Then, if there exist some positive $M$, {$a>0$ and $\alpha>0$} such that for $|x|>M$, $\langle b(x),x\rangle\le  -\alpha |x|^{2a}$, 


$$\big\| {\cal W}_p(\nu_t,\nu) \big\|_p\lesssim t^{-\frac{1}{2p}\wedge\left(\frac{1}{d}\right)^{-}}\quad \textnormal{in the sense of~\eqref{eq:toutunbis}}.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 27 of arXiv:2603.27433, 'The $k$-cycle shuffling with repeated cards'] Let $n=ml$, such that $2\le l\le n^{o(1)}$. Moreover, suppose that $x=n^{o(1)}$. Sample a uniformly random subset $T$ of size $x$ in $[n]$, then sample a uniformly random element $\sigma\in\S_{[n]\backslash T}$ and view it as an element of $\S_n$ by fixing all of the elements in $T$. Then, we have
\begin{equation}
\mathbf{P}(\sigma\text{ is clustered})\le n^{-1+o(1)},
\end{equation}
and
\begin{equation}
d_{TV}(|F_{n,k}(\sigma)|,x+\Pois(l))\le n^{-1+o(1)}.
\end{equation}

[Theorem th:stable_equivalence_def of arXiv:2412.06374, 'Stable and tempered stable distributions and processes: an overview toward trajectory simu'] A random variable $X$ is said to have a stable distribution if one of the equivalent following properties is met.
\begin{itemize}
\item \textbf{Sum stability for linear combination.} For any $a,b>0$ there exist two constants $c>0$ and $d\in \mathbb{R}$ such that 
    \begin{align}
        a X_1 + b X_2 \stackrel{d}{=} cX + d,
    \end{align}
    where $X_1$ and $X_2$ are independent copies of $X$.

\item \textbf{Sum stability for $n$ terms sum.} For any $n\in \mathbb{N}$ such that $n\geq 2$, there exist two constants $c_n>0$ and $d_n \in \mathbb{R}$ such that 
    \begin{align}
        X_1 + X_2 + \cdot + X_n \stackrel{d}{=} c_n X + d_n,
    \end{align}
    where $X_1,X_2, \cdots, X_n$ are independent copies of $X$ and for all $n\in N$ there exists $\alpha \in (0,2]$ called the \emph{stability index} such that $c_n = n^{1/\alpha}$.


\item \textbf{General Central Limit Theorem.} There exist $Y_1,\cdots, Y_n$ i.i.d. random variables and two sequences $(a_n)_{n\in\mathbb{N}}$, $(b_n)_{n\in \mathbb{N}}$, where $\forall n\in \mathbb{N}, a_n>0$ and $b_n \in \mathbb{R}$ such that
\begin{align}
 a_n\left(\sum_{i=1}^n Y_i\right) - b_n \stackrel{d}{\rightarrow} X,
\end{align}
when $n\rightarrow +\infty$

\item \textbf{Stable characteristic function.} There exist $0<\alpha\leq 2, \sigma \geq 0, \beta \in [-1,1]$ and $\delta \in \mathbb{R}$ such that the characteristic function $\phi_X$ of $X$ is given for all $u\in \mathbb{R}$ by
\begin{align}
\phi_X(u) = \begin{cases}
    \exp \left( - \sigma^\alpha |u|^\alpha \left(1- i\beta sign(u) \tan \left(\frac{\pi\alpha}{2} \right) \right) + i\delta u \right)& \text{if } \alpha \neq 1 \\
    \exp \left(- \sigma |u|(1+ i\beta \frac{2}{\pi} sign(u) \log(|u|)) + i \delta u \right) &\text{if } \alpha =1.
\end{cases}
\end{align}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

