[Prop link-with-compositions-new-2 of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Under the assumptions of Proposition (prop:link-with-compositions-new-1 of the paper), we have for $n\geq 0$ the identity $\PFtrees{\mathbf{w}} {nd+1}=\PFComp{{\mathbf{w}},{\mathbf{b}}}{nd}$, and for $T\in\trees[d]_{nd+1}$ if we write $c(T)=\underline{n}_1 \cdots  \underline{n}_i$ and $\varphi(T)=(T^{[1]},\dots,T^{[i]})$, then
	\begin{align}
	\SimpGen{{\mathbf{w}}}{nd+1}(T)=\PComp{{\mathbf{w}},{\mathbf{b}}}{n-1}\bigl(c(T)\bigr)\cdot\left(\SimpGen{{\mathbf{w}}}{n_1}\bigl(T^{[1]}\bigr)\cdots \SimpGen{{\mathbf{w}}}{n_i}\bigl(T^{[i]}\bigr)\right).
	\end{align}

[Lem gam of arXiv:2411.11759, 'Milstein-type schemes for McKean--Vlasov SDEs driven by Brownian motion and Poisson random'] Let Assumptions \mbox{\normalfont  (asum:ic of the paper)}, \mbox{\normalfont  (asum:lip of the paper)} and \mbox{\normalfont  (asump:super of the paper)} to \mbox{\normalfont  (asum:convergence2 of the paper)}  hold with 
   $\bar p\geq \max\{2,\eta/8+1\}(\varepsilon+2)(\eta+1)(\eta+2)/{\varepsilon}\color{black}$
   where $\varepsilon\in(0,1)$.
	 Then,
	\begin{align*}
		&\int_Z E\big|\gamma\big( x_s^{i, N,n},\mu_s^{x, N,n}, z\big)-(\widehat{\Gamma})_{tam}^{\displaystyle n}\big(\kappa_{n}(s),s,x_{\kappa_{n}(s)}^{i,N,n},\mu_{\kappa_{n}(s)}^{x,N,n},z\big)\big|^2\nu(d z)\leq Kn^{-1-\frac{2}{\varepsilon+2}}
	\end{align*}
	for any $s\in[0,T]$ and $i\in\{1,\ldots,N\}$	where $K>0$ is a constant independent of $N$ and $n$.

