[Theorem incrementalstrong of arXiv:2603.22652, 'A cohesive account on the ergodic behaviours and scaling limits of Random Walks in Cooling'] {AvedCos24game}}]

Assume that ${\mathbb {X}}$ satisfies (equation C of the paper) and 
\begin{description}
\item[\namedlabel{S1}{S1}]\emph{(Polynomial decay)} There is a
  $\delta>0$ such that for all $\epsilon>0$ there is a $C = C(\epsilon)$ for
  which
\begin{equation}\notag
\sup_k{\mathbb {P}}\left(\abs{X^{(k)}_m/m}>\epsilon\right)<\frac{C}{m^\delta}.
\end{equation}
\item[\namedlabel{S2}{S2}] \emph{(Uniform domination)} There is a random variable $X_*$ and $\gamma>0$ such  that ${\mathbb {E}}(\left\vert X_*\right\vert^{2 +\gamma })<\infty$ and for all $x \in {\mathbb {R}}$
\begin{equation}\notag
\sup_{k,m}{\mathbb {P}}(|X^{(k)}_m/m|)>x)\leq {\mathbb {P}}(X_*>x). \end{equation}  
\end{description}

Let $X_t = X_t(\mathfrak{X},\tau)$ be given by  (equation cooling-general-tau of the paper). Then,
\begin{equation}
{\mathbb {P}}\prt{\lim_{t\to\infty}X_t/t= 0} = 1.
\end{equation}

[Lemma lem:RT of arXiv:2607.12564, 'Power-law and log-periodic degree tails for a family of probability generating function eq'] There exist $C,c>0$, depending only on $p$ and $j$, such that
\begin{equation}
  \mathbb{P}(D^*_n=k)\le C\lambda^{-n}\exp\!\Bigl\{-c\,\frac{k}{\lambda^{n}}\Bigr\},
  \qquad n\ge0,\ k\ge j .
\end{equation}
Consequently, writing $N_k=\lfloor\log_\lambda k\rfloor$ and $m=n-N_k$,
\begin{equation}
  \mathbb{P}(D^*_n=k)\le\lambda^{-n}\mathcal D_m,\qquad
  \mathcal D_m=\begin{cases}C\exp\{-c\lambda^{-m}\},& m<0,\\[2pt] C,& m\ge0,\end{cases}
\end{equation}
and $\mathcal D_m$ is weighted-summable:
\begin{equation}
  \sum_{m\in\mathbb{Z}}\mathcal D_m\,\lambda^{-(\rho+1)m}<\infty .
\end{equation}

[Lemma lem:sig_bound of arXiv:2606.29622, 'Affine Structure of the Brownian Signature'] Let $X = (X_t)_{t \in [0, T]}$ be a continuous semimartingale and let $\sigXhat[]$ denote its time-augmented signature. Then, for any word ${\color{NavyBlue}{\mathbf{v}}} \in V\,$, there exists a constant $C_{{\color{NavyBlue}{\mathbf{v}}}, T} \geq 0\,$, such that
    \begin{equation}
    \begin{aligned}
        \left|\sigXhat[s,t]^{{\color{NavyBlue}{\mathbf{v}}}}\right| &\leq C_{{\color{NavyBlue}{\mathbf{v}}}, T}\,\left(1 + \left|X_{s,t}\right|^{|{\color{NavyBlue}{\mathbf{v}}}|_{{\color{NavyBlue}{\mathbf{1}}}}} + \int_s^t|X_{s,r}|^{|{\color{NavyBlue}{\mathbf{v}}}|_{{\color{NavyBlue}{\mathbf{1}}}}}dr\right), \quad s \leq t \leq T\,, \\
        \left|\sigXhat[s,t]^{{\color{NavyBlue}{\mathbf{v0}}}}\right| &\leq C_{{\color{NavyBlue}{\mathbf{v}}}, T}\left(1 + \int_s^t|X_{s,r}|^{|{\color{NavyBlue}{\mathbf{v}}}|_{{\color{NavyBlue}{\mathbf{1}}}}}dr\right), \quad s \leq t \leq T\,.
    \end{aligned}
    \end{equation}

