[Lemma eq:f_c of arXiv:2605.05193, 'Grokability in five inequalities'] As in Nazarov [Nazarov2003], define
\begin{equation}
f(t):=t^{n-1}e^{-t^2/2},\qquad
c:=\Big(\int_0^\infty f(t)\,dt\Big)^{-1}.
\end{equation}
Then for every $n\geq 1$, every measurable $g:[0,\infty)\to[0,\infty]$,
\begin{equation}
\int_{\mathbb R^n}\varphi_n(y)\,g(|y|)\,dy
=
c\int_0^\infty f(r)\,g(r)\,dr.
\end{equation}

[Thm conv-DL-infty of arXiv:2411.16376, 'Higher order approximations in arcsine laws for subordinators'] Under the assumptions of Theorem $(Thm:potential-infty of the paper)$ with  $\alpha_0=\alpha\in[0,1]$, let us define a function $\varepsilon_2:(0,+\infty)\to\ensuremath{\mathbb{R}}$ by
\begin{align}
    \Pi((x,+\infty))=
    \mathbbm{1}_{\{\alpha>0\}}
    \frac{c_0 x^{-\alpha}}{\Gamma(1-\alpha)}+\varepsilon_2(x),
    \quad 0<x<+\infty.	
\end{align}
Set
\begin{align}
   \varepsilon_3(s,x)
   =
   s\Pi((s-sx,+\infty))\varepsilon_1(sx),
   \quad 0<s, x<+\infty.	
\end{align}
Then, for $s\in(0,+\infty)$, the finite measure 
\begin{align}
\ensuremath{\mathbb{P}}\bigg(\frac{X_{T(s)-}}{s}\in dx,\; 0<\frac{X_{T(s)-}}{s}<1\bigg),
\quad
0<x<1,
\end{align}
 admits a density expressed in the form
\begin{align}
   s\Pi(&(s-sx,+\infty))u(sx)
   \\
   =\,&\frac{\sin(\pi \alpha)}{\pi}x^{-1+\alpha}(1-x)^{-\alpha}
   +
    \mathbbm{1}_{\{\alpha>0\}}
   \sum_{k=1}^n
   \frac{c_0 s^{\alpha_k-\alpha}}{c_k\Gamma(\alpha_k)\Gamma(1-\alpha)}x^{-1+\alpha_k}(1-x)^{-\alpha}
   \\
   &+\sum_{k=0}^n\frac{s^{\alpha_k}}{c_k\Gamma(\alpha_k)}
   x^{-1+\alpha_k}\varepsilon_2(s-sx)
   +
   O(\varepsilon_3(s,x)),
   \quad
   \text{as $s\to+\infty$,}

\end{align}
uniformly in $x\in I$ for any closed interval $I\subset (0,1)$. 
Therefore, for any closed interval $I\subset (0,1)$,
\begin{align}
	\ensuremath{\mathbb{P}}\bigg(&\frac{X_{T(s)-}}{s}\in I\bigg)
	\\
	=
	\,&\frac{\sin(\pi \alpha)}{\pi}\int_I x^{-1+\alpha}(1-x)^{-\alpha}\,dx
	\\
	&+
	 \mathbbm{1}_{\{\alpha>0\}}
	\sum_{k=1}^n
   \frac{c_0 s^{\alpha_k-\alpha}}{c_k\Gamma(\alpha_k)\Gamma(1-\alpha)}
   \int_I x^{-1+\alpha_k}(1-x)^{-\alpha}\,dx
   \\
   &+\sum_{k=0}^n\frac{s^{\alpha_k}}{c_k\Gamma(\alpha_k)}
   \int_I
   x^{-1+\alpha_k}\varepsilon_2(s-sx)\,dx
   +
  O\bigg(\sup_{x\in I}\varepsilon_3(s,x)\bigg),
   \quad
   \text{as $s\to+\infty$}.

\end{align}

\begin{Rem}
By Remark (Rem:Pi-infty of the paper), if $0<\alpha<1$, then $\varepsilon_2(x)=o(x^{-\alpha})$, as $x\to+\infty$.	
\end{Rem} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm: SSC JSQ of arXiv:2603.14163, '\LARGE \bf Tail Bounds for Queues with Abandonment: Constant, Moderate, Large Deviations, '] [State Space Collapse for JSQ]

    For JSQ under in heavily overloaded condition (ass:heavy_overload of the paper), the following inequality holds:
    \begin{align*}
        \mathbb{E}[\|\mathbf{q}_{\perp}\|^{p}]^{1/p} &\leq \max\{ E_{n,\lambda,\mu}^{(1)} p^2, E_{n,\lambda,\mu}^{(2)} p \} \leq E_{n,\lambda,\mu} p^2 \end{align*}
    Where $\mathbf{q}_{\perp} = \mathbf{q} - \frac{1}{n}(\sum_{i=1}^n q_{i})\boldsymbol{1}$.
    $E_{n,\lambda,\mu}^{(i)}, i=1,2$ and $E_{n,\lambda,\mu}$ are constants independent of $p,\gamma$, their closed forms are given in (equation eq: p-moment for q_perp, state space collapse of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemmaJM of arXiv:2604.11212, 'Sofic measures'] A probability measure~$\mu$ on~$A^\mathbb{Z}$ is~$1$-step Markov if and only if
\begin{displaymath}
\hat{\mu}(abw)=\frac{\hat{\mu}(ab)\hat{\mu}(bw)}{\hat{\mu}(b)}
\end{displaymath}
for every~$a,b\in A$ and~$w\in A^*$.

