[Theorem 3 (One-sided cumulants) of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Assume the set-up and conditions of Theorem~\ref{theo:main}. For $q=0$ and any fixed $p\ge 3$ it holds that
\begin{equation}
\kappa_{p,0}\left(X\right) = \frac{\eta^p}{N^{(p-2)/2}}\left(K_{p,0}(z)\kappa_p^{\mathrm{d}} + \mathcal{O}\left(\frac{1}{N^{1/2}}\right)\right),

\end{equation}
uniformly in $z\in\mathcal{D}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 124 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] We have that $(x, y) \in \mathfrak{A}_{q;a,b,c}$ if and only if 
		\begin{flalign}

			\begin{aligned} 
				\big( X(B+C) - Y(& A+C) - AB + (\mathfrak{q}^{-1} - 1) ABY \big)^2 \\
				& - 4 AB Y \big( A + C - X + (1 - \mathfrak{q}^{-1}) (A+C) Y \big) = 0.
			\end{aligned} 
		\end{flalign}

[Theorem 3 of arXiv:2608.27569, 'Laplace and Dolbeault operators on Sasakian manifolds'] Let $(M^{2n+1},g,\xi )$ be a compact Sasakian
manifold. Let $m\in\{1,\ldots, 2n+1\}$. For any $q\in\mathbb{R}$, we have the decomposition
\begin{equation*}
\mathcal{H}_{\overline{\partial }}^{m}\left( q\right) =\mathcal{H}_{
\overline{\partial },P}^{m}\left( q\right) \oplus
\bigoplus\nolimits_{1\leq b\leq \left\lfloor \frac{m}{2} \right\rfloor
}L^{r}E_{-2bq}\left( \Delta _{\overline{\partial },P}\left(
q\right) \right) ,
\end{equation*}
where $E_{\lambda }\left( \Delta _{\overline{\partial },P}(q)\right)$ denotes the eigenspace of $\Delta_{\overline\partial}$ restricted to primitive forms corresponding to eigenvalue $
\lambda $. In particular, for $q>0$, $\mathcal{H}_{\overline{\partial }
}^{m}\left( q\right) =\mathcal{H}_{\overline{\partial },P}^{m}\left(
q\right) $. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Theo2 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Suppose that assumptions (A1 of the paper)-(A8 of the paper) hold and let 
$\varphi$ be an $h$-dependent descendant characteristic, for some $h \in \mathbb{N}_{0}$, satisfying (C1 of the paper)-(C5 of the paper). Suppose also that $m_{t}^{\mathbb{E}[\varphi]}$ satisfies (E1 of the paper). Let $n \coloneqq \max\{i \in \mathbb{N}_{0}: \rho_{i} >0\}$ with $n = -1$ if the set is empty; in that case we set $\rho_{-1} \coloneqq 0$. Then, there exists a finite constant $\sigma \geq 0$ such that, with
\begin{align}  
a_{t}^{2} \coloneqq \sigma^{2} + \frac{\rho_{n}^{2}}{2n+1}t^{2n +1}, \quad t >0,
\end{align}
\noindent it holds:
\begin{enumerate}[label=(\textbf{\roman*})]
\item if $\sigma^{2} = \rho_{n}^{2} = 0$, then there exists an individual characteristic $\phi$ such that 
\begin{align} 
t \in \mathbb{G}\cap \mathbb{R}_{+} \mapsto H(t) +  \sum_{0\leq |u| \leq h-1} (\varphi_{u}^{(h-|u|)}(t-S(u)) - \phi_{u}(t-S(u)))  + \sum_{|u| = h} r(t - S(u))
\end{align}
\noindent is a version of $t \in \mathbb{G}\cap \mathbb{R}_{+} \mapsto \mathcal{Z}^{\varphi}_{t}$. (If $h=0$, the sum $\sum_{0\leq |u| \leq h-1}$ in (equation eq68 of the paper) is defined to be $0$.) 
\item if $\sigma^{2}>0$ or  $\rho_{n}^{2} > 0$, then 
\begin{align}  
a_{t}^{-1} e^{-\frac{\alpha}{2}t} \left(\mathcal{Z}_{t}^{\varphi} - H(t) \right) \xrightarrow[]{\rm st} \left( \frac{W}{\beta} \right)^{1/2} \mathcal{N},
\end{align}
\noindent as $t \rightarrow \infty$, $t \in \mathbb{G}$,  where $\beta \in (0, \infty)$ is defined in (equation eq3 of the paper), $W$ is the limit of Nerman's martingale and $\mathcal{N}$ is a standard normal random variable independent of $\mathcal{F}$ (and thus of $W$).
\end{enumerate}

If $n =-1$, the constant $\sigma$ can be explicitly computed, specifically:
\begin{align} 
\sigma^{2} \coloneqq  \int_{\mathbb{G}} \mathbb{E}[(\chi^{(\varphi + (m^{\mathbb{E}[\varphi]} - \mathbb{E}[H_{\Lambda}])\ast \xi,h)}(s))^{2}] e^{-\alpha s}  \ell({\rm d} s),
\end{align}
\noindent where $\mathbb{E}[H_{\Lambda}]$ denotes the function $t \in \mathbb{R} \mapsto \mathbb{E}[H_{\Lambda}(t)]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition of arXiv:2606.13264, 'Interference Queueing Networks: A Replica Mean-Field Approach in the Symmetric Setting'] There exists $p$ such that \begin{equation}
        p=\mathbb{P}(q^p>0)
    \end{equation}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop approx_hyper of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] For $\mathsf{P}\in \mathcal P_{s,1}(\Gamma)$ with $\mathcal W^{elec}(\mathsf{P})<\infty$ there exists  $(\mathsf{P}^N)_{N\geq 1}\in \mathcal P_{s,1}(\Gamma)$ with
    $\mathsf{P}^N\xrightarrow{N\to \infty}\mathsf{P}$ weakly and 
    \begin{align*}
        \mathcal E(\mathsf{P}^N)\xrightarrow{N\to \infty}\mathcal E(\mathsf{P})
    \end{align*}and \begin{align*}
       \limsup_{N\to \infty}\limsup_{n\to \infty} (nN)^{-1}\left(\mathcal H(\mathsf{P}^N,nN)-B_{nN}\right)\leq \mathcal W^{elec}(\mathsf{P}). 
    \end{align*}
    Moreover, $\mathcal W^{mod}(\mathsf{P}^N)\to \mathcal W^{elec}(\mathsf{P})$ as $N\to \infty$.
    For $\xi \in \supp(\mathsf{P}^N)$ and $x\in \xi$ we have
    \begin{align}
    \inf\{y\in \supp(\xi):y>x\}-x\leq 2N.
    \end{align}
    Finally, it holds that $\int \xi(\Lambda_1)^2\mathsf{P}^N(d\xi)<\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 3 (cf.\ Section 2 of \cite{Chen2024}) of arXiv:2608.26598, 'Pinching cones for positive isotropic curvature in dimensions seven and eight'] If $S$ evolves by \eqref{eq:pullback-ode}, then
    \begin{equation}
        \begin{split}
            \dt\Ric(S)={}&2\bigl(S*\Ric(S)\bigr)-4b\,\Ric(S)^2
            +\frac4n\bigl(2b+(n-2)a\bigr)\Scal(S)\Ric(S)\\
            &+2\,\frac{n^2b^2-2(n-1)(a-b)(1-2b)}{n\bigl(1+2(n-1)a\bigr)}\,|\Rico(S)|^2\mathrm{id}
            +\frac4{n^2}(a-b)\Scal(S)^2\mathrm{id},
        \end{split}
    \end{equation}
    where $(S*\Ric)_{ik}=\sum_{p,q}S_{ipkq}\Ric_{pq}$, and $\dt\Scal(S)$ is given by
    \eqref{eq:scalar-evol}. In particular, $P+nQ=2+4(n-1)a$.

[Dfn 105 (discrete-time coefficients) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] We let $B^N$ be the piecewise constant function on $\R^5$ such that
for all $(t,\vy)\in I_d\times R_{\vl,j}$, we have
	\beq
	B^N (t,\vy) 
	\equiv \frac{\rho_{D,N}(I_d\times R_{\vl,j})}
		{\rho_{\vY,N}(I_d\times R_{\vl,j})}
	\stackrel{\eqref{e:review.b}}{=}
	(p^N)'(t)^{1/2} \cdot
	\bbb^{\frozen,N}(t,\vy)\,.\eeq
Likewise, let $V^N$ and $U^N$ be the piecewise constant functions on $\R^5$ such that
	\begin{align}

	V^N(t,\vy) 
	&\equiv 
	\frac{\rho_{V,N}(I_d\times R_{\vl,j})}
		{\rho_{\vY,N}(I_d\times R_{\vl,j})}
	\stackrel{\eqref{e:review.v}}{=}
	p^N(t) 
	\cdot \vvv^{\frozen,N}(t,\vy)\,,\\
	U^N(t,\vy) 
	&\equiv
	\frac{\rho_{U,N}(I_d\times R_{\vl,j})}
		{\rho_{\vY,N}(I_d\times R_{\vl,j})}
	\stackrel{\eqref{e:review.u}}{=}
	\Big[ p^N(t)\cdot
	t (p^N)'(t) 
	\Big]^{1/2}
	\cdot
	\uuu^{\frozen,N}(t,\vy)

	\end{align}
for all $(t,\vy)\in I_d\times R_{\vl,j}$. Similarly, for all $(t,\vy)\in I_d\times R_{\vl,j}$ we have the identities
	\beq
	\rrr^{\frozen,N}(t,\vy)
	= \frac{\rho_{\rrr,N}(I_d\times R_{\vl,j})}
		{\rho_{\vY,N}(I_d\times R_{\vl,j})}\,,\quad
	\www^{\frozen,N}(t,\vy)
	= \frac{\rho_{\www,N}(I_d\times R_{\vl,j})}
		{\rho_{\vY,N}(I_d\times R_{\vl,j})}\,.
	\eeq
It follows from Definitions~\ref{d:disc.coefficients} and \ref{d:discrete.occ} that $(B,V,U,\rrr)^N$ do not depend on $y^4$; we will often abuse notation and regard them as functions of $(t,y^1,y^2,y^3)\in\R^4$. Likewise, $\www^{\frozen,N}$ does not depend on $(y^1,y^2,y^3)$; we will often abuse notation and regard it as a function of $(t,y^4)\in\R^2$. We let  $\Psi^N\equiv(B,V,U)^N$.

[Lemma 17 of arXiv:2512.19517, 'Spiking and Resetting'] There exists a constant $C>0$ such that for any $\alpha \in (0,1/2)$ and $x\in (0,1)$, the following holds
\begin{equation}

\begin{split}
V^\varepsilon(x) &= - \log \varepsilon +  \log \Big(\frac{h(0)}{f(0)} \Big)  +  \log x + R_{V^\varepsilon} (x) 
\end{split}
\end{equation}
where 
\begin{equation}

\begin{split}
\vert R_{V^\varepsilon} (x) \vert \le C \big[ \varepsilon^{1/2 - \alpha}/{\mathfrak  h}(x) + \varepsilon^{2\alpha} {\mathfrak h}(x)  \big] \ .
\end{split}
\end{equation}

