body:
[Lemma 10 of arXiv:2608.12451, '2608.12451'] Let $(X,X')$ be an exchangeable pair with values in $\N_0$
and $X\in L^4(\PP)$, 
and define 
$D:=X'-X$.
 Suppose that, for some
$a>0$, $\theta>0$ and a random variable $R\in L^1(\Omega, \sigma\{X\}, \PP)$,
we have

\noi
\begin{align}
 \E[D |  X]=-a(X-\theta)+R.

\end{align}
Set $c_\theta:= (1-e^{-\theta})/\theta.$
Then,
\begin{align}
 &\dTV ( X, P_\theta  )
\leq c_\theta
 \bigg\{
 \E\Big|
 \frac{\E[D^2 |  X]}{2a}
 -\frac{X+\theta}{2}
 \Big|
 +\frac{\E[D^2(D^2-1)]}{6a}
 \bigg\}
 +\left(1+\frac{c_\theta}{2}\right)
  \frac{\E|R|}{a}.

\end{align}

[Thm 160 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Under the assumptions of Theorem~\ref{thm:IAMP-main}\ref{i:IAMP-main-chaotic}, for fixed $L,\epsilon,\delta$, we have 
  \beq
     \lim_{\eta\downarrow 0}
     \lim_{\upp\uparrow 1}
     \lim_{\linit\to\infty}
    \plim_{N\to\infty} \frac{(\hat{\by}^{\ubl},\tilde{\by}^{\ubl})}{N}
     =
     0\,.\eeq
(We note that the order of parameters is consistent with \eqref{eq:eta-delta-eps}.) (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 ({\cite{bhatt2022Prismsa}*{Lemma 4.22}}) of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Let \(A\to A'\) be a flat morphism of commutative rings, and let \(K^\bullet\) be a cosimplicial object of \(\mcalD(A)\). Assume that there exists an integer \(c\) such that \(K^n\in\mcalD^{\geq c}(A)\) for every integer \(n\geq0\). Then the canonical morphism
  \begin{equation}

    A'\otimes_A^L\Tot(K^\bullet)\to\Tot(A'\otimes_A^LK^\bullet)
  \end{equation}
  is an equivalence in \(\mcalD(A')\).

[Theorem 5 of arXiv:2607.23401, 'Limit Theorems for the Pitman-Yor Frequency Spectrum'] We have, for   $0<\lambda < 1$ and $\ell=0,1,\ldots$, the limit 
   \be
  \lim_{n\to\infty} \PP\big(S_n^\lambda(\alpha,\theta) =\ell\big)
= \frac{ 
(c(\lambda))^\ell\Gamma(\theta)
(\Gamma(1-\alpha))^{\theta/\alpha+\ell}
}
{\Gamma(\theta/\alpha) \ell!}
\int_0^\infty x^{\theta/\alpha+\ell-1}e^{-x\lambda^{-\alpha}}f_{Y_x(\alpha,\lambda)+ H_\ell(\lambda)}(1)\rmd x.
 \ee
  The right-hand side of \eqref{f28} 
defines a proper probability mass function. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2603.28093, 'Random Stability of Random Variables'] Pick a distribution $Q$ on $[0, \infty)$, and assume $G(Q) \ne \{1\}$ is nontrivial. Then let $N$ be any nontrivial random variable with distribution from $G(Q)$, and let $Y$ be the standard $N$-stable random variable. Then:
\begin{itemize} 
\item $\mathbb E[N\ln N] < \infty$ if and only if $\mathbb E[Y] < \infty$;
\item $\mathbb E[N\ln^{a+1} N] < \infty$ for a fixed $a > 0$ if and only if $\mathbb E[Y\ln^{a}Y] < \infty$;
\item $\mathbb E[N^k] < \infty$ for a fixed $k = 2, 3, \ldots$ if and only if $\mathbb E[Y^k] < \infty$. 
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:const_increm of arXiv:2412.03366, 'Regularity of Weighted Tensorized Fractional Brownian Fields and associated function space'] [ELLV]
For all {$\alpha \in [0,1]$ and $H \in (0,1)$}, there is a constant $c_1>0$ such that the rectangular increments of $\{X^{\alpha,H}_{(x_1,x_2)}\}_{(x_1,x_2) \in \mathbb{R}^2}$ satisfy 
$$ \mathbb{E}\big[ |\Delta  X^{\alpha,H}_{(h_1,h_2);(x_1,x_2)}|^2 \big]
  \,\,  \leq   c_1 \left(\max\{|h_1|,|h_2| \}^{1-\alpha}\min\{|h_1|,|h_2| \}^{1+\alpha}\right)^{2H}
$$
for all $(x_1,x_2),(h_1,h_2) \in \mathbb{R}^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 122 ({\cite{KO,RT,LTDMLS}}) of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] For any indices $i, j \in \{ x, y \}$, there exists $\mathfrak{a}_{ij} : \mathcal{T} \rightarrow \mathbb{R}$
                satisfying $\mathfrak a_{xy}=\mathfrak a_{yx}$ as well as the following two statements:
		\begin{enumerate} 
			\item For any $z \in \mathfrak{L}_{q;a,b,c}$, we have 
			\begin{flalign}
                          \displaystyle\sum_{i,j \in \{ x, y \}} 	\mathfrak{a}_{ij} (\nabla \mathcal{H}_{q;a,b,c} (z)) \cdot \partial_{ij} \mathcal{H}_{q;a,b,c} (z) = -q.

			\end{flalign}

			\item For any $\omega > 0$, there exists a constant $C = C(\omega) > 1$ such that the following holds. Whenever $\gamma\in\mathcal T$ with  $\dist (\gamma, \partial \mathcal{T}) \ge \omega$, we have
			\begin{flalign*} 
				C^{-1} \le \mathfrak{a}_{xx} (\gamma) \le C; \qquad |\mathfrak{a}_{xy} (\gamma)| \le C; \qquad C^{-1} \le \mathfrak{a}_{yy} (\gamma) \le C.
			\end{flalign*} 

		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor statequiv-bound of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] There exists $\beta_0(d)<\infty$ such that for every $\beta>\beta_0$, for every $k$, every $B\in \mathscr{B}_k$, 
    \begin{align*}
        \mathbb P(\mathsf{StatEquiv}_k(B)^c )\le \frac{1}{(2\ell_{k+1})^d} \frac{q_{k+1}}{10}\,.
    \end{align*}

