[Lemma lem5-1 of arXiv:2606.28631, '\Large \bf On the maximal displacement of subcritical branching random walks with stretche'] Assume {\bf(H2)} and $b\in (0,1)$. 
	\begin{itemize}
		\item[(i)] We have 
		\begin{align}
			\sup_{I\subset [0,\infty)}  \frac{e^{\lambda x^b}}{\ell(x)x^a }(T_1+T_2) \lesssim_\beta  e^{-\lambda x^{b}/2}.
		\end{align}
		\item[(ii)] Fix $\delta\in (0,1)$. For any $k\delta >x$ and $I= [(k-1)\delta, k\delta)$, it holds that 
		\begin{align}
		\frac{e^{\lambda x^b}}{\ell(x)x^a }(T_3+T_4)  \lesssim_\beta \frac{e^{ \lambda (k\delta)^b }}{\ell(k\delta)(k\delta)^a}.
		\end{align}
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 20 of arXiv:2608.30589, 'Vector-Valued Wavelet Bases as Hilbert $\mathbb{M}_m(\mathbb{R})$-Module Bases: A Construc'] Let $(\phi_1,\phi_2)$ and $(\psi_1,\psi_2)$ be an orthonormal $2$-multiwavelet system in $L^2(\mathbb{R})$
associated with an MRA, and set
$\phi=(\phi_1,\phi_2)^T$, $\psi=(\psi_1,\psi_2)^T$.
Then the vector-valued scaling functions $\{\Phi^i_k\}_{i\in\{1,2\},k\in\mathbb{Z}^2}$ and wavelet functions
$\{\Psi^i_{j,k}\}_{i\in\{1,\dots,6\},k\in\mathbb{Z}^2,\ j\ge 0}$ defined below form an orthogonal basis of
$L^2(\mathbb{R}^2,\mathbb{R}^2)$, where
\begin{equation*}
     \begin{cases}
        &\Phi^1_k(x,y)=(\phi_1(x-k_1)\phi_1(y-k_2),\phi_2(x-k_1)\phi_2(y-k_2))^T \\
        & \Phi^2_k(x,y)=(\phi_1(x-k_1)\phi_2(y-k_2),\phi_2(x-k_1)\phi_1(y-k_2))^T,
     \end{cases}
\end{equation*}
\begin{equation*}
     \begin{cases}
        &\Psi^1_{j,k}(x,y)=(\phi_1(2^jx-k_1)\psi_1(2^jy-k_2),\phi_2(2^jx-k_1)\psi_2(2^jy-k_2))^T \\
        & \Psi^2_{j,k}(x,y)=(\phi_1(2^jx-k_1)\psi_2(2^jy-k_2),\phi_2(2^jx-k_1)\psi_1(2^jy-k_2))^T\\
        &\Psi^3_{j,k}(x,y)=(\psi_1(2^jx-k_1)\phi_1(2^jy-k_2),\psi_2(2^jx-k_1)\phi_2(2^jy-k_2))^T \\
        & \Psi^4_{j,k}(x,y)=(\psi_1(2^jx-k_1)\phi_2(2^jy-k_2),\psi_2(2^jx-k_1)\phi_1(2^jy-k_2))^T,
\end{cases}
\end{equation*}
\begin{equation*}
\begin{cases}
   &\Psi^5_{j,k}(x,y)=(\psi_1(2^{j}x-k_1)\psi_1(2^{j}y-k_2),\psi_2(2^{j}x-k_1)\psi_2(2^{j}y-k_2))^T \\
   & \Psi^6_{j,k}(x,y)=(\psi_1(2^{j}x-k_1)\psi_2(2^{j}y-k_2),\psi_2(2^{j}x-k_1)\psi_1(2^{j}y-k_2))^T.
\end{cases}
\end{equation*}

