[Theorem thm:topevent of arXiv:2604.15146, 'Renormalised two-point functions of CLE$_4$ gaskets'] Let $n\geq 1$ be an integer. The following equality holds:
\begin{multline*}
-\log\mathbb{P}
\left(
\nexists \widetilde C_i^{\varepsilon_1,\dots,\varepsilon_n}
\text{ with a closed path }
\tilde \gamma \subset \widetilde C_i^{\varepsilon_1,\dots,\varepsilon_n}
\text{ such that }
\sum_{j=1}^{n}
\indx_{\tilde \gamma}(z_j)
\text{ is odd}
\right)
=
\\
\tilde\mu^{\rm loop}_{\widetilde D_{\varepsilon_1,\ldots,\varepsilon_n}}
\Big(
\sum_{j=1}^n \indx_{\tilde\gamma}(z_j)
\text{ odd}
\Big).
\end{multline*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 7 of arXiv:2609.02197, '2609.02197'] Let $\left(q,m\right) \in \left[1,+\infty\right[\times \mathbb{N}^*.$
\begin{enumerate}
\item We denote by $L^2\left(\left(\mathbb{R}_+\times \mathbb{T}^d\right)^m\right)$ the set of functions $g:\left(\mathbb{R}_+\times \mathbb{T}^d\right)^m\longrightarrow\mathbb{R}$ such that $g$ is a $\left(\mathcal{B}\left(\left(\mathbb{R}_+\times \mathbb{T}^d\right)^m\right),\mathcal{B}\left(\mathbb{R}\right)\right)$-measurable function and $$\int_{\left(\mathbb{R}_+\times \mathbb{T}^d\right)^m}\left|g\left(x\right)\right|^2\,\mathrm{d}x<+\infty.$$
\item We denote by $L^q\left(\mathbb{T}^d\right)$ the set of functions $g:\mathbb{T}^d\longrightarrow\mathbb{R}$ such that $g$ is a $\left(\mathcal{B}\left(\mathbb{T}^d\right),\mathcal{B}\left(\mathbb{R}\right)\right)$-measurable function and $$\int_{\mathbb{T}^d}\left|g\left(x\right)\right|^q\,\mathrm{d}x<+\infty.$$
We also define
\begin{align*} 
\left\Vert\cdot\right\Vert_{L^q\left(\mathbb{T}^d\right)}: L^q\left(\mathbb{T}^d\right) &\longrightarrow \mathbb{R}_+ \\ h & \longmapsto \left\Vert h\right\Vert_{L^q\left(\mathbb{T}^d\right)}=\left(\int_{\mathbb{T}^d}\left|h\left(x\right)\right|^q\,\mathrm{d}x\right)^{\frac{1}{q}}
\end{align*}
\item We denote by $L^\infty\left(\mathbb{T}^d\right)$ the set of functions $g:\mathbb{T}^d\longrightarrow\mathbb{R}$ such that $g$ is a $\left(\mathcal{B}\left(\mathbb{T}^d\right),\mathcal{B}\left(\mathbb{R}\right)\right)$-measurable function and there exists $\mu \in \mathbb{R}_+$ such that $\left|g\left(x\right)\right|\leq \mu$ $\mathrm{d}x$-almost everywhere on $\mathbb{T}^d.$
\\
We also define
\begin{align*} 
\left\Vert\cdot\right\Vert_{L^\infty\left(\mathbb{T}^d\right)}: L^\infty\left(\mathbb{T}^d\right) &\longrightarrow \mathbb{R}_+ \\ h & \longmapsto \left\Vert h\right\Vert_{L^\infty\left(\mathbb{T}^d\right)}=\mathrm{ess\,sup}_{x \in \mathbb{T}^d}|h\left(x\right)|
\end{align*}
\end{enumerate}

[Corollary 29 (Equivalent modified formulations) of arXiv:2607.26377, '\textbf{Entire Logarithmic Signatures\\ of Bounded-Variation Paths in Finite Dimensions}'] Let $V$ be a finite-dimensional real normed space, let $\gamma:[0,T]\to V$ be a continuous tree-reduced bounded-variation path, and put $v=\gamma_T-\gamma_0$. If $v\neq0$, then the following formulations are equivalent:
\begin{enumerate}[label=\textup{(\roman*)}]
\item centred weak path conjugacy to a line in the sense of \cref{def:two-conjugacies};
\item conjugacy to $\e^v$ in the reduced bounded-variation path group;
\item a signature identity $S(\gamma)=a\e^v a^{-1}$ with $a\in\Sl(V)$.
\end{enumerate}
When $v=0$, the corresponding formulations all reduce to the constant reduced path. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 8 (Minimal primitive support) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] For $1\le s\le Q$, define
\begin{equation}
 \cS_s(F)
 =\ol{\Span}
 \left\{
 \Ran\mathscr L_{a,q,\bm m}^{(s)}:
 1\le a\le d,\ q\le Q,\ m_s\ge1
 \right\}\subset E_s.

\end{equation}
Put $\cS(F)=\bigoplus_{s\le Q}\cS_s(F)$.

[Corollary cor:ordered-generic-type-diversity of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] For each fixed $k\geq3$, as $h\to\infty$, both the number of realized ordered
$h$-addition-table types and the number of realized generic $B_h$-types
are
\begin{equation}
 \Theta_k\!\left(h^{(k-1)(k-2)}\right).
\end{equation}

[Lemma lem:brownian-ball-localization of arXiv:2609.02829, 'Quantitative explosion and percolation of the divisible sandpile'] Assume $d<4$. For every $0<T<\infty$ there are $C=C(d)>0$ and $c=c(d)>0$
	such that, for every $A\geq1$ and every compact $K\subset\mathbb{R}^d$,
	\[
		\sup_{u\in K}
		\bigl(\mathcal U_Z(T,u)-\mathcal U_{Z,A}(T,u)\bigr)
		\leq
		Ce^{-cA^2/T}
		\sup_{\substack{z\in\mathbb{R}^d:\\ \inf_{y\in K}|z-y|\leq A}}
		\mathcal U_Z(T,z)\, .
	\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 43 of arXiv:2608.12947, 'Branch-stationary max-stable fields on rooted trees'] Assume (equation 42 of the paper) and define the law of a random field
\(Z^{Q,\pi}\) on \(\mathcal T\) by
\begin{equation}
  \Ehat{H(Z^{Q,\pi})}
  =
  \frac1{c_Q}
  \sum_{g\in\mathbb G}
  \E*{
    \rho_\pi(Q^{[g]})^\alpha
    H\left(
      \frac{Q^{[g]}}{\rho_\pi(Q^{[g]})}
    \right)
  }, \qquad H \in \mathfrak H.

\end{equation}  On
\(\{\rho_\pi(Q^{[g]})=0\}\), the ratio in
(equation 44 of the paper) may be defined arbitrarily and the
corresponding summand is understood to be zero. If
\(\widehat{\mathbb P}_\pi\) stands for the resulting probability measure,
then:
\begin{enumerate}[(i)]
\item (equation 44 of the paper) is a probability law,
\[
  \rho_\pi(Z^{Q,\pi})=1
  \quad\text{almost surely},
  \qquad
  \Ehat{(Z_v^{Q,\pi})^\alpha}=1,
  \quad v\in\mathcal T;
\]
in particular, \(Z^{Q,\pi}\neq\mathbf 0\) almost surely;
\item \(Z^{Q,\pi}\) is almost surely \(\alpha\)-summable, i.e.,
\[
  \sum_{v\in\mathcal T}(Z_v^{Q,\pi})^\alpha<\infty;
\]
\item for every \(F\in\mathfrak H_\alpha\),
\begin{equation}
  \Ehat{F(Z^{Q,\pi})}
  =
  \frac1{c_Q}
  \sum_{g\in\mathbb G}\E{F(Q^{[g]})}.

\end{equation}
Consequently, \(Z^{Q,\pi}\) is branch-BR stationary, and its
homogeneous class does not depend on \(\pi\);
\item its tail measure is
\begin{equation}
  \nu_Q(A)
  =
  \frac1{c_Q}
  \sum_{g\in\mathbb G}
  \int_0^\infty
  \mathbb P\{rQ^{[g]}\in A,\ Q^{[g]}\neq\mathbf 0\}
  \alpha r^{-\alpha-1}\mathrm d r,
  \qquad A\in\mathcal B(\mathcal F),

\end{equation}
and satisfies
\begin{equation}
  \nu_Q\bigl((B^u)^{-1}A\bigr)
  =
  \nu_Q(A),
  \qquad
  A\in\mathcal B(\mathcal F^\circ),\quad u\in\mathcal T;

\end{equation}
\item the root spectral tail field \(\Theta^Q\) is independent of
\(\pi\) and satisfies
\begin{equation}
  \E{H(\Theta^Q)}
  =
  \frac1{c_Q}
  \sum_{g\in\mathbb G}
  \E*{
    \mathbf 1_{\{Q_g>0\}}
    Q_g^\alpha
    H\left(
      \left(\frac{Q_{gv}}{Q_g}\right)_{v\in\mathcal T}
    \right)
  }, \qquad F\in\mathfrak H.

\end{equation}
The summand is understood to be zero on \(\{Q_g=0\}\). In particular, $
  \mathbb P\{\sum_{v\in\mathcal T}(\Theta_v^Q)^\alpha<\infty\}=1$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 108 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Recalling the definition of $k$ from \eqref{eq:h0new}, set 
	\begin{flalign*}
		x^{\pm} =\bar{x} \pm N^{B\delta/9} \td_{\bar{z}}
	\end{flalign*} 

	\noindent and let ${\bf L}^{\pm}$ denote the line parallel to the $y$-axis and with $x$-coordinate $x^\pm$.

[Corollary cor:global_subgraph_clt of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Assume that there are sequences $\sigma_n \gtrsim n$ and $\delta_n \to 0$ such that
\begin{equation}
    \mathbf{d}_\mathrm{Was}\mleft(\frac{\mathsf{E}(X) - \mathbb{E}[\mathsf{E}(X)]}{\sigma_n}, Z \mright) \leq \delta_n,
\end{equation}
where $Z \sim \mathcal{N}(0,1)$.
Then for all $\varepsilon > 0$,
\begin{equation}
    \mathbf{d}_\mathrm{Was}\mleft(\frac{\mathsf{N}_G(X) - \mathbb{E}[\mathsf{N}_G(X)]}{2 \mathsf{e} p^{\mathsf{e}-1} n^{\mathsf{v}-2} \sigma_n}, Z\mright)
    \lesssim n^{-\frac{1}{2}+\varepsilon} + \delta_n.
\end{equation}

