body:
[Theorem thm:main of arXiv:2608.18293, 'Critical tensor covariance at the Marchenko--Pastur threshold'] Assume (equation eq:base-assumptions of the paper) and (equation eq:critical-scaling of the paper). Then the
empirical spectral distribution of $S_n$ converges weakly almost surely to a
deterministic probability measure $\mu_{c,\lambda,v}$ on $[0,\infty)$. Its
Stieltjes transform $m(z)$ is characterized as the unique $m(z)\in\mathbb{C}_+$
satisfying
\begin{equation}
  1+z m(z)
  =m(z)\int_{0}^{\infty}
  \frac{r}{1+cr m(z)}\,\nu_{\lambda,v}(\,\mathrm{d} r),

\end{equation}
or equivalently
\begin{equation}
  \boxed{
  \frac1{m(z)}+z
  =\mathbb{E}\left[\frac{R}{1+cRm(z)}\right].}

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:inv_mp of arXiv:2412.04589, 'Inverting the Markovian projection for pure jump processes'] Let Assumption~(asm:1 of the paper) hold. Suppose that $\Omega$ supports a sequence of i.i.d.\ $\operatorname{Exp}(1)$ random variables $(E_k)_{k \in \mathbb{N}^*}$ which is independent of $\mathcal{F}_\infty$. Then, there exist an enlarged filtration $\mathbb{G}$ (satisfying the usual conditions) and a counting process $X$ adapted to $\mathbb{G}$ such that the process
	\begin{equation}
		X_t - \int_0^t \frac{\eta_s}{\mathbb{E}[\eta_s \,|\, X_{s-}]} \lambda(s, X_{s-}) \,ds,\quad t \geq 0,
	\end{equation}
	is a $\mathbb{G}$-martingale. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem SRWestimates of arXiv:2411.13926, 'Random walks on random walks:\\ non-perturbative results in high dimensions'] Let $(Y_t)_{t \in \ensuremath{\mathbb{Z}}}$ be a simple random walk on $\mathbb{Z}^d$ with $d\geq 3$.
\begin{enumerate}
\item There exists $\delta>0$ such that 
\begin{equation} 
\inf_{\gamma\in \Gamma_{-\infty}} P_{o,0}^{RW} \big( Y_i \neq \gamma_i \text{ for all } i \in [-|\gamma|,-1] \big)>\delta.
\end{equation}
\item There exists $C<\infty$ 
such that, for any $\gamma \in \Gamma_{-\infty}$, $t \leq |\gamma|$ and $s>t$, 
\begin{equation} 
\sup_{z \in \ensuremath{\mathbb{Z}}^d} P_{o,0}^{RW} (Y_{-s} = z \mid Y_i \neq \gamma_i \text{ for all } i \in [-t,-1] ) \leq Cs^{-d/2}. \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

