	{\mathcal{F}}'(t) + \Gamma_{10} {\mathcal{F}}(t)
	+ \Big\{ \Gamma_{10} - \Gamma_{11} {\mathcal{F}}^{\kappa_1}(t) \Big\} \cdot \int_\Omega |\nabla v|^{p-2} |D^2 v|^2
	\le \Gamma_{11} {\mathcal{F}}^{\kappa_2}(t)
	\qquad \mbox{for all } t\in (0,T).
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 (Well-posedness of the SDE to transition path process) of arXiv:2506.09462, 'Transition Path Theory For L\'{e}vy-Type Processes: SDE Representation and Statistics'] Let \((\widehat{W}, \mathcal{F}_t^{\widehat{W}})\) be a standard Brownian motion in \(\mathbb{R}^d\), and let \(\widehat{N}\) be an independent Poisson random measure on \([0, \infty) \times (\mathbb{R}^d \setminus \{0\}) \times [0, \infty)\) with intensity measure \(m \times \nu \times m\). Both are defined on a probability space \((\widehat{\Omega}, \widehat{\mathcal{F}}, \mathbb{Q})\).  Let \(\xi : \widehat{\Omega} \to \bar{A}^c \cap (A + 1)\) be a random variable defined on the same probability space and independent of \(\widehat{W}\) and \(\widehat{N}\). Then, there exists a unique c\`{a}dl\`{a}g process \(Y_t : [0, \infty) \to \mathbb{R}^d\), adapted to the augmented filtration \(\widehat{\mathcal{F}}_t\), which satisfies the following equation \(\mathbb{Q}\)-almost surely:
    \begin{equation*}
        \begin{aligned}
            Y_t = &\ \xi + \int_0^{t \wedge \tau_B} K(Y_{s-}) \d s 
            + \int_0^{t \wedge (\tau_A \wedge \tau_B)} \sigma(Y_{s-}) \d \widehat{W}_s \\
            &\ + \int_0^{t \wedge (\tau_A \wedge \tau_B)} 
            \int_{[0, \infty) \times \{|r| < 1\}} 1_{[0, \lambda(Y_s, r)]} F(Y_{s-}, r) \widetilde{\widehat{N}}(\d v, \d r, \d s), \quad t \geq 0,
        \end{aligned}
    \end{equation*}
    where \(\tau_B = \inf\{t \geq 0 \mid Y_t \in \bar{B}\}\) and \(\tau_A = \inf\{t \geq 0 \mid Y_t \in \bar{A}\}\). Moreover, \(Y_t \notin \bar{A}\) for all \(t > 0\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2606.30349, 'Attenuated Poisson Dirichlet approximations for divisibility configurations'] Let $\mu,\nu$ be elements in $\mathrm{Lv}(\mathbbm{X})$, satisfying $\mu\preceq\nu$. Then there exists a coupling of two sequences $\{X_k^1;\,k\ge1\}$ and $\{X_k^2;\,k\ge1\}$ such that $X_k^1 \le X_k^2$ for all $k\ge1$, and
\begin{align*}
\rho_{\mu_i}
=
\mathrm{Law}\big(\sum_{k\ge1} \mathbbm{1}_{\{X_k^i>0\}}\delta_{X_k^i}\big),
\end{align*}
for $i=1,2$, where $\mu_1=\mu$ and $\mu_2=\nu$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 39 (No extremal pair) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] Let $\alpha > \sigma$, let $X \in \SE(\sigma^2,\alpha)$, and let $f \colon \R \to \R$ be convex and non-affine with $\E[f(\alpha \Lap)] < \infty$. Then $\E[f(X)]$ is finite and
\begin{align*}
    \E[f(X)] < \E[f(\alpha \Lap)] \, .
\end{align*}
The multiple $\alpha\Lap$ has no extremal pair, in contrast with the regime $\alpha \le \sigma$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:sphere-volume of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:sphere-volume}
\begin{equation}
 \lim_{N\to\infty}\frac1N\log\omega_N
 =\frac12\log(2\pi e).
\end{equation}

