body:
[Definition 4 (Caputo fractional derivative) of arXiv:2608.25164, 'A time-fractional Kalman filter'] Let $\alpha>0$ and let $n=\lceil\alpha\rceil$. The Caputo derivative is
defined by
\begin{align}
D_C^\alpha f(t)
&=I^{n-\alpha}f^{(n)}(t)\nonumber\\
&=\frac{1}{\Gamma(n-\alpha)}
  \int_0^t(t-s)^{n-\alpha-1}f^{(n)}(s)ds,
  \qquad n-1<\alpha<n,
\end{align}
while $D_C^n f=f^{(n)}$ when $\alpha=n$.

[Theorem 1 of arXiv:2511.09280, 'Random Walk conditioned to stay above a non-flat floor: curvature effects'] Let \(X, X_1,X_2,\dots\) be an i.i.d.\ family of \(\Z\)-valued, irreducible, aperiodic random variables satisfying~\eqref{eq:conditions_steps}. Let \(a_*,b_*\) be defined as in~\eqref{eq:dual_allowed_slopes}, and \(a_*<a<b<b_*\). Let \(h\in C^2([0,1])\) be a non-negative concave function with \(h''<0\), \(\mathrm{Image}(h')\subset H_X'([a,b])\), and \(h(0)=0\). Define
    \begin{equation*}
        h_n(k) = nh(k/n),\quad k=0,\dots, n.
    \end{equation*}
    Then, there are \(c_+\geq c_- >0, n_0\geq 1\) such that for any \(n\geq n_0\),
    \begin{equation*}
        e^{-c_+n^{1/3}}
        \leq
        e^{n\int_{0}^1 I(h'(s))ds} P\bigl(S\geq h_n, S_n = \lceil h_n(n)\rceil\bigr)
        \leq
        e^{-c_-n^{1/3}},
    \end{equation*}
    where \(S_0=0\), \(S_k=S_{k-1}+X_k\) and \(I(x) = \sup_{\lambda} \bigl(\lambda x - H(x)\bigr)\).

[Definition def:complex-SaS of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] A \emph{complex isotropic S$\alpha$S random measure}
$\widetilde{M}_\alpha$ on $\mathbb{R}$ with Lebesgue control measure
is a complex random measure such that, for every
$f \in L^\alpha(\mathbb{R},\mathbb{C})$:
\begin{equation}

\mathbb{E}\!\left[\exp\!\left(
i\,\mathrm{Re}\int_\mathbb{R} f(\xi)\,d\widetilde{M}_\alpha(\xi)
\right)\right]
= \exp\!\left(-c_\alpha\int_\mathbb{R}|f(\xi)|^\alpha\,d\xi\right),
\end{equation}
where
\begin{equation}

c_\alpha
:= \frac{1}{2\pi}\int_0^{2\pi}|\cos\theta|^\alpha\,d\theta
= \frac{\Gamma\!\left(\frac{\alpha+1}{2}\right)}
{\sqrt{\pi}\;\Gamma\!\left(\frac{\alpha}{2}+1\right)}.
\end{equation}
The measure $\widetilde{M}_\alpha$ is \emph{isotropic}: for every
$\phi \in \mathbb{R}$, $e^{i\phi}\widetilde{M}_\alpha(\cdot)
\overset{d}{=} \widetilde{M}_\alpha(\cdot)$.

[Lemma lem:somevsall_tail_conditions of arXiv:2509.02074, 'On the Kolmogorov-Feller weak law of large numbers for the Fr\'{e}chet mean on non-compact'] Let $(M,d)$ be a metric space, and let $(X_i)_{i=1}^\infty$ be a sequence of independent $M$-valued random variables. For an $m \in M$, let $c_1(m)$, $c_2(m)$ and $c_3(m)$ denote the following conditions, respectively: 
\begin{align*}
   c_1(m): & \lim_{n\to\infty} n\mathbb{P}(d(X_1,m) > n) = 0;\\
   c_2(m): & \lim_{n\to\infty} n^{-2}\sum_{i=1}^n\mathbb{E}[d^2\{\overline{X_{n,i}}(m),m\}] = 0;\\
   c_3(m): & \lim_{n\to\infty} \sum_{i=1}^n\mathbb{P}(d(X_i,m) > n) = 0.
\end{align*}
\begin{itemize}
    \item[(i)] For any $m,m' \in M$, $c_1(m)$ holds if and only if $c_1(m')$ holds.
    \item[(ii)] For any $m,m' \in M$, $c_2(m)$ holds if and only if $c_2(m')$ holds.
    \item[(iii)] Additionally assume that $M$ is a symmetric space and,  for a given $\mu \in M$, $\mathbb{P}_{X_i}$ is geodesically symmetric about $\mu$. Then, for any $m \in M$, $c_3(\mu)$ holds if $c_3(m)$ holds.
\end{itemize}

