body:
[Theorem thm:main of arXiv:2503.21737, 'High-intensity Voronoi percolation on manifolds'] Let $M$ be a connected, complete, $d$-dimensional Riemannian manifold satisfying the following conditions 
\begin{enumerate}[i)]

    \item $M$ has positive global injectivity radius \(r_\text{inj}(M)>0\),\footnote{See Section (sec:localcomparison of the paper) or [LeeRM] for a precise definition.}

    \item the sectional curvatures of M are uniformly bounded from above and from below,\footnote{see, e.g., [LeeRM] for a definition and an introduction to sectional curvatures.}

    \item $M$ is simply connected and one-ended,\footnote{We call $M$ \emph{one-ended} when $M\setminus B$ has exactly one unbounded connected component for any bounded $B\subset M$.}

    \item there exists a log-expanding, bi-infinite path in $M$, i.e., a Lipschitz continuous path $\gamma:(-\infty,\infty)\to M$ satisfying, for some constants $c,C\in(0,\infty)$, the inequality
        \begin{equation}
            \mathrm{d}_{M}(\gamma(t),\gamma(s))\geq c\log |t-s|-C ~~~ \text{ for all } t,s\in(-\infty,\infty).
        \end{equation} 
\end{enumerate} 

Then, both $p_c(M,\lambda)$ and $p_u(M,\lambda)$ converge to $p_c(\mathbb R^d)$ as $\lambda\rightarrow \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn 14 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] We say that a continuous function $m:\mc{T}_{\A{1},\A{2}}\to (0,+\infty)$ is an order function on $\mc{T}_{\A{1},\A{2}}$ if there exist $C_0>0$ and $N_0\geq 0$ such that for all $\rho$, $\mu\in \mc{T}_{\A{1},\A{2}}$
    \begin{equation*}
        m(\rho)\leq C_0\jap{\rho-\mu}_{\mc{T}_{\A{1},\A{2}}}^{N_0}m(\mu)
    \end{equation*}
    with $\jap{\rho}_{\mc{T}_{\A{1},\A{2}}}=\pr{1+\bb{\rho}_{\mc{T}_{\A{1},\A{2}}}}^{1/2}$, where for $\rho=(x,\xi)\in \mc{T}_{\A{1},\A{2}}$,
    \begin{equation}
        \bb{\rho}_{\mc{T}_{\A{1},\A{2}}}:=\inf\limits_{{\gamma_1,\gamma_2\in \Z^d}}\pr{\bb{x-\Ab{1}\gamma_1}^2+\bb{\xi-\Ab{2}\gamma_2}^2}^{\frac{1}{2}}.

    \end{equation}

[Lemma l:BL-limits-moments of arXiv:2605.28430, 'Limit theory for Lipschitz-localized statistics in random geometric models'] Let  $\tilde{\mathcal{P}}$  be a marked point process on $\mathbb{R}^d\times\mathbb{K}$ with non-null, finite intensity $\rho$.  Let $\xi : \mathbb{R}^d \times \mathbb{K} \times \hat\mathcal{N}_{\mathbb{R}^d \times \mathbb{K}} \to \mathbb{R}$ be an real-valued score function which is \textnormal{BL}-localizing on all finite windows  for Palm distributions of some order $q\in \mathbb{N}$ (that is~(equation Lp-stab of the paper) holds  with  $p$ replaced by  $q$,  with  uniformly bounded correlation function $\rho^{(q)}$).
\begin{enumerate}[wide,label=(\roman*),labelindent=0pt]
\item  
If $\xi$ satisfies the $(p + \epsilon)$-moment condition on finite windows~(equation e:xinpmomcopied of the paper) for some $p\geq q$ and some $\epsilon > 0$, then the random variables $\Upsilon_{\bk{x}{1}{q}}[i],1  \leq i \leq q$ have uniformly bounded $p$-moments, namely 

\begin{equation}
\sup_{x_1,\ldots,
  x_{q} \in \mathbb{R}^d}\max_{i=1,\ldots,q} \mathbb {E} [\max(1,|\Upsilon_{ \bk x1q}[i]|^p)]\le M^\xi_p.
  \end{equation}

\item 
Furthermore, under the assumptions of part ~(i.BL-limit-p-moment of the paper) above, we also obtain the speed of convergence of (natural) moments $p\in\mathbb{N}$; namely for $x_1,\ldots,x_q \in W_n$ we have

\begin{equation}
\max_{i=1,\ldots,q} 
      \Big | \mathbb {E} _{\bk x1{q}}[ (\xi(\tilde{x}_i,\tilde{\mathcal{P}}_n))^p]-\mathbb {E} [(\Upsilon_{\bk x1q}[i])^p]\Bigr| \le  (2M_{p+\epsilon/2}^\xi+6p)\varphi_{q} (d(\bk x1q,\partial W_n))^{\epsilon/(2p+\epsilon)},
  \end{equation}

  where $d(\bk x1q,\partial W_n)$ is the distance  between $x_1,\ldots,x_q \in W_n$ and the boundary of $W_n$.
  \item 
  If $\xi$ is \textnormal{BL}-localizing on all finite windows    of Palm order $q=2$ as in~(equation Lp-stab of the paper) and  satisfies the $(2+\epsilon)$-moment condition on finite windows~(equation e:xinpmomcopied of the paper) for some $\epsilon > 0$, then the  vector $\Upsilon_{\bk{x}{1}{2}}$ has uniformly bounded correlations, i.e.,  
\begin{equation}
\sup_{x_1,x_2 \in \mathbb{R}^d} 
 \mathbb {E} [\max(1,|\Upsilon_{\bk x12}[1]\Upsilon_{\bk x12}[2]|)] 
  \le M^\xi_2.
  \end{equation}
\item 
Furthermore, under the assumptions of part ~(i.BL-correlation-bound of the paper), the correlations have the speed of convergence:
\begin{equation}
  \Big | \mathbb {E} _{\bk x1{2}}[\xi(\tilde{x}_1,\tilde{\mathcal{P}}_n)\xi(\tilde{x}_2,\tilde{\mathcal{P}}_n)]-\mathbb {E} \bigl[\Upsilon_{\bk x12}[1]\Upsilon_{\bk x12}[2]\bigr]\Bigr| \le  (4M^\xi_{2+\epsilon/2} + 12)\varphi_{2}(d(\bk x12,\partial W_n))^{\epsilon/(4+\epsilon)}\,,
  \end{equation}
  where $ d(\bk x12,\partial W_n)$ is the distance between $\{x_1, x_2\}\subset W_n$ and the boundary of $W_n$.
  \end{enumerate}

[Lemma lem:global_step_concentration of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] For $\alpha \in (0,\frac{1}{2})$ there is some $c > 0$ such that
\begin{equation}
    \mathbb{P} \mleft[ | \mathsf{N}_G(X,e) - 2 \mathsf{e} p^{\mathsf{e}-1} n^{\mathsf{v}-2} | > n^{\mathsf{v} - 2.5 + \alpha} \mright]
    \leq \Exp{- c n^{2\alpha}}.
\end{equation}

[Lem 213 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Recall $\by(q_{d+1})$ defined in \eqref{e:normalized.vectors.y}. With probability at least $1-\exp(-N^{0.1})$, we have 
    \[
    \bigg|\frac{\|\by(q_{d+1})\|^2}{N}-1\bigg|
    \le \frac{1}{N^{1/4}}\]
for all $0\leq d\leq \dmax-1$.

\begin{proof}
Recalling \eqref{e:normalized.vectors.y}, we have
    \[
    \frac{\|\by(q_{d+1})\|^2}{N}
    =
    \frac{1}{\delta_d}
    \bigg(
    \frac{(\bx(q_{d+1}),\bx(q_{d+1}))}{N}
    -
    \frac{2(\bx(q_{d+1}),\bx(q_{d}))}{N}
    +
    \frac{(\bx(q_{d}),\bx(q_{d}))}{N}
    \bigg)\,.\]
Applying Lemma~\ref{l:nearly.ultrametric} to each term on the right-hand side gives 
    \[
    \frac{\|\by(q_{d+1})\|^2}{N}
    =\frac{1}{\delta_d}
    \bigg\{q_{d+1}-q_d +\frac{O(1)}{N^{1/3}} \bigg\}
    = 1 + O\bigg(\frac{1}{\delta_d N^{1/3}}\bigg)
    \]
for all $0\le d\le \dmax$, with probability at least $1-\exp(-N^{0.1})$.
The claim follows by sending $N\to\infty$ fast enough depending on $\delta$, as discussed in Assumption~\ref{a:params}.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 38 of arXiv:2608.27307, '2608.27307'] Suppose that the assumptions of Theorem~\ref{thm:rand_sc_eq} hold. Suppose that $\|R_G\|=O(1)$ with high probability. Then
        \begin{align}
                R_G\Om(G,z)=O_\prec(\psi_\phi(z)), \qquad
                \avg{BR_G\Om(G,z)}_L=O_\prec(\psi_\phi(z)^2) \nonumber
        \end{align}
        uniformly for deterministic $B$ with $\|B\|\leq1$.

[Lemma 14 of arXiv:2606.31528, 'Well-posedness and stationary distribution of free stochastic differential equations'] For $T\in[0,\infty)$, and $n\in\mathbb{N},$ let $\mathcal{P}_n: 0=t_0 < t_1<\cdots < t_{n-1} < t_n =T$ be 
an uniform partition of $[0,T]$ with mesh $1/n$ and $X^{(n)}_t$ be a piecewise-constant $\mathscr{A}_{\le t}$-adapted process such that
\begin{equation*}
X_t^{(n)} = X_{t_{j-1}}^{(n)}, \quad \forall t \in \bigl[t_{j-1},\, t_j\bigr), \; j = 1, \dots, n.
\end{equation*}

Similarly, for $m\in\mathbb{N},$ let $\mathcal{P}_m: 0=s_0 < s_1<\cdots < s_{m-1} < s_m =T$ be 
another uniform partition of $[0,T]$ with mesh $1/m.$ Let  $Y^{(m)}_t$ be a piecewise-constant $\mathscr{A}_{\le t}$-adapted process such that
\begin{equation*}
Y_t^{(m)} = Y_{s_{j-1}}^{(m)}, \quad \forall t \in \bigl[s_{j-1},\, s_j\bigr), \; j = 1, \dots, m.
\end{equation*}

If $Z_t$ is an $\mathscr A_{\le t}$-adapted process such that
\begin{equation*}
\sup_{t\in[0,T]}\|Z_t\|_2<\infty,
\end{equation*}
then for any $n,m\in\mathbb{N},$ we have 
\begin{equation}
\tau\!\left( \int_0^T Z_s X_s^{(n)}\, {\rm d}W_s \, Y_s^{(m)} \right) =\tau\!\left( \int_0^T X_s^{(n)}\, {\rm d}W_s \, Y_s^{(m)} Z_s\right) = 0.
\end{equation}

[Corollary cor:lbm-square-interface of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] The map $L$ takes values in $\mathcal M_{\rm fin}(D)$, and each $b_i$ is a finite
positive Radon measure.  Moreover,
\begin{equation}
 M_x\perp\mathcal L^2,\qquad \operatorname{supp}M_x=D,\qquad b_i\ll\mathcal L^2,\qquad L(\phi_i^2)=2\Lambda_i\phi_i^2M_x-b_i,\quad 1\le i\le M.

\end{equation}

