[Lemma lem:finite-time-w2-stability of arXiv:2607.00149, '\bf Uniform-in-time Propagation-of-Chaos for\\ Stein Variational Gradient Descent'] Under Assumption~(ass:Wass of the paper), let $(\mu_t)_{0\le t\le T}$ and $(\nu_t)_{0\le t\le T}$ be two (weak) solutions of~(equation eq:mf-svgd of the paper). 
Also, suppose that for every $T \in (0,\infty)$, there is $M_T<\infty$ such that, writing $ m_2(\rho):=\int \left\|x\right\|^2\,\rho(dx)$,
    \begin{equation}
        \int_0^T\{1+m_2(\mu_t)+m_2(\nu_t)\}\,dt\le M_T.
    \end{equation} Then there exists a finite constant $C>0$, depending only on the constants in the bounds of Assumption~(ass:Wass of the paper), such that for any $T>0$,
\begin{equation}
    \sup_{0\le t\le T}W_2(\mu_t,\nu_t)
    \le
    \exp\{C M_T\}\,W_2(\mu_0,\nu_0).
\end{equation}

[Lemma 72 of arXiv:2601.16377, '2601.16377'] Suppose that Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic} and \ref{Assumptions_offcrit}
 hold. Assume that $\mathfrak{b}$ is finite. For any $\zeta_2 \in \big(0,\frac{\mathfrak{b} - \mathfrak{a}}{2}\big)$,
there exists $C > 0$ depending only on the constants in the assumptions and $\zeta_1 \in (0,\zeta_2)$ (which may depend on all the data), such that
\begin{equation}

 \inf_{x\in [\mathfrak{a}+\zeta_2, \mathfrak{b}]} \big(V^{\textnormal{eff}}_h(x) - V^{\textnormal{eff}}_h(\mathfrak{a}+\zeta_1)\big)\geq \frac{1}{C},
\end{equation}
and
\begin{equation}

 V^{\textnormal{eff}}_h(\mathfrak{a}+\zeta_1)=\inf_{x\in [\mathfrak{a}+\zeta_1,\mathfrak{b}]} V^{\textnormal{eff}}_h.
\end{equation}
Moreover, there exist $\zeta_1^\pm$ depending only on $\zeta_2$ and the constants in the
assumptions such that the choice of $\zeta_1$ can be made to obey $0<\zeta_1^-<\zeta_1<\zeta_1^+<\zeta_2$.

[Definition discreteW of arXiv:2605.10617, 'Logarithmic scaling of selective sweep curves:\\ from tents to houses'] Let  
  $$\mathbb W:=\{w=(w(0),w(1), \ldots)\mid w(n) \in \mathbb Z, w(n+1)-w(n) \in \{-1,1\}, n \in \mathbb{N}_0\},$$
  and for $p\in (0,1)$ let $(W, (\mathbb{P}_k^p)_{k\in \mathbb{Z}})$ be the canonical model of a (discrete-time) random walk with step size~1 and upward transition probability  $p$. (In particular, $\mathbb{P}_k^p(W(0)=k)=1$ , $\mathbb{P}_k^p(W(1)=k+1)=p$.)

  For $k \in \mathbb{N}_0$ and $w \in \mathbb W$ let
\begin{equation}
    \tau_k(w):= \min\{n\in \mathbb{N}_0\mid w(n) =k\}, \quad \tau_k^+(w):= \min\{n\in \mathbb{N}\mid w(n) =k\},
\end{equation}
be the first visit time of $k$ and the first return time to $k$, respectively, and let
\begin{equation}
    \sigma_k(w):= \max\{n\in \mathbb{N}_0\mid w(n) =k, \, w(j) \in \mathbb{N} \mbox{ for } j \in \{0, \ldots, n-1\}\}
\end{equation}
be the time of the last visit of $k$ before $w$ hits $0$.

[Conjecture conj:barcode_density_limit of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] The following limits
	\begin{equation*}
	\rho_0(t)\coloneqq
		\lim_{M\to\infty}
		\mathfrak{a}(1-\tfrac{t}{2})
		\sum_{n=0}^{M+1/2}
		\frac{-q^{-n}
		\mathcal{F}_n^t(0)\mathcal{F}_n^{t-1}(0)
		}{\|\mathcal{F}_n\|^2_{\ell^2(\mathbb{Z})}}
		,\quad
		\rho_1(t)\coloneqq
		\lim_{M\to\infty}
		\mathfrak{a}(1-\tfrac{t}{2})
		\sum_{n=0}^{M}
		\frac{-q^{-n}
		\mathcal{F}_n^t(0)\mathcal{F}_n^{t-1}(0)
		}{\|\mathcal{F}_n\|^2_{\ell^2(\mathbb{Z})}}
	\end{equation*}
	exist for all $t\in \mathbb{Z}$,
	where $M\in \mathbb{Z}$, and the sums are over $n\in \frac12\mathbb{Z}_{\ge0}$.
	Moreover, they take only two different values, depending on the parity of $t$:
	\begin{equation*}
		\rho^{\mathrm{barcode}}_{\mathrm{even}}\coloneqq \rho_0(2k)=\rho_1(2k+1),\qquad
		\rho^{\mathrm{barcode}}_{\mathrm{odd}}\coloneqq \rho_0(2k+1)=\rho_1(2k+2),
	\end{equation*}
	and $\rho^{\mathrm{barcode}}_{\mathrm{even}}+\rho^{\mathrm{barcode}}_{\mathrm{odd}}=1$.

	The pre-limit barcode density has the following asymptotic behavior
	for all $t\in \mathbb{Z}$:
	\begin{equation*}
		\lim_{L\to\infty}
		\rho^{\mathrm{barcode}}_{(L)}(t)
		=
		\begin{cases}
			\rho^{\mathrm{barcode}}_{\mathrm{even}}, & \text{if } t \text{ is even};\\
			\rho^{\mathrm{barcode}}_{\mathrm{odd}}, & \text{if } t \text{ is odd}.
		\end{cases}
	\end{equation*} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Theorem thm:uniform-lower-bound of arXiv:2609.00556, 'Higgs--Demailly System and Positivity of Higgs Bundles'] If \((E,\theta)\) is H-ample, then every smooth admissible solution
of the Higgs--Demailly system satisfies
\begin{equation}
 f_t\geq-C,
\end{equation}
where \(C\) is independent of \(t\) and of the solution.

[Lemma lem:far_term_bound_layer of arXiv:2607.04514, 'Boundary-layer asymptotics for Gaussian-smoothed singular measures'] Assume (ass:standing:measure of the paper) and~(ass:standing:chart of the paper) of (ass:standing of the paper).
  Fix \(A>0\). There exists \(\sigma_0>0\) such that
  \begin{equation*}
    \widetilde p_{{\mathrm{far}},\sigma}(a,x) = p_{{\mathrm{far}},\sigma}\bigl(y_\sigma(a,x)\bigr)
  \end{equation*}
  is well defined and satisfies \(\widetilde p_{{\mathrm{far}}, \sigma}\in \mathfrak E_r^2\) on
  \(\mathcal D_{A, \mathcal{K}_{\mathcal{S}},\sigma_0}\). Consequently, the normalized remainder
  \begin{equation*}
    \mathscr E_{\mathrm{far}}(a,x,\sigma)
    = (2\pi)^{d/2} \sigma^{k-2} \widetilde p_{{\mathrm{far}},\sigma}(a,x)
  \end{equation*}
  belongs to \(\mathfrak E_r^2\), and hence to \(\mathfrak B_r\), on the same parameter domain.

