[Lemma E[weak-sl]_asymp of arXiv:2604.05921, 'Simplicity of random hypergraphs'] If $\forall e \in E: \delta_e^{\textnormal{tail}} = \delta^{\textnormal{tail}}\in O(1)$ and $\delta_e^{\textnormal{head}} = \delta^{\textnormal{head}}\in O(1)$ and 
\begin{enumerate}
    \item $\mathds{E}[(d_U^{\textnormal{out}})^{\delta^{\textnormal{tail}}}(d_U^{\textnormal{in}})^{\delta^{\textnormal{head}}}] \in o(n)$
    \item $\exists c>0 \textnormal{ s.t.}    \lim_{n \rightarrow \infty} \mathds{P}(d_U^{\textnormal{out}} \geq \delta^{\textnormal{tail}}), \mathds{P}(d_U^{\textnormal{in}} \geq \delta^{\textnormal{head}}) \geq c$
\end{enumerate}
then
\begin{align*}
    \mathds{E}[WS_n] &= \Big( \frac{\delta^{\textnormal{tail}} + \delta^{\textnormal{head}}-2}{2} + \frac{\delta^{\textnormal{head}} \mathds{E}[d_U^{\textnormal{out}}d_U^{\textnormal{in}}]}{\mathds{E}[d_U^{\textnormal{in}}]} \Big)(1+o(1)).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2506.18558, '2506.18558'] {\rm(\textbf {Strong averaging principle})}
Suppose that Assumptions {\rm\ref{A1}}, {\rm\ref{A2}}, {\rm\ref{A3}} and {\rm\ref{A4}} hold. Then, for any initial value $(x,y)\in\RR^{n}\times\RR^{m}$ and $T>0$,
\begin{align}
\lim_{\varepsilon\rightarrow 0}\sup_{t\in[0,T]}\mathbb{E}|X_{t}^{\varepsilon}-\bar{X}_{t}|^2=0,
\end{align}
where $(\bar{X}_t)_{t\ge0}$ is the unique strong solution to the following averaged SDE \begin{equation}
d\bar{X}_{t}=\bar{b}(\bar{X}_t)\,dt+\bar\sigma(\bar{X}_t)\,d W^1_t,\quad\bar{X}_{0}=x.
\end{equation}
Here, $\bar{b}(x)=\displaystyle\int_{\RR^{m}}\hat b(x,y)\,\mu^x(dy)$, and $\mu^x$ is the unique invariant measure of the  SDE \eqref{e:IN}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:mixing of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] Assume the setting of Theorem~(thm:dichotomy of the paper).
\begin{enumerate}
\item[\rm(i)] In case \emph{(Q)}, choose $\lambda\in[1,\kappa]$ for which (equation eq:quadrootrateintro of the paper) holds, and let $\pi_\lambda$ be the unique invariant law of $Q_{h,\gamma}^{U_\lambda}$. Then there are initial states $z,\widetilde z\in\mathbb R^4$ and a constant $c>0$ such that, for every $\varepsilon\in(0,c/4]$, there exists $z_\varepsilon\in\{z,\widetilde z\}$ satisfying
\begin{equation*}
 t_{\mathrm{mix}}(z_\varepsilon,\varepsilon;Q_{h,\gamma}^{U_\lambda},\pi_\lambda)
 \ \ge\ \frac{\kappa}{3C_\star}\,\log\frac{c}{4\varepsilon}-1.
\end{equation*}
\item[\rm(ii)] In case \emph{(C)}, for every $R\ge1$ and every $\varepsilon\in(0,3/8)$,
\begin{equation*}
 t_{\mathrm{mix}}\bigl(z_R,\varepsilon;Q_{h,\gamma}^{U_R},\pi_R\bigr)
 \ >\ \left\lfloor\tfrac1{16}e^{c_0R^2}\right\rfloor,
 \qquad
 W_2(\delta_{z_R},\pi_R)\le C_0(1+R).
\end{equation*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 (Global Schauder estimate) of arXiv:2604.17973, 'Schauder estimates and classical solutions of the Dirichlet problem for stochastic parabol'] Let $G$ be a domain of class $C^{2+\alpha}$ in the standard sense, and let Assumptions~\ref{ass:compatibility}--\ref{ass:data} be satisfied. If $u$ is a quasi-classical solution of \eqref{eq:main}--\eqref{eq:boundary-initial}, then
\begin{equation}
|u|_{(2+\alpha,\alpha/2);Q_T}^{L_\omega^\gamma}
\le Ce^{CT}\Bigl(|f|_{\alpha;Q_T}^{L_\omega^\gamma}+|f|_{(\alpha,\alpha/2);\Gamma_T}^{L_\omega^\gamma}+|g|_{1+\alpha;Q_T}^{L_\omega^\gamma(\elltwo)}\Bigr),
\end{equation}
where $C$ depends only on $n$, $\alpha$, $\gamma$, $\kappa$, $K$, $L$, $L_\alpha$, and the $C^{2+\alpha}$-character of $G$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 50 of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] Assume Assumption \ref{ass:SRI}.
\begin{enumerate}\item If $d=1$ then Theorem \ref{inv01} remains valid even when $x_1=x_2,$ under the same assumptions.

    \item If $d=2$ then in the same setting as Theorem \ref{inv01}, if $\x_N$ is any sequence in $I^k$ such that $x^1_N-x^2_N$ remains bounded as $N\to\infty$, then we have that  \begin{equation} 
    \lim_{N\to\infty}   \frac1{\log N}\sum_{r=0}^N\Ebbnn \bigg[f_N(   R^1_r-   R^2_r)\bigg] = \frac12 \int_I f\;\dr \pi^{\mathrm{inv}} . \end{equation}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:covimpact of arXiv:2411.16366, 'Connections between sequential Bayesian inference and evolutionary dynamics'] Adopt the same conditions as in Lemma (lem:optimalrs of the paper).  Then the following results hold: 
\begin{enumerate}
    \item The optimal $(r,s)$ such that $\tilde{P}_\infty = C_\infty$ satisfies (equation eq:optsr of the paper) and 
	\begin{align}

		r^{\text{opt}} - s^{\text{opt}} = \frac{(A_\infty^\ast)^2(G - A_\infty^\ast)}{-0.5A_\infty^\ast \left( H^2 \Xi^{-1} \Sigma + (G - A_\infty^\ast)^2   \right) + b^2H^2 \Xi^{-1}}
	\end{align}
	where $A_\infty^\ast$ is given by (equation eq:Ainfstarexp of the paper).
    \item For $s = 0$, it holds that the value of $r$ minimising $E_\infty$, $r_0^{\text{opt}}$, satisfies 
\begin{align}

		r_0^{\text{opt}} > \frac{2(G^2 + H^2\Xi^{-1}\Sigma)}{H^2\Xi^{-1}\Sigma} > 1
	\end{align}
independently of the unknown $b$.  Furthermore, for the case $\tau > 0$ where $\tau$ is as defined in Lemma (lem:optimalrs of the paper) and $G >0$, it holds that 
\begin{align}

    \frac{C_\infty(r_0^{\text{opt}})}{\hat{C}_\infty} < \frac{1}{\sqrt{r_0^{\text{opt}}}} \left( \frac{2|G| + \sqrt{H^2\Xi^{-1} \Sigma}}{(G + \sqrt{G^2 + H^2\Xi^{-1} \Sigma})} \right) < 1
\end{align}
where $\hat{C}_\infty$ denotes the asymptotic covariance in the perfect model setting as defined in (equation eq:covperfect of the paper). 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 15 (Hilbert totality and $\mathcal A$-orthonormality $\Rightarrow$ Parseval $\mathcal A$-module frame) of arXiv:2608.30589, 'Vector-Valued Wavelet Bases as Hilbert $\mathbb{M}_m(\mathbb{R})$-Module Bases: A Construc'] Let $\mathcal A$ be a finite-dimensional $C^*$-algebra and let $\mathbb H$ be a Hilbert $\mathcal A$-module with inner product
$\langle\cdot,\cdot\rangle_{\mathcal A}$. Fix a faithful trace $\tau$ on $\mathcal A$ and define the scalar inner product
$\langle x,y\rangle_{\tau}=\tau(\langle x,y\rangle_{\mathcal A})$ on $\mathbb H$.
Assume that $\{u_n\}_{n\in\mathbb N}\subset\mathbb H$ satisfies
\begin{itemize}
\item[(i)] $\langle u_n,u_k\rangle_{\mathcal A}=\delta_{n,k}\,1_{\mathcal A}$ for all $n,k$;
\item[(ii)] $\{u_n\}$ is total in the Hilbert space $(\mathbb H,\langle\cdot,\cdot\rangle_{\tau})$.
\end{itemize}
Then $\{u_n\}$ is a Parseval $\mathcal A$-module frame for $\mathbb H$, that is, for every $f\in\mathbb H$,
\begin{equation}
f=\sum_{n\in\mathbb N}\langle f,u_n\rangle_{\mathcal A}\,u_n,
\end{equation}
with convergence in the module norm (equivalently, in the norm induced by $\langle\cdot,\cdot\rangle_{\tau}$).
Moreover, the following Parseval-type identity holds:
\begin{equation}
\sum_{n\in\mathbb N}\langle f,u_n\rangle_{\mathcal A}\,\langle u_n,f\rangle_{\mathcal A}
=\langle f,f\rangle_{\mathcal A}.
\end{equation}

