[Lemma lem.TransitionGreen of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] The following estimates hold for the transition kernel $\overline{p}_t(\{0,1\},Y)$ and the Green function $\overline{g}_\lambda(Y)$:
		\begin{enumerate}
			\item [LandimGaussian] There exist finite positive constants $C_1,C_2,C_3$ such that for every $t>C_1$ and every $x<y$, the following estimate holds:
			\begin{equation*}
				\overline{p}_t(\{0,1\},\{x,y\})\leqslant \frac{2C_1}{1+t}\left(\exp\left(-\frac{\left\Vert{(x,y)}\right\Vert_{2}^2}{C_2t}\right)+\exp\left(-\frac{\left\Vert{(x,y)}\right\Vert_2}{C_2\log t}\right)\1_{\left\Vert{(x,y)}\right\Vert_2\geqslant \frac{C_3et}{\log t}}\right),
			\end{equation*}
			where the norm $\left\Vert{(x,y)}\right\Vert_2$ is defined as $\left\Vert{(x,y)}\right\Vert_2^2:=x^2+(y-1)^2.$
			\item [CarinciExact]
			The Laplace transform of the transition kernel for every $x<y$ is given by:
			\begin{equation*}
				\overline{g}_\lambda(\{x,y\})\\
				=\frac{1}{8\pi^2\mathbf{D}(\rho)}\int_{\pi}^{\pi}\int_{-\pi}^{\pi}\frac{e^{i(k_1 x+k_2(y-1))}+{\mathsf{A}}(\frac{k_1+k_2}{2},\lambda)e^{i(k_1 y+k_2(x-1))}}{2+\lambda-(\cos k_1+\cos k_2)}\, {\mathrm{d}} k_1\, {\mathrm{d}} k_2,
			\end{equation*}
			where the function ${\mathsf{A}}(k,\lambda)$ is defined as:
			\begin{equation*}
				{\mathsf{A}}(k,\lambda):=2\frac{\cos k\cdot(\xi_{\lambda,k}^{-2}-1)}{\cos k\cdot(\xi_{\lambda,k}^{-2}-1)-2(x_{\lambda,k}-\cos k)}-1,
			\end{equation*}
			with
			\begin{equation*}
				\xi_{\lambda,k}=x_{\lambda,k}-\sqrt{x_{\lambda,k}^2-1},\qquad x_{\lambda,k}=\frac{1}{\cos k}\left(1+\frac{\lambda}{2}\right).
			\end{equation*} 
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition lem:rho-closed of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] Let $w\ge10$ and set
\[
  \lambda_w=\frac{14(w-1)}{36w-25}.
\]
Then $\ell=\mu(w)$ satisfies
\begin{equation}
  (1+\lambda_w^2)\ell^2-(5+\lambda_w)\ell+6-4w\le0.
\end{equation}
Relaxing $\lambda_w\ge\tfrac38$ in (equation eq:rho-sharp of the paper) gives
\begin{equation}
  73\ell^2-344\ell+384-256w\le0,
\end{equation}
and hence the closed form
\begin{equation}
  \mu(w)<\frac{15}{8}\sqrt w+\frac{12}{5}.
\end{equation}
Moreover (equation eq:rho-closed of the paper) holds for every $w\ge1$.

[Lemma lem:density of arXiv:2503.21737, 'High-intensity Voronoi percolation on manifolds'] Let $\delta, C>0$. There exists $r_0 = r_0(\delta,C)>0$ such that for $r\geq r_0$, $\lambda>0$ and $\xi\sim \mathrm{PPP}\big(\lambda dx, \mathbb R^d\big)$ we have
\begin{equation}
\mathbb P \bigg(\mathrm{d}_{\mathbb{R}^d}(x,\xi)\leq r\lambda^{-1/d}/C \; \text{ for all } x\in B_{\mathbb R^d}\big(0, r\lambda^{-1/d}\big) \bigg) \geq 1-\delta.
\end{equation}

[Proposition eq:jet-h-linear of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[proposition]{prop:jet-linear}
For every frame \(O\),
\begin{align}
 h_J(O)&=\sum_I e_I(O)J_I,
 &e_I(O)&=N^{-1/2}x_I,\\
 g_{a,J}(O)&=\sum_I b_{a,I}(O)J_I,\\
 A_{ab,J}(O)&=\sum_I C_{ab,I}(O)J_I.
\end{align}

[Cor corollary:identificacionL* of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] Under $\mathbb{N}_{x,0}$ and $\mathbb{P}_{0,x,0}$, for every $u \in \mathcal{D}$, we have 
\begin{equation} 
    ( L^*_t(\rho^{u,*} ,  W^{u,*}) : t \geq 0 ) = ( L_{\Gamma_t}( \rho^u,W^u ) : t \geq 0). 
\end{equation}

[Corollary cor:one-band-centered-capped-estimate-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] There exist constants \(C<\infty\), \(c>0\), and \(\eta>0\) such that, for every \(n\ge1\), every \(2^n\le\lvert\xi\rvert\le2^{n+1}\), and every \(d\in\mathfrak D_{\xi,n}^{\mathrm{osc}}\), 
\[\mathbb{P}\left(
\mathcal G_n^{\mathrm{pre}}
\cap
\left\{
\lvert F^{\mathrm{pre,cap}}_{\xi,d,n}\rvert
+
\sup_{L>m_{\xi,d}}
\lvert F^{\mathrm{post,cap}}_{\xi,d,n,L}\rvert
>
2^{-sn/2}2^{-2\varepsilon n}
\right\}
\right)
\le
C\exp(-c2^{\eta n}).\]

[Thm finiteVsInfinite of arXiv:2609.02588, 'Ramsey-type results for Maker-Breaker games'] {}
    For a given graph $H$, the following three statements are equivalent.
    \begin{itemize}
        \item[(I)]{$\mathcal{M}^1_{MB}(H)$ consists of infinitely many graphs.}
        \item[(II)]{$\mathcal{M}^1_{BM}(H)$ consists of infinitely many graphs.}
        \item[(III)]{At least one connected component of $H$ contains at least three edges.}
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem.npoint of arXiv:2411.19145, 'On the intersection of critical percolation clusters and other tree-like random graphs'] Assume $\alpha \in (d/2,d)$. There exists a constant $C>0$, such that for any $L\ge 2$, any $x_1,\dots,x_L,z\in V$, one has 
$$\sum_{y\in V} g_\alpha(z,y) \prod_{\ell =1}^L g_\alpha(y,x_\ell) \le C^L\cdot \sum_{\sigma \in \mathfrak S_L}
g_\alpha(x_{\sigma(1)},z) \prod_{\ell = 1}^{L-1} g_{2\alpha-d}(x_{\sigma(\ell)},x_{\sigma(\ell +1)}). $$

