[Definition DefAvoidingLawBer of arXiv:2410.23899, 'Tightness for interlacing geometric random walk bridges'] Let $k \in \mathbb{N}$ and $\mathfrak{W}_k$ denote the set of signatures of length $k$, i.e.
\begin{equation}
\mathfrak{W}_k = \{ \vec{x} = (x_1, \dots, x_k) \in \mathbb{Z}^k: x_1 \geq  x_2 \geq  \cdots \geq  x_k \}.
\end{equation}
Let $\vec{x}, \vec{y} \in \mathfrak{W}_k$, $T_0, T_1 \in \mathbb{Z}$ with $T_0 < T_1$, and $f: \llbracket T_0, T_1 \rrbracket \rightarrow (-\infty, \infty]$ and $g: \llbracket T_0, T_1 \rrbracket \rightarrow [-\infty, \infty)$ be two functions. With the above data we define the {\em $(f,g)$-interlacing geometric line ensemble on the interval $\llbracket T_0, T_1 \rrbracket$ with entrance data $\vec{x}$ and exit data $\vec{y}$} to be the $\Sigma$-indexed geometric line ensemble $\mathfrak{Q}$ with $\Sigma = \llbracket 1, k\rrbracket$ on $\llbracket T_0, T_1 \rrbracket$ and with the law of $\mathfrak{Q}$ equal to $\mathbb{P}^{T_0,T_1, \vec{x},\vec{y}}_{\operatorname{Geom}}$ (the law of $k$ independent uniform increasing paths $\{B_i: \llbracket T_0, T_1 \rrbracket \rightarrow \mathbb{Z} \}_{i = 1}^k$ from $B_i(T_0) = x_i$ to $B_i(T_1) = y_i$), conditioned on 
\begin{equation}
\begin{split}
\mathsf{Inter}  = &\left\{ B_i(r-1) \geq B_{i+1}(r)  \mbox{ for all $r \in \llbracket T_0 + 1, T_1 \rrbracket$ and $i \in \llbracket 0 , k \rrbracket$} \right\},
\end{split}
\end{equation}
with the convention that $B_0(x) = f(x)$ and $B_{k+1}(x) = g(x)$.

The above definition is well-posed if there exist $B_i \in \Omega(T_0,T_1,x_i,y_i)$ for $i \in \llbracket 1, k \rrbracket$ that satisfy the conditions in $\mathsf{Inter}$. We denote by $\Omega_{\mathsf{Inter}}(T_0, T_1, \vec{x}, \vec{y}, f,g)$ the set of collections of $k$ increasing paths that satisfy the conditions in $\mathsf{Inter}$ and then the distribution of $\mathfrak{Q}$ is simply the uniform measure on $\Omega_{\mathsf{Inter}}(T_0, T_1, \vec{x}, \vec{y}, f,g)$. We denote the probability distribution of $\mathfrak{Q}$ as $\mathbb{P}_{\mathsf{Inter}, \operatorname{Geom}}^{T_0,T_1, \vec{x}, \vec{y}, f, g}$ and write $\mathbb{E}_{\mathsf{Inter}, \operatorname{Geom}}^{T_0, T_1, \vec{x}, \vec{y}, f, g}$ for the expectation with respect to this measure. If $f=+\infty$ and $g=-\infty$, we drop them from the notation and simply write $\Omega_{\mathsf{Inter}}(T_0,T_1,\vec{x},\vec{y})$, $\mathbb{P}^{T_0, T_1, \vec{x},\vec{y}}_{\mathsf{Inter}, \operatorname{Geom}}$, and $\mathbb{E}^{T_0, T_1, \vec{x},\vec{y}}_{\mathsf{Inter}, \operatorname{Geom}}$.

[Lemma cor:hill-2 of arXiv:2608.08375, 'Algebraic formulas for first-passage times of Markov processes in the linear framework: ge'] With the assumptions above, choose $z \in Z$. Let $W \subseteq \overline{Z} = \mathcal{V}(\mathcal{H}_u[G])$ be the vertex subset of $\mathcal{H}_u[G]$ given by $W = \mathcal{V}_{\text{out}}(u)$. Then,  
\begin{align*}
    \sum_{k \in W : k \to_G z}{\ell(k \to_G z) \, w(\Phi_{\{k\}}(\mathcal{H}_u[G]))}
    & = w(\Phi_{(Z \setminus \{z\}) \cup \{u\} \to Z}(G))\,, \\
    \sum_{z \in Z}{\sum_{k \in W : k \to_G z}{\ell(k \to_G z) \, w(\Phi_{\{k\}}(\mathcal{H}_u[G]))}}
    & = w(\Phi_Z(G))\,.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn counterexample of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] Assume that $\gamma$ is a bounded variation path in $R^2$. We say $\gamma$ is a "figure 8" path if $\gamma=\alpha\sqcup\beta$, the concatenation of $\alpha$ and $\beta$, where $\alpha$ and $\beta$ have the same image like a figure 8 but with different orientations.

    \begin{figure}[H]  
    \centering 
    \includegraphics[width=6cm]{3.jpg} \caption{trajectories of $\alpha$ and $\beta$} 

    \end{figure}

    (\textit{The diagram illustrates a trajectory with two orientations: in the first graph, one starts at the intersection and traverses anti-clockwise, while in the second, the traversal is clockwise, both following the given arrow directions to complete the loop.})

[Definition 2 of arXiv:2606.20169, 'THEORY OF UNCERTAIN PROBABILITY:\\ CAN WE DERIVE THE PROBABILITY DENSITY FUNCTION OF UNCER'] If the set of possible outcomes of a $PDRE_n$ is a sample space $\Phi_{n}$, then the set of all possible outcomes of the relevant $PDRE_{n}$, $n=1, 2, \ldots$ is the union of sample spaces $\Phi_{n}$, $n=1, 2, \ldots$, arising individually in an uncertain manner, denoted by $\Pi$, called an uncertain sample space and equal to

\begin{equation}
\begin{aligned}
\bigcup_{n=1}^{\infty}\Phi_{n}.
\end{aligned}
\end{equation}

[Lemma 22 of arXiv:2609.02699, '\vspace{-0.5 cm}Gauge theory and symplectic structures'] On an almost K\"ahler $3$-fold, write
\begin{align*}
    F_B=\frac{1}{3}\Lambda (F_B)\omega+F_B^{2,0}+F_B^{0,2}+(F_B)^{1,1}_p
\end{align*}
Then we have
\begin{align}
    \langle c_1(\mathcal L)^2\cup [\omega],[M]\rangle=\frac{1}{4\pi^2} \Big(\frac{2}{3}\|\Lambda (F_B)\|^2_{L^2}+\|F_B^{2,0}\|^2_{L^2}+\|F_B^{0,2}\|^2_{L^2}-\|(F_B)^{1,1}_p\|^2_{L^2}\Big)
\end{align}

[Prop 58 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Fix integers $j_0 \in [0, \mathfrak{j}]$ and $i_0 \in [0, a_{j_0}]$. Assume that, for any integers $j \in [j_0, \mathfrak{j}]$ and $i \in [0, a_j]$ such that either $j > j_0$ or $i < i_0$, the following holds w.o.p.: 
\begin{flalign}

	\begin{aligned}
		& H_{\mathsf T_{i,j},j} (w) \le \mathcal{H}_{q_{i}} (w) + N^{\delta-1}, \qquad \text{for each $w \in \mathfrak{X}$}; \\
		& H_{\mathsf T_{i,j},j} (w) \le \mathcal{H}_{q_{i}} (w), \qquad \qquad  \quad  \text{for each $w \notin \mathfrak{L}_{q_i}^+ (\delta)$}.
	\end{aligned}
\end{flalign}

\noindent Then w.o.p., we have for any $t \in [\mathsf{T}_{i_0, j_0}, N^5]$ that 
\begin{flalign}

	\begin{aligned}
		& H_{t,j_0} (z_0) \le  \mathcal{H}_{q_{i_0}} (z_0) + N^{\delta-1}, \qquad \text{for each $z_0 \in \mathfrak{X}$}; \\ 
		& H_{t,j_0} (z_0) \le \mathcal{H}_{q_{i_0}} (z_0), \qquad \qquad \quad    \text{for each $z_0 \notin \mathfrak{L}_{q_{i_0}}^+ (\delta)$}.
	\end{aligned} 
\end{flalign} (Proof in the paper; no proof environment follows the statement in the TeX.)

