[Proposition 1 of arXiv:2609.01166, 'Nonparametric inference for density-dependent McKean--Vlasov diffusions'] Under Assumptions~\ref{ass:potential} and \ref{ass:coefficient}, there exists a unique \(C^1\) zero-flux stationary density for $\xi$ given by
\begin{equation}
 \pi_\xi(x)=g_\xi^{-1}(\mu_\xi-\V(x)),
\end{equation}
where $\mu_\xi$ is the unique constant satisfying \( \int_{v_\star}^{\infty}g_\xi^{-1}(\mu_\xi-s)m_\V(s)\,\dd s=1 \). Equivalently, $q_\xi(s):=g_\xi^{-1}(\mu_\xi-s)$ solves
\begin{equation}
 q_\xi'(s)=-q_\xi(s)\xi(q_\xi(s)) \quad \text{for} \quad s>v_\star,
\end{equation}
where $a_\xi:=q_\xi(v_\star)$ is chosen to satisfy 
\begin{equation}
\int_{v_\star}^{\infty}q_\xi(s)m_\V(s)\,\dd s=1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop_9 of arXiv:2412.03774, '{ Refining Concentration for \\Gaussian Quadratic Chaos with\\ Applications in Sonar and C'] Let $r(A)\geq 3$, $\lambda_{\max}(A)>0$, $\lambda_1,\cdots, \lambda_k$ be as in ((poloi_1 of the paper)) and $r(A)-k$ be even. If
\begin{eqnarray}

t+\mathrm{tr}(A)\ge0,
\end{eqnarray}
then 

\begin{eqnarray}

\Pr(\boldsymbol{\Delta}>t)\leq e^{-\frac{t+\mathrm{tr}(A)}{2\lambda_{\max}(A)}}\sum_{l=0}^{\frac{r(A)-k}{2}-1}\frac{1}{2^l}\sum_{\substack{i_0,i_1,\cdots, i_k\ge0\\i_0+i_1+\cdots+i_k=l}}\tilde{c}_{i_0,i_1,\cdots, i_k}\Big(\frac{t+\mathrm{tr}(A)}{\lambda_{\max}(A)}\Big)^{i_0}\prod_{j=1}^k\frac{(\frac{-\lambda_j}{\lambda_{\max}(A)})^{i_j}}{(\frac{-\lambda_j}{\lambda_{\max}(A)}+1)^{i_j+\frac{1}{2}}},
\end{eqnarray}
where 
\begin{eqnarray}
\tilde{c}_{i_0,i_1,\cdots, i_k}=\frac{\prod_{j=1}^k(2i_j-1)!!}{i_0!i_1!\cdots i_k!}
\end{eqnarray}
and the double factorial notation is given in ((double_factorial of the paper)).

[Lemma lem:samelimdist of arXiv:2608.23135, 'Graph distance and effective resistance of the random walk trace in four and five dimensio'] Fix $\varepsilon,
\delta$ and $R$.  For every bounded continuous function $F$,
\begin{equation}

   \lim_{n\to\infty}
   \left|\mathbb{E}[F(L_{\mathrm{RW}}^R)]-\mathbb{E}[F(L_{\mathrm{LRP}}^R)]\right|=0.
\end{equation}

[Lem 33 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] The functions 
$\beta_\star(\gamma)$ and $g(\gamma)$, as given by \eqref{e:fp-betast} and \eqref{e:freeprob.g.of.gamma},
 have the following properties:
\begin{enumerate}[(a)]
        \item  $g$ is differentiable on $(0,+\infty)$, with $g'(\gamma) = m(\beta_\star(\gamma))$. If $\hx>0$ the statement extends to the right derivative of $g$ at
         $\gamma=0$. If $\hx\le0$, then $g'(\gamma)\uparrow\infty$ as $\gamma\downarrow0$, so $g$ does not have a finite right derivative at $\gamma=0$. 

        \item  $\beta_\star$ is nondecreasing in $\gamma$.
        \item  As $\gamma \to \infty$ for fixed $\hvv, \hx$, we have $g(\gamma) = \Theta(\gamma^{1/2})$.
    \end{enumerate}

\begin{proof} Note that if $\hx\le0$ then it is never the case that $\hx\ge \alpha/m(\beta_{\min})$, so in this case we always have $\beta=\beta_{\min}$. With this in mind, let us define 
    \[
    \tilde{\beta}
    \equiv
    \begin{cases}
    m^{-1}(\alpha/\hx)
        &\textup{if $\hx>0$,}\\
    \hw_1&\textup{otherwise.}
    \end{cases}
    \]
It is then straightforward to verify that
    \[
        g(\gamma) =
         \min\bigg\{
         \beta + \gamma m(\beta)
         : \beta \ge \tilde \beta
         \bigg\}\,,
    \]
and the minimizing $\beta$ is precisely $\beta_\star(\gamma)$. We then separate into two cases:
\begin{itemize}
\item In the case $\hx\le0$, we always have $\beta_\star(\gamma)=\beta_{\min}(\gamma)$, and the conclusion of part \eqref{i:fp-g-diff} for $\gamma>0$ is an immediate consequence of the standard ``envelope theorem'':
    \begin{align}\nonumber
    g'(\gamma)
    &= \frac{d}{d\gamma}
    g( \beta_{\min}(\gamma), \gamma)
    =
    \bigg\{
    \frac{\partial g}{\partial \beta}
    \frac{d\beta_{\min}}{d\gamma}
    +\frac{\partial g}{\partial \gamma}
    \bigg\}
    ( \beta_{\min}(\gamma), \gamma)\\
    &= \frac{\partial g}{\partial \gamma}
    ( \beta_{\min}(\gamma), \gamma)
    = m(\beta_{\min}(\gamma))\,,

    \end{align}
having used that $\partial g/\partial\beta$ must be zero at the point $(\beta_{\min}(\gamma),\gamma)$. As $\gamma\downarrow0$, we note that expanding the equation $m_2(\beta_{\min}(\gamma))=1/\gamma$ implies
    \[\beta_{\min}(\gamma)
    =\hw_1 + (\mu_1\gamma)^{1/2} \Big[1+O(\gamma)\Big]
    \,.\]
It follows that as $\gamma\downarrow0$ we have
    \[g'(\gamma)
    = m(\beta_{\min}(\gamma))
    =\frac{\mu_1}{\beta_{\min}(\gamma)-\hw_1}+O(1)
    =\bigg( \frac{\mu_1}{\gamma}\bigg)^{1/2}+O(1)\,.
    \]
It follows that $g'(\gamma)\to\infty$ as $\gamma\downarrow0$.

\item In the case $\hx>0$, we have $\tilde{\beta}=m^{-1}(\alpha/\hx)$, and \eqref{e:fp-betast} can be rewritten as
    \beq

    \beta_\star(\gamma)
    = \max\Big\{
    \beta_{\min}(\gamma),\tilde{\beta}
    \Big\}
    = \begin{cases}
    \tilde{\beta}
        &\textup{if }
        \gamma <
        \tilde{\gamma}
        \equiv 1/m_2(\tilde{\beta})\\
    \beta_{\min}(\gamma)
        &\textup{otherwise.}
    \end{cases}
    \eeq
At any $\gamma \in(\tilde{\gamma},\infty)$, the function $\beta_\star  = \beta_{\min}$ is differentiable in $\gamma$, and the same calculation as \eqref{e:fp.envelope} shows that $g$ is differentiable at $\gamma$, with derivative $g'(\gamma)=m(\beta_\star(\gamma))$. Similarly, at any $\gamma \in [0,\tilde{\gamma})$, the function $\beta_\star(\gamma) = \tilde{\beta}$ is constant in $\gamma$, so we again conclude that $g$ is differentiable at $\gamma$, with derivative
\[
    g'(\gamma)
    = \frac{\partial g}{\partial \gamma}(\beta_\star(\gamma),\gamma)
    = m(\beta_\star(\gamma))\,.
\]
At $\gamma=\tilde{\gamma}$, note that $\beta_\star(\gamma)$ has well-defined left and right derivatives, equal to $0$ and $(\beta_{\min})'(\tilde{\gamma})$ respectively. The above arguments imply that $g$ has well-defined left and right derivatives, which both equal $m(\beta_\star(\tilde{\gamma}))$, so $g$ is in fact differentiable at $\gamma=\tilde{\gamma}$.
\end{itemize}
The above concludes the proof of \eqref{i:fp-g-diff}. 
The conclus (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm -3 of arXiv:2411.13403, 'Path weighting method for spot sensitivities and its variance reduction'] Let $F(S_{t_{1}},\dots S_{t_{N}})$ be a measurable
function with at most polynomial growth at infinity, and 
\[
f(s)=\mathbb{E}[F(S_{t_{1}},\dots,S_{t_{N}})|S_{t_{0}}=s].
\]
Denote
\begin{equation}
J(s,x)=(\partial_{x}H_{0})^{-1}(\partial_{s}H_{0}).
\end{equation}
Then
\begin{equation}
\begin{aligned}\partial_{s^{(l)}}f(s) & =\mathbb{E}\Big[F(S)\Big(\sum_{k=0}^{1}\frac{1}{(\Delta t_{1})^{k/2}}\Theta_{l}^{(k)}(s,Z_{1},\sqrt{\Delta t_{1}}Z_{1})\Big)\Big]\end{aligned}
,
\end{equation}
where
\begin{align}
\Theta_{l}^{(0)}(s,z,x) & =-\sum_{p=1}^{n}\partial_{x^{(p)}}J_{pl}(s,x),\\
\Theta_{l}^{(1)}(s,z,x) & =\sum_{p=1}^{n}z^{(p)}J_{pl}(s,x),
\end{align}
with $s,z,x\in\mathbb{R}^{1\times n}$. Moreover,
\begin{equation}
\begin{aligned}\partial_{s^{(l)}s^{(m)}}^{2}f(s) & =\mathbb{E}\Big[F(S)\Big(\sum_{k=0}^{2}\frac{1}{(\Delta t_{1})^{k/2}}\Lambda_{lm}^{(k)}(s,Z_{1},\sqrt{\Delta t_{1}}Z_{1})\Big)\Big]\end{aligned}
,
\end{equation}
where 
\begin{align}
\Lambda_{lm}^{(0)}(s,z,x) & =\sum_{p,r}\big(\partial_{x^{(r)}}J_{rm}\partial_{x^{(p)}}J_{pl}\big)(s,x)\nonumber \\
 & \quad+\sum_{p,r}\big(J_{rm}\partial_{x^{(r)}x^{(p)}}^{2}J_{pl}\big)(s,x)-\sum_{p}\partial_{s^{(m)}x^{(p)}}^{2}J_{pl}(s,x),\\
\Lambda_{lm}^{(1)}(s,z,x) & =\sum_{p}z^{(p)}\partial_{s^{(m)}}J_{pl}(s,x)-\sum_{p,r}z^{(p)}\big(J_{rm}\partial_{x^{(r)}}J_{pl}\big)(s,x)\nonumber \\
 & \quad-\sum_{p,r}z^{(p)}\big(\partial_{x^{(r)}}J_{rm}\cdot J_{pl}\big)(s,x)-\sum_{p,r}z^{(r)}\big(J_{rm}\cdot\partial_{x^{(p)}}J_{pl}\big)(s,x),\\
\Lambda_{lm}^{(2)}(s,z,x) & =\sum_{p,r}z^{(r)}z^{(p)}(J_{rm}J_{pl}-\delta_{rp}J_{rm}J_{pl})(s,x),
\end{align}
with $s,z,x\in\mathbb{R}^{1\times n}$ and $\delta_{rp}$ being the
Dirac notation. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:energy of arXiv:2608.16915, 'Exact mean--covariance dynamics of the Weber field in the stochastic Lagrangian representa'] Assume $\int_{\mathbb{T}^3}u_0=0$; this mean is conserved by (equation eq:NS of the paper) on the torus, so
$\int_{\mathbb{T}^3}u(t)=0$ for all $t$. Let $C_P$ denote the Poincar\'e constant of $\mathbb{T}^3$. Then
for all $0<T<T_*$,
\begin{equation}
  \left\lVert \ell(T)\right\rVert_{L^2}^2+\nu\int_0^T\left\lVert M(t)-I\right\rVert_{L^2}^2\,\mathrm{d} t
  \le\frac{C_P^4}{2\nu^2}\left\lVert u_0\right\rVert_{L^2}^2 .
\end{equation}

