[Theorem thm:conv_in_hidaspace of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] Let $(\Phi_n)_{n\in\mathbb{N}}$ be a sequence in $(\mathcal{S})'$. If the corresponding sequence of $U$-functionals $(U_n)_{n\in\mathbb{N}} \coloneqq (\mathrm{S}^{-1}\Phi_n)_{n\in\mathbb{N}}$ satisfies both of the following two conditions
	\begin{enumerate}
		\item $(U_n(\varphi))_{n\in\mathbb{N}}$ is a Cauchy sequence for all $\varphi \in \mathcal{S}(\mathbb{R})$\text{, and}
		\item there exist $p$, $N\in\mathbb{N}$ and $A$, $B\in\mathbb{R}_{\geq0}$ s.th.\
		\begin{equation*}
			|U_n(z\varphi)| \leq A \exp(B|z|^2\|\varphi\|_p^2)\quad \text{for all $z\in\mathbb{C}$, $\varphi \in \mathcal{S}(\mathbb{R})$ and $n\geq N$}.
		\end{equation*}
	\end{enumerate}
	Then, the point-wise limit $U\coloneqq \lim_{n \to \infty} U_n$ is a $U$-functional, and we have $\Phi_n \to \mathrm{S}^{-1}(U) \eqqcolon \Phi$ strongly in $(\mathcal{S})'$ as $n\to\infty$. The analogous statement holds if the $\mathrm{S}$-transform is exchanged for the $\mathrm{T}$-transform. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 5 of arXiv:2512.04297, 'Mixing at the Batchelor Scale for White-In-Time Flows'] The analogous statements of Theorem \ref{thm:lower_bound_low_modes} and its two corollaries hold for the three-dimensional model \eqref{spde:3D}.
\begin{enumerate}[(i)]
    \item     For $\kappa\geq 0$ and $f_0\in L_0^2(\tor^3) \setminus \{0\}$, let $f_t$ be the solution to \eqref{spde:3D}. The decay rate of the $L^2$-norm of the six innermost modes is lower bounded by
    \begin{equation}
        \limsup_{t\to \infty} \frac{1}{t} \log \norm{\Pi_{\leq 1}f_t}_{L^2} \geq -(2\pi)^2 \left( 1 + \kappa \right ).
    \end{equation}
    \item The exponential dissipation rate $\lambda_{\omega, f_0}^\kappa$, as given by \eqref{eq:dissipation_rate}, is lower bounded by
    \begin{equation}
        \lambda_{\omega, f_0}^\kappa  \geq -(2\pi)^2 \left(1 + \kappa \right ).
    \end{equation}
    \item     For $s> 0$ the exponential mixing rate without diffusion is of order $1\land s$, that is, there exists a constant $C>0$ such that
    \begin{equation}
        C^{-1} (1\wedge s) \leq \gamma_s \leq C (1\wedge s), \quad \forall\, s>0.
    \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

