[Lemma 19 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] Let $H\in\left(0,1\right)$ and $\left(\psi_t^{(1)}\right)_{t\geq 0}$ be a solution to the first equation in \eqref{eq:fast system simplified hopf 2} with $||\bm{\sigma}_1||^2\neq 0$. Consider $\alpha=\alpha(\lambda)\in\C$ such that $\underset{\lambda\to\lambda^*}{\lim} \alpha(\lambda)=\alpha(\lambda^*)\in i \R\setminus\{0\}$. Then, it holds that
\begin{align}
    \left| \frac{\underset{t\to\infty}{\lim}\text{Cov}\left(\psi_t^{(1)}, \psi_{t+\tau}^{(1)} \right)}{\underset{t\to\infty}{\lim}\text{Cov}\left(\psi_t^{(1)}, \psi_{t}^{(1)} \right)} - e^{-i \operatorname{Im}(\alpha(\lambda))\tau} \right| = -\operatorname{Re}(\alpha(\lambda)) \tau \Delta(\tau) + \mathcal{O}\left( \operatorname{Re}(\alpha(\lambda))^2 \right) ,
\end{align}
with $\Delta(\tau)\neq 0$ for almost every $\tau \geq 0$. In particular, for almost every $\tau\ge0$, we have that
\begin{align*}
    &\frac{\underset{t\to\infty}{\lim}\text{Cov}\left(\psi_t^{(1)}, \psi_{t+\tau}^{(1)} \right)}{\underset{t\to\infty}{\lim}\text{Cov}\left(\psi_t^{(1)}, \psi_{t}^{(1)} \right)}
    = e^{-i \operatorname{Im}(\alpha(\lambda^*))\tau} 
    + \cO \left(\operatorname{Re}(\alpha(\lambda))\right) + \cO\left( \operatorname{Im}(\alpha(\lambda)-\alpha(\lambda^*))\right) .
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 22 of arXiv:2601.16377, '2601.16377'] Given an equilibrium measure $\boldsymbol{\mu}$, the $h$-th \emph{effective potential} is the function of $x \in [\hat{a}'_h,\hat{b}_h']$ defined through
 \begin{equation}
 V^{{\textnormal{eff}}}_h(x)= V_h(x) - \sum_{g =1}^H 2\theta_{h,g}
\int_{\hat a'_{g}}^{\hat b'_g} \log|x-y|\mu_{g}(y)\dd y.
\end{equation}

[Defn 25 of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] Let $  {\boldsymbol v}\in \mathbb R^d$. We define the function $\z_{  {\boldsymbol v}}:I\to \mathbb R$ by 
    \begin{equation*}
         \z_{  {\boldsymbol v}}(   y_1-   y_2) :=\sum_{\substack{r_1+...+r_d=p\\s_1+...+s_d=p}}\frac{  {\boldsymbol v}^{   r+   s}}{   r!   s!}\boldsymbol \eta_{   r,   s}(   y_1-   y_2).
    \end{equation*}

[Proposition \cite{lawler80selfavoiding} of arXiv:2411.13505, 'Capacity of loop-erased random walk'] Two-sided LERW $\hat\eta$ satisfies the following properties:
\begin{enumerate}
	\item the law $\hat\eta$ is absolutely continuous with respect to the law of $\eta$;
	\item $T^k\eta$ converges weakly to $\hat\eta$ as $k\rightarrow\infty$;
	\item $\hat\eta$ is stationary with respect to $T$, i.e., $T\hat\eta\stackrel{d}{=}\hat\eta$;
	\item $\eta$ and $\hat\eta$ are ergodic with respect to $T$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 18 ({\cite{mingoFreeProbabilityRandom2017}}) of arXiv:2606.31528, 'Well-posedness and stationary distribution of free stochastic differential equations'] If $\{\mu_n\}_{n\in\mathbb N}$ is a sequence of probability measures on $\mathbb R$ such that
\begin{equation*}
G_{\mu_n}(z)\to G_\mu(z), \qquad z\in\mathbb C^{+},
\end{equation*}
for some probability measure $\mu$ on $\mathbb R$, then $\mu_n$ converges weakly to $\mu$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 19 (Hard-Edge Limit) of arXiv:2511.12623, 'The eigenvector bead process'] We have, almost surely,
\[
\lim_{N \to \infty}
\left(
\frac{1}{4N}
+ 
\sum_{j \in \mathbb{Z}} \frac{\gamma_j^{N}}{\mu_j^{N} - z}
- 
\frac{\Gamma_N}{z}
\right)
=
\sum_{j \in \mathbb{Z}} \frac{\gamma_j}{\mu_j - z}
- 
\frac{\chi_{\alpha}}{z},
\]
for all $z \in \mathbb{R} \setminus \{\mu_j\}_{j \in \mathbb{Z}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:lack of detailed balance of arXiv:2607.02367, 'Flux solutions for stochastic chemical systems with sources and sinks'] Assume that $(\Omega, \mathcal R , \mathcal R_s ,  \mathcal K, \mathcal K_s )$ is a chemical system with sources and sinks. Assume that the system $(\Omega , \mathcal R, \mathcal K ) =(\Omega, \mathcal R , \emptyset ,  \mathcal K, \emptyset ) $ without sources and sinks satisfies the detailed balance condition.  Let $\mathcal B_{\mathcal W_r} = \{ w_k \}_{k =1}^{|\mathcal W_r |} $ be a basis for the space of the cycles of $(\Omega , \mathcal R, \mathcal K )$ and let $\mathcal B_{ \mathcal W} =  \{ w_k \}_{k =1}^{|\mathcal W |} $ be a basis of the space of the cycles of  $(\Omega, \mathcal R , \mathcal R_s ,  \mathcal K, \mathcal K_s )$. Assume that 
 \begin{equation} 
 |\mathcal W| >  |\mathcal W_r |. 
 \end{equation}
 Then for every $w \in \mathcal W$ such that $ \pi_{ \mathcal R } w \notin \mathcal W_r $, it holds that 
 \begin{equation} 
 \Delta (w)= (E- D)^T \mathbb S_r \pi_{\mathcal R }  w
 \end{equation}
where $E \in \mathbb R^M $ is a solution to \begin{equation} 
 S_\rho^T  E = \ln \left( \dfrac{ K_{ - \rho} }{ K_{  \rho } }  \right)  \ \forall \rho \in \{ 1, \dots, r \}   
\end{equation} 
and where $D \in \mathbb R^M $ is the vector 
\[
D(k)= \begin{cases} &\log \left( \frac{\alpha_k }{ \beta_k } \right), \quad k \in \{ 1, \dots, |\Omega_c | \}   \\
& 0, \quad   k \in \{|\Omega_c | +1 , \dots , M \}. 
\end{cases}
\]

