[Lemma 23 of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] For all~$\lambda\ge0$,
\begin{equation}

\lim_{k\to\infty}\limsup_{n\to\infty} \wt P\biggl(\,\bigcup_{x\in \BbbL_n}\bigl\{h(x)\ge \wt m_n-\lambda\bigr\}\cap\wt\BB_{n, k}(x)^\cc\biggr) = 0,
\end{equation}
where for $\tilde\sigma:=\frac1{12}$, 
\begin{equation}

\wt \BB_{n,k}(x):=\Bigl\{\wt m_k+k^{\tilde\sigma}\le \wt m_n-h(z)\le \wt m_k+k^{1-\tilde\sigma}\Bigr\}
\end{equation}
with our convention $z:=\frakm^k(x)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 21 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $0<\A{1}\leq \A{2}\ll 1$ be such that there exists $\omega\in \hspace{0.1cm} ]0,1[$ such that 
    \begin{equation}
        N^{-\omega}\leq \pr{\alpha_1\alpha_2}^{1/2}.
    \end{equation}
    Let $p\in S(1,\A{1},\A{2})$. Then, as $N\to +\infty$,
    \begin{equation*}
        \norme{p_{N,\A{1},\A{2}}}\leq \sup_{\rho\in \mc{T}_{\A{1},\A{2}}}\bb{p(\rho)}+o(1).
    \end{equation*}
    In particular, there exists a constant $C>0$ independent of $N$, $\alpha_1$ and $\A{2}$ such that 
    \begin{equation*}
        \norme{p_{N,\A{1},\A{2}}}\leq C.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

