body:
[Theorem 2 of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] For all $t > 0$, there exists an a.s.-finite random Borel measure~$Z_t$ on~$[0,1]$ such that the following holds:
\begin{equation}

\lim_{n\to\infty}P^\varrho(\tau_{\BbbL_n}<t) = \BbbP\bigl(Z_t([0,1])>0\bigr)\in(0,1)
\end{equation}
and, for~$L_t$ sampled under the conditional law $P^\varrho(\cdot\,|\tau_{\BbbL_n}<t)$, 
\begin{equation}

\sum_{x\in\BbbL_n}\delta_{\theta_n(x)}\otimes\delta_{\sqrt{L_t(x)}-m_n}\,\,\,\underset{n\to\infty}\lawarrow\,\,\,\sum_{i\ge1}\sum_{j\ge1}\delta_{x_i}\otimes\delta_{h_i+d_j^{(i)}}.
\end{equation}
Here~$\{(x_i,h_i)\}_{i\ge1}$ enumerates points in a sample of the Poisson point process
\begin{equation}

\PPP\bigl(\,Z_t(\textd x)\otimes\texte^{-2h\slb}\textd h\bigr)
\end{equation}
with~$Z_t$ sampled conditional on~$\{Z_t([0,1])>0\}$
and~$\{d_j^{(i)}\colon j\ge1\}_{i\ge1}$ denoting i.i.d.\ samples from~$\DD$ in Theorem~\ref{thm-1}, drawn independently of ~$\{(x_i,h_i)\}_{i\ge1}$ and~$Z_t$. 
Moreover, with $\wt C_\star \in (0,\infty)$ as in Theorem~\ref{thm-1} and~$L_t$ sampled under~$P^\varrho$,
\begin{equation}

\wt C_\star\,b^{-2n} \sum_{x \in \BbbL_n} \Bigl(n\slb - 
\sqrt{L_t(x)}\,\Bigr)^+ L_t(x)^{1/4}\,
	\texte^{2\slb\,\sqrt{L_t(x)}}\delta_{\theta_n(x)}\,\,\underset{n\to\infty}\lawarrow\,\,Z_t.
\end{equation}
A.e.\ sample of~$Z_t$ is diffuse (i.e., does not charge singletons). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 of arXiv:2605.17494, 'Generalized intersection exponents and local cut points for three-dimensional Brownian loo'] Let $\alpha_*\in I_0$. Then there exist constants $c_1,c_2>0$, depending only on
$\alpha_*$, such that for every $\alpha\in(0,\alpha_*]$, every $0<\epsilon<\frac12$,
and every pair $V,V^-$ as in Lemma~\ref{lem:BM stays in a cone}, we have
\begin{equation}
    \Pb\bigl(\Lambda(V^-)\subseteq V\bigr)\ge c_1\epsilon^{c_2}.
\end{equation}

[Coro 6 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $\gamma>0$ and $\alpha\in\mathbb{R}$.

\begin{enumerate}
\item If $\gamma\in(0,1)$ and a semigroup increment $R\in E^{\gamma}(\Delta_T^2; B_\alpha)$ of a given semigroup defect is available, then its canonical information at this regularity is its class in $\mathfrak E_2^{\gamma}(\Delta_T^2; B_\alpha)$. \mlabel{it:canona}

\item If $\gamma=1$ and a semigroup increment $R\in E_{\log}^{1}(\Delta_T^2; B_\alpha)$ is available, then its canonical information is its class in $\mathfrak E_{\log}^{1}(\Delta_T^2; B_\alpha)$. \mlabel{it:canonb}

\item If $\gamma>1$, this quotient ambiguity disappears. \mlabel{it:canonc}
\end{enumerate}

[Lem 11 of arXiv:2605.30779, '2605.30779'] Let $X$ be an $N$-dimensional real symmetric (resp.~complex Hermitian) matrix with distinct eigenvalues $\mu_1 > \dotsb > \mu_N$, $\w$ be a unit $N$-dimensional column vector in $\realR^N$ (resp.~$\compC^N$), $d$ be a real number, and $Y = X + d \w \w^{\top}$ (resp.~$Y = X + d \w \w^*$) has distinct eigenvalues $\lambda_1 > \dotsb > \lambda_N$. We assume $\{ \mu_j \}^N_{j = 1} \cup \{ \lambda_j \}^N_{j = 1}$ consists of $2N$ distinct real numbers, and for any $k = 1, \dotsc, N$, $\x_k$ is a unit eigenvector of $Y$ associated with $\lambda_k$. Then
  \begin{equation}
    \w^\top(\lambda_k I - X)^{-1} \w =\frac{1}{d},
  \end{equation}
  and
  \begin{equation} 
    \lvert \langle \x_k, \w \rangle \rvert^2 = \frac{\lvert \langle \w, (\lambda_k I - X)^{-1} \w \rangle \rvert^2}{\langle \w, (\lambda_k I - X)^{-2} \w \rangle} = \frac{1}{d^2} \frac{1}{\langle \w, (\lambda_k I - X)^{-2} \w \rangle}.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop p:300.1 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] If $\gamma$ is chosen small enough, then, given any $0 < \eta' < \eta < \frac{1}{2}$ small enough (depending only on $\gamma$), for each $u,k \geq 0$ there exists a probability measure ${\rm O}^{k}_u$ on $\mathbb{R}^{{\rm Q}(k)}$ such~that 
\begin{equation}
\frac{\big|{\mathbf R}_n^{k}(u)\big|}{\sqrt{n}}
\bigg|\int f_k\,{\rm d} \mathcal{O}^{k}_{n,u} - \int f_k\, {\rm d} (\widehat{\Theta}^k_{n,u} \otimes {\rm O}^{k}_u)\bigg| \overset{\mathbb{P}} \longrightarrow \, 0 \,,
\end{equation}
as $n \to \infty$ followed by $k \to \infty$, uniformly over all measurable $f_k: {\rm D} \times \mathbb{R}^{{\rm Q}(k)} \to \mathbb{R}$ with $\|f_k\|_\infty \leq 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

