[Lemma lem5-3 of arXiv:2606.28631, '\Large \bf On the maximal displacement of subcritical branching random walks with stretche'] Assume {\bf(H2)} and $b\in (0,1)$. 
	\begin{itemize}
		\item[(i)] For all $k\delta\geq K_0, I=[(k-1)\delta, k\delta)$ and $x>K_0$, 
		\begin{align}
			\frac{e^{\lambda x^b}}{\ell(x)x^a } T_{41} \lesssim_\beta  \frac{e^{\lambda (k\delta)^b}}{\ell(k\delta) (k\delta)^a}.
		\end{align}
		\item[(ii)] For each $I=[p,q)$, we have 
		\begin{align}
			\lim_{x\to+\infty}\frac{e^{\lambda x^b}}{\ell(x)x^a } T_{41}  =0. 
		\end{align}
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 4 of arXiv:2608.27630, 'Oriented planar maps and \\ annular mating of trees'] Let $D,h,A,\rho$ be described as above.   We  have the orthogonal decomposition
    \begin{equation}
        H(D) = H(A;\partial_1A)\oplus \mathrm{Harm}(D,A,\rho).
    \end{equation}
    Furthermore, let $h^{\mathrm{har}}$ be the harmonic  extension of $h|_{D\backslash A}$ onto $A$ with zero normal derivative on $\partial A\cap\partial D$ and let $h^A = h-h^{\mathrm{har}}$. Then $h^A$ is a GFF on $A$ with zero boundary conditions on $\partial A\backslash\partial D$ and free boundary conditions on $\partial A\cap \partial D$. Moreover, $h^A$ is independent from $h^{\mathrm{har}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_G_large of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] In the setting of (mix of the paper), let $z=E+\mathrm{i} \eta \in \bf D(\tau)$ with $\eta\gtrsim N^{-1/3}$ and $\eta/\im m (z) \sim N^{-\varepsilon_g}$ for a small constant ${\varepsilon}_g\in\left({0,\delta_A/4}\right)$. 
    If $z_1,z_2,z_3\in\ha{z,\overline{z}}$ are not all equal, then we have
    \begin{align}
            \left\|L_{(1,2)}-K_{(1,2)}\right\|_2 &\prec N^{-1} \eta^{-2} \cdot\Big\|\left(1-\widehat{M}_{\left({1,2}\right)}\right)^{-1}\Big\|,\\
            \left\|L_{(1,2,3)}-K_{(1,2,3)}\right\|_2 &\prec N^{-1}\eta^{-3}N^{\varepsilon_g}.
    \end{align}
    On the other hand, if $z_1=z_2=z_3$, then we have 
    \begin{equation}
        \begin{aligned}
            \left\|L_{(1,2,3)}-K_{(1,2,3)}\right\|_2 \prec N^{-1}\eta^{-3}\pa{\frac{1}{\im m (z) }\wedge N^{\varepsilon_g}}.
        \end{aligned}
    \end{equation}
More generally, we can prove the following extension of (equation largG_Ent of the paper): given an arbitrary deterministic matrix $B$ with $\|B\|\le 1$, we have 
    \begin{equation}
        \begin{aligned}
            \left\langle G_1E_aG_2B \right\rangle=\sum_{x=1}^D\pa{1-\widehat M_{\left({1,2}\right)}}^{-1}_{ax}\left\langle M_1E_xM_2B \right\rangle+\opr{N^{-1}\eta^{-2}\cdot\Big\|\pa{1-\widehat M_{\left({1,2}\right)}}^{-1}\Big\|}.
        \end{aligned}
    \end{equation}

[Proposition 14 of arXiv:2605.03851, 'The Relay Random Tree:\\A stochastic geometry approach of multihop relay in an urban visib'] \textbf{Characterisation of the eventual relaying.}

For $(\alpha, \beta)$ a building and $(x, y)$ a point of $\Half$, $(x, y)$ is eventually relayed by $(\alpha, \beta)$ if and only if the two following conditions are fulfilled:
\begin{itemize}
    \item $(x, y)$ is in the reverse shade of $(\alpha, \beta)$.
    \item The base $(x, y)$, $x$, is between $\alpha$ the base of $(\alpha, \beta)$ and $a_{sc}$ the base of its shadow-cutting building: $x\in [\alpha_{sc}, \alpha]$.
\end{itemize}
In other words,
\[\zone(\alpha, \beta) = \{(x, y)\in \rs(\alpha, \beta): x> \alpha_{sc}\}.\]
       \begin{figure}[h]
            \centering
            \includegraphics[width=0.75\textwidth]{Figures/eventual_connection.ipe.png}
            \caption{The buildings that are eventually relayed by $b$ are those located between $b$ and its shadow-cutting building.}
        \end{figure} (Proof in the paper; no proof environment follows the statement in the TeX.)

