[Lemma 3 (Reference-compatible state lift) of arXiv:2609.02196, 'Schr\"odinger Bridges on Lie Group Manifolds for Probabilistic Intrinsic Generation'] If \(Q_i(\dd g\dd\bm\xi)=Q_i^\G(\dd g)Q_i(\dd\bm\xi\mid g)\) and \(\rho\ll Q_i^\G\), then the unique state law with group marginal \(\rho\) minimizing \(\KL(\cdot\|Q_i)\) is
\begin{equation*}
\pi^\circ(\dd g\dd\bm\xi)=\rho(\dd g)Q_i(\dd\bm\xi\mid g).
\end{equation*}
The proof is given in \cref{app:proof-canonical-lift}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 (Resolvents) of arXiv:2608.29872, 'Local Laws and Outlier Eigenvalues for Spiked Separable Covariance Matrices'] For $z = E+ \ii \eta \in \mathbb C_+,$ we define the following resolvents for $\al=1,2$: 
\begin{equation}
 \mathcal G_{\al}(X,z):=\left({\mathcal Q}_{\al}(X) -z\right)^{-1} , \ \ \ \wt{\mathcal G}_{\al} (X,z):=(\wt{\mathcal Q}_{\al}(X)-z)^{-1} .
\end{equation}
 We denote the ESD $\rho^{(p)}$ of ${\mathcal Q}_{1}$ and its Stieltjes transform as
\be
\rho^{(p)} := \frac{1}{p} \sum_{i\in\cal I_1} \delta_{\lambda_i({\mathcal Q}_1)},\quad m^{(p)}(z):=\int \frac{\rho^{(p)}(\dd x)}{x-z}=\frac{1}{p} \mathrm{Tr} \, \mathcal G_1(z).
\ee
We also introduce the following quantities:
\begin{equation}
 m_1^{(n)}(z):= \frac{1}n\tr \left(A \mathcal G_1(z)\right) ,\quad m_2^{(n)}(z):=\frac{1}{n}\tr\left( B\mathcal G_2(z)\right). 
\end{equation}

[Lemma eq:gaussian-shift of arXiv:2607.14087, 'Stochastic Domination of Gaussian Maxima: A Resolution of the Weak Simplex Conjecture'] \label[lemma]{lem:gaussian-shift}
Let $X\sim\mathcal N(0,R)$ for a positive-semidefinite matrix $R$.  For every
$a\in\mathbb R^m$ and every nonnegative Borel function
$F:\mathbb R^m\to[0,\infty]$,
\begin{equation}
  \mathbb E\!\left[e^{a^{\mathsf T}X}F(X)\right]
  =e^{\frac12a^{\mathsf T}Ra}\mathbb E F(X+Ra).
\end{equation}

[Cor derivative bound on ratio of G_n of arXiv:2603.17858, 'Decay of correlations and zeros for the hard-core model'] Given $\lambda_+>\lambda_->0$, $C>0$ and $\alpha\in (0,1)$ there exists a constant $A>1$ such that the following holds: if $(\lambda_n)$ and $(\widehat\lambda_n)$ in $[\lambda_-,\lambda_+]$  satisfy $|\lambda_n-\widehat \lambda_n|<C\alpha^n$ for all $n$, then 
    \begin{equation}

        1/A\leq \abs[\bigg]{\frac{G_{n}'}{\widehat{G}_{n}'}} \leq A.
    \end{equation}

[Proposition 37 of arXiv:2608.26084, 'Localic Esakia Duality\\via Conic Frames'] There is a functor
	\begin{align*}
		\cone\colon \rosLoc &\longrightarrow \dcFrm^\op;
		\\
		(X,R)&\longmapsto (\Opens X,\Down);
		\\
		f &\longmapsto f^{-1}.
	\end{align*}

[Lemma lem:pnqn of arXiv:2607.22291, 'Rare subtree patterns in size-conditioned Bienaymé trees: Poisson approximation and declum'] Assume (hyp:M of the paper) holds for $(G_k)$ along $(k_{n})$ with respect to $(M_{n})$. Set $p_n = \P(I_1^{(M_n)}=1)$ and $r_n = \sqrt{a_{M_n} a_n}$. Then:
\begin{enumerate}
\item[(i)] $\P(I_1^{(M_n)} = 1, |S_{M_n}| > r_n) = o(p_n)$.
\item[(ii)] $p_n \sim q_n \sim \pi_n$.
\end{enumerate}

[Proposition 101 of arXiv:2601.16377, '2601.16377'] Consider a variational datum satisfying Assumptions~\ref{Assumption_A}, \ref{Assumption_B} and \ref{Assumption_C} with $H=1$ and admitting a single band --- we drop the indices $h$ from the notations. Let $\Delta V(z)$ be a holomorphic function in a complex neighborhood of $[\hat a', \hat b']$. Consider the family of variational data parameterized by a real $\epsilon$ in a small enough neighborhood of $0$ and differing from the original variational datum only by the potential $V^t(x) = V(x) + \epsilon \Delta V(x)$. Then, denoting with exponent ${}^{\epsilon}$ all the associated quantities, $\epsilon \mapsto \I^\epsilon[\boldsymbol{\mu}^{\epsilon}]$ is differentiable at $\epsilon = 0$ and its derivative can be computed as
 \begin{equation}

\partial_{\epsilon}\I^\epsilon[\mu^\epsilon]\big|_{\epsilon =0}=-\int_{\hat a'}^{\hat b'} \Delta V(x)\,\mu^0(x)\dd x.
 \end{equation}

[Proposition 16 (Static and pair-specific score weighting) of arXiv:2607.29560, 'Tractable Relaxations of Multivariate Stochastic Dominance via Optimal Transport and CVaR'] For every $0\le\gamma\le1$,
\begin{equation}

g_{s,\lambda,\gamma}(x,y)
=
\sup_{h\in\mathcal H_{\lambda,\gamma}}
\{h(x)-h(y)\},
\end{equation}
\begin{equation}

\mathfrak R_{s,\lambda,\gamma}(P,Q)
=
\frac{1-\gamma}{2}M_s(P,Q)
-
\frac{1+\gamma}{2}\Delta_s(P,Q),
\end{equation}
and
\begin{equation}

\mathfrak D_{s,\lambda,\gamma}(P,Q)
=
\mathfrak R_{s,\lambda,\gamma}(P,Q)
+
\frac{1-\gamma}{2}
\{W_s(P,Q)-M_s(P,Q)\}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 5. lem: pcpt of aging functions off diagonal of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] For every $l \in \mathbb{N}$ and $\eta > 0$,
  \begin{equation}
    \lim_{\delta \to 0} 
    \limsup_{n \to \infty} 
    \sup_{\substack{(s,t) \in T_{2}(l, \eta)\\ |t-t'| \vee |s-s'| < \delta} }
    |\Phi_{n}^{\nu_{n}}(s,t) - \Phi_{n}^{\nu_{n}}(s',t')| 
    = 0.
  \end{equation}

