[Proposition prop:annealed 0 of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $f\in\mathbb{R}$, $u\in(0,1)$, $q\in(0,1)$, and $\zeta\in\mathrm{Prefix}_2(u,q)$. Recall $\mathcal{P}\mathrm{arisi}$ from (equation def:Par of the paper).
		Define the \emph{prefix free energy} 
		\begin{equation*}
			\mathcal{P}(u;q):=\inf_{\zeta'\in\mathrm{Prefix}_2(u,q)}\mathcal{P}\mathrm{arisi}(\zeta')
		\end{equation*}
		and the \emph{complexity functional at level $f$}
		\begin{equation}
			\mathcal{C}_f(u;q)
			\;:=\;
			u\,\bigl(\mathcal{P}(u;q)-f\bigr).
		\end{equation}

		We assume:
		\begin{enumerate}
			\item[\emph{(i)}]
			\emph{(Tail optimality.)} The infimum $\mathcal{P}(u;q)$ is attained at $\zeta$.
			\item[\emph{(ii)}]
			\emph{(Stationarity.)} $(u,q)$ is a critical point of $\mathcal{C}_f$.
		\end{enumerate}

		Let $\varepsilon\in(0,1)$ and let $\mathcal{N}_\varepsilon(f,\zeta,q)$ be the number of critical
		points of $F_{\mathrm{TAP},\zeta}$ in $\mathrm{SUSY}_1(\zeta,\varepsilon)$ with
		$\frac{1}{N}F_{\mathrm{TAP},\zeta}(\mathbf{m})\in(f-\varepsilon,f+\varepsilon)$.  Then
		\[
		\lim_{\varepsilon\to 0}\lim_{N\to\infty}
		\frac{1}{N}\log\mathbb{E}\bigl[\mathcal{N}_\varepsilon(f,\zeta,q)\bigr]
		\;=\;
		\mathcal{C}_f(u;q)
		\;=\;
		\zeta(\{0\})\,\bigl(\mathcal{P}\mathrm{arisi}(\zeta)-f\bigr).
		\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 80 of arXiv:2608.26084, 'Localic Esakia Duality\\via Conic Frames'] We denote by:
	\begin{enumerate}
		\item $\EFrm_\weak$ the full subcategory of~$\dcFrm$ whose objects are Esakia frames;
		\item $\EFrm_\strong$ the wide subcategory of~$\EFrm_\weak$ whose morphisms are the \emph{strong conic morphisms}~$h\colon (E,\dc)\to (F,\dcx)$ satisfying~$h\circ \dc = \dcx\circ h$.
	\end{enumerate}

[Prop 22 of arXiv:2606.08115, '2606.08115'] Let condition (C) be valid for a two-dimensional random walk $\left\{ \ov{S}_n\right\}$.
Then for any $\alpha > 0$ there exists a positive parameter $C = C(\alpha)$ such that for any sufficiently large $n$ and any
$\ov{x} \in K$:
\begin{equation}

\pr\left(\tau(\ov{x})> n, \ov{S}_n +\ov{x} \in K \backslash K_{n, \alpha}\right) \le \frac{C \ln^2n}{n^{p/2 + 1}} u\left(\ov{x}_0 + M \ov{x}\right),
\end{equation}
where
\begin{equation}

K_{n, \alpha}:= \left\{\ov{z} \in K: \mathrm{dist}\left(\ov{z}, \partial K\right) > \alpha \ln n\right\}.
\end{equation}

