[Prop 13 (Randomized measure-valued weak solution) of arXiv:2604.12797, 'A free boundary problem for the mean-field limit of diffusing particles with nonlinear bou'] Let $(\mu_t,I_t,Z_t)_{t\in[0,T]}$ be a limit point of $(\mu^n_t,I^n_t,Z^n_t)_{t\in[0,T]}$. Then, $\mu=(\mu_t)_{t\in[0,T]}$ is a stochastic process taking values in $\mathcal{M}_{\leq 1}(\R^+)$ with $\mu_0=P_0\circ \theta_{a_0}^{-1}$ and it satisfies
\begin{equation}
\di \langle\mu_t,\phi\rangle	=\langle\mu_{t},\tfrac{{1}}{2}\sigma_{A}(t,\cdot)^{2}\partial_{xx}\phi\rangle\dt+\langle\mu_{t}, (b_{A}(t,\cdot)-A^\prime_{t})\partial_{x}\phi\rangle\dt + \di Z^{\phi}_t,
\end{equation}
for all $t\in[0,T]$ and all $\phi \in C^{2}_b(\R)$, almost surely, with 
\begin{equation}
\E\biggl[\int_0^t H_s \di Z_t^{ \phi}\biggr]
= \lim_{\delta \downarrow 0}  \E\biggl[\int_0^t H_s \bigl( \tfrac{1}{2} \partial_x \phi(0) - \phi(0) \gamma(s, C_s) \bigr)\langle \mu_s, \sigma_A(s, \cdot)^2 \psi_\delta  \rangle \ds \biggr],
\end{equation}
for all $t\in[0,T]$, all $\phi\in C_b^2(\R)$, and
all bounded continuous processes $H$ adapted to the filtration \eqref{eq:limit_filtration} generated by $(\mu,I)$, where
\begin{equation}
A_t = a_0 + \alpha\int_{t-\bar{d}}^t \varrho(t-s) I_{s} \ds,\quad C_t = \int_{t-\bar{d}}^t \varrho(t-s) (I_{s} - I_{s-\bar{d
}})\ds,\quad I_t= 1- \mu_t(\R^+).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 210 of arXiv:2601.16377, '2601.16377'] We say that $\boldsymbol{F}(z) = (F_h(z))_{h = 1}^H$ is \emph{tame} if for each $h \in [H]$ there exists a complex neighborhood $\amsmathbb{M}_h$ of $[\alpha_h,\beta_h]$ such that
\begin{itemize}
\item $F_h(z)$ is a holomorphic function of $z \in \amsmathbb{M}_h \setminus [\alpha_h,\beta_h]$;
\item $F_h(x^{\pm}) = \lim_{\epsilon \rightarrow 0^+} F_h(x \pm \ii \epsilon)$ exists for any $x \in (\alpha_h,\beta_h)$;
\item there exists an integer $m_{\boldsymbol{F}}$, called tameness exponent, and a real number $M_{\boldsymbol{F}}$ such that
\[
\sup_{z \in \amsmathbb{M}_h \setminus [\alpha_h,\beta_h]} \big| \big((z - \alpha_h)(z - \beta_h)\big)^{\frac{1}{2}m_{\boldsymbol{F}}} F_h(z)\big| \leq M_{\boldsymbol{F}};
\]
\item the function $x \mapsto F_h(x^+) + F_h(x^-)$ extends to a meromorphic function in $\amsmathbb{M}_h$.
\end{itemize}

[Def weighted stable nodal family of arXiv:2609.04023, 'Characterizing Contractions and Weighted Blowdowns'] \begin{enumerate}
    \item Define input data to be a tuple $(g,\mathscr{A}):=(g,a_1,\dots,a_n)$ consisting of an integer $g\ge 0$ and the {\em weight data} $(a_1,\dots,a_n)\in \mathbb{Q}^n$ satisfying $0<a_j\leq 1$ for $j=1,\ldots,n$ and $2g-2+a_1+a_2+\dots +a_n>0$.
    \item A family of nodal curves with marked points $(C,s_1,\ldots,s_n)\xrightarrow{\pi}B$ is stable of type $(g,\mathscr{A})$ if
    \begin{itemize}
        \item the sections $s_1,\ldots,s_n$ lie in the smooth locus of $\pi$,
        \item for any $\{i_1,\dots, i_r\}\subseteq [n]$ such that $\bigcap_{j=1}^{r}s_{i_j}(B)\neq\emptyset$, we have $a_{i_1}+\dots +a_{i_r}\leq 1$ and,
        \item $K_{\pi}+a_1s_1+a_2s_2+\dots +a_ns_n$ is $\pi$-ample.
    \end{itemize}
\end{enumerate}

[Prop eq:strong:Markov:N of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] Let $T$ be a $(\overline{\mathcal{F}}_{t+})$-stopping time such that  $T > 0$, $\mathbf{N}_{x,r}$-a.e. For every non-negative $\overline{\mathcal{F}}_{T+}$-measurable function $\Phi$  and non-negative measurable function $F$ on $\mathbb{D}(\mathbb{R}_+, \mathcal{M}_{f}(\mathbb{R}_+)\times \mathcal{W}_{\overline{E}})$, we have 
\begin{equation} 
    \mathbf{N}_{x,r} \big( \mathbbm{1}_{\{T<\infty\}} \Phi \cdot  F \big( (\rho_{T + s }, \overline{W}_{T + s } : s \geq 0  ) \big)  \big) 
    = 
    \mathbf{N}_{x,r} \big( \mathbbm{1}_{\{T<\infty\}}  \Phi \cdot  \mathbb{E}^{\dag}_{\rho_T, \overline{W}_T} [ F ]   \big).  
\end{equation}

[Lemma lem:beta_perturb of arXiv:2605.21265, 'The non-Hermitian minor process'] Fix a (small) $c_0>0$ and a (large) $L>0$. For $w_j=E_j\pm\mathrm{i}\eta_j$ it holds that 
\begin{equation}
\beta_+\beta_-(w_1,w_2) = \beta_+\beta_-(\mathrm{i}\Im w_1,\mathrm{i}\Im w_2) +\mathcal{O}\left(\frac{|E_1|}{\eta_1}+\frac{|E_2|}{\eta_2}\right),

\end{equation}
uniformly in $x_1,x_2\in [c_0,1]$, $x_1\le x_2$, $|z_j|\le L$ and $w_j=E_j\pm\mathrm{i}\eta_j$ with $-L\le E_j\le L$, $0<\eta_j\le L$, $j=1,2$. Here by $\beta_+\beta_-(w_1,w_2)$ we abbreviated the dependence of $\beta_+\beta_-$ on $w_1,w_2$, while the parameters $z_1,z_2$ are the same for both $\beta_+\beta_-$ terms in (equation eq:beta_perturb of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thmd 2 of arXiv:2606.08115, '2606.08115'] Let $\bol{Z_n} = \left(Z_n^{(1)}, Z_n^{(2)}\right)$ be a critical PBPJRE. Let the sequence of random vectors $\{\ov{S}_n\}$ be the associated random walk with increments $\ov{X}_i = \left(X_i^{(1)}, X_i^{(2)}\right)$, $i \in \mathbb{N}$. Let
\begin{equation}

\xi_k^{(l)} := \frac{\left(f_{k+1}^{(l)}\right)''(1)}{\left(\left(f_{k+1}^{(l)}\right)'(1)\right)^2}, \quad l = 1, 2; \; k \in \mathbb{N}_0.
\end{equation}
Suppose that $\ex \left|\ov{X}_{i}\right|^2 \ln \left(1 + \left|\ov{X}_{i}\right|\right) < \infty$, $\mathrm{corr}\left(X_i^{(1)}, X_i^{(2)}\right) = \rho \in (0, 1)$, there exists $q > 0$ such that $\ex \left(\xi_1^{(1)}\right)^q < \infty$,
$\ex \left(\xi_1^{(2)}\right)^q < \infty$. Then 
\begin{equation}

\pr\left(Z_n^{(1)} > 0, Z_n^{(2)} > 0\right) \sim \frac{C}{n^{p/2}}, \; n \to \infty,\quad p = \frac{\pi}{ \arccos{(-\rho})}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

