[Defn weak_sol of arXiv:2412.05950, 'Quantitative particle approximation of nonlinear stochastic Fokker-Planck equations with s'] A family of random functions $\left\{\rho_t(\omega): t \ge 0, \omega \in \Omega\right\}$ lying in $S_{\mathcal{F} ^B}^{\infty}\left([0, T] ; L^1 \cap L^q\left(\mathbb{T}^d\right)\right)$ is a solution to ((SPDE_Ito of the paper)) if $\rho_t$ satisfies the following stochastic integral equation for all $\phi \in C^2\left(\mathbb{T}^d\right)$,

\begin{align}
\left\langle \rho_t, \phi\right\rangle &= \left\langle \rho_0, \phi\right\rangle+ \int_0^t\left\langle \rho_s F(\cdot\,, K \ast \rho_s), \nabla \phi \right\rangle ds \nonumber \\
& \quad +\frac{1}{2} \int_0^t\left\langle \rho_s, \sum_{i,j=1}^d \partial_{ij}\phi \,   \sum_{k=1}^d (\nu_s^{ik} \, \nu_s^{jk}+ \sigma_s^{ik} \, \sigma_s^{jk}) \right\rangle \, ds \nonumber \\
&\quad +\int_0^t\left\langle \rho_s, \sum_{i=1}^d \partial_i \phi\,  \sum_{k=1}^{d} \sigma_s^{ik} \right\rangle \, d B_s^k.   
\end{align}

[Thm persistence of arXiv:2410.24170, 'Persistent hubs in CMJ branching processes with independent increments and preferential at'] Assume $(X_{j})_{j \in \mathbb{N}}, (X'_{j})_{j \in \mathbb{N}}$ are defined as in~(equation eq:def-ex of the paper) and Assumption~(ass:gen-ass of the paper) is satisfied. Then, in the process $(\mathscr{T}_{\tau_{n}})_{n \in \mathbb{N}_0}$, we have the following: 
    \begin{enumerate}
        \item   If the series $\sum_{i=1}^{\infty} (X_{i} - X'_{i})$ diverges almost surely, then, almost surely, $(\mathscr{T}_{\tau_{n}})_{n \in \mathbb{N}_0}$ does not contain a persistent hub.
        \item  Suppose that, for $\alpha > 0$ and $K \in \mathbb{N}$ we have



        \begin{equation} 
             \sum_{j=1}^{\infty} \E{e^{-\alpha \sum_{i=1}^{j} X_{i}}} < 1 \quad \text{and} \quad \prod_{i=K+1}^{\infty}\E{e^{\alpha (X'_{i} - X_{i}) }} < \infty.
        \end{equation}
        Then, almost surely, $(\mathscr{T}_{\tau_{n}})_{n \in \mathbb{N}_0}$ contains a persistent hub.  
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 36 of arXiv:2601.16377, '2601.16377'] Let $\boldsymbol{\chi}_{\N}^{(1)}$ and $\boldsymbol{\chi}_{\N}^{(2)}$ be two families (indexed by a large parameter $\N$) of discrete random $K$-dimensional real vectors. We say that the distribution of $\boldsymbol{\chi}_{\N}^{(1)}$ is asymptotically equal to the distribution of $\boldsymbol{\chi}_{\N}^{(2)}$ if
\begin{equation}

 \lim_{\N\rightarrow\infty} \sup_{f \in \textnormal{Lip}_1} \big|\E[f(\boldsymbol{\chi}_{\N}^{(1)})]-\E[f(\boldsymbol{\chi}_{\N}^{(2)})]\big| =0,
\end{equation}
where $\textnormal{Lip}_1$ is the set $1$-Lipschitz functions real-valued functions on $\amsmathbb{R}^K$ that are upper-bounded by $1$. If \eqref{eq_asymptotic_equivalence} holds, we write $\chi_{\N}^{(1)} \stackrel{\textnormal{d}}{\sim} \chi_{\N}^{(2)}$.

