[Corollary 9 of arXiv:2604.12334, 'On additive averaging kernels for finite Markov chains'] For any $\pi$-reversible $P$, $S \neq \mathcal{X}, \emptyset$ and $\mathcal{X} = S \sqcup S'$, we have that for any fixed $\alpha \in (0,1),$ the non-trivial set $S \subset \mathcal{X}$ that minimises $\| A_\alpha(S) - \Pi\|_{F, \pi}^2$ maximises the function 
     \begin{equation} 
         g(S) = g(S,P) := \frac{1}{\pi(S) \pi(S')} \sum_{\substack{x \in S \\ y \in S'}} \pi(x) P(x,y).
     \end{equation}

     The other direction holds as well. Concretely, we have that 
     \begin{align*}
         \argmin_{S \neq \mathcal{X}, \emptyset} \|A_\alpha(S) - \Pi\|_{F, \pi}^2 &= \argmax_{S \neq \mathcal{X}, \emptyset} g(S),\\
         \argmax_{S \neq \mathcal{X}, \emptyset} \|A_\alpha(S) - \Pi\|_{F, \pi}^2 &= \argmin_{S \neq \mathcal{X}, \emptyset} g(S).
     \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma claim_estimate_remainder_terms of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] For any admissible sequence of operations ${\mathcal{O}}_1,\ldots,{\mathcal{O}}_T$, there exists a constant $C>0$ that does not depend on $\varepsilon$ such that
        \begin{equation}\nonumber
            \begin{aligned}
            \mathbb{E}{\mathcal R}_{{\mathcal{O}}_T\circ\cdots\circ{\mathcal{O}}_1\left({\mathcal T_0}\right)}\prec  N^{C\varepsilon}N^{-5/3}k^{2/3}\left\lVert A \right\rVert_{\text{\rm{HS}}}^2, 
            \end{aligned}
        \end{equation}
        where ${\mathcal R}_{{\mathcal{O}}_T\circ\cdots\circ{\mathcal{O}}_1\left({\mathcal T_0}\right)}$ is defined as in (equation reminder_terms_expansion of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 of arXiv:2606.15432, 'A Concavity Theorem for the Parisi PDE'] For all $(s,x)\in [0,1]\times \R$,
\begin{equation}
\paraop_s
v^\gamma(s,x)
=
(\partial_x\Psi^\gamma)^2.

\end{equation}
Therefore, for all $0\leq \rho\leq r\leq 1$,
\begin{equation}
P_{\rho,r}^\gamma[v^\gamma(r,\cdot)](x)
=
1-\int_r^1 w_{\rho,\sigma}^\gamma(x)\,d\sigma.

\end{equation}

