[Corollary 7 of arXiv:2606.27774, 'Variational Formulas for the Spectrum of\\ Block Wishart Matrices'] Fix $\alpha\in(0,\infty)$, integer $k\ge1$, $\nu\in\cuP_0(\sa{k}{\C})$. 

Let $\{\nu_j\}_{j\ge 1}$ be a sequence $\nu_j\in\cuP_0(\sa{k}{\C})$ such that
$\nu_j \stackrel{w}{\Rightarrow} \nu$ as $j\to\infty$, and,
for all $\delta>0$ there exists $j_0(\delta)$ such that
\begin{align}
j\ge j_0(\delta)\;\; \Rightarrow\;\;
\supp(\nu_j) \subseteq\bigcup_{\bT\in\supp(\nu)} \big\{\bX\in \sa{k}{\C}
:\;\; \bX\succeq \bT-\delta\bI\big\}\, .
\end{align}
Then
\begin{equation}
    \lim_{j\to \infty} \zeta_{-,\up{\nu_j,\alpha}} =  \zeta_{-,\up{\nu,\alpha}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem t:orgs of arXiv:2604.03979, 'Stationary Distributions in Monotone Markov Models: Theory and Applications'] Let $P$ be an increasing stochastic kernel on $S$.
    If $P$ is order reversing, then $P$ is globally stable if and only
            if $P$ is bounded in probability. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary corollary_riccati_with_source of arXiv:2606.29622, 'Affine Structure of the Brownian Signature'] Consider a Riccati equation 
    \begin{equation}
    \begin{cases}
        \bm \dot{\bm{\psi}}_t + \bm{\psi}_t|_{{\color{NavyBlue}{\mathbf{0}}}} + \frac{1}{2}\, \bm \bm{\psi}_t|_{{\color{NavyBlue}{\mathbf{11}}}} + \frac{1}{2}\, \bm \bm{\psi}_t|_{{\color{NavyBlue}{\mathbf{1}}}}^{\mathrel{\sqcup \mkern -3mu \sqcup} 2} + \bm{\psi}_t|_{{\color{NavyBlue}{\mathbf{1}}}}\mathrel{\sqcup \mkern -3mu \sqcup}\bm{\gamma} + \bm f = 0,\quad t \in [0, T]\\
        \bm \bm{\psi}_T = \bm{p},
    \end{cases}
    \end{equation}
    where $\bm{p}, \bm{\gamma}, \bm f \in \TA[2]$. If the coefficient 
    $$
    \widetilde\bm{p} := \bm{p} + \left(\bm f - \dfrac{1}{2}\bm{\gamma}|_{{\color{NavyBlue}{\mathbf{1}}}} - \dfrac12\bm{\gamma}^{\mathrel{\sqcup \mkern -3mu \sqcup} 2}\right){\color{NavyBlue}{\mathbf{0}}} + \gamma{\color{NavyBlue}{\mathbf{1}}} \in \mathcal{B},
    $$
    then there exists a solution $\bm{\psi}$ and $r > 0$ such that
    \begin{enumerate}
        \item For any ${\color{NavyBlue}{\mathbf{v}}} \in V\,$, the function $t \mapsto \bm \psi_t^{{\color{NavyBlue}{\mathbf{v}}}}$ is $C^1$ on $[0\,, T]\,$.
        \item For any ${\color{NavyBlue}{\mathbf{v}}} \in V\,$, $\bm \psi_t|_{{\color{NavyBlue}{\mathbf{v}}}} \in \mathcal{A}_{\widetilde\bm{p}, r}$.
    \end{enumerate}

[Lem E.g., Lemma 2.8 of~\cite{MaTo} of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] Starting from a domain $\Lambda$ with boundary conditions $\tau$, if we change the boundary conditions on a subset $\Delta \subset \partial \Lambda$ of size $|\Delta|$ to get boundary conditions $\tau^{\Delta}$, then 
    \begin{align*}
        t_{\textsc{mix}}(\Lambda, \tau) \le  4\beta |E(\Lambda)|\log 2\cdot e^{4\beta |\Delta|}\cdot  t_{\textsc{mix}}(\Lambda, \tau^\Delta)
    \end{align*}

[Theorem thm:lattice of arXiv:2412.09145, 'Asymptotic expansions for normal deviations of random walks conditioned to stay positive'] Assume that $\mathbf E|X|^{r+3}$ is finite for some integer $r \ge 1$.
Assume also that $S_n$ is integer valued with maximal span $1$. Then there exist polynomials $P_1$, $P_2$,\ldots, $P_{r+1}$ such that
\begin{align*}
    \mathbf P(S_n=x,\tau>n) 
=
    e^{-\frac{x^2}{2\sigma^2n}}
    \sum_{\nu = 2}^{r+1}
        \frac{P_\nu(x/\sigma\sqrt{n})}{n^{\nu/2}} 
+
    O\left( \frac{1}{\min (n^{(r+2)/2}, x^{r+2})} \right).
\end{align*}
Every polynomial $P_\nu$ has degree $3\nu-5$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 22 of arXiv:2609.04033, 'From configuration spaces to graph complexes via $\mathbf{FA}$-modules'] Let $d>0$.  The $\mathbf{FS}$-module structure on $H^d(\Gamma_{2,\ast})$ lifts to an $\mathbf{FA}$-module given by:	

	\begin{itemize}
		\item  If $d\equiv 2 \text{ mod } 4$ then $H^d(\Gamma_{2,\ast}) = 0$.
		\item  If $d\equiv 0 \text{ mod } 4$ then $H^d(\Gamma_{2,\ast}) = 
		\mathsf{C}_{(2^{d/2})}$.
		\item If $d=q+1$ is odd then 

	$$H^{d}(\Gamma_{2,\ast}) = 
\ds\bigoplus_{0\leq i<q/2} w_{i,q}\mathsf{C}_{(2^i,1^{q-2i})}$$

where 
$$w_{i,q} = \begin{cases}
	 \text{dim}(\op{M}_{q-2i+2}) & \text{ if } i \text{ is odd,} \\ 	 
	 \text{dim}(\op{S}_{q-2i+2}) & \text{ if } i \text{ is even.} 
\end{cases}
$$
the dimensions of the space of modular (resp.\ modular cusp) forms of the given weight.
	\end{itemize}

[Prop 15 of arXiv:2608.03956, 'From Triangular Array Progression\\ to Near-Log-Concave State Transitions'] Let $\tau^{(1)}$ be defined by $\tau^{(1)}_{n,j} \triangleq \T^{(1)}_{n + 3, j + 3}$ for every $n \geq 0$ and $1 \leq j \leq n +1$. Then, 
\begin{enumerate}
\item $\tau^{(1)}_{n,*}$ is a strictly-positive log-concave sequence for every $n\geq 2$
\item $\tau^{(1)}$ generates a lower-triangular Toeplitz matrix by setting $\emph{diag}(\tau^{(1)}) = 0$  
\end{enumerate}

[Lemma 47 of arXiv:2601.16377, '2601.16377'] Suppose that Assumption~\ref{Assumptions_Theta} holds and let
$\nu$ be an integrable signed measure on
$\amsmathbb{A}$ such that
\begin{equation}

\forall e \in [\mathfrak{e}]\qquad \mathfrak r_e\big((\nu([\hat a'_h,\hat b'_h]))_{h = 1}^H\big) = 0.
\end{equation}
Then the limit in \eqref{eq_functional_quadratic_alternative} is either nonpositive or $-\infty$, and it admits the Fourier representation \eqref{eq_Fourier}
\begin{equation}

 \mathcal I^{(2)}[\boldsymbol{\nu}]=-\int_{0}^{+\infty} \frac{\dd s}{s}\bigg( \sum_{g,h = 1}^H \theta_{g,h}\,\widehat \nu_g(s) \widehat \nu_{h}^*(s) \bigg).
\end{equation}
 In particular, both sides of \eqref{eq_I_quadratic_Fourier} are nonpositive and they achieve the value $-\infty$ simultaneously.

