body:
[Theorem 39 ({\cite[Theorem 1.2 and Theorem 1.5) of arXiv:2607.18104, '2607.18104'] {BLL:FixedPointGeneral}}]
Suppose that $\lambda_N \in \Lambda_{N,k}$ with $k=\lfloor \theta N\rfloor$ for some $\theta \in (0,1)$ is a family of TASEP initial conditions so that for some $\hfixp_0 \in \UCp$
\begin{equation}
  \frac{-\hpTASEP(\lambda_N;\alpha N,0) + \theta\alpha N}{-\sqrt{2\theta(1-\theta)}N^{1/2}}   \rightarrow \hfixp_0(\alpha)
\end{equation} as $N\to \infty$ where the convergence is as a process in $\alpha$ in the space $\UCp$. Then for all $M \in \N$, 
and all $\tau=(\tau_i)_{i \in \lbr M \rbr}$, $\alpha=(\alpha_i)_{i \in \lbr M \rbr}$ and $\beta=(\beta_i)_{i \in \lbr M \rbr}$, 
 \begin{equation}
 \lim_{N \rightarrow \infty} \P\left( \bigcap_{i=1}^{M} \left\{ \frac{-\hpTASEP(\lambda_N;y_i,t_i)+\theta y_i-\theta(1-\theta)t_i}{ -\sqrt{2\theta(1-\theta)}N^{1/2}}\leq \beta_i \right\} \right) = F_{\hfix_0}^M(\beta,\alpha,\tau) , 
 \end{equation}
 where we set
 \begin{equation}
     t_i := \frac{\tau_i N^{3/2}}{\sqrt{\theta(1-\theta)}}, \quad y_i := \alpha_i N + (1-2\theta)t_i , 
 \end{equation}
 and $(F_{\hfix_0}^M)$ has an explicit formula given in Definition~2.1 of \cite{BLL:FixedPointGeneral}. Moreover, the family $(F_{\hfix_0}^M)$ defines a random field $(\alpha,\tau) \mapsto \mathcal{H}^{\per}_1(\hfixp_0;\alpha,\tau)$, called the \textbf{periodic KPZ fixed point}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:two-large-position of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] If $m\ge40$, then
\begin{equation}
  \kappa\le\floor*{\frac{3m}{2}}+\mu(d)+2\mu(\kappa),
  \qquad 1\le d<\frac\kappa2.
\end{equation}
Moreover
\begin{equation}
  \kappa\le3m,
\end{equation}
and, setting $\Pi_m=\floor{5m/2}+1$,
\begin{equation}
  p=\kappa-d-1\le \Pi_m.
\end{equation}

[Lemma lem:weighted-energy-detailed of arXiv:2609.00556, 'Higgs--Demailly System and Positivity of Higgs Bundles'] For every $0<\sigma\leq1$, the normalized endomorphisms $H_i$ satisfy
\begin{align}
 &\|H_i^{-\sigma/2}\partial^{h_{\rm ref}}H_i^\sigma\|_{L^2}^2
 +\|H_i^{-\sigma/2}[\theta_{h_{\rm ref}}^*,H_i^\sigma]\|_{L^2}^2
 \leq C,
\end{align}
where $C$ is independent of both $i$ and $\sigma$.  Moreover, the constant below can be chosen independent of $\sigma$:
\begin{equation}
 \int_M\operatorname{tr}(H_i^\sigma)\,\omega\geq c_0>0.
\end{equation}

[Prop strongly-convex-coordinate-gradients of arXiv:2608.30382, 'Convergence rates for the RMSprop optimizer with full control of the hyperparameters'] Let $ m, d, M \in {\mathbb N} $, $ \mu, B, R \in (0,\infty) $, and let
$\mathcal V\subseteq{\mathbb R}^d$. Let $U$ be an ${\mathbb R}^m$-valued random variable with a
Lebesgue density $g$ satisfying
\bas{
  \|g\|_{L^\infty}\le B,
  \qquad
  \text{and}
  \qquad
  {\mathbb P}\bigl( | U | < R \bigr) = 1 .
}
Let $U_1,\dots,U_M$ be independent copies of $U$, and set
$\mathbf U=(U_1,\dots,U_M)$. Let
$\ell:{\mathbb R}^d\times{\mathbb R}^m\to{\mathbb R}$ be differentiable in its first argument. For
every $ \theta \in \mathcal V $, $ i \in \{ 1, \dots, d \} $, define
\bas{
  \varphi_{\theta,i} \colon {\mathbb R}^m \to {\mathbb R},
\qquad
  \varphi_{\theta,i}( u )
  =
  \frac{\partial\ell}{\partial\theta_i}(\theta,u),
}
and assume that $\varphi_{\theta,i}$ is $\mu$-strongly convex.
For every $ \theta \in \mathcal V $, $ i \in \{ 1, \dots, d \} $, define
\bas{
X_M^{(i)}(\theta,\mathbf U)
=-\frac1M\sum_{r=1}^M
\frac{\partial\ell}{\partial\theta_i}(\theta,U_r).
}
Let $\omega_m$ denote the Lebesgue volume of the Euclidean unit ball in
${\mathbb R}^m$, and set
\bas{
C_m=1+m3^{m-1}
}
and
\bas{
s_0
=\mu\min\left\{
\frac{R^2}{4},
\frac{1}{
16B^2\omega_m^2C_m^2R^{2m-2}}
\right\}.
}
Then the minibatch innovation $(X_M,\mathbf U)$ is $(c_M,q)$-regular on
$\mathcal V$ with
\bas{
c_M=\frac{(1-e^{-1})s_0^2}{2M^2}
\qquad
  \text{and}
\qquad
q=\frac{1-e^{-1}}2.
}
If, in addition, the coordinate derivatives of $\ell$ are uniformly bounded
on $ \mathcal V \times \{ u \in {\mathbb R}^m \colon | u | < R \} $,
then assumption~(equation eq:combined-main-boundedness of the paper) in
(thm:combined-early-late-numerical-time of the paper) is satisfied for $X_M$.

[Theorem 1 (Absorption probability for a random walk) of arXiv:2608.16752, 'Absorption Probabilities for Random Convex Hulls: Distribution-Freeness via the Wall-Cross'] Let $d\geq 1$ and $n\geq d+1$. Let $\xi_1,\dots,\xi_n$ be (possibly dependent) random $d$-dimensional vectors with partial sums
$$
S_i = \xi_1 + \dots + \xi_i,\quad  1\leq i\leq n,\quad  S_0=0.
$$
We impose the following conditions on the joint distribution of the tuple $(\xi_1,\dots, \xi_n)$:
\begin{itemize}
\item [(i)] \emph{Symmetric exchangeability:} For every permutation $\sigma$ of $\{1,\dots,n\}$ and every choice of
signs $\eps_1,\dots,\eps_n\in\{+1,-1\}$, we have the equality in
distribution
    $$
    (\xi_1,\dots,\xi_n) \stackrel{d}{=}(\eps_1 \xi_{\sigma(1)}, \dots, \eps_n \xi_{\sigma(n)}).
    $$
\item[(ii)] \emph{General position of partial sums:}
For every $1\leq i_1 < \dots < i_d\leq n$, the probability that the vectors $S_{i_1}, \dots,S_{i_d}$ are linearly dependent is $0$.
\end{itemize}

Then
\begin{align}
    \pwalk{n}{d}
    &:=
    \pr\big(0 \in \Conv(S_1, S_2, \dots, S_n)\big)
    =
    \frac{2}{2^{n}n!}
    \sum_{r\geq 0}
    \stirlingb{n}{d+1+2r},

    \\
        \qwalk{n}{d}
    &:=
    \pr\big(0 \notin \Conv(S_1, S_2, \dots, S_n)\big)
    =
    \frac{2}{2^{n}n!}
    \sum_{r\geq 0}
    \stirlingb{n}{d-1-2r}.

\end{align}
Here, the numbers $\stirlingb{n}{k}$ with $n\in \{1,2,\dots\}$ and $k\in \mathbb Z$ are the $B$-Stirling numbers of the first kind defined by the generating function
\begin{align*}
    (t+1)(t+3) \cdots (t+2n-1)
    = \sum_{k\in \mathbb Z} \stirlingb{n}{k}\, t^k.
\end{align*}
In particular, $\stirlingb{n}{k}= 0$ for $n\in \{1,2,\dots\}$ and $k\notin\{0,\dots,n\}$, so that the sums appearing above terminate after finitely many nonzero terms. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 7 of arXiv:2605.07050, 'Universality of the fluctuations of the free energy in generalized Sherrington--Kirkpatric'] Recall the definition of $F_N(\beta)$ in Definition \ref{defn:sub_Gaussian}. Suppose that $W$ is a Wigner matrix, $\sqrt{N} W_{ij}$ $(i<j)$ is symmetric, and one of the following is true:
\begin{itemize}
\item the (rescaled) entry $\sqrt{N} W_{ij}$ is strictly sub-Gaussian, or
\item the (rescaled) prior $\sqrt{N} x_i$ is bounded, and its distribution is absolutely continuous in a neighborhood of $0$.
\end{itemize}
Suppose that Assumption \ref{assump:second_moment} holds with $\SNR_c$. Then, the statement in Theorem \ref{thm:free_energy_1} holds without any change for any $\beta \in (0, \sqrt{\SNR_c})$. In particular, it holds for any $\beta \in (0, 1/\sigma)$ if the prior is sub-Gaussian with variance proxy $\sigma^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

