[Lemma 30 (Scalar quotient recursion and convergence) of arXiv:2608.30027, 'Under Ricci flow, a 3-torus goes flat'] Fix \(C_0\geq0\), and let \(b_k\geq0\), \(k\geq0\), be a summable
sequence.  Suppose that the sequences \(E_k\geq0\) and \(\ell_k>0\),
\(k\geq0\), satisfy
\begin{equation}
        E_{k+1}\leq \frac{100E_k}{1+99E_k/2}+C_0b_k,
        \qquad
        \ell_{k+1}\leq(1+C_0b_k)
        \left(\frac{1+99E_k/2}{100}\right)^{1/2}\ell_k.
\end{equation}
Then \(\sup_kE_k<\infty\) and \(\sup_k\ell_k<\infty\), with a bound depending
only on \(E_0\), \(\ell_0\), \(C_0\), and \(\sum_k b_k\).  If, in addition,
\begin{equation}
        \inf_k\ell_k>0,
\end{equation}
then there is a number \(\ell_\infty>0\) such that
\begin{equation}
        \ell_k\longrightarrow\ell_\infty,
        \qquad E_k\longrightarrow2.
\end{equation}

[Proposition 160 of arXiv:2601.16377, '2601.16377'] The total number of lozenge tilings of the trapezoid of width $N$ and with dents at $\ell_1 < \ell_2 < \dots < \ell_N$ is
\begin{equation}

\prod_{1 \leq i < j \leq N}{\frac{\ell_j - \ell_i}{j - i}}.
\end{equation}

[Theorem thm:main of arXiv:2509.02074, 'On the Kolmogorov-Feller weak law of large numbers for the Fr\'{e}chet mean on non-compact'] Suppose that Condition (C) holds. If either of the following conditions is satisfied, then $\mu_{n} \overset{\mathbb{P}}{\to} \mu$ as $n$ tends to infinity.
\begin{enumerate}
  \item[(i)] For some $\mu_0 \in M$, it holds that $\sum_{i=1}^{n} \mathbb{P}(d(X_i, \mu_0) > n) \underset{n \to \infty}{\to} 0$ and $n^{-2}\sum_{i=1}^{n}\mathbb{E}[d^2\{\overline{X_{n,i}}(\mu_0), \mu_0\}] \underset{n \to \infty}{\to} 0$;

  \item[(ii)] The $X_i$'s are identically distributed and for some $\mu_0 \in M$, $n\mathbb{P}(d(X_1, \mu_0) > n) \underset{n \to \infty}{\to} 0$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem T:InvMea of arXiv:2412.03521, 'On ergodic properties of stochastic PDEs'] Let $u(t,x)$ be the solution to~(equation E:SHE of the paper) starting from a rough initial
  condition $\mu$, namely, $\mu$ is a signed Borel measure on $\mathbb{R}^d$ such
  that~(equation A:icon of the paper) holds. Assume that
  \begin{enumerate}[wide, labelwidth=!, labelindent=0pt, label=\emph{(\roman*)}]
    \setlength\itemsep{.1in}

    \item  $b(x,u)=b(u)$ and it verifies condition~(equation E:Cond-b of the paper).

    \item  there are two admissible weight functions $\rho$
      and $\tilde{\rho}$ such that~(equation E:rhorho of the paper) holds and
      \begin{equation}
        \limsup_{t\to\infty}\: \mathcal{G}_{\tilde{\rho}}(t;|\mu|) < \infty;
      \end{equation}

    \item  the spectral measure $\widehat{f}$
      satisfies~(equation E:Upsilon_0 of the paper), i.e., $\Upsilon(0)<\infty$ and the
      Lipschitz constant $L_b$ is small enough such that $4 L_b^2 \Upsilon(0)
      <1$;

    \item  for some $\alpha \in
      \left(4L_b^2\Upsilon(0),1\right)$, the spectral measure $\widehat{f}$
      satisfies the following condition
      \begin{align}
        \Upsilon_\alpha(\beta) \coloneqq \left(2\pi\right)^{-d} \int_{\mathbb{R}^d} \frac{\widehat{f}(\ensuremath{\mathrm{d}}\xi)}{\left(\beta+\lvert\xi\rvert^2\right)^{1-\alpha}}<\infty
        \quad \text{for some (hence all) $\beta>0$.}
      \end{align}

  \end{enumerate}
  Then we have that
  \begin{enumerate}[wide, labelwidth=!, labelindent=0pt, label=\emph{(\arabic*)}] \setlength\itemsep{.1in}

    \item for any $\tau>0$, the sequence of laws of
      $\{\mathcal{L}u(t,\cdot;\mu)\}_{t\ge \tau}$ is tight, i.e., for any
      $\epsilon \in (0,1)$, there exists a compact set $\mathscr{K}\subset
      L^2_{\rho}(\mathbb{R}^d)$ such that
      \begin{equation}
        \mathscr{L}u(t,\cdot;\mu)(\mathcal{K}) \ge 1-\epsilon,
        \qquad \text{for all $t\ge \tau>0$};
      \end{equation}

    \item there exists a nontrivial invariant measure for~(equation E:SHE of the paper).

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 3 (Regularity of the coefficient fields) of arXiv:2608.22636, 'Q-Learning with Stable Infinite-Dimensional \\Linear Function Approximation'] Suppose Assumptions~\ref{assump:mdp}, \ref{assump:stable_kernels}, and \ref{assump:stepsizes} hold. Then, for every $n\ge0$, $\theta_n^\mrm U,\theta_n^\mrm N\in\Theta$. Moreover, the coefficient fields are also Lipschitz with
\begin{equation}
        [\theta_n^{\mrm U}]_{\rho}
        \le L_{0,\rho} + \frac{2\alpha_{\mrm U} L_{\kappa,\rho}}{1-\gamma}
        \log\crbk{\frac{n+n_0^{\mrm U}}{n_0^{\mrm U}}},

\end{equation}
and
\begin{equation}
        [\theta_n^{\mrm N}]_{\rho}
        \le
        L_{0,\rho}+
        \frac{2\alpha_{\mrm N} L_{\kappa,\rho}}{1-\gamma} \crbk{\frac{1}{c_\wedge}+\frac{1}{c_\wedge^2}}
        \log\crbk{\frac{n+n_0^{\mrm N}}{n_0^{\mrm N}}}.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Ppn 211 (quenched second moment bounds for $\vY$ and $\vY^\frozen$) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] For all $0\le s<t\le1$ we have
    \[
    \sum_{\sigma\in\{\RomII,\RomIII,\Ising\}}
    \frac{\bE[(Y^\sigma(t)-Y^\sigma(s))^2]}{(t-s)}
    \le L^{O(1)} \bigg\{
    (\MAX_N)^2+ \frac{(\SMAX_N)^2\BUCKETS}{N\delta}
    \bigg\}
    = L^{O(1)} (\TMAX_N)^2
    \,,
    \]
with $\TMAX_N$ defined by \eqref{e:def.TMAX}. The same bound holds with $\vY^\frozen$ in place of $\vY$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 9 (Uniform Ginibre power bound) of arXiv:2608.20998, 'Free-Probability Kernels for Zero-Rollout Hyperparameter Selection in Reservoir Computing'] Let
\[
A_n
=
(1-\alpha)I_n
+
\alpha\frac{\sigma_r}{\sqrt n}G_r^{(n)}
\]
and assume $\sigma_r<1$. For any
$1<R<\sigma_r^{-1}$, set
$q_R:=1-\alpha+\alpha\sigma_rR<1$.
Almost surely, there are finite random constants $C_R$ and $N_R$ such
that, for all $n\geq N_R$ and $m\geq0$,
\begin{equation}
\lVert A_n^m\rVert
\leq
C_Rq_R^m.

\end{equation}
Consequently, for bounded input histories,
\begin{equation}
x_t^{(\infty)}
:=
\alpha\sum_{k=0}^{\infty}
A_n^kW_{\rm in}^{(n)}u_{t-1-k}

\end{equation}
is well defined for all sufficiently large $n$, and
\begin{equation}
\limsup_{n\to\infty}
\frac1{\sqrt n}
\left\|
x_t^{(\infty)}-x_t^{(L)}
\right\|
\leq
\frac{\alpha C_R\sigma_{\rm in}U}
{\sqrt{d_{\rm in}}(1-q_R)}
