[Theorem thm:moderate.dev.FPP of arXiv:2411.02046, 'Speed of Convergence and Moderate Deviations of FPP on Random Geometric Graphs'] Consider first-passage percolation as in Theorem~(thm:speed.FPP of the paper), under the same assumptions as in that theorem. There exist finite constants~$\upvarphi > 0$ and~$C > 0$ such that, for~$x \in \R^d$ with~$\|x\|$ large enough,
	\begin{equation}
		\frac{\|x\|}{ \upvarphi} \leq  \E\left[ T(x) \right]   \leq \frac{\|x\|}{ \upvarphi} + C \sqrt{\|x\|} \log\big(\|x\|\big)
	\end{equation}
	and
    \begin{equation} 
    \operatorname{Var} T(x) \le C\|x\| \log \big(\|x\|\big).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop.L2FluxErr of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] We have the following estimates for the two-scale expansion $\widetilde{G}_\lambda$:
		\begin{enumerate}
			\item [gu2025relaxation] There exists a finite positive constant $C(d, c_{-},c_{+})$ such that 
			\begin{equation*}
				\norm{\widetilde{G}_\lambda-\overline{G}_\lambda}^2_{L^2}\leqslant C3^{2m}\expec{\overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}} \overline{G}_\lambda}.
			\end{equation*}
			\item [gu2025relaxation] There exists an exponent $\alpha(d,c_{-},c_{+}, \mathbf{r}) > 0$ and a finite positive constant $C(d,c_{-},c_{+}, \mathbf{r},\rho)$ such that the following estimate holds for any $V\in L^2$:
			\begin{equation*}
				\left|\expec{V,-\mathcal{L}\widetilde{G}_\lambda+{\overbracket[1pt][-1pt]{\mathcal{L}}} \overline{G}_\lambda}\right|\leqslant C\left\langle V,-{\overbracket[1pt][-1pt]{\mathcal{L}}} V \right\rangle^{\frac{1}{2}}\left(3^{-\alpha m}\expec{\overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}} \overline{G}_\lambda}^{\frac{1}{2}}+3^m \expec{-{\overbracket[1pt][-1pt]{\mathcal{L}}} \overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}} \overline{G}_\lambda}^{\frac{1}{2}}\right).
			\end{equation*}
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:DDapprox of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] (An Approximation for Donsker's Delta) For all $x\in (0,1)$ it holds that
	\begin{equation}
		L_+^2(\mathcal{S}'(\mathbb{R}), \mu) \mathrel{\reflectbox{$\in$}} \gamma_{\varepsilon}(\beta_x) \xrightarrow{\varepsilon \downarrow 0} \delta_0(\beta_x) \;\,\text{in $(\mathcal{S})'$},
	\end{equation}
	and for all $\varepsilon >0$, $x\in (0,1)$ and $\varphi \in \mathcal{S}(\mathbb{R})$ it holds
	\begin{align*}
		&\mathrm{T}(\gamma_{\varepsilon}(\langle q_x, \cdot \rangle))(\varphi)
		= \frac{1}{\sqrt{2\pi (x(1-x)+\varepsilon)}}\\
		&\quad\quad\quad \cdot\exp\left( -\frac{1}{2}\int_{\mathbb{R}}\varphi^2ds + \left(\frac{1}{2x(1-x)}-\frac{\varepsilon}{2(x(1-x)+\varepsilon)}\right) \left(\int_{\mathbb{R}} q_x \varphi ds\right)^2\right),
	\end{align*}
	and further, for all $z\in\mathbb{C}$, we have
	the bound
	\begin{equation}
		|\mathrm{T}(\gamma_{\varepsilon}(\langle q_x, \cdot \rangle))(z\varphi)|\leq \frac{1}{\sqrt{2\pi x(1-x)}}\exp\left(\frac{3}{2}|z|^2\|\varphi\|_{L^2(\mathbb{R})}^2\right).
	\end{equation}

[Corollary eq:BregEsts of arXiv:2412.06420, 'Accuracy, Estimates, and Representation Results'] Also iff
	\begin{align}\mathrm{Exp}_p\mathsf{acc}(e)-\mathrm{Exp}_p\mathsf{acc}(x)={\varphi(p)-\varphi(x)-(p-x)\varphi'(x)}
	\end{align}where $e:=\mathrm{Exp}_p[V]$.

[Prop 4 of arXiv:2604.24189, 'Malliavin calculus and densities for chaos-driven stochastic differential equations'] Under the conditions and with the notations of Proposition \ref{pro:Nualart}, the mapping
\begin{align}
T & \, : \, W_{2}^{1-\alpha}\left(0, T; \mathbb{R}^{m}\right) \times  W_{1}^{\alpha}\left(0, T; \mathbb{R}^{d}\right) \to  W_{1}^{\alpha}\left(0, T; \mathbb{R}^{d}\right) \nonumber \\ &\, : \, (\psi,x) \mapsto x-x_0-\int_0^\star b(x_s) ds - \int_0^\star \sigma(x_s) d(\varphi_s+\psi_s)
\end{align}
is Fréchet differentiable with, for any $(\psi,x) \in W_{2}^{1-\alpha}\left(0, T; \mathbb{R}^{m}\right) \times  W_{1}^{\alpha}\left(0, T; \mathbb{R}^{d}\right)$, $\phi \in W_{2}^{1-\alpha}\left(0, T; \mathbb{R}^{m}\right) $ and $y \in W_{1}^{\alpha}\left(0, T; \mathbb{R}^{d}\right)$, for all $1 \leq k \leq d$,
\begin{equation}
(\mathcal{D}_1 T (\psi,x) [\phi])^k = - \sum_{\ell=1}^m \int_0^\star \sigma_{k,\ell}(x_s) d\phi_s^\ell
\end{equation}
and
\begin{equation}
(\mathcal{D}_2 T (\psi,x) [y])^k=y^k-\sum_{p=1}^d \int_0^\star \partial_p b_k(x_s)y_s^k ds - \sum_{p=1}^d \sum_{\ell=1}^m \int_0^\star \partial_k \sigma_{p,\ell} d(\varphi_s^\ell+\psi_s^\ell).
\end{equation}
Furthermore, $\mathcal{D}_2 T (0,x)$ is a linear homeomorphism from $W_{1}^{\alpha}\left(0, T; \mathbb{R}^{d}\right)$ to\\  $C^{1-\alpha}\left(0, T; \mathbb{R}^{d}\right)$ and we have, for any $\varphi \in W_{2}^{1-\alpha}\left(0, T ; \mathbb{R}^{m}\right)$
\begin{equation}
\mathcal{D} \Psi (\varphi)=-\mathcal{D}_2 T (0,x)^{-1} \circ \mathcal{D}_1 T (0,x).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:lines of arXiv:2608.30254, 'Exact Recovery Thresholds for Weighted Data Selection\\ in Vector-Valued Linear Regression'] Let the features span $\mathbb{R}^d$ and $\tau(D)=(m+1)d=k$. Then:
\begin{enumerate}
\item every data point with $x_i\ne0$ belongs to some positive circuit of
  dyads supported on a single feature line and of size exactly $m+1$;
\item there is no positive circuit of dyads whose features span a subspace of
  dimension $\ge2$, and no line circuit of size $\le m$; in particular no
  point has $x_i\ne0$ and $\rho_i=0$;
\item the nonzero features lie on exactly $d$ linearly independent lines.
\end{enumerate}
Consequently, any dataset whose nonzero features are \emph{not} of this
$d$-line form satisfies $\tau(D)\le(m+1)d-1$ and is recovered exactly within
budget $(m+1)d-1$.

[Lemma Determinant lemma of arXiv:2608.27248, 'Optimal Transport and the ABP Method in Higher Codimension'] Set $Z=\nabla^\Sigma\log f+H\in\mathbb{R}^{n+4}$.  For every $(x,y)\in\mathcal{C}$,
\begin{equation}
 \operatorname{tr} Q_x(y)=nf(x)^{\frac{1}{n-1}}
 -\big(h_{\mathcal E}(Z(x))+\langle Z(x),\Phi(x,y)\rangle\big),
\end{equation}
and
\begin{equation}
 0\leq\bigl(\det Q_x(y)\bigr)^{\frac{1}{n}}
 \leq\frac{\operatorname{tr} Q_x(y)}n\leq f(x)^{\frac{1}{n-1}}.
\end{equation}

