body:
[Defn 1 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $\varrho\in \hspace{0.1cm} ]0,1]$. We define $\mathscr{C}^{0,\varrho}_{\mathrm{pw}}S_d$ as the set of functions $f:[0,1]^d_x\times \T^d_\xi\to \C$ that are smooth with respect to $\xi$ and such that 
    \begin{enumerate}
        \item there exists a finite family of open connected disjoint sets $U_1,...,U_s$ of $[0,1]^d$ so that
        \begin{equation}
            \overline{\bigsqcup_{j=1}^s U_j}=[0,1]^d,
        \end{equation}
        \item for all $j\in \disc{1}{s}$, there exists  $f_j:\overline{U_j}\times \T^d\to \C$ such that ${f_j}_{|U_j\times \T^d}={f}_{|U_j\times \T^d}$ and such that for all $\beta\in \N^d$, there exists $C_{j,\beta}>0$ so that for all $\xi \in \T^d$,
        \begin{equation}
            \norme{\partial_\xi^\beta f_j(\cdot,\xi)}_{\mathscr{C}^{0,\varrho}\pr{\overline{U_j}}}\leq C_{j,\beta}.
        \end{equation}
    \end{enumerate}
    Additionally, for $f\in \mathscr{C}^{0,\varrho}_{\mathrm{pw}}S_d$, we will denote 
    \begin{equation}
        \mathscr{U}_f:=\bigcup_{j=1}^s \partial U_j

    \end{equation}
    the set of potential singularities of $f(\cdot,\xi)$ in $[0,1]^d$.

[Lemma 36 of arXiv:2608.17374, '\textbf{On the Pseudo-Mixing of Kac's Walk}'] Fix $i\neq j$ and define  $q=1-\frac{2m(d-m)}{d(d-1)}$, $q_3=1-\frac{3m(d-m)}{d(d-1)}$, and $q_4=1-\frac{4m(d-m)}{d(d-1)}+\frac{4m(m-1)(d-m)(d-m-1)}{d(d-1)(d-2)(d-3)}$. For each $t\ge 0$ and any $I\subseteq[d]$ with $|I|=k$,
\begin{equation}

\mathbb{P}\Bigl(\exists i\neq j\in I:\;H_i(t)=H_j(t)\Bigr)\le \binom{k}{2}\,q^t
\end{equation}
and 
\begin{equation}

\mathbb{P}\Bigl(\exists i\neq j\in I:\;H_i(t)=H_j(t)\Bigr)
\ge
\binom{k}{2}q^t
-3\binom{k}{3}q_3^t
-3\binom{k}{4}q_4^t.
\end{equation}

