[Thm 7 (Main result in spatial dimension $d=2$) of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] Let $d=2$, let $\{K_n\}_{n\ge 1}$ denote an environment satisfying Assumption \ref{a1}, and let $\mathfrak H^N$ be as in \eqref{hn}. Assume as in Definition \ref{goodseq} that one has a good sequence of initial data $\mathfrak H^N(0,\bullet)$ converging weakly as measures to some limit $\mathfrak H_0$. There is an explicit Banach space $X$ of distributions on $\mathbb R^2$, which is continuously embedded in $\mathcal S'(\mathbb R^2)$, such that the rescaled and recentered collection $\{ \mathfrak F^N\}_{N \ge 1}$ is tight with respect to the topology of $C([0,T], X)$. Furthermore any limit point as $N\to \infty$ can be described as follows. 
\begin{itemize} \item (Bulk fluctuations in $d=2$) If $N^{1/2}   \varsigma_N \to   {\boldsymbol{\varsigma} }\text{ as } N\to\infty$, then the limit point is unique and coincides with the law of $(t,x)\mapsto e^{\varsigma\bullet x +\frac12 |\varsigma|^2 t} \mathcal U(t,x+\varsigma t)$ where $\mathcal U$ is the solution of the additive-noise SPDE \begin{equation}\partial_t \mathcal U(t,   x) = \frac12\Delta \mathcal U(t,   x) +\sqrt{2\pi} \cdot\eta_p(t,x),
\end{equation}started with initial data $\mathcal U(0,   x)=0$. Here $\eta_p$ is the Gaussian field on $\mathbb R_+\times \mathbb R^2$ that is white in time and for each fixed time $t>0$ has a spatial covariance structure given by $\mathbb E[(\eta_p(t,\bullet),\phi)_{L^2(\mathbb R^2)}^2] = \int_{\mathbb R^2} A_p[\phi,\phi](a)\cdot (\mathfrak H_0 *G_t)(a)^2\dr a$ where
\begin{multline*}A_p[\phi,\psi](a)  := \\
\int_{I} \int_{I^2}  [(   x_1-   y) \bullet \nabla]^p \phi (a)\cdot [   x_2 \bullet \nabla]^p \psi(a) \bigg( \boldsymbol p^{(2)}\big( (   y,   0), (\dr    x_1,\dr    x_2)\big) -\mu(\dr    x_1-   y)\mu(\dr    x_2 )\bigg) \pi^{\mathrm{inv}}(\dr    y). \end{multline*}
\item (Extremal fluctuations up to location scale $N/(\log N)^{\frac1{2p}}$ in $d=2$) If $N^{-1/2}\ll |   \varsigma_N| \ll  (\log N)^{-\frac1{2p}} \text{ as } N\to \infty$ and if $\frac{   \varsigma_N}{|  \varsigma_N|} \to   {\boldsymbol v}_{\mathrm{unit}}$ as $N\to\infty$, then the limit point is unique and coincides with the law of the solution of the additive-noise SPDE \begin{equation}\partial_t \mathcal U(t,   x) = \frac12\Delta \mathcal U(t,   x) + \sqrt{2\pi} \cdot \gamma_{\mathrm{ext}}(  {\boldsymbol v}_{\mathrm{unit}})\cdot   (\mathfrak H_0 *G_t)(x)\; \xi(t,   x),
\end{equation}
started from $\mathcal U(0,   x)=0.$ Here $ \xi$ is a standard space-time white noise defined on $\mathbb R_+\times \mathbb R^2$ and $\gamma_{\mathrm{ext}}$ is the homogeneous polynomial of degree $2p$ defined by
\begin{equation}
\gamma_{\mathrm{ext}}(  {\boldsymbol v})^2:= \frac{1}{(2p)!}\int_{I} \bigg[ \int_{I^2}[(   x-   y)\bullet   {\boldsymbol v}]^{2p}\mu(\mathrm d   x)\mu(\mathrm d   y)-\int_I [(   a-   z)\bullet   {\boldsymbol v}]^{2p} \pdif(   z,\mathrm d   a)\bigg]
\pi^{\mathrm{inv}}(\mathrm d   z).
\end{equation}
\item (Extremal fluctuations at scale $N/(\log N)^{\frac1{2p}}$ in $d=2$) There exists $\epsilon_{\mathrm{thr}} \leq 2$ such that the following holds for all $\boldsymbol v$ with $\gamma_{\mathrm{ext}}(  {\boldsymbol v})^2< \epsilon_{\mathrm{thr}}.$ If $   \varsigma_N (\log N)^{\frac1{2p}} \to   {\boldsymbol v} \ne 0\text{ as } N\to \infty,$ then the limit point is unique and coincides with the law of the solution of the additive-noise SPDE \begin{equation}\partial_t \mathcal U(t,   x) = \frac12\Delta \mathcal U(t,   x) + \frac{\sqrt{2\pi} }{|  {\boldsymbol{v}}|^{p}}\sqrt{\frac{\gamma_{\mathrm{ext}}(  {\boldsymbol v})^2 }{1 -\frac12\gamma_{\mathrm{ext}}(  {\boldsymbol v})^2}}\cdot   (\mathfrak H_0 *G_t)(x)\; \xi(t,   x),
\end{equation}
started from $\mathcal U(0,   x)=0.$ Here $ \xi$ is a standard space-time white noise defined on $\mathbb R_+\times \mathbb R^2.$

\end{itemize} Above $G_t(x)=G(t,   x) = (2\pi t)^{-1}e^{-|   x|^2/2t}$ is the standard deterministic heat kernel, and $*$ is spatial convolution. Furthermore $\pi^{\mathrm{inv}}$ is the invariant measure of the  (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 (Generalized resolvent identity) of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] For $H=H^*\in\C^{N\times N}$ and $z_j\in\C\setminus\R$ denote $G_j:=(H-z_j)^{-1}$, $j=1,2$. For any $k,l\in\N$ it holds that
\begin{equation}
G_1^kG_2^l = \sum_{u=1}^k (-1)^{k-u} \binom{l+k-u-1}{l-1} \frac{G_1^u}{(z_1-z_2)^{l+k-u}} + \sum_{v=1}^l (-1)^{l-v} \binom{l+k-v-1}{k-1} \frac{G_2^v}{(z_2-z_1)^{l+k-v}}.

\end{equation}

