[Thm moment theorem 1_intro of arXiv:2505.11700, 'Distribution of the cokernels of determinantal row-sparse matrices'] (Theorem (thm: moment theorem 1 of the paper)) Let $G$ be a finite abelian group. Assume that a sequence $(k_n)_{n=1}^{\infty}$ satisfies the following:
\begin{enumerate}
    \item $\gcd(|G|, k_n)=1$ for all sufficiently large $n$;
    \item for every $\epsilon>0$, $k_n < n^{\epsilon}$ for all sufficiently large $n$;
    \item if $|G|$ is even, then for every $\delta>0$, $\delta \log\log n < k_n$ for all sufficiently large $n$.
\end{enumerate}
Then
\begin{equation}

\lim_{n\to \infty} \mathbb{E}(\# \mathrm{Sur}(\mathrm{cok}(A_n), G)) = 1.     
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 4 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] We say that $(u,F)$ is a weak solution to the Vlasov(--Fokker--Planck)--Navier--Stokes system \eqref{eq:PDE} if
\begin{align*}
&  u \in L^\infty([0,T];L^2(\T^d)^d) \cap L^2([0,T];H^1(\T^d)^d),\\
& \dive u_{t} =0  \quad \text{for a.e. } (t,x)\in(0,T)\times\T^d,\\
& F(t,x ,v )\geq0,\quad \text{for a.e. } (t,x ,v)\in(0,T)\times\T^d\times\R^d, \\
& F\in L^\infty([0,T];L^\infty(\T^d\times\R^d)\cap L^1(\T^d\times\R^d)), \\
& |v |^2F \in L^\infty([0,T]; L^1(\T^d\times\R^d)) ;
\end{align*}
and $(u,F)$ satisfy, for all $\phi\in \mathcal{C}^\infty([0,T]\times\mathbb{T}^d\times\mathbb{R}^d)$ with compact support in $v $ and with $\phi(T,\cdot,\cdot)=0$,

\begin{align*}
-\int^T_0 &\int_{\mathbb{R}^d}\int_{\mathbb{T}^d} \bigl[\partial_s\phi+v \cdot\nabla_x \phi+(u-v )\cdot\nabla_v \phi - \frac{\sigma^2}{2} \Delta_v \phi \bigr] F \dd x \dd v \dd s
 =\int_{\mathbb{R}^d}\int_{\mathbb{T}^d} \phi(0,x ,v) F^\circ \dd x \dd v ;
\end{align*}

and for all $\psi\in \mathcal{C}^\infty([0,T]\times\mathbb{T}^d;\R^d)$ with $\nabla \cdot \psi =0 $ and $ \psi(T,\cdot) =0$,
\begin{equation}

\begin{split}
 - \int_0^T\int_{\mathbb{T}^d} u \cdot \partial_s \psi \dd x \dd s
 & +\int_0^T\int_{\mathbb{T}^d} \big((u \cdot \nabla) \psi \cdot u \big) \dd x \dd s +\int_0^T \int_{\mathbb{T}^d}  u \cdot \Delta \psi \dd x \dd s \\
& =-\int_0^T\int_{\mathbb{R}^d}\int_{\mathbb{T}^d} (u-v) F \cdot \psi \dd x \dd v \dd s + \int_{\T^d} u^\circ \psi(0,x)  \dd x.
\end{split}
\end{equation}

[Lemma lem:scalar-powers-app of arXiv:2609.00556, 'Higgs--Demailly System and Positivity of Higgs Bundles'] Let \(x,y>0\) and \(0<\sigma\leq1\). Then
\begin{equation}
 (x-y)(x^\sigma-y^\sigma)\geq0.
\end{equation}
Moreover,
\begin{equation}
 \left(\frac yx-1\right)(y^\sigma-x^\sigma)
 \geq x^{-\sigma}|y^\sigma-x^\sigma|^2.
\end{equation}
Finally, if \(0<s\leq\sigma/2\) and \(0<x\leq1\), then
\begin{equation}
 0\leq
 \frac{s+\sigma/2}{s}(1-x^s)
 \leq x^{-\sigma/2}.
\end{equation}

[Lemma 17 (Regularity of $\psi_\circ$) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] The function $\psi_\circ$ given in~\eqref{e.psi_single=} can be extended to $\mcl Q_1$ and satisfies
\begin{align*}
    \Ll|\psi_\circ(q)-\psi_\circ(q')\Rr|\leq |q-q'|_{L^1},\quad\forall q,q'\in\mcl Q_1.
\end{align*}
The restriction $\psi_\circ:\mcl Q_2\to\R$ is Gateaux differentiable everywhere; we denote its Gateaux derivative by $\dr_q \psi_\circ(q) = \dr_q \psi_\circ(q, \cdot) \in L^2([0,1])$. We have, for every $q \in \mcl Q_2$,
\begin{equation}

\partial_q\psi_\circ(q) \in \mcl Q_{\infty,\leq 1},
\end{equation}
and, for every $q \in \mcl Q_\infty$ and $\pi \in L^2([0,1]; \R)$,  \begin{equation*}
\la \pi,\dr_q \psi_\circ(q)\ra_{L^2} = \E \la \pi \Ll(\alpha\wedge\alpha'\Rr)\tau\tau'\ra_{q}
\end{equation*}
where $\la\cdot\ra_q \propto  \exp\Ll(\sqrt{2}w^q(\alpha)\cdot \tau-q(1) \tau\tau\Rr)\d \fR(\alpha) \d P_{\{-1,1\}}(\tau)$, and $(\tau',\al')$ denotes an inpendent copy of the canonical random variable $(\tau,\al)$ under $\la \cdot \ra_q$.
Moreover, for every $r \in [1,+\infty]$ and $q, q' \in \mcl Q_2$ with $q-q' \in L^r$, we have
\begin{equation}

\Ll|\dr_q \psi_\circ(q) -\dr_q \psi_\circ(q')\Rr|_{L^r}\leq 16\Ll|q-q'\Rr|_{L^r}.
\end{equation}
In particular, the mapping $q \mapsto \dr_q \psi_\circ(q)$ can be extended to $\mcl Q_1$ by continuity, and the properties in \eqref{e.bound.der.psi} and \eqref{e.continuity.der.psi} remain valid with $q, q' \in \mcl Q_1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

