[Definition def:well_posed of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] We say that MKV$({\bf b},{\boldsymbol\sigma})$ is:
\begin{itemize}
\item[-] \emph{\textcolor{black}{weakly} well-posed}, if there exists a unique (\textcolor{black}{in law}) solution to MKV$({\bf b},{\boldsymbol\sigma};\textcolor{black}{\nu})$ for any $\nu\in \mathcal{P}(\mathbb{R}^d)$;
\item[-] \emph{\textcolor{black}{pathwise} well-posed}, if there exists an (\emph{almost surely}) unique solution to MKV$({\bf b},{\boldsymbol\sigma};\textcolor{black}{\xi, W, (\mathcal{F}_t)_t})$ for any $(W, (\mathcal{F}_t)_t )$ Brownian motion  and any \textcolor{black}{$\xi\in m\mathcal{F}_0$}. \vspace{-8pt}
\end{itemize}

[Proposition 9 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] In the setting of Example~\ref{ex:a representative SIS epidemic model} let~\eqref{a.1} and $\eta_{0} = \frac{1}{2}$ be valid. Further, suppose that either
\begin{equation*}
c_{1,2} = c_{2,1} = c_{2,2} = g_{1,1} = 0
\end{equation*}
or both~\eqref{a.2} and one of the following four scenarios hold:
\begin{enumerate}[(i)]
\item $\frac{1}{2}(g_{1,2}^{2} + g_{2,1}^{2}) \geq \beta + \beta_{1}^{+} + (2c_{1,2} + c_{2,1})N  + c_{2,2}N^{2}$ and $g_{1,1}g_{1,2}\geq 0$.

\item $-\frac{3}{2}g_{1,1}g_{1,2} \geq 4(c_{1,2} + c_{2,1} + c_{2,2}N + \frac{1}{2}g_{1,1}^{2})\sqrt{N}$.

\item $\frac{1}{2}(g_{1,2}^{2} + g_{2,1}^{2}) \leq \beta - \beta_{1}^{-} -(\frac{3}{2}g_{1,1}g_{1,2} + (c_{2,1} + g_{1,1}^{2})\sqrt{N} + c_{2,2}N^{\frac{3}{2}})\sqrt{N}$.

\item If $g_{1,1} > 0$, then
\begin{align*}
\frac{1}{2}(g_{1,2}^{2} + g_{2,1}^{2}) &\geq \beta + \beta_{1}^{+} + (2c_{1,2} + c_{2,1})N + c_{2,2}N^{2}\\
&\quad + \frac{1}{2}\bigg(\frac{3}{4}\bigg)^{2}\frac{g_{1,1}^{2}g_{1,2}^{2}}{\frac{1}{2}g_{1,1}^{2} + c_{1,2} + c_{2,1} + c_{2,2}N}.
\end{align*}
\end{enumerate}
 If there are $u_{1},u_{2},u_{3}\in\R$ satisfying~\eqref{eq:extinction in the epidemic models 4},
\begin{equation}
\liminf_{t\uparrow\infty} g_{1,1}(t)g_{1,2}(t) \geq u_{2}\quad\text{and}\quad \limsup_{t\uparrow\infty} c_{1,2}(t) - \frac{1}{2}g_{1,1}(t)^{2} \leq u_{3},
\end{equation}
then any positive solution $I$ to~\eqref{eq:SIS epidemic model} becomes exponentially extinct if $\mu_{\infty} + \gamma_{\infty} > 0$ and
\begin{equation}
(u_{1} + u_{3}N_{\infty} - u_{2}N^{\frac{1}{2}})N_{\infty} < \mu_{\infty} + \gamma_{\infty}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2607.11608, '2607.11608'] Let  $\mu$ as in \eqref{mu_def}.  Then, for every $K\in \R$ and $\eps>0$,
\begin{equation*}
\mu\bigg(\int_{\R^d}:\!|\P_{N}u|^2\!:dx \in [K-\eps,K+\eps]\bigg)\les \eps,
\end{equation*}
where the implicit constant is independent of $K$ and $\eps$. 
In particular, the same holds true for $\int_{\R^d}:\!|u|^2\!:dx=\lim_{N\to +\infty}\int_{\R^d}:\!|\P_{N}u|^2\!: dx$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:wcutoff of arXiv:2608.23135, 'Graph distance and effective resistance of the random walk trace in four and five dimensio'] For fixed $\varepsilon$ and $\delta$,
\begin{equation*}

   \mathbb{P}(L_{\mathrm{RW}}\ne L_{\mathrm{RW}}^R)
   \le \frac{C\delta^{-1}\varepsilon^{-1}}{R}+o_n(1).
\end{equation*}

[Proposition p:skewBM RK i of arXiv:2411.04773, 'Meeting of squared Bessel flow lines and application to the skew Brownian motion'] For any $r\ge 0$, a.s.
\begin{equation}
    L_{\tau^0_z}^r = \inf \{ x\ge \max(r,z): \mathcal S_{r,x}(0)= Y_x\}.
\end{equation}

\noindent As a result, Theorem (thm: skewBM RK of the paper) (i) holds (take $(\mathcal S, Y, z)$ in place of $(\mathcal S,Y^0,z)$ in Section (s:meetingL of the paper)).

[Lemma eq:zero-first-moment of arXiv:2607.14087, 'Stochastic Domination of Gaussian Maxima: A Resolution of the Weak Simplex Conjecture'] \label[lemma]{thm:centered-product}
Let $R$ be an $m\times m$ correlation matrix and let $X\sim\mathcal N(0,R)$.  For
each $i$, let $f_i:\mathbb R\to[0,\infty)$ be bounded and log-concave, with positive
Gaussian integral, and suppose that
\begin{equation}
  \int_{\mathbb R}z f_i(z)\,d\gamma_1(z)=0.
\end{equation}
Then
\begin{equation}
  \mathbb E\prod_{i=1}^m f_i(X_i)
  \geq \prod_{i=1}^m \mathbb E f_i(X_i)
  =\prod_{i=1}^m\int_{\mathbb R}f_i\,d\gamma_1.
\end{equation}
The covariance matrix $R$ may be singular. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2606.26619, 'Ergodicity of stochastic reaction-diffusion equations on unbounded domains driven by space'] Let $u$ be the solution to the following equation driven by space-time white noise $W$:
\begin{align}
\begin{cases}
    d u(t,x) = \frac{1}{2}\partial_{xx} u(t,x) dt  + W(dt,dx), \quad x\in\mathbb{R},\\
    u(0,x) = f(x), \quad x\in\mathbb{R},
\end{cases}
\end{align}
where $f\in L^p_{\lambda}$ for some $p\geq 1$. 
Then the solution $\{u(t): t\geq 0\}$ is not strong Feller on $L^p_{\lambda}$.

