[Lemma L:Gronwall of arXiv:2412.03521, 'On ergodic properties of stochastic PDEs'] Let $g(\cdot)$ be a nonnegative and monotone function on $[0,\infty)$ that
  decreases to $0$ as $t\to\infty$, and such that $g(0)<\infty$. Let $k(\cdot)$
  be a nonnegative and integrable function on $[0,\infty)$ and define
  \begin{align}
    h(t) \coloneqq \int_t^{\infty} k (s) \ensuremath{\mathrm{d}} s.
  \end{align}
  Then, we have:

  \begin{enumerate}[wide, labelwidth=!, labelindent=0pt, label=\emph{(\roman*)}]
    \setlength\itemsep{.1in}

    \item For any nonnegative integer $n$ and $t\ge 0$, it
      holds that
      \begin{align}
        \int_0^t g \left(\frac{t - s}{2^n}\right) k(s) \ensuremath{\mathrm{d}} s
        \le g(0) h \left(\frac{t}{2^{n + 1}}\right) + h(0) g \left(\frac{t}{2^{n + 1}}\right).
      \end{align}
      In particular, when $g = h$ as defined in (equation E:def-gnr-H of the paper), the above
      inequality~(equation E:g*h of the paper) reduces to
      \begin{align}
        \int_0^t h \left(\frac{t - s}{2^n}\right) k(s) \ensuremath{\mathrm{d}} s
        \le 2 h(0) h \left(\frac{t}{2^{n + 1}}\right).
      \end{align}

    \item For any nonnegative integer $n$ and $t\ge 0$, it
      holds that
      \begin{align}
        \int_{[0, t]^{n}_<}
            & \ensuremath{\mathrm{d}} u_n \cdots \ensuremath{\mathrm{d}} u_1\:  g \left(t - u_n \right) \prod_{i = 1}^n k(u_{i} - u_{i - 1} ) \nonumber \\
        \le & \left( 2^{n} - 1\right) g(0) h(0)^{n-1} h \left(\frac{t}{2^{n}}\right) + h(0)^n g \left(\frac{t}{2^{n}}\right),
      \end{align}
      where $[0, t]_<^{n} \coloneqq \left\{(s_1,\dots, s_n) \in [0,t]^n; 0 <
      s_1< \dots < s_n <t\right\}$ and we have used the convention that $u_0
      \equiv 0$.

    \item Let $f$ be a function on $[0,\infty)$ such that
      \begin{align*}
        f(t) \le g(t) + \beta \int_{0}^t f(t - s) k(s) \ensuremath{\mathrm{d}} s, \quad \text{for all $t\ge 0$ with $\beta>0$}.
      \end{align*}
      Then, whenever $\beta < [2 h(0)]^{-1}$, the following convergence is true,
      \begin{align}
        \lim_{t\to \infty} f(t) = 0.
      \end{align}

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 5 of arXiv:2608.27307, '2608.27307'] Under Assumptions~\ref{ass:basic} and \ref{ass:rand_ent}, let $E_*$ be a regular right edge in the sense of Definition~\ref{def:reg_r_edge}. Then, for any sufficiently small $\tau>0$, uniformly for $z=E+\ii\eta\in\mb D_*^{\eps_*}(\tau)$,
        \begin{align}
                G(z)-\Pi(z) = O_{\prec}\left(\sqrt{\frac{\Im m(z)}{N\eta}}+\frac1{N\eta}\right). 
        \end{align}
        Moreover, for every deterministic matrix $B\in\C^{L\times L}$ with $\|B\|\leq1$,
        \begin{align}
                \avg{B(G(z)-\Pi(z))}_L = O_{\prec}\left(\frac1{N\eta}\right). 
        \end{align}
        On the gap side, writing $\kappa:=E-E_*\geq0$, we further have
        \begin{align}
                \avg{B(G(z)-\Pi(z))}_L = O_{\prec}\left(\frac1{N(\kappa+\eta)}+\frac1{(N\eta)^2\sqrt{\kappa+\eta}}\right). 
        \end{align}
        If $E_*=E_+$, then \eqref{eq:opt_anis_ll}--\eqref{eq:gap_avg_ll} hold uniformly for $\{E_+-\eps_*\leq E\leq\tau^{-1}, N^{-1+\tau}\leq\eta\leq1\}$, with the gap side estimate \eqref{eq:gap_avg_ll} restricted to $E\geq E_+$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 246 of arXiv:2601.16377, '2601.16377'] We define
\begin{equation}

\mathrm{gr}_{\boldsymbol{v}}(p_1,p_2) = \text{Re}\left( \int^{p_1}_{p_1^*} \int_{p_2^*}^{p_2} \mathcal{B}_{\boldsymbol{v}}\right),
\end{equation}
where the $i$-th integration ($i = 1,2$) runs over a path from $p_i$ to $p_i^*$ in the (closure of) sheet to which these points belong to, for $i = 1,2$.

