[Defi 37 of arXiv:2608.28148, 'Flows and homotopies of Banach Lie algebroids'] A map $a \colon [0,1]\times[0,1]\to A$ such that $a_\varepsilon := a(\varepsilon,\cdot)$ is an admissible curve for every $\varepsilon \in [0,1]$ is called a \emph{variation of admissible curves} if $\g_\varepsilon:=\pi\circ a_\varepsilon \colon [0,1]\rightarrow M$ satisfies\begin{itemize}
\item $\g_\varepsilon(0)=x$ and $\g_\varepsilon(1)=y$, and both $x,y$ fixed for all $\varepsilon\in [0,1]$
\item
$\rho(a_\varepsilon)=\dis\frac{d\g_\varepsilon}{dt}$ for all $\varepsilon\in [0,1]$
\end{itemize}

[Proposition 32 of arXiv:2608.19065, 'Boundedly exchangeable graphs'] Write
    \begin{equation*}
        \widehat{C}_n \coloneqq \frac{1}{\nu(E_n)}
        \sum_{x \in v(G) \cap E_n} C(x)
    \end{equation*}
    on the event $\{\nu(E_n) > 0\}$, and $\widehat{C}_n \coloneqq 0$ otherwise. Then
    \begin{equation*}
        \widehat{C}_n \overset{\pbb}{\to}
        \big(1 - e^{-\delta V_t}(1 + \delta V_t)\big)\, p_t.
    \end{equation*}
    If, in addition, \eqref{CondSummable} holds, then this convergence
    holds almost surely.

[Lemma 23 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] There exists a constant $C_{14}>0$, which depends on $\delta$, $T^*$, $\|v_0\|_{H^1(\Omega)}$ and $\|w_0\|_{H^1(\Omega)}$, such that 

\begin{align*}
&\sup_{\varepsilon \in (0,1),\,\nu \in (0,1)} \left( \sup_{0 \le t \le T} \|w_{\text{{\tiny $\delta,\!\varepsilon,\!\nu$}}}(t)\|_{H^1(\Omega)}^2
+\int_0^T \|w_{\text{{\tiny $\delta,\!\varepsilon,\!\nu$}}}'(t)\|_{L^2 (\Omega)}^2dt \right.\\
&\hspace*{4cm}\left.+\int_0^T \|w_{\text{{\tiny $\delta,\!\varepsilon,\!\nu$}}}(t)\|_{H^2(\Omega)}^2 ds \right) \le C_{14}.
\end{align*}

