[Thm 9 of arXiv:2604.26499, 'Spectrum of Random Matrices with Exploding Moments'] \cite[Theorem 9]{weaver1985centrosymmetric}
 \begin{enumerate}[label=(\alph*)]

     \item  If $M=\left(\begin{array}{ll}A & B \\ C & D\end{array}\right)$ is an $N \times N$ centrosymmetric matrix with $N=2s$ and $A, B, C$, and $D \text{ are } s\times$ s matrices, then $M$ is orthogonally similar to
     \begin{align*}
         Q^T M Q=\left(\begin{array}{cc}
    A+J C & 0 \\
    0 & A-J C
\end{array}\right),
     \end{align*}
     where 
     \begin{align*}
         Q  =  \sqrt{\frac{1}{2}}\left(\begin{array}{ll}\mathbb{I} & -J \\ J & \mathbb{I}\end{array}\right).
     \end{align*}

     \item If $M=\left(\begin{array}{lll}A & x & B \\ y & q & yJ \\ C & Jx & D\end{array}\right)$ is an $N \times N$ centrosymmetric matrix with $N=2s+1$, and $A, B, C, D$  are  $s \times s$ matrices, $x$ is $s \times 1$ matrix, $y$ is $1 \times s$ matrix, and $q$ is a scalar, then $M$ is orthogonally similar to
     \begin{align*}
         Q^{T} M Q=\left(\begin{array}{ccc}
			A+J C & \sqrt{2} x & 0 \\
			\sqrt{2} y & q & 0 \\
			0 & 0 & A-J C
		\end{array}\right),
     \end{align*}
		where
  \begin{align*}
      Q  =  \sqrt{\frac{1}{2}}\left(\begin{array}{lll} \mathbb{I} & 0 & -J \\ 0 & \sqrt{2} & 0\\ J & 0 & \mathbb{I}\end{array}\right).
  \end{align*}
 \end{enumerate}
 Here $\mathbb{I}$ is the identity matrix and $J$ is the counter-identity matrix. In both cases $Q^TQ=\mathbb{I}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition {\cite{MR773445}} of arXiv:2604.04882, 'On a Problem of M. Kac on Laplace Distributions'] A characteristic function $f$ is said to be \textit{geometrically infinitely divisible} if for every $p\in(0,1)$ there exists a characteristic function $g_p$ such that
    \begin{align}
        f(\xi)=\frac{p\,g_p(\xi)}{1-(1-p)g_p(\xi)}.
    \end{align}

[Proposition 22 of arXiv:2609.03954, 'Galois representations ramified at one prime via relative deformation theory'] For every $j\ge j_0$ there exist continuous representations
\[
 \tau_j:G_{\{p\}}\longrightarrow\GG(\Z/p^j\Z)
\]
and
\[
 \varrho_{j+R}:G_{\{p\}}
 \longrightarrow\GG(\Z/p^{j+R}\Z)
\]
such that
\begin{enumerate}[label=\textup{(\arabic*)}]
\item $\varrho_{j+R}\pmod{p^j}=\tau_j$;
\item $\tau_{j+1}\pmod{p^j}=\tau_j$;
\item $\varrho_{j+R}\pmod{p^R}=\rho_R$;
\item $\tau_{j_0}=\rho_{2A}^*\pmod{p^{j_0}}$.
\end{enumerate}

[Theorem existence_heat_eq of arXiv:2606.29622, 'Affine Structure of the Brownian Signature'] Let $\bm p \in \mathcal B\,$, and $\bm u$ be as in Theorem (theorem:analyticity_general of the paper). Then,
\begin{enumerate}
    \item For all ${\color{NavyBlue}{\mathbf{v}}} \in V\,$, the function $t \mapsto \bm u_t^{{\color{NavyBlue}{\mathbf{v}}}}$ is $C^1$ on $[0, T]\,$. 
    \item The following linear equation is satisfied:
    \begin{equation}

    \begin{cases}
         \dot \bm{u}_t + \mathscr{L}\bm{u}_t= 0\,, \quad t \in [0, T], \\
    \bm u_T = \exp^{\mathrel{\sqcup \mkern -3mu \sqcup}}\left({\bm p}\right).
    \end{cases}
    \end{equation}
    \item For any ${\color{NavyBlue}{\mathbf{v}}} \in V\,$, there exists a constant $C_{\bm p, T, {\color{NavyBlue}{\mathbf{v}}}} \geq 0$ such that {for all $\sigX[] \in G$}
    \begin{equation}

    \sup_{t \in [0, T]}\,\|\bm u_t|_{{\color{NavyBlue}{\mathbf{v}}}}\|_{\sigX[]} \leq C_{\bm p, T, {\color{NavyBlue}{\mathbf{v}}}}\,(1 + M_{\bm p}(\sigX[]))^{|{\color{NavyBlue}{\mathbf{v}}}|}\,  \exp \left(C_{\bm p, T}\, (1 + M_{\bm p}(\sigX[]))^{\deg_{{\color{NavyBlue}{\mathbf{1}}}}(\bm p)} \right) < + \infty\,.
    \end{equation}
\end{enumerate}

[Dfn 219 (admissible controls) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Let $B,W,U,U',\cF_X,\cF_{\Ising}$ be as in
Definition~\ref{d:achievable-msrs-sym}. Let
\begin{align*}
    \sS &= \lt\{
        \begin{array}{ll}
        (b,\sigma): & \textup{$b,\sigma\in\ProgMsrbl(\cF_X)$, with
        $\sigma_t \ge 0$ almost surely} \\
        &\textup{and
        $\max\{\bbE[(b_t)^2], \bbE[(\sigma_t)^2]\} < \infty$ for all $t\in[0,1]$}
        \end{array}
    \rt\}\,, \\
    \sW &= \lt\{
        \begin{array}{ll}
        w : & \textup{$w\in\ProgMsrbl(\cF_{\Ising})$, with 
        $\bbE [(w_t)^2] = 1$ and} \\
        &\textup{$X^{\Ising}(1) \in \{\pm 1\}$ almost surely} 
        \end{array}
    \rt\}\,,
\end{align*}
where $X^{\Ising}$ is as in \eqref{eq:X-ising-intro}.
    For $p\in \sP$, let $\Adm^{\Ising}(\alpha,p)$
 denote the set of controls $(b,\sigma,w)\in \sS \times \sW$ satisfying, for all $0\le t\le 1$, the \textbf{Ising budget constraint}
    \beq

        \bbE \bigg[(b_t)^2 + \frac{(tp)'(t)}{p(t)}(\sigma_t-1)^2\bigg]
        \le \frac{(\bbE w_t)^2 }{ \alpha}\,.
    \eeq
Similarly, let $\Adm^{\sph}(\alpha,p)$ denote the set of controls $(b,\sigma)\in\sS$ satisfying, for all $0\le t\le 1$, the \textbf{spherical budget constraint}
    \beq

        \bbE \bigg[(b_t)^2 + \frac{(tp)'(t)}{p(t)}(\sigma_t-1)^2\bigg]
        \le \frac1\alpha\,.
    \eeq
Then $\Adm^{\Ising}(\alpha,p)$ and $\Adm^{\sph}(\alpha,p)$ are the \textbf{admissible controls} for the stochastic control problems corresponding to the Ising and spherical problems.

[Theorem thm:conv of arXiv:2605.05904, 'Schr\"odinger's problem with constraints'] Suppose Assumptions~(a:main of the paper),(ass:f of the paper) and  (a:feps of the paper) hold. 
As $\eps\to0$, the solutions of the Schr\"odinger problems $\mathcal{S}_E(\mu_0,\mu_1^\eps)$
weakly converge to the distribution of
\begin{equation}

\begin{split}
X_t &=x_0+\int_0^t \mathbf{I}(u, X_u)\cdot
\left\{\mathbf{b}(u,X_u) + \Sigma^2(u,X_u)\frac{(\nabla h^0(u,X_u))^*}{h^0(u,X_u)}\right\} du\\
&\hspace{1cm}+\int_0^t \mathbf{I}(u, X_u)\cdot\Sigma(u,X_u)d\beta_u,
\end{split}
	\end{equation}
	where $x_0=(z_0,z_0)$, and $\beta$ is a 2-dimensional standard Brownian motion. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:lipsde of arXiv:2411.16366, 'Connections between sequential Bayesian inference and evolutionary dynamics'] \textbf{Continuity of solutions of SDEs} 
Let $g, \sigma$ be lipschitz continuous functions satisfying linear growth conditions. Denote by $\xi_t(x)$ the unique solution to 
\begin{align*}
d\xi_t =  g(\xi_s)ds +  \sigma(\xi_s)dB_s 
\end{align*}
with $\xi_0 = x$.  Suppose $h$ is a globally lipschitz continuous real vector valued function.  Then it holds that 
\begin{align*}
\mathbb{E} \left[ |h(\xi_{s}(x)) - h(\xi_r(x))|^q  \right] \leq C(x)|s-r|^{q/2}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

