body:
[Cor 15 of arXiv:2605.15501, 'Well-posedness of the obstacle problem for generalized Dean--Kawasaki equation\thanks{ The'] For the lower obstacle problem, in which we require $u\geq\psi$ on $Q_T$ rather than $u\leq\psi$, the corresponding approximating penalized equation \eqref{eq:appro penalized eq} becomes
\begin{align}
\mathrm{d}u_{\alpha,n,\varepsilon} & =\Big[\Delta\Phi(u_{\alpha,n,\varepsilon})+\alpha\Delta u_{\alpha,n,\varepsilon}+\frac{1}{2}\nabla\cdot(F_{1}[\sigma_n^{\prime}(u_{\alpha,n,\varepsilon})]^{2}\nabla u_{\alpha,n,\varepsilon}+\sigma_n(u_{\alpha,n,\varepsilon})\sigma_n^{\prime}(u_{\alpha,n,\varepsilon})F_{2})\nonumber \\
 & \quad-\nabla \cdot g(u_{\alpha,n,\varepsilon})+\frac{1}{\varepsilon}(u_{\alpha,n,\varepsilon}-\psi)^{-}\Big]\mathrm{d}t-\nabla\cdot(\sigma_{n}(u_{\alpha,n,\varepsilon})\mathrm{d}\xi^{F}).
\end{align}
A priori estimates for the solution $u_{\alpha,n,\varepsilon}$ to \eqref{eq:appro penalized eq lower obstacle} remain valid under additional assumptions that $|\sigma(r)|\leq C(1+|r|)$ and $p=2$ using Gronwall inequality instead of \cite[Lemma 5.4]{fehrman2021wellarxiv}.
This includes the important Dean--Kawasaki equation
\begin{align*}
\mathrm{d}u & =\Delta\Phi(u)\mathrm{d}t+\nabla\cdot\sqrt{\Phi(u)}\circ\mathrm{d}\xi^{F},
\end{align*}
provided that $|\Phi(r)|\leq C(1+|r|^{2})$ for all $r\in\mathbb{R}$, and thus in particular covers the case $\Phi(r)=r$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Ppn 142 (\hyperlink{proof:p.IAMP-to-SDE-limit.Ax.y}{proved in \S\ref{ss:proof.iamp.diffus.limit}}) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] In the setting of Theorem~\ref{thm:IAMP-main}\ref{i:IAMP-main-main},  the IAMP defined by \eqref{eq:proxy-y-amp-def}--\eqref{eq:x-amp-def} satisfies the bound
  \[
  \sup\bigg\{
  \plim_{N\to\infty}
  \frac{\|\bA_{\ell}\by^\ell-\bx^\ell\|}{N^{1/2}}
  : 0\le \ell\le\ubl
  \bigg\}
  \leq 
  C\delta^{1/4}
  +C_0\epsilon^{1/2}\,.\]
where $C=C(L,\alpha)$ and $C_0=C_0(\alpha)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma tricky of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] Let $E,F\subseteq \mathbb R^3$ be non-empty Borel sets. Let $\mu$ be a finite measure on $F$, and $\nu(y,\cdot)$ be a finite measure on $E$ for each $y\in F$. 
    Suppose $p(x,y)$, $s(y)$ and $r(z)$ are non-negative bounded Borel functions on $E\times F,\,F,\,E$, respectively, such that the following equality holds for all $x\in E$,
    \begin{equation}
        r(x)=\int _F p(x,y)\left (\int _E r(z)\nu(y,dz)\right )\mu(dy)+\int _F p(x,y)s(y)\mu(dy).
    \end{equation}
    Moreover, suppose there exists a constant $0\le a <1$ such that for all $x\in E$,
    \begin{equation}
        \int_F p(x,y)\nu(y,E)\mu(dy)\leq a,
    \end{equation}
    then for all $x\in E$,
    \begin{equation*}
        \int p(x,y)s(y)\mu(dy)\geq \dfrac{1-a}{1+(K(p)-1)a}r(x).
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

