body:
[Lemma lem:frostman-green-smoothing of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] Let $\mu$ be a finite positive Radon measure on $D$ satisfying, for some
$C_\mu<\infty$ and $\alpha>0$,
\begin{equation}
 \mu(B_D(z,r))\le C_\mu r^\alpha,
 \qquad z\in D,
 \quad 0<r\le1.
\end{equation}
Then $\mu(\{z\})=0$ for every $z\in D$.  For every $p>0$,
\begin{equation}
 L_p(\mu)
 :=\sup_{z\in D}\int_D
 \left(1+\log^+\frac1{|z-w|}\right)^p\mu(dw)<\infty.
\end{equation}
Moreover, for every compact $K\Subset D$,
\begin{equation}
 \sup_{\substack{z,z'\in K\\|z-z'|\le\delta}}
 \int_D|G_D(z,w)-G_D(z',w)|^2\,\mu(dw)
 \xrightarrow[\delta\downarrow0]{}0.
\end{equation}
In particular,
\begin{equation}
 \sup_{z\in D}\int_DG_D(z,w)^2\,\mu(dw)
 \le C_D^2L_2(\mu)<\infty.
\end{equation}

[Proposition prop:Markov of arXiv:2411.19810, 'Radial conformal welding in Liouville quantum gravity'] Let $D\subset \mathbb{C}$ be a domain with $\partial D =  \partial^D\cup\partial^F$, $\partial^D\cap\partial^F=\emptyset$, and $U\subset D$ open. Let $h$ be the GFF on $D$ with  \textit{Dirichlet} (resp. free) \textit{boundary conditions} on $\partial^D$ (resp. $\partial^F$). Then we can write $h=h_1+h_2$ where: 
		\begin{enumerate}
			\item $h_1$ and $h_2$ are independent;
			\item $h_1$ is a GFF on $U$ with Dirichlet boundary condition on $\partial U\backslash \partial^F$ and free on $\partial U\cap \partial^F$;
			\item $h_2$ is the same as $h$ outside $U$ and harmonic inside $U$.
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:lerw of arXiv:2411.13505, 'Capacity of loop-erased random walk'] Let $\omega\in\Omega$ be a one-sided nearest-neighbour, transient path in $\mathbb{Z}^d$. The loop-erasure $\LE(\omega)$ of $\omega$ is the path obtained by erasing loops from $\omega$ chronologically. To be precise, $\LE(\omega)_i=\omega_{\ell_i}$, where the times $(\ell_i)_{i\geq0}$ are defined inductively as $\ell_0=0$ and $\ell_{i+1}=1+\max\{k\colon\omega_k=\omega_{\ell_i}\}$. When $S$ is a simple random walk on $\mathbb{Z}^d$ for $d\geq3$, we write
\begin{equation}
	\eta:=\LE(S[0,\infty)).
\end{equation}
This is well-defined, since simple random walk is almost surely transient for $d\geq3$.

[Definition of arXiv:2412.04589, 'Inverting the Markovian projection for pure jump processes'] We use the following notation.
	\begin{enumerate}[label=(\roman*), nosep]
		\item Let $a \in \mathbb{R}^n$. Define $S_k(a) \coloneqq \sum_{i=1}^k a_i$ for $0 \leq k \leq n$. In particular, $S_0(a) = 0$ by our convention.

		\item Let $\varnothing \neq A \subseteq \mathbb{R}$. The collection of all finite (including empty) sums of elements of $A$ is denoted by $\operatorname{FS}(A)$, namely
		\begin{equation*}
			\operatorname{FS}(A) \coloneqq \{S_k(a): a \in A^k,\, k \in \mathbb{N}\},
		\end{equation*}
		where $A^0 \coloneqq \{0\}$ by convention.
	\end{enumerate}

[Lemma driftcompar of arXiv:2605.10617, 'Logarithmic scaling of selective sweep curves:\\ from tents to houses'] For $p> 1/2$ and $k=1,2,\ldots$
\begin{equation}
 \mathbb{P}(W_p^*(1) = k+1 \mid W_p^*(0) =k)  >  \mathbb{P}(W_{1/2}^*(1) = k+1 \mid W_{1/2}^*(0) =k).
\end{equation}

