[Definition def:Idot_clean of arXiv:2605.15401, 'Noise Tradeoffs, Stationary Information Flow, and Structural Balance in Unit-Birth Network'] Assume that the series below is absolutely convergent. Define
\begin{align}
\begin{split}
(\dot I)_{X_i}
&:=\sum_{n\ge0}\sum_{v\in\mathbb{Z}_{\ge0}^{N-1}}
J_i(n+1,n;v)\,\log\frac{\pi_{n+1}^i(v)}{\pi_n^i(v)}\\
&=
\sum_{n\ge0}\sum_v
\left(
\pi(n,v)f_i(v)-\pi(n+1,v)\frac{n+1}{\tau_i}
\right)
\big(h_i(n,v)-h_i(n+1,v)\big),
\end{split}
\end{align}
where the second equality utilizes the notation from (equation eq:log_potentials of the paper).

[Proposition 11 (FKG inequality for Gaussian fields~\cite{pitt1982}) of arXiv:2607.13308, 'No infinite clusters at criticality for two-dimensional dependent percolation under abstra'] Let $A$ and $B$ be two increasing events depending on finitely many coordinates of $g$. Then
  \begin{equation}
    \tag{FKG}
    \P \big( g \in A \cap B\big) \geq \P \big( g \in A \big) \P \big( g \in B \big).
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn Ornstein-Uhlenbeck Process of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] The normalized stationary scalar Ornstein--Uhlenbeck process $\mathrm{OU}(c)$, is the unique solution to
    \begin{equation}
    \begin{split}
        &dx(t)=-m x(t)\mathop{}\!\mathrm{d}{t} +\sqrt{2m} \mathop{}\!\mathrm{d}{W(t)} \\
        &x(0) \sim N(0,1)
    \end{split}
\end{equation}
for a standard one dimensional Brownian motion $W(t)$. Or equivalently, $\mathrm{OU}(m)$ is a stationary Gaussian process for all time with covariances given by $\mathbb{E}[x(t)x(s)]=e^{-m|t-s|}$. Furthermore if $m=(m_1,...,m_n)$ denote by $\mathbf{OU}_n(m)$ the vector valued Ornstein--Uhlenbeck process that has independent $\mathrm{OU}(m_i)$ entries. If $c$ is scalar, the notation $\mathbf{OU}_n(m)$ will be short for $\mathbf{OU}_n((m,...,m))$.

[Definition Def:ms-dissipative-schurz of arXiv:2604.28068, 'Mean-square Stability and Bifurcations for Dissipative SDEs'] Let $\left\{X(t):t\in[0,\infty)] \subseteq D \subseteq \mathbb{R}^d \right\}$ be a solution of the SDE (equation eq:main_d of the paper) corresponding to initial data $X(0)\in D$ which is measurable with respect to $\mathcal{F}_0$. The SDE is called 
    \begin{enumerate}
    \item mean-square dissipative if  there exist $r,R>0$ such that     $$\limsup_{t\to\infty}\mathbb{E}\left[\|X(t)\|^2\right]<R^2$$
    whenever $\mathbb{E}\left[\|X(0)\|^2\right]<r^2$;

    \item uniformly mean-square dissipative if  there exist $r,R>0$ such that $$\lim_{t\to\infty}\expect{\sup_{0\leq s \leq t}\|X(s)\|^2} <R^2$$
    whenever $\mathbb{E}\left[\|X(0)\|^2\right] < r^2$.
    \end{enumerate}

