[Theorem 8 (Branching capacity and asymptotics of visiting probability) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] Consider a \(\Tree\)-walk in \(\Z^{d}\), and assume that 
\begin{enumerate}[(i)]
  \item \(d> \frac{2\alpha}{\alpha-1}\), or \(d=\frac{2\alpha}{\alpha-1}\) and
\Cref{Assum:SufficientConditionTransience} holds;
\item the jump distribution \(\theta\) has a finite
moment of order \(d-1\);
\end{enumerate}


Then for all finite \(A \subset \Z^d\) we have

\begin{equation*}{
 \P(\Tree^{x} \cap A \neq \emptyset) \sim_{x \to \infty} \bcp(A)g_{\theta}(x).
}\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2605.03057, 'Uniform-in-time quantitative fluctuations of large scale interacting particle systems'] Let $F\in\mathbb{D}^{2,4}$ be centered with $\E[F^2]=\sigma^2>0$ and
let $Z_\sigma\sim\mathcal{N}(0,\sigma^2)$. Then,
\begin{equation*}
W_1(F,Z_\sigma)\le \sqrt{\frac{8}{\pi\sigma^2}}
\sqrt{
\iint_{A\times A}
\sqrt{\E\left(\left(D^2F\otimes_1 D^2F\right)(x,y)^2\right)}
\sqrt{\E\left(DF(x)^2DF(y)^2\right)}
 \lambda(dx)\lambda(dy)
}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Coro of arXiv:2411.19543, 'Feller property and convergence for semigroups of time-changed processes'] Under assumptions of Theorem (Approximation of the paper), let $v\in C_0(F)$ and  let $u_\infty$ be the mild solution of the heat equation
\begin{equation}
\begin{cases} 
		- \frac{\partial u_\infty(t)}{\partial t} = \check{L}^\infty u_\infty(t),\\
		u_\infty(0) = v
\end{cases}

\end{equation}
and for each $n\in\mathbb{N}$  let $u_n$ be the mild solution of the  heat equation
\begin{equation}
\begin{cases} 
		- \frac{\partial u_n(t)}{\partial t} = \check{L}^n u_n(t),\\
		u_n(0) =P_Fv|_{F_n}.
\end{cases}

\end{equation}
Then 
\begin{enumerate}
\item[\rm(1)]
\[
\lim_{n\to\infty}\|u_n(t) - P_F u_\infty(t) \|_{\infty,F_n} = 0
\]
locally uniformly in $t\in [0,\infty)$.
\item[\rm(2)] If moreover  $F_n\subset F$ for all $n$ then 
\[
\lim_{n\to\infty}\| u_n(t) -  u_\infty(t) \|_{\infty,F_n} = 0
\]
locally uniformly in $t\in [0,\infty)$.
\item[\rm(3)] Whereas if $F\subset F_n$ for all $n$ then 
\[
\lim_{n\to\infty}\| u_n(t) -  u_\infty(t) \|_{\infty,F} = 0
\]
locally uniformly in $t\in [0,\infty)$.
\end{enumerate}
Here  $\|\cdot\|_{\infty,F}$, $\|\cdot\|_{\infty,F_n}$ denotes the supremum respectivly  on $F$ and $F_n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

