[Proposition 16 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Let~\eqref{co:3},~\eqref{co:5} and~\eqref{co:7}--\eqref{co:9} hold. Then the unique strong solution $I$ to~\eqref{eq:SIS epidemic model} with $I_{0} = \xi_{0}$ a.s.~satisfies
\begin{align*}
u(t)\E\big[|\hat{I}_{t}^{(n)} &- I_{t}|^{p}\big] \leq 
u(t_{j,n})\E\big[|I_{t_{j,n}}^{(n)} - I_{t_{j,n}}|^{p}\big]\\
&\quad  + \int_{t_{j,n}}^{t}u(s)\big(\delta_{p,j,n}(s) + \hat{\lambda}_{k+1}(s,N(s))p\E\big[|\hat{I}_{s}^{(n)} - I_{s}|^{p-1}\mathcal{W}_{p}(\mathcal{L}(I_{s}),L_{j,n})\big]\big)\,\mathrm{d}s\\
&\quad + \int_{t_{j,n}}^{t}\big(\dot{u}(s) + u(s)\lambda_{p,j,n}(s)\big)\E\big[|\hat{I}_{s}^{(n)} - I_{s}|^{p}\big]\,\mathrm{d}s
\end{align*}
for all $n\in\N$, $j\in\{0,\dots,k_{n}-1\}$ and $t\in [t_{j,n},t_{j+1,n}]$ and each absolutely continuous function $u\colon [t_{j,n},t_{j+1,n}]\rightarrow\R_{+}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 24 (One-sided endpoint domination) of arXiv:2608.10992, '2608.10992'] Fix $s\geq0$ with $\mathbb E[L_s]<\infty$ and $K\geq1$. Let
$q^{s,K}$ be the tail flow of Lemma~\ref{lem:tail-flow-general-data}
with initial data
\[
q_k^{s,K}(0)
:=
\mathbb P(L_s\wedge K\geq k).
\]
Then, for every $k\geq1$ and $t\geq0$,
\begin{equation}

q_k^{s,K}(t)
\leq
\mathbb P(L_{s+t}\geq k).
\end{equation}
Consequently, with $m_{s,K}:=\mathbb E[L_s\wedge K]$,
\begin{equation}

t_{\infty}^{\mathrm{iso}}
\leq
s+2\log\left(1+\frac1{m_{s,K}}\right).
\end{equation}
In particular,
\begin{equation}

X_t\preceq L_t,
\qquad
t_{\infty}^{\mathrm{iso}}
\leq t_{\infty}^{\mathrm{os}}.
\end{equation}

[Lemma 33 of arXiv:2608.17509, '2608.17509'] Let \(a>1\), and for \(m\geq1\) set
\(
        M_m(a):=\int_0^\infty r_a(\xi)^m\,\mathrm d\xi.
\)
Then
\begin{equation}

        M_m(a)
        =
        \frac{1}{2(a-1)}
        B\left(\frac{m}{a-1},m+1\right),
\end{equation}
where \(B\) is the Beta function. Equivalently,
\begin{equation}

        M_m(a)
        =
        \frac{1}{2}
        \sum_{j=0}^{m}
        (-1)^j
        \binom{m}{j}
        \frac{1}{m+(a-1)j}.
\end{equation}
Moreover, as \(m\to\infty\),
\begin{equation}

        M_m(a)
        \sim
        \sqrt{\frac{\pi}{2a}}\,m^{-1/2}\rho_a^m.
\end{equation}

