[Lemma of arXiv:2608.24731, 'Optimal Alternating Regret for Online Learning and Games\thanks{Authors are alphabetically'] \label[lemma]{lem:one-step}
Assume $\eta \le \frac{1}{8}$ and $\beta = \eta/4$. Then for any $t \ge 1$, we have
\begin{equation*}
\log \left( \sum_{i=1}^d p_{t,i}
\exp\!\left(
\eta\bigl((\boldsymbol{\xi}_t+\boldsymbol{\xi}_{t+1})^\top \boldsymbol{x}_t
-\xi_{t,i}-\xi_{t+1,i}\bigr)
+\beta(\xi_{t,i}^2-\xi_{t+1,i}^2)
\right)  \right) 
\leq 0.
\end{equation*}

[Ppn 188 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] The following estimates hold for $N$ large enough. We have
	\beq
	\E Q^{\RomI}(1) \le L^{O(1)} \delta\,.
	\eeq
In the Ising case, we also have
	\beq
	\sum_{\sigma\in\{\RomII,\RomIII\}}
	\E \sup\bigg\{ |\tilde{Q}^{\sigma,\Ising}(t)|
	: 0\le t\le 1\bigg\}
	\le
	\frac{L^{O(1)} \BUCKETS}{N}\,,
	\eeq
where we recall $\BUCKETS$ from \eqref{e:buckets.scB}. The errors $E^{\sigma,\tau}$ satisfy 
	\beq
	\sum_{\sigma,\tau\in\{\RomII,\RomIII,\Ising\}}
	\E \bigg[ \sup\bigg\{ |E^{\sigma,\tau}(t)|
	: 0\le t\le 1\bigg\}\bigg]
	\le
	L^{O(1)} 
		\bigg\{\frac{\eta}{\delta^{1/2}} 
		+ \frac{\BUCKETS}{N}
	\bigg\}
	\,.
	\eeq
Finally, the error $\tilde{E}^{\RomIII}$ satisfies
	\beq
	\E
	\sup\bigg\{
	|\tilde{E}^{\RomIII}(t)| : 0\le t\le 1\bigg\}
	\le
	L^{O(1)} 
	\bigg\{
	\frac{1}{N\delta}
	+ \frac{\BUCKETS}{N}
	\bigg\}^{1/2}
	\eeq
The ``$\frozen$'' variant of this proposition also holds. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition of arXiv:2606.10257, 'Downward conditional monotonicity gives survival and extinction for contact processes in r'] Consider the CPMRE having parameters $\beta,\mu,T$ as above, and with $\delta=1$. We have established the following results. 
	\begin{longlist}
		\setlength{\itemindent}{28pt}

		\setlength{\labelsep}{0.4em}
		\item The model is infection-DCM when $0<\lambda\leq \gamma$. 
		\item  If $\gamma>\lambda_c(2+\sqrt2)$, then the interval $(\lambda_\mathcal S, \gamma]$ is nonempty, and, for every $\lambda$ in this interval, the CPMRE is infection-DCM and dominates a supercritical contact process. Then, by monotonicity in $\lambda$, the CPMRE survives for all $\lambda>\lambda_\mathcal S$ (with $\lambda_\mathcal S$ defined in (equation eq:lamS of the paper)).
		\item The model is recovery-DCM when $\gamma\geq1$, in which case it goes extinct when $\lambda\leq\lambda_\mathcal E$ (with $\lambda_\mathcal E$ defined in (equation eq:lamE-def of the paper)). 
	\end{longlist} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:local-set-1 of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] Let $D$ and $\mathbb P_\delta$ be as in Lemma (lem:conv-fields-fractal of the paper). Let $\ell_\delta$ be an inner boundary of the boundary cluster of $\hat\mathbf{n}_\delta$ on $D_\delta$, with parity label $c_\delta$. Let $\mathcal O(\ell_\delta)$ be the induced subgraph of $D_\delta$ whose vertices are enclosed by $\ell_\delta$, and let $\mathcal{O}(\ell_\delta)^*$ be its \emph{strong} dual graph, where all vertices of $D_\delta^\dagger$ belonging to $\ell_\delta$ are identified. Then,
    \begin{enumerate}
        \item[$\bullet$]  the law of the restriction of $\tau_\delta$ to $\mathcal O(\ell_\delta)$ is that of $-c_\delta$ times a XOR-Ising model $\tau_\delta^{\ell_\delta}$ with free boundary conditions, 
        \item[$\bullet$]  the law of the restriction of $\tau_\delta^\dagger$ to $\mathcal O(\ell_\delta)^*$ is that of $c_\delta$ times a XOR-Ising model  $(\tau_\delta^{\ell_\delta})^\dagger$  with $+$ boundary conditions.
    \end{enumerate}
    Moreover, every subsequential limit as $\delta\to0$ of the joint law
    \begin{equation}
        \left( h_\delta,\ \ell_\delta,\ c_\delta,\ \tau_\delta,\ \tau_\delta^\dagger,\ \tau_\delta^{\ell_\delta},\ (\tau_\delta^{\ell_\delta})^\dagger \right) 
    \end{equation}
    is given by 
    \begin{equation}
        \left(\frac{1}{2\sqrt{2}\lambda}\ h,\ \ell,\ c,\ \field{\cos(\frac{1}{\sqrt{2}}\phi)},\ \field{\sin(\frac{1}{\sqrt{2}}\phi)},\ \field{\sin(\frac{1}{\sqrt{2}}\phi^\ell)},\ \field{\cos(\frac{1}{\sqrt{2}}\phi^\ell)} \right),
    \end{equation}
    where 
    \begin{enumerate}
        \item[$\bullet$] the loop $\ell$ is a loop of the two-valued set $\mathds A_{-\sqrt{2}\lambda, \sqrt{2}\lambda}$ of $h$,
        \item[$\bullet$] the label $c$ is the label of the above two-valued set,
        \item[$\bullet$] given $\ell$, the conditional law of $\phi^\ell$ is that of a GFF with zero boundary conditions in $\mathcal O(\ell)$,
        \item[$\bullet$] given $\ell$, the label $c$ and the pair $\big(\field{\cos(\frac{1}{\sqrt{2}}\phi^\ell)}, \ \field{\sin(\frac{1}{\sqrt{2}}\phi^\ell)} \big)$ are conditionally independent.
    \end{enumerate}

