 \right| ^{2}
 \right] \\
 &\quad -\frac{1}{2}\ex \!\left[ 
 \Phi ''(M_{s})^{2}|\dv _{s}|^{2}\int _{s}^{t}du\,\left( 
 \frac{1}{\Phi ''}
 \right) ''\!(M_{u})|\dv _{u}|^{2}
 \right] .
\end{split}
\end{equation}

