body:
[Theorem thm:LIL of arXiv:2608.20537, 'Persistent anisotropy in multi-dimensional\\ branching Brownian motion'] Let $\beta \in \mathcal{C}^2\big([0, \infty); \mathbb{R}\big)$ satisfy $t \dot{\beta}_t \to 0$ as $t \to \infty$.
  If 
  \begin{equation}

    \int_1^\infty \frac{\mathrm{d} r}{r \exp \beta_r} = \infty,
  \end{equation}
  then almost surely, for every nonempty open $U \subset S^{d-1}$, there exist sequences $t_n \nearrow \infty$ and $p_n \in \mathcal{P}_{t_n}$ such that for all $n \in \mathbb{N}$,
  \begin{equation}

    R_{t_n}(p_n) = 2t_n + \frac{d-2}{2} \log t_n + \beta_{t_n} \quad \text{and} \quad \Theta_{t_n}(p_n) \in U.
  \end{equation}
  If (equation eq:integral-condition of the paper) does not hold, then almost surely there exists $\tau > 0$ such that for all $t > \tau,$
  \begin{equation*}
    \max_{p \in \mathcal{P}_t} R_t(p) < 2t + \frac{d-2}{2} \log t + \beta_t.
  \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Th:simulation_stable of arXiv:2412.06374, 'Stable and tempered stable distributions and processes: an overview toward trajectory simu'] Let $\alpha \in (0,2)$ and  $U,V$ be two independent random variables such that $U\sim \mathcal{U}\left([-\frac\pi2, \frac\pi2] \right)$ and $V\sim \mathcal{E}(1).$
Let $\theta = \alpha^{-1}\arctan\left(\beta \tan\left(\frac{\pi\alpha}{2} \right) \right)$ for  $\beta \in [-1,1]$  and $\alpha \neq 1$ then
 \begin{align}
     X \sim \begin{cases}
\frac{\sin(\alpha(\theta + U))}{\left(\cos(\alpha \theta)\cos(U)\right)^{1/\alpha}} \left(\frac{\cos(\alpha \theta + (\alpha-1)U)}{V}\right)^{(1-\alpha)/\alpha} & \text{ if } \alpha \neq 1, \\
  \frac{2}{\pi} \left[\left( \frac{\pi}{2} + \beta U\right)\tan(U) - \beta \log\left( \frac{\frac{\pi}{2}V\cos(U)}{\frac{\pi}{2}+ \beta U} \right) \right]       & \text { if } \alpha=1,
     \end{cases}
 \end{align}
 is distributed as $S_\alpha (1,\beta, 0).$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[The 25 (Alexandrov's theorem) of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let $\phi\in\text{\rm SCL}\,(\T^n)$. Then we have
\begin{align*}
	\mathscr{L}(\text{\rm Alex}\,(\phi))=\mathscr{L}(\T^n).
\end{align*}

[Proposition 13 of arXiv:2608.12947, 'Branch-stationary max-stable fields on rooted trees'] Let \(Z\) be an \(\alpha\)-spectral representer satisfying
(equation 2 of the paper), and let \(\eta\) be given by
(equation 3 of the paper). The following statements are
equivalent:
\begin{enumerate}[(i)]
\item \(\eta\) is branch-stationary;
\item \(B^aZ\sim_\alpha Z\) for every \(a\in\mathcal T\);
\item the punctured tail measure is branch-invariant, i.e.,
\begin{equation}
  \nu_Z^\circ\bigl((B^a)^{-1}A\bigr)
  =
  \nu_Z^\circ(A),
  \qquad
  A\in\mathcal B(\mathcal F^\circ),\quad a\in\mathcal T,

\end{equation}
where
\[
  (B^a)^{-1}A
  =
  \{f\in\mathcal F^\circ:B^af\in A\};
\]
\item the local spectral tail fields satisfy
\begin{equation}
  B^a\Theta^{[au]}\stackrel{\mathrm d}{=}\Theta^{[u]},
  \qquad a,u\in\mathcal T;

\end{equation}
\item for every \(a,u\in\mathcal T\) and every \(F\in\mathfrak H_0\),
\begin{equation}
  \E*{
    Z_{au}^{\alpha}F(B^aZ)
  }
  =
  \E*{
    Z_u^{\alpha}F(Z)
  }.

\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 27 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $\widetilde{m}$ be  an order function satisfying \eqref{Hypothèse fonction d'ordre Mildred} with $\alpha$ replaced by $t$. Let $\psi\in \mathscr{C}^\infty_c(\R)$ and consider $0<h^{1-2\eta}\ll\alpha\leq t\leq \beta$ with notations \eqref{Scaling en fonction de t}, \eqref{Scaling de q atchek en fonction de t}, \eqref{Scaling de q_0 atchek en fonction de t} and \eqref{Fonction d'ordre théorème central - version en t}. Then, under the assumptions of Theorem \ref{Théorème central}, for $a\in \{0,1\}$ the following decomposition holds:
        \begin{equation}
        \mathrm{tr}\pr{\frac{1}{t^a}\psi\pr{\frac{\atc{q}_{N,t_1,t_2}}{t}}}=N^d\Bigl(I^a_t+II^a_t+III^a_t+IV^a_t\Bigl)

    \end{equation}
    where for $k\geq 1$,
    \begin{equation}
        \begin{split}
            I^a_t &:=\frac{(h^\eta t)^d}{t^a}\int_{\mc{T}_{t_1,t_2}}\psi\pr{\frac{\atc{q}_0(\widetilde{\rho})}{t}}d\widetilde{\rho}\\
            II^a_t &:=\mc{O}_M(1)\frac{(h^\eta t)^d}{t^a}\Tilde{h}\int_{\mc{T}_{t_1,t_2}}\widetilde{\chi}\pr{\frac{\atc{q}_0(\widetilde{\rho})}{t}}d\widetilde{\rho}\\
            III^a_t &:= \mc{O}_M(1)\frac{(h^\eta t)^d}{t^a}\Tilde{h}^M\int_{\mc{T}_{t_1,t_2}}\widetilde{m}(\widetilde{\rho})d\widetilde{\rho}\\
            IV^a_t &:= \mc{O}_k(1)\frac{(h^\eta t)^d}{t^a}\pr{Nh^\eta t^{1/2}}^{-k}\int_{\mc{T}_{t_1,t_2}}\widetilde{m}(\widetilde{\rho})d\widetilde{\rho}.
        \end{split}

    \end{equation}
    and where $\widetilde{\chi}\in \mathscr{C}^{\infty}_c(\R;[0,1])$ is such that $\widetilde{\chi}\equiv 1$ on a neighborhood of $[0,\sup\mathrm{supp}(\psi)]$.

