body:
[Lemma 15 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $p\geq 2$ and let $(X_N=I_p(f_N), N\geq 1)$ satisfy 
	\eqref{c1}. Let $Y_N=I_q(g_N)$ with $p<q<2p$ and 
	$\sup_N\|g_N\|_{H^{\otimes q}}<\infty$. Define
	\begin{equation}
		h_N := \frac{f_N\otimes_p g_N}
		{\|f_N\|^2_{H^{\otimes p}}}\in H^{\odot(q-p)},
	\end{equation}
	\begin{equation*}
		g_N^{(2)} := g_N - \frac{q!}{p!(q-p)!}
		f_N\widetilde\otimes h_N\in H^{\odot q},
		\qquad
		\varepsilon_N := I_q(g_N^{(2)}).
	\end{equation*}
	Then for every $N\geq 1$:
	\begin{equation}
		Y_N = \frac{1}{p\sigma^2}X_N\cdot Y_{1,N} 
		+ \varepsilon_N + r_N,
	\end{equation}
	where:
	\begin{enumerate}
		\item $f_N\otimes_p g_N^{(2)}=0$, and consequently 
		$\langle DX_N, D\varepsilon_N\rangle_H\to 0$ in 
		$L^2(\Omega)$, so $\varepsilon_N$ is asymptotically 
		independent of $X_N$;
		\item $r_N\to 0$ in $L^2(\Omega)$ as $N\to \infty$.
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 (Averaged diagonal self-averaging) of arXiv:2608.20998, 'Free-Probability Kernels for Zero-Rollout Hyperparameter Selection in Reservoir Computing'] For every fixed $L<\infty$,
\begin{equation}
\max_{0\leq k,\ell\leq L}
\frac1n\sum_{i=1}^{n}
\left|
\left[A_n^k(A_n^\ell)^\top\right]_{ii}
-\tau_{k,\ell}
\right|^2
\xrightarrow{\mathbb P}0.

\end{equation}

[Definition 56 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $q \in (0,1), c \in (1, q^{-1})$ and set $\hat{\kappa}_0 = \left( \frac{1-qc}{c-q} \right)^2 \in (0,1)$. For $\hat{\kappa} \in (\hat{\kappa}_0, 1]$ and $z \in \mathbb{C} \setminus \{0,q,q^{-1}\}$, we define
\begin{equation}
\begin{split}
&\hat{S}_1(z; \hat{\kappa}) = \log(1 - q/z) - \hat{\kappa} \log (1 -q z) - \frac{q(q+ 2\hat{\kappa}^{1/2} + q \hat{\kappa})}{1 - q^2} \cdot \log(z), \\
&\hat{S}_2(z;\hat{\kappa}) = \log(1-q/z) - \hat{\kappa} \log(1-qz) - \frac{qc\hat{\kappa} (c-q) + q(1-qc)}{(1-qc)(c-q)} \cdot \log(z).
\end{split}
\end{equation}

[Lemma G_at_q0 of arXiv:2603.27906, 'Marked GUE-corners process in doubly periodic dimer models'] The function 
$\exp(G(z,w))= (z-1)^{\ell} w z^{-\tau }$ has a zero of order $2\ell$ at $q_0$. Hence in a neighbourhood of $q_0$ setting $z=1+\frac{Z}{\sqrt{N}}$, with respect to the (canonical) local chart coming from $(z,w)\mapsto z$ we have that
\begin{equation} 
w_k^{-r_k}\exp(NG(z_k,w_k))=\left(B^{-1}+\mathcal{O}\left(\frac{|Z_k|}{N^{\frac{1}{2}}}\right)\right)^{N-r_2}\left(\frac{Z_k}{N^{\frac{1}{2}}}\right)^{2\ell N-r_k\ell},\quad\text{for}\quad k=1,2,
\end{equation}
where $B>0$ is as in Lemma (lemma:local_action_function of the paper).

[Lemma 13 of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Let $W$ be an $N\times N$ GOE/GUE matrix. For any fixed $D\in\N$, $n_1,n_2\in\N\cup\{0\}$ and multi-indices $\bm{k}\in \N^{n_1},\bm{l}\in\N^{n_2}$, it holds that
\begin{equation}
\E\left(\bm{k},\bm{l}\right) = \sum_{d=0}^{D-1} \frac{1}{(N\eta)^d}\Phi_d\left(\bm{k},\bm{l}\right) + \mathcal{O}\left(\frac{1}{(N\eta)^D}+\eta\right),

\end{equation}
where the implicit constant in $\mathcal{O}(\cdot)$ is uniform in $z\in\mathcal{D}$. For $d\in \N\cup\{0\}$, the coefficients $\Phi_d$ depend only on $\Re z$, $\bm{k}$, $\bm{l}$ and $\beta$, and satisfy the following recurrence relations for $\bm{k}\neq\emptyset$:
\begin{equation}
\begin{split}
\Phi_d(\bm{k},\bm{l})=&\frac{2\ma_0}{\beta}\Im m_0 \sum_{j=1}^{n_2} \frac{\ii^{k_1-l_j-1}}{2^{k_1+l_j-1}} l_j\binom{k_1+l_j-1}{k_1-1} \Phi_d\left(\bm{k}^{[1]},\bm{l}^{[j]}\right)+\bm{1}_{\beta=1}\ma_0 k_1\Phi_{d-1}\left(\big(k_1+1,\bm{k}^{[1]}\big),\bm{l}\right)\\
+& \ma_0 \sum_{u=1}^{k_1} \Phi_{d-1}\left(\big(u,k_1+1-u,\bm{k}^{[1]}\big),\bm{l}\right)+\frac{2\ma_0}{\beta} \sum_{i=2}^{n_1} k_i \Phi_{d-1}\left(\big(k_1+k_i+1,\bm{k}^{[1,i]}\big),\bm{l}\right)\\

+&\frac{2\ma_0}{\beta} \sum_{j=1}^{n_2} \sum_{u=1}^{k_1} l_j \frac{(-1)^{k_1-u}}{(2\ii)^{k_1+l_j+1-u}} \binom{k_1+l_j-u}{l_j}\Phi_{d-1}\left( \big(u, \bm{k}^{[1]}\big), \bm{l}^{[j]}\right)\\
+&\frac{2\ma_0}{\beta} \sum_{j=1}^{n_2} \sum_{v=1}^{l_j+1} l_j\frac{(-1)^{k_1}}{(2\ii)^{k_1+l_j+1-v}}\binom{k_1+l_j-v}{k_1-1}\Phi_{d-1}\left(\bm{k}^{[1]},\big(v,\bm{l}^{[j]}\big)\right).
\end{split}

\end{equation}
Here we additionally set $\Phi_{d'}:=0$ for $d'<0$ and $\Phi_0(\emptyset,\emptyset):=1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Hopf Lax of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $\mu$ be a probability measure on $\mathbb{R}$ with support bounded from below and let $t>0$.
		\begin{enumerate}
			\item Let $x\in\mathbb{R}$ and set $\omega := \omega_{\mu,t}(x)\in\mathbb{C}^+\cup\mathbb{R}$. Define the characteristic path $(z_s)_{s\in [0,t]}$ by
			\begin{equation}
				z_s = \omega + s\, G_\mu(\omega).
			\end{equation}
			If $x\leq \ell(\mu\boxplus\sigma_t)$, then for every $s\in [0,t]$,
			\begin{equation}
				x \leq z_s \leq \ell(\mu\boxplus\sigma_s).
			\end{equation}
			If instead $x$ lies in the interior of $\mathrm{supp}(\mu\boxplus\sigma_t)$, then for every $s\in [0,t)$,
			\begin{equation*}
				\Im\bigl(\omega + s\,G_\mu(\omega)\bigr) > 0.
			\end{equation*}

			\item For every $x\leq \ell(\mu\boxplus\sigma_t)$,
			\begin{multline}
				\int \log|\lambda-x|\,\mathrm{d} (\mu\boxplus \sigma_t)(\lambda) = \int \log |\lambda-\omega_{\mu,t}(x)|\,\mathrm{d} \mu(\lambda) + \frac{\Re\bigl(\omega_{\mu,t}(x)-x\bigr)^2 - \Im\bigl(\omega_{\mu,t}(x)\bigr)^2}{2t}\\
				= \inf_{u\leq \ell(\mu)}\;\sup_{\substack{v\geq 0 \\ u+iv\in \overline{\Omega_{\mu,t}}}} \Bigl(\int \log |\lambda-(u+iv)|\,\mathrm{d} \mu(\lambda) + \frac{(x-u)^2-v^2}{2t}\Bigr).
			\end{multline}
			Moreover, the infimum in (equation eq:ch of the paper) is uniquely attained at $(u,v)=\bigl(\Re(\omega_{\mu,t}(x)),\,\Im(\omega_{\mu,t}(x))\bigr)$.
		\end{enumerate}

