body:
[Lemma lem:weight-removal-interface-match of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] Put $\chi_{\rm rad}=50r^2/29$ and define
\begin{equation}
 \begin{aligned}
 \varphi_-(r)&=\sum_{n=0}^\infty a_n\chi_{\rm rad}^n,
 &a_0&=1,
 &a_n&=-\frac{3}{n!(2n-1)(2n+1)(2n+3)}\quad(n\geq1),\\
 \varphi_+(r)&=r-\frac{39}{25r}-\frac{507}{625r^3}
                 -\frac{6591}{15625r^5},
 &&& &r>0.
 \end{aligned}

\end{equation}
The two profiles solve
\begin{equation}
 \frac{29}{200}\varphi_-''
 +\left(\frac{29}{50r}-\frac r2\right)\varphi_-'
 +\frac12\varphi_-=0,
 \qquad
 \frac{13}{50}\varphi_+''
 +\left(\frac{39}{25r}-\frac r2\right)\varphi_+'
 +\frac12\varphi_+=0.

\end{equation}
There exist matching parameters
\begin{equation*}
 R_{\mathrm{int}}\in
 \left(\sqrt{\frac{29}{15}},\frac{\sqrt{203}}{10}\right),
 \qquad \mathfrak s_{\mathrm{match}}\ne0,
\end{equation*}
For these parameters, the matched profile
\begin{equation}
 \varphi_{\rm dw}(r)=
 \begin{cases}
  \varphi_-(r),&0\leq r\leq R_{\mathrm{int}},\\
  \mathfrak s_{\mathrm{match}}\varphi_+(r),&r\geq R_{\mathrm{int}}
 \end{cases}

\end{equation}
is $C^1$ and piecewise smooth.

[Prop admissibility-vs-shift of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Let $({\mathbf{a}},{\mathbf{b}})$ be a non-degenerate weight pair.
	\begin{enumerate}
		\item If ${\mathbf{a}}=(a_0,a_1,0,0\dots)$ with $a_0,a_1>0$ then $({\mathbf{a}},{\mathbf{b}})$ is admissible.
		\item If $({\mathbf{a}}^+,{\mathbf{b}})$ is admissible and if the inequalities
		\begin{align}
		\frac{\PFComp{{\mathbf{a}}^+,{\mathbf{b}}}{n+1-m}}{\PFComp{{\mathbf{a}}^+,{\mathbf{b}}}{n-m}}
		\leq
		\frac{\PFComp{{\mathbf{a}},{\mathbf{b}}}{n+1}}{\PFComp{{\mathbf{a}},{\mathbf{b}}}{n}}
		\geq
		\frac{b_{m+1}}{b_m},
		\end{align}
		are satisfied for $m=1,\dots,n$, then $({\mathbf{a}},{\mathbf{b}})$ is admissible.
	\end{enumerate}

[Lemma 23 (Second overshoot lemma) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] We assume that there is \(\delta >  d\) such that
\(\P(\lVert S_{1} \rVert>u) \preceq u^{-\delta}\). There is a constant
\(C\) such that for \(r' \geq r\) and \(\lVert x \rVert > r+r'\), we
have

\begin{equation*}{
\sum_{y :\lVert y \rVert < r } \sum_{\gamma:x \to y \subset B(0,r+r')} s(\gamma) \leq  C \frac{r'^{d-\delta}}{\lVert x \rVert ^{d-2}}
}\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 12 of arXiv:2608.12291, 'When should one stop the most exciting game?\\ {\tiny Sequential Inference for win-marting'] The second spatial derivative of the value function admits the representation
    \begin{equation*}
        \partial_{xx} V_T(t,x)=\begin{cases}
            -2\frac{c(t)+\partial_tV_T(t,x)}{\sigma^2(x)} & \text{for }(t,x)\in\mathcal{C}_T\\
            g''(x)&\text{for }(t,x)\in(\mathcal{D}_T)^\circ.
        \end{cases}
    \end{equation*}
    Specifically, it is not continuous across the boundary. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:2 of arXiv:2412.04539, 'Counting minimal cutsets and $p_c<1$'] Let $u\in V$, let $\Pi$ be a minimal cutset from $u$ to $\infty$. Let $A$ be the connected component of $u$  in $(V,E\setminus \Pi)$ and $B=\{e\cap A,\, e\in \Pi\}$  be the set of inner vertices of $\Pi$. For every set $S$ of vertices, we have
  \begin{equation}

    (B \subset S \subset A) \implies (\partial_\infty S= \Pi).
  \end{equation}

