body:
[Definition 199 of arXiv:2601.16377, '2601.16377'] The master problem asks to find an $H$-tuple of functions $\boldsymbol{F}(z)=(F_h(z))_{h=1}^H$ with the following properties for any $h \in [H]$.
\begin{enumerate}
\item $F_h(z)$ is a holomorphic function of $z \in \amsmathbb C\setminus \amsmathbb{A}_h^{\mathfrak{m}}$.
\item There exists a holomorphic function $A_h(z)$ of $z \in \amsmathbb{M}_h$ such that
\begin{equation}

 A_h(z) = \sqrt{(z-\alpha_h) (z-\beta_h)} \,\big\langle \bth_h \cdot \boldsymbol{F}(z)\big\rangle + E_h(z).
 \end{equation}
 \item $F_h(z) = \frac{\kappa_h}{z}+O\big(\frac{1}{z^2}\big)$ as $z \rightarrow \infty$. This can be equivalently restated as
\[
F_h(z)\,\, \mathop{=}_{z \rightarrow \infty} \,\, O\bigg(\frac{1}{z}\bigg) \qquad \textnormal{and} \qquad \oint_{\gamma_h} \frac{\dd z}{2\ii\pi}\,F_h(z) = \kappa_h.
\]
\end{enumerate}

[Thm P th gau of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] There exist a deterministic constant $c_1\in(0,\infty)$
  and a deterministic function $c_2\colon (0,\infty)\to(0,\infty)$ such that the following holds.
  \begin{enumerate} [label = \textup{(\roman*)}]
    \item
    If $\hat{d}_{\mathrm{s}}>2$, then, $\hat{P}_{\bm{\rho}}$-a.s., for all $t \in (0,\infty)$,
    \begin{equation}
      c_1
      \leq
      \sup_{x\in M}
      \varlimsup_{r\downarrow0}
      \frac{\Pi_t(B(x,r))}{r^{d_{\mathrm{cp}}}\log(1/r)}
      \leq
      \varlimsup_{r\downarrow0}
      \sup_{x\in M}
      \frac{\Pi_t(B(x,r))}{r^{d_{\mathrm{cp}}}\log(1/r)}
      \leq
      c_2(t).
    \end{equation}

    \item
    If $\hat{d}_{\mathrm{s}}=2$, then, $\hat{P}_{\bm{\rho}}$-a.s., for all $t \in (0,\infty)$,
    \begin{equation}
      c_1
      \leq
      \sup_{x\in M}
      \varlimsup_{r\downarrow0}
      \frac{\Pi_t(B(x,r))}{r^{d_{\mathrm{f}}}(\log(1/r))^2}
      \leq
      \varlimsup_{r\downarrow0}
      \sup_{x\in M}
      \frac{\Pi_t(B(x,r))}{r^{d_{\mathrm{f}}}(\log(1/r))^2}
      \leq
      c_2(t).
    \end{equation}
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

