    \begin{equation*}
        \diam(B_{\alpha^n}(x; D); D_\sigma) \le C \prod_{j = 1}^n \left(\eta + 2\sup\{\sigma(y, j) : y \in X \text{ with } D(x, y) \le 26\alpha^j\}\right), \quad \forall (x, n) \in V. 
    \end{equation*}

