[Lemma lem:wp:entropyEstimates of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Let $m \in \mathbb{N}$ and $\lambda_0 \in \mathcal{P}(\ensuremath{\mathbb{R}}^m)$. Suppose $b^1, b^2:[0, T] \times \ensuremath{\mathbb{R}}^m \rightarrow \ensuremath{\mathbb{R}}^m$ are measurable and satisfy a linear growth condition, that is there exists $C \in (0, \infty)$ such that
\begin{equation*}
    \sup_{(t, x) \in [0, T] \times \ensuremath{\mathbb{R}}^d} |b^i(t, x)| \leq C(1 + |x|), \quad i = 1, 2.
\end{equation*}
For $i = 1, 2$, suppose $(\Omega^i, \mathcal{F}^i, \mathbb{F}^i, \mathbb{P}^i)$ is a filtered probability space supporting an $m$-dimensional Brownian motion $B^i$ and a continuous $m$-dimensional $\mathbb{F}^i$-adapted process $Z^i$ satisfying
\begin{equation*}
    dZ^i(t) = b^i(t, Z^i(t)) dt + \sqrt{2}dB^i(t),
\end{equation*}
with $\mathcal{L}(Z^1(0)) = \mathcal{L}(Z^2(0)) = \lambda_0$. Then the following identity holds: 
\begin{equation*}
    \mathcal{H} \big( \mathcal{L}(Z^1[T])\,|\, \mathcal{L}(Z^2[T]) \big) = \frac{1}{2} \mathbb{E}^{\mathbb{P}^1} \Bigg[ \int_0^T |b^1(t, Z^1(t)) - b^2(t, Z^1(t))|^2 dt\Bigg]. 
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 111 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Define $\widetilde{U}_j$ by shifting $\mathcal{U}_{a,b,c}^{j/N}$ (vertically) down by $\mathfrak{d}^{2/3} j_{\bar{z}}^{-1/3} N^{\delta/2-2/3}$ and (horizontally) to the right by $\mathfrak{d}^{-1/3} j_{\bar{z}}^{-1/3} N^{-2/3-\delta}$. Specifically, for $j\le k$ and $x\in[x^-,x^+]$, set 
	\begin{flalign*} 
		\widetilde U_j(x) = \mathcal{U}_{a,b,c}^{j/N} (x - \mathfrak{d}^{-1/3} j_{\bar{z}}^{-1/3} N^{-2/3-\delta}) - \mathfrak{d}^{2/3} j_{\bar{z}}^{-1/3} N^{\delta/2-2/3}.
	\end{flalign*} 

	\noindent Furthermore, for each $t \in [0, N^5]$, let $\mathtt{U}_t^{j/N} (x)$ denote the $jN^{-1}$-level line (as in Definition \ref{ttU}, recalling also \Cref{ftn:minorabuse}) of $H_t$, and set $\mathtt{y}_t^{\pm,j} = \mathtt{U}_t^{j/N} (x^{\pm})$.

[Theorem 3 (Parameter-uniform curvature correction) of arXiv:2608.30211, '2608.30211'] Assume \eqref{eq:f-assumptions} and that $\Omega$ is bounded, connected, and
$C^{4,\gamma}$.  For every fixed $R>0$ there is $C_R>0$ such that, for all
sufficiently large $\kappa$,
\begin{align}
 &\sup_{\varrho\in[0,1]}
 \sup_{\substack{x\in D_\kappa\\d_\kappa(x)\le R}}
 \left|u_{\kappa,\varrho}(x)-\phi_\varrho(d_\kappa(x))
 -\frac{\mathcal H(\pi_\kappa(x)/\kappa)}{\kappa}
       \chi_\varrho(d_\kappa(x))\right| \notag\\
 &\hspace{35mm}\le C_R(\kappa^{-1-\gamma}+\kappa^{-2}).

\end{align}
Consequently,
\begin{equation}
 \sup_{\varrho\in[0,1]}
 \sup_{\substack{x\in D_\kappa\\d_\kappa(x)\le R}}
 \left|\kappa\bigl(u_{\kappa,\varrho}(x)-\phi_\varrho(d_\kappa(x))\bigr)
 -\mathcal H(\pi_\kappa(x)/\kappa)\chi_\varrho(d_\kappa(x))\right|
 \longrightarrow0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:metastability of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] Suppose Assumptions~(ass:cycle of the paper) and~(ass:monodromy of the paper)
hold, and let $R\ge1$, $j\in\mathbb Z$, $n\ge1$,
$\varepsilon_0\ge0$, $\delta'>0$, the sequences
$(Y_k)_{k\ge-1}$ and $(\zeta_i)_{i\ge1}$ satisfying the
recursion (equation eq:abstract-recursion of the paper), and the event
$\mathcal G$ in (equation eq:good-general of the paper) be as above. Assume
\begin{equation}
 C\varepsilon_0+G_0\delta'\le\frac{a}{2},
\end{equation}
where $C$ is the constant fixed after
Assumption~(ass:monodromy of the paper), and $G_0$ and $a$ are defined in
(equation eq:impulsegain-general of the paper) and (equation eq:tuberadius-general of the paper).
Then the following conclusions hold.
\begin{enumerate}
\item[\rm(i)] On $\mathcal G$, $\abs{Y_k-Rx_{j+k}^\circ}\le aR/2$ for $0\le k\le n$.
\item[\rm(ii)] Let $(Y_k^{(j)})$ and $(Y_k^{(j+1)})$ be sequences as above with consecutive indices $j$ and $j+1$. Then
\begin{equation*}
 \norm{\operatorname{Law}(Y_n^{(j)})-\operatorname{Law}(Y_n^{(j+1)})}_{\mathrm{TV}}
 \ge1-\mathbb P(\mathcal G_j^c)-\mathbb P(\mathcal G_{j+1}^c).
\end{equation*}
The same lower bound holds for the laws of random elements $Z_n^{(j)}$ and $Z_n^{(j+1)}$ if there is a common measurable map $f$ such that $Y_n^{(r)}=f(Z_n^{(r)})$ for $r\in\{j,j+1\}$.
\item[\rm(iii)] Suppose $E_0=0$ and
\begin{equation*}
 \sup_{i\ge1}\mathbb P\bigl(\lvert \zeta_i\rvert>\delta'R\bigr)\le Ae^{-bR^2},
\end{equation*}
where $A,b>0$ are independent of $R$, $n$, and $i$. Then $\mathbb P(\mathcal G^c)\le Ane^{-bR^2}$. If the sequences with consecutive indices $j$ and $j+1$ both satisfy these assumptions, then
\begin{equation*}
 \norm{\operatorname{Law}(Y_n^{(j)})-\operatorname{Law}(Y_n^{(j+1)})}_{\mathrm{TV}}\ge1-2Ane^{-bR^2}.
\end{equation*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 52 (Backwards-time propagation of test functions in $d=2$) of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] Let $d=2$. Assume $\x_N=(x^1_N,x^2_N)$ is any sequence such that $N^{-1/2}x_N^1 \to x_1$ and $x^1_N-x^2_N$ remains bounded, and consider the same setting as Assumption \ref{ass:SRI}. 
      Consider smooth bounded functions $\phi_1, ..., \phi_m : \mathbb R^d\to \mathbb R$ with globally bounded and continuous first and second partial derivatives, and consider $f^1,..., f^m : I\to \mathbb R$ of exponential decay at infinity. Then \begin{equation} 
    \lim_{N\to\infty} \Ebbnn \bigg[ \frac1{(\log N)^m}\sum_{0\leq r_1 < \ldots < r_m \leq Nt} \prod_{\ell =1}^m f^{\ell}(   R^1_{r_{\ell}}-   R^2_{r_{\ell}})\phi_{\ell}(N^{-1/2} (R^1_{r_\ell}-   s_N r_\ell))\bigg] = \prod_{\ell = 1}^m \bigg( \phi_\ell (x_1) \int_I f^\ell \; \dr \pi^{\mathrm{inv}} \bigg)\end{equation}
    The claim remains true if we replace $(f^1,...,f^m)$ on the left side by some sequence $(f^1_N,...,f^m_N)$ converging uniformly on compact sets as $N\to\infty$ to some $(f^1,...,f^m)$, as long as $\sup_{N} |f^j_N|$ decays exponentially fast at infinity for $j=1,...,m$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 5 of arXiv:2607.06242, 'Exponential mixing and Freidlin--Wentzell large deviation principle for Markov cocycles'] Under assumptions $(H2)$--$(H4)$, there exist constants $\a_0, v, \g_{*}>0$ depending only on $\varpi,b_1,\zeta,\k$ such that for every $\a\in(0,\a_0]$ and the premetric 
      \begin{align}
        \theta_\alpha(x, y):=p(x, y)^\alpha e^{\alpha v U(x)}, \quad x,y\in E,
      \end{align}
      the following conclusions hold:
      \begin{enumerate}
        \item[(1)] There exists $C_{\a}\geq 1$, such that for any $x,y\in E$,
        \[ \mathbf{E} \theta_\alpha\left(X_t^\sigma, Y_t^\sigma\right)\leq A_t(\s)\theta_\alpha(x, y),\]
        and 
      \[d_{TV}\left(\mathcal{L}(Y_t^{\s}), P_{t}^{\s}(y,\cdot)\right)\leq B_t(\s)\theta_\alpha(x, y),\]
        where 
        \begin{align}
          A_t(\s) = C_{\a}e^{-\a\chi_{t}(\s)}, \quad B_{t}(\s) = C_{\a}\left(\int_0^{t}b_3(\beta_s\s)e^{-\chi_s(\s)}ds\right)^{\a}
        \end{align}
        with 
        \[\chi_t(\sigma) = \zeta t- \frac{\k}{\varpi-\g_{*} b_1}\int_0^t\left(b(\beta_s\s)+\g_{*} b_2(\beta_s\s)\right)ds.\]
        \item[(2)] For any $B\subset E$ such that $U$ and $p$ are bounded on $B$ and $B\times B$, and any $t\geq0$, there is  $C_{\a,B}>0$ such that for any $x,y\in B$, one has 
        \[d_{TV}\left(\mathcal{L}(Y_t^{\s}), P_{t}^{\s}(y,\cdot)\right)\leq 1-\bar{\varepsilon}_{\a}(C_{\a,B}B_{t}(\s)),\]
        and 
        \[\mathbf{E} \theta_\alpha\left(X_t^\sigma, Y_t^\sigma\right) \leq C_{\alpha,B} A_{t}(\s),\]
        where $\bar{\varepsilon}_{\a}$ is the function from $(H4)$. 
      \end{enumerate}

