[Corollary 12 of arXiv:2607.11608, '2607.11608'] Let  $r\ge 1$. Then, 
\begin{align*}
	\bigg|\!\bigg| \int_{\R^d}:\!|Y_N|^2\!:dx\bigg|\! \bigg|_{L^r(\Omega)}\les_r 1.
\end{align*}
Moreover,   $\int_{\R^d}:\!|Y_N|^2\!:dx$ is a Cauchy sequence in $L^{r}(\Omega)$ and, 
\begin{align*}
\bigg|\!\bigg| \int_{\R^d}:\!|Y_N|^2\!:dx-\int_{\R^d}:\!|Y|^2\!:dx\bigg|\! \bigg|_{L^r(\Omega)}\les_r N^{-\frac{1}{2}}.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 26 of arXiv:2609.02878, '2609.02878'] Let $d\nu_{x,b;a}$ be the conjugate heat-kernel probability at time $a$
with pole $(x,b)$, where $a<b<T$.  Then every smooth real or complex
function $\phi$ satisfies
\begin{equation}
 \int\left|\phi-\int\phi\,d\nu_{x,b;a}\right|^2d\nu_{x,b;a}
 \le2(b-a)\int|\nabla\phi|_{g(a)}^2\,d\nu_{x,b;a}.
\end{equation}

[Lemma 9 of arXiv:2609.03958, '2609.03958'] Let $n\geq 2$ and $K\geq 0$. Suppose that  $\kappa\in \Gamma_2$ satisfies $\kappa_1\geq\ldots \geq \kappa_n\geq -K$ and $\sigma_2(\kappa)=f$ with $f_0\leq f \leq f_1$ for two constants $f_1\geq f_0>0$.  Then there exists some constant $C>0$ depending only on $n$, $K$, $f_0$ and $f_1$ such that
\begin{equation}
\mathcal C(\kappa)\geq-C H^2.
\end{equation}

[Proposition prop:unif_lower_bound of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] Let $B=(B_t)_{t\geqslant0}$ denote the hypoelliptic Brownian motion on
$\mathbb G$ starting from the identity $e$, and let
$\mathcal C_e^+(\beta,\rho;X)$ be as in
Definition~(def:oriented_cone_horiz of the paper). Then
\begin{align}
\inf_{\substack{X\in V_1\\ |X|=1}}
\operatorname{Vol}(\mathcal C_e^+(\beta,\rho;X))
>0.
\end{align}
Moreover, for every fixed $t>0$,
\begin{align}
\inf_{\substack{X\in V_1\\ |X|=1}}
\mathbb P_e\bigl(B_t\in\mathcal C_e^+(\beta,\rho;X)\bigr)
>0.
\end{align}

