[Definition of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] Let $ X(\cdot) $ be an $ \mathcal{X} $-valued stochastic process.
    \begin{enumerate}[(i)]
        \item  We say that $ X(\cdot) $ is measurable if the map $ (t , \omega) \mapsto X(t, \omega) $ is strongly $ (\mathcal{B}([0,T] )\times  \mathcal{F}) / \mathcal{B}(\mathcal{X}) $-measurable; 
        \item We say that $ X(\cdot) $ is $ \mathbf{F} $-adapted if it its measurable and for each $ t \in [0,T] $, the map $ \omega \mapsto X(t, \omega) $ is strongly $ \mathcal{F}_{t}/ \mathcal{B}(\mathcal{X}) $-measurable;
        \item We say that $ X(\cdot) $ is $ \mathbf{F} $-progressively measurable if for each $ t \in [0,T] $, the map $ (s, \omega) \mapsto X(s, \omega) $ from $ [0, t] \times \Omega $ is strongly $ ( \mathcal{B}([0,t]) \times \mathcal{F}_{t})/ \mathcal{B}(\mathcal{X}) $ -measurable.
    \end{enumerate}

[Lemma Benamou Brenier for W-p of arXiv:2603.14163, '\LARGE \bf Tail Bounds for Queues with Abandonment: Constant, Moderate, Large Deviations, '] \textnormal{Benamou-Brenier for Wasserstein-$p$ distance [ambrosio2005gradient][ledoux2015stein]} 
    Suppose $X, Z$ are two random variables in $\mathbb{R}^d$ with probability measures $\mathcal{L}(X), \mathcal{L}(Z) \in \mathcal{P}_p(\mathbb{R}^d)$ respectively. 
    For a weakly continuous curve of probability measures $\mu_t : I \to \mathcal{P}_p(\mathbb{R}^d)$ with open interval $I \subset \mathbb{R}$. If it  satisfies the continuity equation for some Borel vector field $v_t$ with $\int_I \int_{\mathbb{R}^d} \|v_t(x)\|_2^p d\mu_t(x) dt < \infty$ and
        $\partial_t \mu_t + \text{div}(\mu_t v_t) = 0, \; \forall (x,t) \in \mathbb{R}^d\times I$. Then curve $\mu_t: I\to \mathcal{P}_p(\mathbb{R}^d)$ is absolutely continuous and for Lebesgue-almost everywhere $t \in I$, we have
        \begin{align*}
            \lim_{ s\to t} \frac{W_p(\mu_s, \mu_t)}{|s-t|} \leq \left\{\int_{\mathbb{R}^d} \|v_t(x)\|_2^p d\mu_t(x) \right\}^{1/p} 
        \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 of arXiv:2609.03512, ''] Let $G$ be a connected graph with $g(G)\neq 3$, $\gamma(G)=2.$ 
Let $D=\{u,v\}$ be a dominating set of $G$. Then $D$ is a total dominating set if and only if the following hold:
\begin{itemize}
\item $N(u)\cap N(v)=\emptyset,$ and
\item $\deg(u)+\deg(v)=|V(G)|.$
\end{itemize}

[Extratheorem 2 of arXiv:2608.19179, 'A random walk on $p$-groups with a symmetric perfect pairing'] \cite{FriedmanWashington}

  If $\mathcal{M}_{k,k}$ is a random matrix whose entries are independent Haar distributed elements of $\Z_p$, $ker(\mathcal{M}_{k,k})$ is finite almost surely and:
  \begin{equation}

  \lim_{k \rightarrow \infty}\probP\Big( ker(\mathcal{M}_{k,k}) \cong G \Big) \propto \frac{1}{|Aut(G)|}
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 of arXiv:2603.28093, 'Random Stability of Random Variables'] Take a random variable $Y \ge 0$ with $\mathbb E[Y] = 1$. Assume its semigroup $G(Y)$ is not trivial. Let $N_c$ be the random variable with probability generating function as in~\eqref{eq:Bunge}, with $c \in S(Y)$. Then a random variable  
$X$ is $N$-stable for at least one, and therefore for all, $N$ with distribution in $G(Y)$, if and only if there exists a sequence of independent identically distributed random variables $U_1, U_2,\ldots$ independent of all these $N$, and a function $a : S(Y) \to [0, \infty)$ such that 
\begin{equation}

\frac{U_1 + \ldots + U_{N_c}}{a(c)} \stackrel{d}{\to} X,\quad c \to \infty,\quad c \in S(Y).
\end{equation}
If this is true, then for any such sequence $U_1, U_2, \ldots$ the statement~\eqref{eq:1} is equivalent to~\eqref{eq:2}:
\begin{equation}

\frac{U_1 + \ldots + U_{[c]}}{a(c)} \stackrel{d}{\to} Z,\quad c \to \infty,\quad c \in S(Y).
\end{equation}
In this case, we have~\eqref{eq:repr}, with $Z$ strictly $\alpha$-stable, and $Y$ and $Z$ independent. Moreover, the distributions of $X$ and $Z$ are related as in~\eqref{eq:repr}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 10 of arXiv:2609.02175, '2609.02175'] Let $g$ be a smooth Riemannian metric on $\mathbb R^n$,
	$n\geq3$. Assume that there exists $R>0$ such that
	\begin{equation}
		\operatorname{supp}(g-g_0)\Subset B(0,R),
	\end{equation}
	and that $(B(0,R),g)$ is simple. If
	\begin{equation}
		\|S_{g,h}(\lambda)-S_{g_0,h}(\lambda)\|
		_{\mathcal B(L^2(\mathbb S^{n-1}))}
		=
		o(1),
		\qquad h\to0,
	\end{equation}
	then there exists a diffeomorphism
	\begin{equation}
		\psi:B(0,R)\longrightarrow B(0,R),
		\qquad
		\psi|_{\partial B(0,R)}
		=
		\operatorname{Id},
	\end{equation}
	such that
	\begin{equation}
		g
		=
		\psi^*g_0.
	\end{equation}

