[Corr martingaleutile of arXiv:2603.21634, 'Individual-based stochastic model with unbounded growth, birth and death rates: a tightnes'] Under the \hyperlink{gen}{general setting}, let $\varphi \in \mathcal{C}^{1,1}_{\omega}(\mathbb{R}^{+} \times \mathbb{R}^{*}_{+})$. Then the process $(\langle \mu_{t}, \varphi_{t} \rangle)_{t \geq 0}$ is a semi-martingale, with for all $t \geq 0$, a finite variation part given by
\begin{align*}
V_{\varphi,t} := & \hspace{0.1 cm} \langle \mu_{0}, \varphi_{0} \rangle + \displaystyle{\int_{0}^{t}} \langle \mu_{s}, \Phi_{s}(R_{s},.) \rangle \mathrm{d}s - \displaystyle{\int_{0}^{t}\int_{\mathbb{R}^{*}_{+} }} d(x)\varphi_{s}(x) \mu_{s}(\mathrm{d}x) \mathrm{d}s \\
    &  + \displaystyle{\int_{0}^{t}}\int_{\mathbb{R}^{*}_{+} } b(x)\bigg( \varphi_{s}(x_{0})+\varphi_{s}(x-x_{0})-\varphi_{s}(x)\bigg) \mu_{s}(\mathrm{d}x) \mathrm{d}s,
\end{align*}
with $\Phi$ associated to $\varphi$ as in (equation eq:Phidef of the paper), and a square-integrable martingale part $\heartsuit_{\varphi,t} := \langle \mu_{t}, \varphi_{t} \rangle - V_{\varphi,t} $ whose predictable quadratic variation is given by
\begin{align*}
\langle \heartsuit_{\varphi} \rangle_{t} =  \displaystyle{\int_{0}^{t}\int_{\mathbb{R}^{*}_{+}}}b(x)\bigg[ \varphi_{s}(x_{0})+\varphi_{s}(x-x_{0})-\varphi_{s}(x) \bigg]^{2} \mu_{s}(\mathrm{d}x) \mathrm{d}s + \displaystyle{\int_{0}^{t}\int_{\mathbb{R}^{*}_{+}}}d(x)\varphi_{s}^{2}(x) \mu_{s}(\mathrm{d}x) \mathrm{d}s.
\end{align*}

[Lemma lem:orderMN of arXiv:2603.16824, 'Age-dependent random connection models with arc reciprocity: clustering and connectivity'] Let \(\gamma\geq 1/2\) and consider the quantities \(\mathbf{M}_t\) and \(\mathbf{N}_t\), defined in~(equation eq:defMN of the paper). We have
	\begin{equation*}
	\mathbb{E}[\mathbf{M}_t]\asymp 
	\begin{cases}
		t \log(t), & \text{ if }\gamma = 1/2,
		\\
		t^{2\gamma}(\log t)^{2\gamma-1}, & \text{ if } \gamma>1/2.
	\end{cases}
\end{equation*}
Moreover, \(\mathbb{E}\mathbf{N}_t =o(\mathbb{E}\mathbf{M}_t)\).

[Lemma opt2prefix of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $f\in \mathbb{R}$, $q\in (0,1)$ and $u\in (0,1)$. Let $\zeta\in \mathrm{Prefix}_2(u,q)$ satisfy the assumptions of Proposition (prop:annealed 0 of the paper). Let $(X_t)_{t\in [0,1]}$ be the Auffinger--Chen process
		\begin{equation*}
			\begin{cases}
				\mathrm{d} X_t=\xi''(t)\zeta([0,t])\partial_x \Phi_\zeta(t,X_t)\mathrm{d} t+\sqrt{\xi''(t)} \mathrm{d} B_t\\
				X_0=0.
			\end{cases}
		\end{equation*}
		For every $s\in [0,1]$, set
		\begin{equation*}
			H_\zeta(s):=\frac{1}{2}\int_s^1 \xi''(r)\Bigl(\mathbb{E}[(\partial_x\Phi_\zeta(r,X_r))^2]-r\Bigr)\mathrm{d} r.
		\end{equation*}
		Then, the following hold:
		\begin{enumerate}[label=(\roman*)]
			\item \begin{equation}
				-\mathbb{E}[\Phi_\zeta(q,X_q)]+\int_0^q t\xi''(t)\zeta([0,t])\mathrm{d} t +\frac{1}{2}\int_q^1 t\xi''(t)\zeta([0,t])\mathrm{d} t=-f,
			\end{equation}
			\item \begin{equation}
				\mathbb{E}[(\partial_x\Phi_\zeta(q,X_q))^2]=q,
			\end{equation}
			\item  \begin{equation}
				\mathrm{supp}(\zeta)\cap [q,1]\subset \underset{[q,1]}{\mathrm{arg\,min}}(H_\zeta).
			\end{equation}
		\end{enumerate}

[Lemma 3 (Evolution of the area and its push-forward) of arXiv:2609.00501, 'Uniqueness of Finite-Time Varifold Limits for the M\"obius-Invariant Willmore Flow'] Let $X_t:=\partial_tF_t$.  Then the induced area measure on the fixed
domain satisfies
\begin{equation}

 \partial_t\dd\mu_t
 =-\langle H_t,X_t\rangle\dd\mu_t
 =a_t^{-2}\langle H_t,G_t\rangle\dd\mu_t.
\end{equation}
Moreover, for every $\varphi\in C^1(\Sph^3)$,
\begin{equation}

 \begin{aligned}
 \frac{\dd}{\dd t}\int_{\Sph^3}\varphi\dd\lambda_t
 &=\int_\Sigma
 \left[
  \big\langle\nabla^{\Sph^3}\varphi(F_t),X_t\big\rangle
  -\varphi(F_t)\langle H_t,X_t\rangle
 \right]\dd\mu_t\\
 &=\int_\Sigma a_t^{-2}
 \left[
  -\big\langle\nabla^{\Sph^3}\varphi(F_t),G_t\big\rangle
  +\varphi(F_t)\langle H_t,G_t\rangle
 \right]\dd\mu_t.
 \end{aligned}
\end{equation}

