[Thm T th gau of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] There exist a deterministic constant $c_1\in(0,\infty)$
  and a deterministic function $c_2\colon (0,\infty)\to(0,\infty)$ such that,
  $\hat{P}_{\bm{\rho}}$-a.s., for all $t \in (0,\infty)$,
  \begin{equation}
    c_1
    \leq
    \sup_{s\in[0,t]}
    \varlimsup_{\delta\downarrow0}
    \frac{\mathcal{C}_t([s-\delta,s+\delta])}
    {\delta^{d_{\mathrm{ct}}}(\log(1/\delta))^{\hat{d}_{\mathrm{s}}^*/2}}
    \leq
    \varlimsup_{\delta\downarrow0}
    \sup_{s\in[0,t]}
    \frac{\mathcal{C}_t([s-\delta,s+\delta])}
    {\delta^{d_{\mathrm{ct}}}(\log(1/\delta))^{\hat{d}_{\mathrm{s}}^*/2}}
    \leq
    c_2(t).
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:basisconvolution of arXiv:2412.09145, 'Asymptotic expansions for normal deviations of random walks conditioned to stay positive'] There exist polynomials $P_{k,j,\ell}$ each of degree $k$ such that 
\begin{align}
&\sum_{k=2}^{n-1}
        \frac{z^m}{k^{j+1/2}(n-k)^{\ell+1/2}}
        e^{-\frac{z^2}{2 (n-k)}}
=
    {\rm sgn}(z)\sqrt{2\pi}
    e^{-\frac{z^2}{2n}}
    \frac{Q_{j,\ell,m}(z/\sqrt{n})}{n^{\ell+j-m/2}}
        \\
\nonumber   
&\hspace{1cm}+
    e^{-\frac{z^2}{2n}}
    \frac{z^m}{n^{\ell+1/2}}
    \sum_{k=0}^{\lceil \frac{r+m}{2}\rceil - \ell+1}
        \frac{P_{k,j,\ell}(z^2/n)}{n^{k}}
+
    O\left(\frac{1}{(\min(\sqrt{n},1+|z|))^{r+3}}\right),
\end{align}
where
\begin{align*}
    Q_{j,\ell,m}(t)
=
    t^m
    \sum_{q=0}^{j}
        \gamma_{q,j,\ell} t^{2q}
        \sum_{k=0}^{\ell+j+q-1}
            \frac{(2k-1)!!
            \binom{\ell+j+q-1}{k}}
            {t^{2k+1}}
\end{align*}
and the reals $\gamma_{q,j,\ell}$ can be computed recursively; the corresponding expressions are given in (equation eq:gammas of the paper) below. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 2 of arXiv:2605.10452, 'A secretary for Messrs. Luce and Mallows'] \begin{equation*}
\min(V_1,V_2,\cdots, V_r)\sim\text{\rm Exp}(\sum_{i=1}^r\theta_i),\ r\in\mathbb{N}.
\end{equation*}
\begin{proof}
$$
P(\min(V_1,V_2,\cdots, V_r)\ge x)=\prod_{i=1}^rP(V_i\ge x)=\prod_{i=1}^r e^{-\theta_ix}=e^{-(\sum_{i=1}^r\theta_i)x}.
$$
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 53 of arXiv:2608.05931, 'Effective Lagrangian regularity and the uniqueness threshold for random H\"older velocity '] For all $y \in \T^d$ and $h>0$,
    \[\P_U\big(\text{there exists more than one solution to~\eqref{eq:main refreshing ODE 0} on } [0,h]\big) = 1.\]
    Further, for all $y \in \T^d$ and almost surely in $U$, for all $\ep>0$ sufficiently small
    \begin{equation}
    \limsup_{t \to 0} t^{- \frac{1}{2-2\alpha - \beta - \ep}}\mathrm{diam}\{X_t : X \text{ is a solution to~\eqref{eq:main refreshing ODE 0}}\} =\infty.

    \end{equation}

[Thm 3.2 of arXiv:2608.00420, '{Weighted $L^p$ solutions of scalar BSDEs with general unbounded stochastic coefficients}\'] Let the generator $g$ satisfy assumption (A:H1 of the paper). Assume further that either $\mu_\cdot\in {\mathbb R}_+$ or (A:H1 of the paper)(iii) is replaced with the following stronger condition: $g$ has a general growth in $y$ and a stochastic linear growth in $z$, i.e., there exists a function $\phi_t(\omega,x)\in\mathbf{S}$ such that for each $(t,y,z)\in[0,\tau]\times{\mathbb R}\times{\mathbb R}^d$,
\begin{align}
|g(\omega,t,y,z)|\leq \phi_t(\omega,|y|)+\nu_t(\omega)|z|.
\end{align}
Then, for each $\xi\in L_\tau^p(\rho_\cdot;{\mathbb R})$, BSDE (equation BSDE1.1 of the paper) admits a solution $(y_t,z_t)_{t\in[0,\tau]}$ such that $y_\cdot\in S_\tau^p(\rho_\cdot;{\mathbb R})$. Furthermore, if the process $\rho_\cdot$ also satisfies
\begin{align}
\rho_t\geq \mu_t+\frac{\theta}{2[1\wedge(p-1)]}\nu_t^2, \ \ t\in[0,\tau],
\end{align}
then $z_\cdot\in M_\tau^p(\rho_\cdot;{\mathbb R}^{d})$.\vspace{0.1cm} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 26 (Isotropic sharpness) of arXiv:2608.10992, '2608.10992'] In the isotropic model,
\begin{equation}

        t_{\mathrm{sus}}^{\mathrm{iso}}
        =t_{\infty}^{\mathrm{iso}}
        =:t_c^{\mathrm{iso}}.
\end{equation}
Moreover,
\begin{equation}

        \frac13
        \leq t_c^{\mathrm{iso}}
        \leq t_c^{\mathrm{os}}
        \leq2\log2,
\end{equation}
and
\[
        \mathbb{P}(S_{t_c^{\mathrm{iso}}+s}=\infty)>0,
        \qquad s>0.
\]

[Theorem 8 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb$, $f\in \Sob^k(\Rbb^n,\gamma_n)$ with $\left\|f\right\|_{\Leb^\infty}\leq 1$, and $p\in [1,2)$,
\begin{equation}
    \left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p} \geq C^{\text{\rm\ref{thm:high-order-iso-Gaussian}}}(p)^k\Wop^{\geq k}(f) \left[1+ \frac{1}{2k}\ln\left(\frac{1}{\Wop^{\geq k}(f)}\right)\right]^\frac{kp}{2},
\end{equation}
and further,
\begin{equation}
    \max_{\kappa\in \Nbb^n:|\kappa|=k}\left\|\Dop^\kappa f\right\|_{\Leb^p}^{p} \geq C^{\text{\rm\ref{thm:high-order-iso-Gaussian}}}(p)^k\, \frac{\Wop^{\geq k}(f)}{\binom{n+k-1}{k}} \left[1+ \frac{1}{2k} \ln\left(\frac{\binom{n+k-1}{k}}{\Wop^{\geq k}(f)}\right)\right]^{\frac{kp}{2}},
\end{equation}
with $C^{\text{\rm\ref{thm:high-order-iso-Gaussian}}}(p) = C^{\text{\rm\ref{thm:high-order-Tal-isoper-Boolean}}}(p) \gtrsim 2-p$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 16 (Eigenvalue master equation — Wishart case) of arXiv:2511.12623, 'The eigenvector bead process'] Fix integers $N, T \ge 1$, and let $\{\lambda_i\}_{i=1}^{N}$ denote the (positive) eigenvalues of $X_{N}^{\!\top} X_{N}$.
Consider the rank-one extension
\[
X_{N+1} \;=\; \big( X_N \;\; g \big),
\qquad g \in \mathbb{R}^{T},
\]
that is, $X_{N+1}$ is obtained by appending the column vector $g$ to $X_N$.
Then the eigenvalues $z$ of $X_{N+1}^{\!\top} X_{N+1}$ are the zeros of the \emph{secular equation}
\begin{equation}
F_N(z)
\;=\;
1
+ \sum_{i=1}^{N}
\frac{|\langle v_i, g \rangle|^2}{\lambda_i - z}
- \frac{\Gamma}{z}
\;=\;0,
\end{equation}
where ${v_i}$ are the eigenvectors associated with the nonzero eigenvalues of $X_N X_N^{\top}$, and
\(
\Gamma
:= \sum_{j=1}^{T-N} |\langle w_j, g \rangle|^2,
\)
with $\{w_j\}$ forming an orthonormal basis of the null space of $X_{N} X_{N}^{\!\top}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 30 of arXiv:2606.23099, 'Path-dependent Affine Processes'] Let $T \in \R_{\geq 0}$.
    Assume that $\mu \in \ccM([0,T], \C^d)$, and
    $P_T \in L^1([0,T],\R_{\geq 0})$ such that
    \begin{equation}
        |p(t,s,0)| \leq P_T(s), \quad 0\leq t\leq s\leq T,
    \end{equation}
    and that there exists a positive constant $\Theta_T$ and a function $\Pi_T \in L^2([0,T], \R_{\geq 0})$ such that
    \begin{equation}
        |p(t,s,x)-p(t,s,y)| \leq \Pi_T(s)|x-y| + \Theta_T|x-y|(|x|+|y|), \quad x,y \in \C^d, 0 \leq t \leq s \leq T.
    \end{equation}
    Then the Riccati-type equation \eqref{eq:def-basline-existence} has a unique noncontinuable solution $(\psi, T_{\text{min}})$. If $\mu$ and $p$ are real-valued, then so is $\psi$.

