[Theorem 8 of arXiv:2608.13631, 'The classical discrete laws near the mode:\\ complete local expansions for the negative bi'] Under the hypotheses of Theorem~\ref{thm:hyp-main}, with $k=\mu+t$,
	\begin{equation}
		\log\Bigl[\sqrt{2\pi\,\frac{k\,(K-k)\,(n-k)\,(L+k)\,N}{K(N-K)\,n\,(N-n)}}\;P(k)\Bigr]
		\sim\sum_{m\ge1}\frac{\widehat A_m(t)}{N^{m}},
	\end{equation}
	with
	\begin{equation}
	\begin{gathered}
		\widehat A_m=\frac{(-1)^{m+1}}{m(m+1)}
		\Bigl[(W_m-1)\,B_{m+1}-\widehat\Xi_m\,\Bh_{m+1}(t)\Bigr],\\
		\widehat\Xi_m=(a^{-m}+d^{-m})
			+(-1)^{m+1}(b^{-m}+c^{-m}).
	\end{gathered}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 of arXiv:2609.01346, '2609.01346'] Let
\begin{equation}
 K_0\subset\{(x,r):x>0,\ r>0\}
\end{equation}
be a compact set of crossing data at $\theta=\pi/2$.  There is $u_0>0$ such
that every solution whose data at $u=0$ belong to $K_0$ is represented in the
$u$-chart on the full interval $[-u_0,u_0]$.  On a neighbourhood of the
corresponding incoming data, the map from the section $u=-u_0$ to the section
$u=u_0$, including the elapsed arclength, depends continuously on the
incoming data.

