[Lemma lem:lemma5.5 of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Set 
\begin{equation}
    \mathcal{D}_n:=U_{n_j}(\frac{H}{2})-V_{n_j}=\sum_{k\ge 1}\sum_{a\in \{2,3\}^k}\sum_{l_0+\ldots +l_k=n}V_{l_0}\underline{\Phi_{a_1}V_{l_1}}\cdots\underline{\Phi_{a_k}V_{l_k}}
\end{equation}
and
\begin{equation}
\widehat{\mathcal{D}}_n
:= \sum_{k \geq 1} 8^k
\sum_{\substack{
    l_0 + \cdots + l_k = n
}}
\widehat{V}_{l_0} \,
\widehat{\underline{\Phi_{2} V_{l_1}}} \cdots
\widehat{\underline{\Phi_{2} V_{l_k}}},
\end{equation} then for all $s\ge 1$, 
    \begin{equation}
        |\mathbb{E}\big[\prod_{j=1}^s \mathrm{Tr} ({\mathcal{D}}_{n_j})\big]|\le \mathbb{E}\big[\prod_{j=1}^s \mathrm{Tr}( \widehat{\mathcal{D}}_{n_j})\big]
    \end{equation}

[Lem of arXiv:2606.09228, 'On topological indices of random caterpillar graphs'] We have
    \begin{align*}
        \Cov\bigg(\sum_{i<j} (j-i+2)I_iI_j,&\sum_{k,\ell=1}^m \left(\vert \ell-k \vert +1\right)I_\ell\bigg)\\
        &=\frac{n(n-1)(m-1)(m-2)(m+1)(m+2)}{180m}.
    \end{align*}

[Proposition 40 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $(X, d, \mu)$ be a Polish probability space. Suppose that either of the following equivalent conditions holds (by Lemma~\ref{l:isop_to_enl} and Proposition~\ref{p:symmetric_isop_enlargement}):
\begin{enumerate}
    \item it has a continuous isoperimetric function $I$ such that \eqref{eq:sym_iso} holds and that $v\mapsto \frac{I(v)}{v}$ is non-increasing;
    \item it has $R_s^I(v) = \Psi\left(\Psi^{-1}(v) +  s\right)$ as an enlargement function, where the distribution function $\Psi$ defined in \eqref{eq:Psi_def} is log-concave and is such that \eqref{eq:Psi_reflexive} holds.
\end{enumerate}
Then, we have 
\begin{equation}

    \Theta^I(s)=\Psi\left(-\frac{s}{2}\right),
\end{equation}
where $\Theta^I$ is defined in \eqref{eq:theta_I_def}.

[Lem 14 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let $x\in\R^n$, $r>0$ and $\phi\in\text{\rm SCL}\,(B(x,r))$ with linear modulus $C_1>0$, and let $\psi:B(x,r)\to\R$ be a semiconvex function with linear modulus $C_2>0$. If $\psi$ touches $\phi$ from below at $x$ in $B(x,r)$, then we have the following properties:
	\begin{enumerate}[\rm (1)]
		\item both $\phi$ and $\psi$ are differentiable at $x$ and $D\psi(x)=D\phi(x)$.
		\item for $C=\max\{C_1,C_2\}$ we have that
		\begin{align*}
			|p-D\phi(x)|\leqslant 3C|y-x|,\qquad \forall y\in B(x,\frac r2), p\in D^+\phi(y);\\
			|p-D\psi(x)|\leqslant 3C|y-x|,\qquad \forall y\in B(x,\frac r2), p\in D^-\psi(y).
		\end{align*}
	\end{enumerate}

