[Proposition pro: Lp norm of q_infty of arXiv:2603.14163, '\LARGE \bf Tail Bounds for Queues with Abandonment: Constant, Moderate, Large Deviations, '] \textnormal{($L^p$ norm of queue length)} For SSQ, under assumption (ass:heavy_overload of the paper), the $L^p$ norm of the centered queue length is bounded in the below interval
    \begin{align}
        \| \hat{q} \|_{L^p} &\leq \min\{(C_{1,\lambda,\mu}\sqrt{\frac{1}{\gamma}} \sqrt{p} + C_{2,\lambda,\mu} p),  (C_{3,\lambda,\mu} \frac{p}{\log(1+\gamma p/\lambda)})\} \\
        \| \hat{q} \|_{L^p}&\geq C_{4,\lambda,\mu} \exp\left( -C_{5,\lambda,\mu} \frac{1}{ \gamma p} \right) \frac{p}{\log(1+\gamma p/\lambda)} 
    \end{align}
    All the above constants are only dependent on $\lambda, \mu, C$ and $\alpha$. Their closed forms are given in (equation eq: constants for L-p norm of the paper) (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 35 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Let $q \in (0,1)$, $c \in [0,1)$, $p = \frac{q}{1-q}$, $\sigma=\sqrt{p(1+p)}$, $k\in\mathbb{N}\cup\{\infty\}$, $\Sigma=\llbracket1,2k+2\rrbracket$, $\beta \in (0, \infty]$ and set $\Lambda=[0,\beta)$. Let $d_n\in(0,\infty)$, $T_n\in\mathbb{Z}_{\geq 0}$ be sequences that satisfy:
\begin{equation}
d_n\rightarrow\infty, \hspace{2mm} T_n/d_n\rightarrow\beta, \mbox{ as } n \rightarrow \infty.
\end{equation}
We further suppose that we have a sequence of $\Sigma$-indexed geometric line ensembles $\mathfrak{L}^n = \{L^n_i\}_{i \in \Sigma}$ on $\mathbb{Z}_{\geq 0}$ that satisfy the following conditions:
\begin{enumerate}
\item [$\bullet$] for each $t\in (0, \beta)$ and $i\in\llbracket 1, 2k\rrbracket$, the sequence of random variables $\sigma^{-1}d_n^{-1/2} (L_i^n(\lfloor td_n\rfloor)-ptd_n)$ is tight;
\item [$\bullet$] the restriction $\{L_i^n(s):i\in\Sigma \mbox{ and } s\in\llbracket0,T_n\rrbracket\}$ satisfies the interacting pair Gibbs property from Definition \ref{Def.IPGP}.
\end{enumerate}
Then, the sequence of line ensembles $\mathcal{L}^n=\{\mathcal{L}_i^n\}_{i=1}^{2k}\in C(\llbracket1,2k\rrbracket\times\Lambda)$, defined through $\mathcal{L}_i^n(t)=\sigma^{-1}d_n^{-1/2}(L_i^n(td_n)-ptd_n)$, is tight. Moreover, any subsequential limit satisfies the pinned half-space Brownian Gibbs property from Definition \ref{Def.PinnedBGP}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] We have that
	\begin{align*}
		\Pi \circ \Phi = \tilde{\Pi}, \qquad \Gamma \circ \Phi = \Phi \circ \tilde{\Gamma}.
	\end{align*}

	  Furthermore, if $(\Hb, \Hp, \tilde{\mcW})$ is a solution of the system \eqref{eq: tct_sys} on $\tilde{\mfT}$ with respect to the model $(\tilde{\Pi}, \tilde{\Gamma})$ a modelled distribution $\mcV_{\<0t>}$, and initial data $\psi_{\<bsq>} = \psi = \psi_{\<psq>}$ and $w_0 = 0$ then $(\Phi(\Hb), \Phi(\Hp), \Phi(\tilde{\mcW}))$ is a solution of the system of Lemma~\ref{lem: DPD_1} on $\mfT$ with respect to the model $(\Pi, \Gamma)$ and modelled distribution $\Phi(\mcV_{\<0t>})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:exact_values of arXiv:2603.27906, 'Marked GUE-corners process in doubly periodic dimer models'] Let~$\tau $ and~$\sigma^2$ be as above and set~$a_k=\alpha_k\beta_{k-1}^{-1}$ and~$b_k=\alpha_k^{-1}\beta_k$. Then
\begin{equation}
\tau =
\sum_{k=1}^\ell \frac{1+a_k+a_kb_k+a_kb_ka_{k+1}}
{(1+a_k)(1+b_k)(1+a_{k+1})}
\end{equation}
and
\begin{equation}
\sigma^2=
\sum_{k=1}^\ell \frac{(1+a_k+a_kb_k+a_kb_ka_{k+1})(b_k+a_{k+1}+b_ka_{k+1}+a_ka_{k+1})}
{(1+a_k)^2(1+b_k)^2(1+a_{k+1})^2}
\end{equation}
where~$a_{\ell+1}=a_1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Given any fixed integers  $s\ge 1$ and  $t_i\ge 1$ for $1\le i\le s$, $1\le j\le t_i$, if  $\|A\|\le \sqrt{\alpha}+O(N^{-\frac{1}{3}})$ with $ \epsilon\le \alpha\le 1$ for some fixed $\epsilon>0$, and
    \begin{equation}
        \theta t_N\ll n_{i,j}\le  \tau N^{\frac{1}{3}}
    \end{equation}
    for any fixed constant $\tau$  such that   $t_1n_1+\cdots+t_kn_k$ is even, then   
    \begin{equation}
        \mathbb{E}\Big[\prod_{i=1}^{s}\mathrm{Tr} \prod_{j=1}^{t_i} (\frac{1}{n_{i,j}}Q_{n_{i,j}}(\frac{X}{2}))\Big]=\mathbb{E}\Big[\prod_{i=1}^{s}\mathrm{Tr} \prod_{j=1}^{t_i}(\frac{1}{n_{i,j}}Q_{n_{i,j}}(\frac{\widetilde{X}}{2}))\Big]+o(1).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 14 of arXiv:2606.21111, 'On Elephant Random Walk with Delayed Amnesia'] Let $0\le p<(4a-1)/4a$. Then,
{\small\begin{equation*}
\lim_{n\to \infty}\frac{1}{\log n}\sum_{k=1}^{n}\frac{S_k^2}{k^2}=\frac{1}{(2a(1-p)-1)^2}\Big(\frac{(a(2p-1))^2}{4a(1-p)-1}+\frac{(1-2p)(a-1)}{1-p}+(a-1)^2\Big)\ \ \text{a.s.}
\end{equation*}}

