[Proposition 3 of arXiv:2605.03902, 'Bundles of Probability Schemes'] The outer rectangle obtained by pasting two fiber products of bundles
  as shown
  \begin{equation}
    \begin{split}
  \xymatrix{
    \Omega_3 \otimes_{\Omega_2} (\Omega_2 \otimes_{\Omega_0}\Omega_1)
      \ar[r] \ar[d] & \Omega_2 \otimes_{\Omega_0} \Omega_1 \ar[r] \ar[d]
      & \Omega_1 \ar[d]^{\alpha} \\ \Omega_3 \ar[r]_{\gamma} & \Omega_2
      \ar[r]_{\beta} & \Omega_0
  }
\end{split}
 \end{equation}
 is isomorphic to the fiber product of the bundles $\alpha$ and $\delta =
 \beta\gamma$.

[Lemma 18 of arXiv:2605.20115, 'Moment bounds on correctors for the degenerate random conductance model'] Let $f:\ZZ^d\to\RR$. Then for all $R\ge 1$,
    \begin{equation}
        \left(\fint_{B_R}\Big|f-\fint_{B_R }f\Big|^{q}\right)^\frac1q\,\lesssim_{p}\, R\left(\fint_{ B_{R}}|\nabla f|^{p}\right)^\frac1p
    \end{equation}
    provided that $\frac1p\le\frac1q+\frac1d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

The cohomological Bousfield class of an object $E \in \mathcal{T}$, denoted $\langle E \rangle^*$, is the class of all objects $X \in \mathcal{T}$ such that $\underline{\operatorname{Hom}}(X, E) \neq 0$, where $\underline{\operatorname{Hom}}$ is the internal function object in $\mathcal{T}$.
\mathcal{T} is a closed symmetric monoidal triangulated category
E \in \mathcal{T}

[Definition def:dynamics-coupling of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] [Grand coupling of dynamics] For each vertex $v$ in $\mathbb Z^d$, assign an independent intensity-$1$ Poisson process process on $(0,\infty)$, denoted $\mathcal T_v = (t_{v,1}<t_{v,2}<...)$ and to each point $t\in \bigcup_i \{t_{v,i}\}$ assign a $\text{Unif}[0,1]$ random variable $\mathcal U_{v,t}$. For every finite $\Lambda \subset \mathbb Z^d$, boundary conditions $\eta \in \{\pm 1\}^{\Lambda^c}$ and inital configuration $x_0\in \{\pm 1\}^\Lambda$, generate the Glauber dynamics $(X_t)_{t\ge 0} = (X_{\Lambda^\eta,t}^{x_0})_{t\ge 0}$ on $\Lambda$ with boundary conditions $\eta$ initialized from $x_0$ as follows: let $t_1<t_2<...<t_{k(t)}<t$ be the ordered points of $\bigcup_{v \in \Lambda} \mathcal T_v$ at times before $t$, 
    \begin{itemize}
        \item for $s\in [0,t_1)$, let $X_s = x_0$; 
        \item iteratively, for $i = 1,...,k(t)$, for $s\in [t_i,t_{i+1})$, if $t_i\in \mathcal T_v$, let 
        \begin{align*}
            X_s(w) & = X_{t_i^-}(w) \qquad w\ne v\\ 
            X_s(v) & = \begin{cases}+1  & \text{ if }\quad  \mathcal U_{v,t_i}\le \pi_{\Lambda}^{\eta}(\sigma_v = +1 \mid (\sigma_w)_{w\ne v} = (X_{t_i^-}(w))_{w\ne v}) \\ -1 & \text{ else}
            \end{cases}
        \end{align*}
    \end{itemize}

Let N take values in {0, ..., m}, 1 <= k <= m and Y = (N - k + 1)_+. Put A_k = sum_{j=k}^m P(N >= j) and B_k = sum_{j=k}^m (2j - 2k + 1) P(N >= j). Then A_k = E[Y] and B_k = E[Y^2], and if A_k > 0, P(N >= k) >= A_k^2/B_k. If moreover mu = E[N] > k - 1, then A_k^2/B_k >= (mu - k + 1)^2/E[N^2], the bound from applying the second-moment threshold argument to N itself; the two agree for k = 1, and for k >= 2 the first is strictly larger.
N takes values in {0, ..., m}
1 <= k <= m

[Lemma 10 of arXiv:2607.11608, '2607.11608'] Let $k\in \N$. Then, we have 
\begin{align*}
\|X\|_{L^{p}(\Omega)}\le (p-1)^{\frac{k}{2}}\|X\|_{L^{2}(\Omega)},
\end{align*}
for any $p\ge 2$ and $X\in \mathcal{H}_{\le k}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Gonzalez and Qing \cite{GonzQing} of arXiv:2609.00324, 'Quantitative Stability for Fractional Yamabe minimizers'] Let $\gamma \in (0,1)$ and $a= 1-2\gamma$. There exists a constant $\bar{S} (n,\gamma)$ such that, for every $U\in \dot{W}^{1,2}(\mathbb{R}_{+}^{n+1}, y^a )$ with trace $TU =w$, the following inequality holds
    \begin{align*}
        \|w \|_{L^{2^{*}}(\mathbb{R}^n )}^2 \leq \bar{S}(n,\gamma) \int_{\mathbb{R}_{+}^{n+1}} y^a |\nabla U|^2 dxdy \, ,
    \end{align*}
    where $\bar{S}(n,\gamma) = d_\gamma^* S(n,\gamma)$. Equality holds if and only if
    \begin{align*}
        w(x) = c \left(\frac{\mu}{\mu^2 + |x-x_0 |^2}\right)^{\frac{n-2\gamma}{2}} \quad x \in \mathbb{R}^n,
    \end{align*}
    for $c \in \mathbb{R}$, $\mu >0$ and $x_0 \in \mathbb{R}^n$, and $U$ is the Poisson extension of $w$ given by the convolution with the Poisson kernel. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 26 (\textsf{Uniform small-diagonal estimate}) of arXiv:2609.02064, 'Coalescence and fluctuations of O'Connell--Yor polymers\\ via the free-energy correlation '] Fix $\wt x\in\R$ and a compact set
  $K\Subset\R\setminus\{\wt x\}$.  With
  $\ga_0=\wt\ga_0=0$, if $(i,j)\neq(0,0)$, then
  \begin{align}
    \lim_{\eta\downarrow0}\ 
    \sup_{\substack{u\in K\\0\leq\eps\leq\eps_K}}
    &(Q_{\wt x}^\eps\otimes Q_u^\eps)
    \bigl(
      |\wt x+\wt\ga_i-u-\ga_j|\leq\eta
    \bigr)=0.
  \end{align}
  Here $\eps_K>0$ is sufficiently small.  Also, for every compact
  $K\subset\R$ and $j\in\{1,\dots,n\}$,
  \begin{align}
    \lim_{\eta\downarrow0}\ 
    \sup_{\substack{u\in K\\0\leq\eps\leq\eps_K}}
    Q_u^\eps\bigl(|u+\ga_j|\leq\eta\bigr)=0.
  \end{align}

[Proposition Cesaro average upper bound of arXiv:2606.01683, 'Singular-value gap of nonreversible Markov processes'] Let $V \subset  L^2_0 (\mu)$ be a subspace such that $U = L(V \cap \operatorname{Dom}(L)) \subset L^2_0 (\mu)$.
Assume that the local gap defined in (equation gap definition subspace of the paper) satisfies $\gamma_V > 0$. Then
\begin{align*}
    \delta_t^U \leq \frac{2}{t \mkern1mu \gamma_V}.
\end{align*}

