    \[\tau_{n+1}=\inf\{t\geq \tau_n:\;\norm{X_{n}(t)-\Lambda(X_{n})(t)}\geq \epsilon\},\]
    and
    \begin{equation}
    X_{n+1}(t)=
    \begin{cases*}
      X_n(t) & if $t<\tau_{n+1}$, \\
