[Lemma lem:R<p/q of arXiv:2607.14062, 'Gilbert's disc model conditioned on the square lattice'] Let $a,b\in \mathbb{Z}_{>0} = \{1,2,\dots\}$, let $R \in (0, a/b)$, and let $u_0,\ldots,u_n\in\mathbb{Z}^2$. If there exists $P\in\mathcal P$ such that $u=(u_0,\ldots,u_n)$ is a path of $\Gamma_{p,R}^{\texttt{CN}}(P)$ (resp.\ of $\Gamma^{\texttt{NN}}_{p,R}(P)$), then 
    \begin{equation}
    \forall k\in \{0,\ldots, n-b\}, \quad \|u_{k+b}-u_k\|_\infty \leq a.
    \end{equation}

[Proposition 22 of arXiv:2609.03512, ''] Let $g(G)=3$ and $r(G)=5$. Then $\gamma(G)=\gamma_t(G)=2$ if and only if $G$ belongs to one of the following classes:
\begin{enumerate}
\item $G\in\mathcal{M}\bigl(D_2,D_5,D_6,D_8,D_9,D_{11},D_{12},D_{13},D_{14},D_{16},D_{17},D_{19}\bigr)$; or
\item $G\in\mathcal{M}\bigl(D_{10},D_{15},D_{18},D_{20},D_{21},D_{22},D_{24}\bigr)$, with $m_i\geq 2$ for at least one index $i$ corresponding to a dominating vertex $v_i$ of the base graph.
\end{enumerate}

[Lemma 32 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] Let $a\in[1/2,1]$. Then for all $r\in[0,1]$,
\begin{equation*}
    \Beta\left(\frac{r}{1+r};a,a\right)\le \frac{r^a}{a}.
\end{equation*}

