[Lemma lem:eigen-laplacian-detailed of arXiv:2609.00556, 'Higgs--Demailly System and Positivity of Higgs Bundles'] On $W$,
\begin{align}
 \Delta_\omega^{\mathbb C}\ell_a={}&-
 \left(\sqrt{-1}\Lambda_\omega
 \bar\partial(g^{-1}\partial^{h_{\rm ref}}g)\right)^a_a\\
 &+\sum_b(e^{\ell_a-\ell_b}-1)C_{ab}
 -\sum_b(e^{\ell_b-\ell_a}-1)C_{ba}.\notag
\end{align}

[Cor sufficient-inequalities-new of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Let $({\mathbf{a}},{\mathbf{b}})$ be a $(d,0)$-non-degenerate weight pair with $d\geq 1$ and assume that $r=r_{d,0}({\mathbf{a}})$ is finite.
	Assume that the following inequalities hold for all $n\geq 0$, all $q\leq q'$ in $\{0,\dots,r-1\}$, and all $s \leq s'$ in $\{0,\dots,d-1\}$,
	\begin{equation}
	\frac{b_{nd+1}}{b_{(n-1)d+1}}
	\leq
	\frac{
		\PFComp{\shift{q' d+s'}{\mathbf{a}},{\mathbf{b}}}{nd+(d-s')}
	}{
		\PFComp{\shift{q' d+s'}{\mathbf{a}},{\mathbf{b}}}{(n-1)d+(d-s')}}
	\leq
	\frac{
		\PFComp{\shift{q d+s}{\mathbf{a}},{\mathbf{b}}}{nd+(d-s)}
	}{
		\PFComp{\shift{q d+s}{\mathbf{a}},{\mathbf{b}}}{(n-1)d+(d-s)}}
	\leq
	\frac{b_{(n+1)d+1}}{b_{nd+1}},
	\end{equation}
	where we omit the ill-defined inequality on the left when $n=0$.
	Then $({\mathbf{a}},{\mathbf{b}})$ is $(d,0)$-admissible, and $(\shift{qd+s}{\mathbf{a}},{\mathbf{b}})$ is $(d,\overline{d-s})$-admissible for every $s\in\{0,\dots,d-1\}$ and $q\in\{0,\dots,r-1\}$.

[Theorem 4 (Letwin--Yaskin) of arXiv:2607.23980, 'Sharp small-deviation inequalities for sums of independent\\nonnegative random variables'] Let $K\subseteq \mathbb{R}^n$ be a convex body with centroid at the origin. Then for $\alpha\in (-1,\frac{1}{n})$, every non-zero vector $\xi\in \mathbb{R}^n$, and the closed halfspace
\begin{align*}
H_{\alpha,\xi} := \left\{x\in \mathbb{R}^n: \langle x,\xi \rangle \ge \alpha h_K(-\xi)\right\}, 
\end{align*}
where $h_K(t)=\sup_{x\in K}\langle x,t\rangle$ is the support function of $K$, it holds that
\begin{align*}
\frac{\vol_n(K\cap H_{\alpha,\xi})}{\vol_n(K)} \ge \begin{cases}
    (\frac{n-\alpha}{n+1})^n &\text{if }-1<\alpha\le 0, \\
    (\frac{n}{n+1})^n(\alpha+1)^{n-1}(1-\alpha n) &\text{if } 0<\alpha<\frac{1}{n}.
\end{cases}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:v of arXiv:2606.10257, 'Downward conditional monotonicity gives survival and extinction for contact processes in r'] For an MMPP (with some assumed initial distribution $B_0\sim x$), the \emph{equilibrium no arrival distribution}, when it exists, is defined by
	\begin{equation*}
		v^*\coloneq\lim_{t\to\infty} \mathcal{L}(B_t \mid X_s=0 ~\forall  s\in[0,t]).
	\end{equation*}

[Prop geographic ineq coupling map of arXiv:2604.21663, 'Large deviations for non-irreducible Markov chains on Euclidean spaces'] Let $\underline u=(u^1,\ldots ,u ^N)\in \widetilde{\mathcal{W}}_n^N$ be such that $\underline u^i:=F_n(u^i)\neq(e,\ldots,e)$ for all $i$, and $\underline v= (\underline u^1,\ldots, \underline u^N)$. Then, for all $w\in \Psi_{N,n, T}(\underline u)$, we have
	\begin{equation}

		d_{\mathrm{LP}}(L[\underline u],L[w])\leqslant \frac 1N\sum_{i=1}^N\Big(h\Big(\frac{N|\underline u^i|}{|\underline v|}\Big)+h\Big(\frac{|\underline u^i|}{n}\Big)\Big)+ 2h\Big(\frac{|\underline v|}{T}\Big).
	\end{equation}

