body:
[Corollary 16 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] Let $T = \E X >0$ and $X \sim f \dd \pi_{T}.$  
     \begin{enumerate}
         \item If $f : \N \rightarrow [0, \infty),$ then
         \begin{displaymath}
             H \Big( \sum_{i=1}^{n} T_{1/n}(X_{i}) |\pi_{T} \Big) \le \frac{I(X | \pi_{T})}{n}
         \end{displaymath}
         \item and if $f : \N \rightarrow (0,\infty) $ is ultra log-concave, then 
         \begin{displaymath}
             H \Big( \sum_{i=1}^{n} T_{1/n}(X_{i}) |\pi_{T} \Big) \le 
         \frac{1}{n} \Big( I(X | \pi_{T}) - T^{2} C^{2} \Big) + \frac{1}{n^{2}} T^{2} C^{2}
         \end{displaymath}
         where $C = \frac{f(0)}{f(1) + f(0)}.$
     \end{enumerate}

[Corollary 32 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Fix $m\in \N$ and a measurable, non-increasing function $\Omega:\R_+\to\R_+$. Let $f_1,\dots,f_{m+1}:\R^n\to\R_+$ be measurable, even functions that satisfy
    $$\left(\prod_{i=1}^{m}f_i(a_i)\right)\cdot f_{m+1}(v) \leq \Omega^{m+1}\left(\sum_{i=1}^m\langle a_i,v\rangle_+\right) \quad \text{for all } a_1,\dots,a_m,v\in \R^n.$$ 
    Then, we have
    \begin{equation}
  \begin{split}
    &\prod_{i=1}^m\left(\int_{\R^n}f_i(x)dx\right)\Bigg(\int_{\R^n} f_{m+1}(v)^\frac{1}{m}dv\Bigg)^m
    \\
    &\leq \left(\int_{\R^n}\cdots\int_{\R^n}\Omega\left(\left(\max_{|\xi| \leq 1} \sum_{i=1}^m \langle a_i, \xi \rangle_+\right)^{m+1}\right)da_1\cdots da_m\right)\left(\int_{\R^n}\Omega\left(|v|^\frac{m+1}{m}\right)dv\right)^{m}.
\end{split}
    \end{equation}
    When $\Omega$ is log-concave and integrable over $\R_+$, there is equality when there exists $C>0$ such that $$\prod_{i=1}^mf_i(a_i) = C\cdot \Omega\left(\left(\max_{|\xi| \leq 1} \sum_{i=1}^m \langle a_i, \xi \rangle_+\right)^{m+1}\right) \text{ and }f_{m+1} = \frac{1}{C} \cdot \Omega\left( |\cdot|^{\frac{m+1}{m}}\right)^m.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 2 of arXiv:2606.04950, 'The Tricomi equation in the hyperbolic half plane under additive space-time Gaussian White'] For any $t>0$ the stochastic process $\{U(t,x)\}_{x\in\mathbb{R}}$ is second order stationary with expectation
\begin{align*}
\mathbb{E}[U(t,x)]=0\quad\mbox{ for all }x\in\mathbb{R}
\end{align*}
and covariance
\begin{align}
\mathtt{cov}(U(t,x),U(t,y))=\frac{1}{2\pi^2}\int_0^{+\infty}\cos(\rho |x-y|)\int_0^t|C(t,s,\rho)|^2dsd\rho\quad\mbox{ for all }x,y\in\mathbb{R}.
\end{align}
Moreover, the correlation function
\begin{align*}
r_t(h):=\frac{\mathtt{cov}(U(t,x+h),U(t,x))}{\mathbb{V}[U(t,x)]},\quad t>0,x,h\in\mathbb{R},
\end{align*}
verifies
\begin{align*}
r_t(h)=1-\alpha_t|h|+o(|h|)\mbox{ as $|h|$ tends to zero},
\end{align*}
with
\begin{align*}
\alpha_t:=\frac{\pi}{2\int_0^{+\infty}\int_0^{t}\left|C(t,s,\rho)\right|^2ds d\rho}.
\end{align*}
In particular, the stochastic process $\{U(t,x)\}_{x\in\mathbb{R}}$ admits a continuous modification. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 18 of arXiv:2604.00882, 'On some extensions of generalized counting processes'] The probabilities ${\tilde p}_n^{\alpha,\rho}(t)$
satisfy the following  equation
\begin{equation}
	\left({\mathcal D}^{2\alpha,\rho}_t + {\mathcal D}^{\alpha,\rho}_t\right) \tilde p_k^{\alpha,\rho}(t) = - \Lambda \tilde p_n^{\alpha,\rho}(t) + \sum_{j=1}^{\min\{n,k\}}\lambda_j \tilde p_{n-j}^{\alpha,\rho}(t), \, n\geq0, 
\end{equation}
with the standard initial condition,
and  the corresponding probability generating function $
	\tilde{G}_{\alpha,\rho}(u, t)$, $|u| \leq 1$, solves the equation
	\begin{equation*}
		\left({\mathcal D}^{2\alpha,\rho}_t + {\mathcal D}^{\alpha,\rho}_t\right)  \tilde G_{\alpha,\rho}(u, t) = -\sum_{j=1}^{k}\lambda_j(1-u^j)\tilde G_{\alpha,\rho}(u, t), 
	\end{equation*}
	with $\tilde G_{\alpha,\rho}(u, 0) = 1$; 
  the generalized fractional derivatives in the C-D sense are defined in \eqref{exfDt}.

[Lem A.1 of arXiv:2412.03370, 'TASEP with a general initial condition and a deterministically moving wall'] As claimed in the proof of Lemma~(lem:6.3 of the paper), 
	\begin{equation} \begin{aligned} 
	\mathbb{P}\left(\exists k \in I_\varkappa, |k| \leq \varkappa T^{2/3+\iota}: \ x_{d^{-2}T-k}(T) \leq \left(1-2\sqrt{d^{-2}-kT^{-1}}\right)T -\tfrac{d^3 k^2}{4(1+\sqrt{\alpha}d)^2} T^{-1}\right)
	\end{aligned} \end{equation} 
	can be bounded by $C e^{-c\varkappa}$ for all $T$ and $\varkappa$ large enough.

