[Theorem thm:7 of arXiv:2510.13572, 'Coalescence in Markov chains'] {ncftp}}]
Let $S$ be a non-empty, finite set, let $P\in\mathcal{P}_S$, and let $\mathcal S = \{S_r: r\in I\}$  be  a partition of $S$
with index set
$I=\{1,2,\dots,\ell\}$. 
For $i\in S_r$, let
\begin{equation}
\lambda_{r,s}^{(i)}= \sum_{j \in S_s} p_{i,j}.
\end{equation}
If there exists an $\mathcal S$-block measure $\mu\in \mathcal L_P$, then
\begin{letlist}
\item
for $r,s\in I$, 
\begin{equation}
\text{$\lambda_{r,s} := \lambda_{r,s}^{(i)}$ is constant for $i\in S_r$},
\end{equation}

\item
the \lq block-transition matrix'  $\Lambda=(\lambda_{r,s}: 1\le r,s\le \ell)$ is irreducible. Moreover, 
\begin{equation}
\text{$\Lambda$ is doubly stochastic,}
\end{equation}
which may be expressed as
\begin{equation}
\sum_{i\in S}\sum_{j \in S_s} \frac1{|S_{r(i)}|}p_{i,j}=1, \qquad r,s\in I,
\end{equation} 
where $r(i)$ is the index $r\in I$ such that $i \in S_r$.
\end{letlist} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Random Walk of arXiv:2606.14895, 'Effective Resistances and Commute Times in Sparse Random Geometric Graphs'] A random sequence $X_1, ..., X_k$ of vertices in $G$ is a random walk if independently for all $i \in [k-1]$:
\begin{equation*}
    \Pr\left(X_{i+1} = v \mid X_i = u\right) = 
    \begin{cases} 
        \frac{w_{(u,v)}}{\deg(u)} & \text{if } (u,v) \in E\,, \\
        0 & \text{otherwise}.
    \end{cases}
\end{equation*}
Furthermore, let $\mathbf{W} = \mathbf{A}\mathbf{D}^{-1}$ so that 
$\mathbf{W}_{vu} = \Pr\left(X_{i+1} = v \mid X_i = u\right)$. Then
$\mathbf{W}\vec{\mathbf{1}}_u$ is the distribution of vertex locations after one step of a random walk starting from $u$.

[Theorem thm:global_clt of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] As in (equation eq:sigmadef_global_intro of the paper), set
\begin{equation}

    \sigma_n^2 = 
    \mleft( 1 - 2 p (1-p) \sum_{j=1}^K \beta_j \mathsf{e}_j (\mathsf{e}_j-1) p^{\mathsf{e}_j-2} \mright)^{-1}
    \times p(1-p) \binom{n}{2},
\end{equation}
Then for any $\varepsilon > 0$, if $X$ is distributed as (equation eq:tilt of the paper) with $Y \sim \mathcal{G}(n,p)$ and $\mathsf{g}$ given in
(equation eq:smallgdef of the paper), under the ``phase-uniqueness or forest'' assumption, we have
\begin{equation}
    \mathbf{d} \mleft( \frac{\mathsf{E}(X) - \mathbb{E}[\mathsf{E}(X)]}{\sigma_n}, Z \mright) \lesssim n^{-\frac{1}{2} + \varepsilon},
\end{equation}
for both $\mathbf{d} = \mathbf{d}_\mathrm{Was}$ and $\mathbf{d} = \mathbf{d}_\mathrm{Kol}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary coro_2 of arXiv:2412.03774, '{ Refining Concentration for \\Gaussian Quadratic Chaos with\\ Applications in Sonar and C'] For a symmetric matrix $A$, 
\begin{eqnarray}

\Pr(\boldsymbol{\Delta}>t)\leq \liminf_{m\to\infty}\inf_{0<b<1}e^{\Lambda_m(t,b)}\leq \Big(1+\frac{t}{r(A)\|A\|}\Big)^{\frac{r(A)}{2}}e^{-\frac{t}{2\|A\|}}.
\end{eqnarray}

[Definition 1 of arXiv:2606.17381, 'Large deviation principle for friendship-biases\\ in Galton--Watson trees'] {\bf [Vertex types]}
$\mbox{}$
\begin{itemize}
\item[{\rm (a)}] 
{\rm A vertex $u \in V(\Tt_\infty)$ is called a \textit{branching point} if $X_u = 2$.}
\item[{\rm (b)}] 
{\rm A vertex $u \in V(\Tt_\infty) \setminus \{\phi\}$ with $d_u = 2$ is called a \textit{linear point} if its parent is not a branching point, and a \textit{branching-linear point} if its parent is a branching point.}
\item[{\rm (c)}] 
{\rm A \emph{linear piece} from a vertex $v$ is the maximal path
\[
v = v_0 \to v_1 \to \cdots \to v_{\ell(v)} = \tau(v),
\]
where the terminal vertex $\tau(v)$ is the first branching point on the path, i.e. $X_{\tau(v)} = 2$. The random integer $\ell(v)\in\mathbb N_0$ is called the \emph{length} of the linear piece from $v$.}
\end{itemize}

