body:
[Definition ParScale of arXiv:2410.23899, 'Tightness for interlacing geometric random walk bridges'] We assume that $c^+$, $\{a_i^+\}_{ i \geq 1}$, $\{b_i^+\}_{ i \geq 1}$ are non-negative reals such that
\begin{equation}
\sum_{i = 1}^{\infty} (a_i^+ + b_i^+ ) < \infty \mbox{ and } a_{i}^{+} \geq a_{i+1}^{+},  b_{i}^{+} \geq b_{i+1}^{+} \mbox{ for all } i \geq 1.
\end{equation}
We let $J_a^{+} = \inf \{ k \geq 1: a_{k}^{+} = 0\} - 1$ and $J_b^{-} = \inf \{ k \geq 1: b_{k}^{-} = 0\} - 1$. In words, $J_a^{+}$ is the largest index $k$ such that $a_{k}^{+} > 0$, with the convention that $J_a^{+} = 0$ if all $a_k^{+} = 0$ and $J_a^{+} = \infty$ if all $a_k^{+} > 0$, and analogously for $J_b^{+}$. We fix $q \in (0,1)$ and set
\begin{equation}
\sigma_q = \frac{q^{1/3} (1 + q)^{1/3}}{1- q} \mbox{ and } f_q = \frac{q^{1/3}}{2 (1 + q)^{2/3}}.
\end{equation}
For $N \in \mathbb{N}$ increasing to infinity, we consider three numbers $A_N, B_N, C_N^{+}$ and sequences $\{x^N_i \}_{ i\geq 1}$ and $\{y^N_i\}_{i \geq 1}$ such that
\begin{equation}
\begin{split}
&x_i^N =1 - \frac{1}{N^{1/3} b_i^+ \sigma_q } \mbox{ for $i = 1, \dots, B_N$, and } y_i^N =1 -\frac{1}{N^{1/3} a_i^+ \sigma_q } \mbox{ for $i = 1, \dots, A_N$},
\end{split}
\end{equation}
where $B_N \leq \min\left(\lfloor N^{1/12} \rfloor, J_b^+ \right)$ is the largest integer such that $x^N_{B_N} \geq q$, and $A_N \leq \min\left(\lfloor N^{1/12} \rfloor, J_a^+ \right)$ is the largest integer such that $y^N_{A_N} \geq q$. Here, we use the convention $x_0^N = y_0^N = 1$ so that $A_N =0$ and $B_N = 0$ are possible. We also have
\begin{equation}
\begin{split}
x_{B_N + i }^N = y_{A_N + i}^N =1 - \frac{2}{N^{1/4}c^+ \sigma_q} \mbox{ for } i = 1 ,\dots, C_N^+ \mbox{, where } C^+_N =  \begin{cases} 0 &\mbox{ if $c^+ = 0$, } \\  \lfloor N^{1/12} \rfloor  &\mbox{ if } c^+ > 0 \end{cases}, 
\end{split}
\end{equation}
 and 
\begin{equation}
\begin{split}
\mbox{ $x_i^N = q$ for $i > B_N + C_N^+ $ and $y_i^N = q$ for $i > A_N + C_N^+ $.}
\end{split}
\end{equation}
We let $N_0 \in \mathbb{N}$ be sufficiently large (depending on $q, c^+$) so that $x_i^N, y_i^N \geq q$ for all $i \in \mathbb{N}$, provided that $N \geq N_0$. Note that if $N \geq N_0$ and $M \geq 1$ we can define the ascending Schur process in ((S61E2 of the paper)) with parameters $N, M, \{x_i^N\}_{i = 1}^M$ and $\{y_i^N\}_{ i = 1}^N$ as above, since $x^N_i, y_i^N \in [q, 1)$ for all $i \in \mathbb{N}$.

[Proposition 5 of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] With $(m_i)$'s fixed as in \eqref{e.m_i=}, the map 
\begin{equation}  

\Ll\{
\begin{array}{rcl}  \{(q_i) \,:\, 0<q_0<q_1<\cdots<q_k\} & \to  & \R \\
(q_i) & \mapsto & \psi_\circ(q) = \psi_\circ \Ll( \sum_{i = 0}^k q_i \1_{[m_i, m_{i+1})} \Rr)
\end{array}
\Rr.
\end{equation}
is convex. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 11 of arXiv:2606.31596, 'The Invariant Measure of Multiscale Markov Chains via Fast Arborescence Factorization'] The limiting measure \eqref{laformula} in Theorem \ref{ilteo} is the unique solution $\pi=\bar\pi^{(0)}$ of the recursion \eqref{laformulaiti}. It can be computed as:
\begin{equation}
\begin{split}
	&\bar{\pi}^{(0)}\big(M^{(0)}\big) =\\ &=\begin{cases}
		\;\prod_{\left(M^{(i)},M^{(i-1)}\right)\,\in\,\gamma_{M^{(0)}}} \,\mu^{(i-1)}_{M^{(i)}}\left(M^{(i-1)}\right) & \textrm{if }\, M^{(0)}\in \textup{Su}\left(M^{(k)}\right)\\[4pt]
		\;0 & \textrm{if }\, M^{(0)}\notin \textup{Su}\left(M^{(k)}\right)
	\end{cases}
\end{split}
\end{equation}
for all $M^{(0)}=x\in V=\mathcal M^{(0)}\,$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 22 of arXiv:2605.15501, 'Well-posedness of the obstacle problem for generalized Dean--Kawasaki equation\thanks{ The'] Let Assumption \ref{assu:assum for F} and Assumption \ref{assu:assu for unique} hold for $\xi^F, \psi, u_{\text{init}},\Phi,\sigma$.
Suppose that the pair $(u,\nu)$ fulfills all items in Definition \ref{def:def of stochastic kinetic solution} except the initial condition (iii), and satisfies the following preservation of energy for all $\phi\in C_c^\infty([0,T))$:
\begin{align}
&-\mathbb{E}\int_0^T\int_{\mathbb{T}^d}u^2(x,s)\partial_s\phi(s)\mathrm{d}x\mathrm{d}s+2\mathbb{E}\int_0^T\int_{\mathbb{T}^d}\phi(s)\psi(x,s)\mathrm{d}\nu(x,s)\\
&\ +2\mathbb{E}\int_0^T\phi(s)\mathrm{d}q(\mathbb{T}^d,[0,\infty),s)+\frac{1}{2}\mathbb{E}\int_{0}^{T}\int_{\mathbb{T}^d}\phi(t)\sigma^2(u)(\nabla_{x}\cdot F_{2}-2F_3)\mathrm{d}x\mathrm{d}s\nonumber\\
&=\mathbb{E}\int_{\mathbb{T}^d}u^2_{\mathrm{init}}(x)\phi(0)\mathrm{d}x.\nonumber
\end{align}
Then, we have almost surely
\begin{align}
\lim_{\tau\to0}\frac{1}{\tau}\int_0^{\tau}\int_{x}|u(x,t)-u_{\mathrm{init}}(x)|^2\mathrm{d}t=0,
\end{align}
which can be viewed as a strong trace result with respect to the initial data.

