body:
[Lemma lem:delmeyer of arXiv:2411.16366, 'Connections between sequential Bayesian inference and evolutionary dynamics'] \textbf{Exponential moment bounds.}  Let $Y_s$ for $s \in [0,t]$ denote a non-decreasing scalar-valued adapted process such that $\mathbb{E}[Y_t - Y_s|\mathcal{F}_s] \leq K$ for all $s \in [0,t]$.  Then for any $L < \frac{1}{K}$, 
\begin{align*}
\mathbb{E}[\exp \left( L Y_t \right)] < \frac{1}{1 - LK}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemme continuityphi of arXiv:2603.21634, 'Individual-based stochastic model with unbounded growth, birth and death rates: a tightnes'] Let $t \in [0,T]$, $\varphi \in \mathcal{C}_{\varpi+\omega}([0,T] \times \mathbb{R}^{*}_{+})$ and $\phi$ continuous on $[0,R_{\max}]$, then
\begin{align*}
\sup_{t \in [0,T]} | \langle \mu^{K}_{t} - \mu^{*}_{t}, \varphi_{s} \rangle | \xrightarrow[K \longrightarrow + \infty]{}  0,
\end{align*}
and
\begin{align*}
\displaystyle{\int_{0}^{t}} \phi(R^{K}_{s}) \langle \mu^{K}_{s}, \varphi_{s} \rangle \mathrm{d}s \xrightarrow[K \longrightarrow + \infty]{} \displaystyle{\int_{0}^{t}} \phi(R^{*}_{s}) \langle \mu^{*}_{s}, \varphi_{s} \rangle \mathrm{d}s.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 3 (Second-chaos representation) of arXiv:2604.00642, 'Quantitative central limit theorem for an integrated periodogram via the fourth moment the'] There exists $k_n\in\Hh^{\odot 2}$ such that
\begin{equation*}
F_n=I_2(k_n).
\end{equation*}
Moreover, with
\begin{equation}
 A_{n,h}(\lambda,\mu):=\int_{-\pi}^{\pi} h(\omega)\,D_n(\lambda-\omega)\,D_n(\omega-\mu)\,\dd\omega,\qquad h\in L^1(-\pi,\pi),
\end{equation}
we have
\begin{equation}
 V_n=2\,\norm{k_n}_{\Hh^{\otimes 2}}^2
 =2n\int g(\lambda)g(\mu)\,\left| A_{n,f}(\lambda,\mu) \right|^2\,\dd\lambda\,\dd\mu.
\end{equation}

[Theorem 16 (Observed endpoint Schr\"odinger system) of arXiv:2609.02196, 'Schr\"odinger Bridges on Lie Group Manifolds for Probabilistic Intrinsic Generation'] Under Assumption~\ref{ass:endpoint-kernel}, the static endpoint problem
\begin{equation*}
\inf_{\Gamma\in\Pi(\rho_0,\rho_T)}\KL(\Gamma\|\mathcal R_{0T})
\end{equation*}
has a unique minimizer \(\Gamma^*\). There exist positive factors \(f_0,f_0^{-1}\in L^\infty(\rho_0)\) and \(g_T,g_T^{-1}\in L^\infty(\rho_T)\), unique up to reciprocal scaling, such that
\begin{equation*}
\Gamma^*(\dd y_0\dd y_T)
=f_0(y_0)g_T(y_T)\mathcal R_{0T}(\dd y_0\dd y_T).
\end{equation*}
With \(\int g_T\,\dd\rho_T=1\), one may choose
\begin{equation*}
\frac1M\leq f_0\leq\frac1m,
\qquad
\frac mM\leq g_T\leq\frac Mm.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 116 of arXiv:2601.16377, '2601.16377'] In the setting of Proposition~\ref{Proposition_ZW_partition}, the leading term of the partition function satisfies
\begin{equation} 
\F^{[0],\textnormal{ref}} = \I[\mu]+ \frac{\mathbbm{Rest}_0^{\textnormal{ref}}}{\N}+ o\bigg(\frac{1}{\N^{2}}\bigg),
\end{equation}
as $\N \rightarrow \infty$. Here $\mu$ is the equilibrium measure, $-\I$ is the energy functional that it minimizes, $\mathbbm{Rest}_0^{\textnormal{ref}}$ depends on $\N$ and are twice-continuously differentiable with respect to $(\hat{n},\hat{A}_1,\hat{A}_2,\hat{B}_1,\hat{B}_2)$ for $(\theta, \hat{n},\hat{A}_1,\hat{A}_2,\hat{B}_1,\hat{B}_2)\in\mathcal D$ with derivatives of orders $0$, $1$, $2$, uniformly bounded in $\N$. Finally, $o(\frac{1}{\N^{2}})$ is a term which after multiplication by $\N^{2}$ tends to $0$ as $\N\rightarrow\infty$ uniformly over the parameters varying in compact subsets of $\mathcal D$. (Proof in the paper; no proof environment follows the statement in the TeX.)

