[Thm 8 of arXiv:2604.24189, 'Malliavin calculus and densities for chaos-driven stochastic differential equations'] Let $q \in \N$ and $f \in \mathfrak{H}^{\odot  q}$ be fixed, and set $F=I_q(f)$. There exist two events $\Omega_F^\prime \subseteq \Omega_F$ with $\mathbb{P}(\Omega_F^\prime)=\mathbb{P}(\Omega_F)=1$, together with a random variable $\widetilde{F} \in \widetilde{\mathbb{D}}^{\infty}$, such that
\begin{enumerate}[(a)]
\item  $\Omega_F + j(\mathfrak{H}) \subseteq \Omega_F$;
\item for all $\ell \in \N$, $\widetilde{D}^\ell \widetilde{F}=D^\ell F$ on $\Omega_F^\prime$;
\item for all $\omega \in \Omega_F$, $h \in \mathfrak{H}$ and $0 \leq \ell \leq q$,
\begin{align}
\widetilde{D}^\ell \widetilde{F}(\omega + j(h)) = \sum_{k=0}^{q-\ell} \frac{1}{k!} \langle \widetilde{D}^{k+\ell} \widetilde{F}(\omega),h^{\otimes k} \rangle_{\mathfrak{H}^{\otimes k}}.
\end{align}
\item for all $\ell >q$, $\widetilde{D}^\ell \widetilde{F}=0$.
\end{enumerate}

