body:
[Theorem thm:ZIMsurvival of arXiv:2607.29409, 'The Zombie Infection Model'] The following statements are equivalent:
		\begin{enumerate}
			\item $\exists \lambda_{*}^{\ZIM}\in [1,\infty)$ such that $\BP^{\ZIM}_{\lambda,G,\Delta}
				( \lim_{t\rightarrow \infty}{\mathcal{Z}}_{t}= \infty ) >0$ for all $\lambda
				>\lambda_{*}^{\ZIM}$ and $\Delta \Subset V$.


			\item $\exists \lambda_{c}^{\SIR}\in (0,\infty)$ such that $\BP_{\lambda,G,\Delta}
				^{\SIR}( \lim_{t\rightarrow \infty}{\mathcal{I}}_{t} = \infty ) >0$ for
				all $\lambda>\lambda_{c}^{\SIR}$ and $\Delta \Subset V$.


			\item $p_{c}^{\siteperc}(G)<1$. 
		\end{enumerate}
		In particular, if $p_{c}=p_{c}^{\siteperc}(G)<1$, we may set
		$\lambda_{*}^{\ZIM}= \frac{\sqrt[d]{p_{c}}}{1-\sqrt[d]{p_{c}}}$ with
		$d=\mathrm{deg}(G)-1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:pathwise-cluster-product-green-energy of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] Fix $x\in\Omega_{\rm Fr}\cap\Omega_{\rm op}$, and let
$(\Lambda_i^x,\phi_i)$ and $(\Lambda_j^x,\phi_j)$ be positive eigenpairs of
$A_x$ with real $L^2(M_x)$-normalized eigenfunctions.  Then
\begin{equation}
 \phi_i\phi_jM_x\in\mathcal M_{\rm fe}(D),

\end{equation}
and
\begin{equation}
 I_D(|\phi_i\phi_j|M_x)
 \le M_x(D)^{1/2}K_G(x)^{3/2}
      \min\{(\Lambda_i^x)^2,(\Lambda_j^x)^2\}<\infty.

\end{equation}
Consequently, for every $g\inH$,
\begin{equation}
 \big\langleU_D(\phi_i\phi_jM_x),g\big\rangle_{H}
 =\int_D\widetilde g\,\phi_i\phi_j\,dM_x.

\end{equation}

