[Definition of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] We call an $ H $-valued, $ \mathbf{F} $-adapted, continuous stochastic process $ X(\cdot) $ a strong solution to (eqSEE of the paper) if 
    \begin{enumerate}[(i)]
        \item $X(t) \in D(A)$ for a.e. $(t, \omega) \in[0, T] \times \Omega$ and $A X(\cdot) \in L^1(0, T ; H)$ a.s.; 
        \item $F(\cdot, X(\cdot)) \in L^1(0, T ; H)$ a.s., $\widetilde{F}(\cdot, X(\cdot)) \in L_{\mathbb{F}}^{2}(0, T ; H)$;  
        \item For all $t \in[0, T]$,
        \begin{align*}
        X(t)=X_0 \!+\! \int_0^t(A X(s)+F(s, X(s))) d s+\int_0^t \widetilde{F}(s, X(s)) d W(s), \text{ a.s. }
        \end{align*}
    \end{enumerate}

[Lemma 16 of arXiv:2605.15931, '2605.15931'] The sequence of processes $(n^{1/2}(X_{\tilde{\tau}^n(X)\wedge.}-x))_{n \in \mathbb{N}}$ converges in the sense of finite-dimensional distributions over $\{t_1,t_2,...,t_m\}\subset (0,\infty)$. In particular, for any $\{t_1,t_2,...,t_m\}\subset (0,\infty)$ and $\varphi:\mathbb{R}^{m\times d}\to \mathbb{R}$ continuous and bounded we have
		$$
		\begin{aligned}
		&|\mathbf{E}[\varphi(n^{1/2}(X_{\tilde{\tau}^n(X)\wedge t_1}-x),...,n^{1/2}(X_{\tilde{\tau}^n(X)\wedge t_m}-x))]\\
		&-\mathbf{E}[\varphi(\sigma(x)W_{\tau^1(\sigma(x)W)},...,\sigma(x)W_{\tau^1(\sigma(x)W)})]|\,{{\to}}\,0
		\end{aligned}
		$$
		{as $n\to \infty$.}

