[Proposition 50 (Maximal canonical Gaussian factor) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] \begin{equation}
 F=A^{\can}+G^{\can},
 \qquad
 G^{\can}\indep A^{\can}.

\end{equation}
If a Hilbert--Stein split has an independent Gaussian factor and zero proper residual contraction
register, then closed graded spaces $T_s\subset\cN_s(F)^\perp$ exist such that
\begin{equation}
 G_a^{\mathrm{HS}}
 =
 \sum_sI_1(P_{T_s}\ell_{a,s}),
 \qquad
 \Cov(G^{\mathrm{HS}})
 \preccurlyeq
 \Cov(G^{\can}).

\end{equation}

[Theorem 3 (\cite{BS2024}) of arXiv:2604.00882, 'On some extensions of generalized counting processes'] The process ${M}^{\psi,f}$ has probability distribution function
   	 \begin{equation}
   	          \tilde{p}_n^{\psi,f}(t)=\sum_{\Omega(k,n)}^{}\prod_{j=1}^{k}\frac{\lambda_j ^{x_j}}{x_j!}\left(-\partial_{\Lambda}\right)^{z_k}\tilde{\ell}_f(t,\psi (\Lambda)), \, n\ge 0,
    	\end{equation}
    	and $\tilde{p}_n^{\psi,f}(t)$ satisfy the following equation
    	\begin{equation}
   		 \mathcal{D}^f_t \tilde{p}_n^{\psi,f}(t)=-\psi(\Lambda)\tilde{p}_n^{\psi,f}(t) -\sum_{m=1}^{n}\sum_{\Omega(k,m)}^{}\psi^{(z_k)}\left(\Lambda\right) \prod_{j=1}^{k}\frac{(-\lambda_j )^{x_j}}{x_j!}\tilde{p}_{n-m}^{\psi,f}(t),, \, n\ge 0, \,t>0,
  	\end{equation}
   	 with initial conditions 
    \begin{equation*}
         \tilde{p}_n^{\psi,f}(0)=
         \begin{cases}
                1,\quad n=0,\\
                0,\quad n\geq1.\\
         \end{cases}
     \end{equation*}
        The probability generating function of the process ${M}^{\psi,f}$ is of the form
\begin{equation}
             \tilde G^{\psi,f}(u,t)=\tilde \ell_f\Big(t, \psi\Big(\sum_{j=1}^{k}\lambda_j(1-u^j)\Big)\Big),\, |u|<1,
\end{equation}
and satisfies the equation
\begin{equation}
        	\mathcal{D}^f_t \tilde G^{\psi,f}(u,t)=-\psi\Big(\sum_{j=1}^{k}\lambda_j(1-u^j)\Big)\tilde G^{\psi,f}(u,t)
    \end{equation}
    with $\tilde G^{\psi,f}(u,0)=1$.
    The derivatives used in \eqref{Dtfpn} and \eqref{DftG} are the C-D convolution-type derivatives defined in \eqref{fDt}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 50 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Fix $\delta>0$.
		Let $k \ge 1$ be a positive integer and $q', q \in [0, \varepsilon_0]$, and $u \ge 0$ be real numbers such that $|q-q'| \le 2^k N^{-1-4\delta} u$. We have
		\begin{flalign}

		\mathcal C^q_k(u):=	\left[\mathcal{B}_{k+1}^q (u) \cup \bigcup_{j=1}^k \mathcal{A}_j^q (u)\right] \subseteq \bigcup_{j=1}^{k+1} \mathcal{A}_j^{q'} \big( (1 - N^{-\delta}) u \big),
		\end{flalign} 
and
		\begin{flalign}

			1 - 2N^{-2\delta} \le \mathtt{e}_{z;q'} \mathtt{e}_{z;q}^{-1} \le 1 + 2 N^{-2\delta}, \qquad \text{for every $z\in \mathcal C^q_k(u)$}.
		\end{flalign}

