[Lemma lem:collision-moments-proof of arXiv:2608.18320, 'Asymptotics for Beta-Splitting Trees via Homogeneous Fragmentations and Meromorphic Potent'] Conditionally on $\mathbf P(t)$,
    \begin{equation}
            \operatorname{Var}\bigl(C_n(t)\mid\mathbf P(t)\bigr)=\binom n2S_2(t)\bigl(1-S_2(t)\bigr)+6\binom n3\bigl(S_3(t)-S_2(t)^2\bigr).
    \end{equation}
    In particular,
    \begin{equation}
            \operatorname{Var}\bigl(C_n(t)\mid\mathbf P(t)\bigr)\le\mu_n(t)+n^3S_3(t).
    \end{equation}

[Cor sufficient-inequalities of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Let $({\mathbf{a}},{\mathbf{b}})$ be a non-degenerate weight pair and assume that $r=r({\mathbf{a}})$ is finite.
	Assume that the following inequalities hold for all $n\geq 0$ and all $\ell\in\{0,\dots,r-1\}$,
	\begin{equation}
	\frac{b_{n+1}}{b_{n}}
	\leq
	\frac{
		\PFComp{\shift{\ell}{\mathbf{a}},{\mathbf{b}}}{n+1}
	}{
		\PFComp{\shift{\ell}{\mathbf{a}},{\mathbf{b}}}{n}}
	\leq
	\frac{b_{n+2}}{b_{n+1}},
	\end{equation}
	where we omit the ill-defined inequality on the left when $n=0$.
	Then $({\mathbf{a}},{\mathbf{b}})$ is admissible, as well as the pairs $(\shift\ell{\mathbf{a}},{\mathbf{b}})$ for $\ell=0,\dots,r-1$.

[Lemma 21 of arXiv:2605.20115, 'Moment bounds on correctors for the degenerate random conductance model'] For any measurable random variable $X=X(A)$,
    \begin{equation}
        \textup{Var}(X)\le \frac12 \expecb{ \int_{x\in \ZZ^d} |D_x X |^2},
    \end{equation}
    where 
    \begin{equation*}
     D_x X(A):=X(A)-X(A^{(x)}).
    \end{equation*}
Here $A^{(x)}$ is the random field defined by $A^{(x)}(x')=A(x')$ for $x'\neq x$, while $A^{(x)}(x)$ is an i.i.d. copy of $A(x)$.
    Moreover, this implies, for $p\ge 1$,
    \begin{equation}
        \expecb{|X-\expec X|^{2p}}^{\frac1p}\lesssim 4 p^2\expecb{\Big(\int_{x\in \ZZ^d} |D_x X |^2\Big)^p}^\frac1p.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition of arXiv:2607.14062, 'Gilbert's disc model conditioned on the square lattice'] Let $p_1,p_2\in[1,\infty]$ with $p_1\leq p_2$. We have
    \begin{displaymath}
    R_{\min}^{\texttt{CN}}(p_2) \leq R_{\min}^{\texttt{CN}}(p_1)\text{, }
    R_{c}^{\texttt{CN}}(p_2) \leq R_{c}^{\texttt{CN}}(p_1)\text{, and }
    R_{\max}^{\texttt{CN}}(p_2) \leq R_{\max}^{\texttt{CN}}(p_1).
\end{displaymath}
    The same property holds for the nearest neighbor model.

[Lemma eloge-derivative of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] Fix $\nu\in \P(\X)$ and $\k\geq 2$. Given $\pi\in \Psym{\X}$, for any $\xi\in \Psym{\X}$, define
\begin{equation*}
    \pi_\varepsilon=\pi_\varepsilon[\xi]\coloneqq (1-\varepsilon)\pi+\varepsilon\xi,\quad \forall \varepsilon\in [0,1].
\end{equation*}
Then
\begin{equation}
    \lim_{\varepsilon\rightarrow 0^+}\frac{1}{|\varepsilon\log \varepsilon|}\cpr{J_\k^\nu(\pi_\varepsilon)-J_\k^\nu(\pi)}=(\k-1)\sum_{x\in \X}\xi^o(x)\indf_{\pr{\pi^o(x)=0}}-\frac{\k}{2}\sum_{x,z\in \X}\xi(x,z)\indf_{\pr{\pi(x,z)=0}}.
\end{equation}

[Lemma 23 (Lemma 7.2.7 from \cite{vershynin2018high}) of arXiv:2604.01978, 'Homogenized Transformers'] Consider two independent Gaussian random vectors $X\sim\cN(0,\Sigma^{X})$ and $Y\sim \cN(0,\Sigma^{Y})$. Define the interpolated Gaussian vector 
\begin{equation*}
    X_t=\sqrt{t}X+\sqrt{1-t}Y.
\end{equation*}
Then for all $\varphi\in C^2(\R^m)$, we have
\begin{equation*}
    \frac{\de}{\de t}\E \varphi(X_t)=\frac{1}{2}\E\left[\Tr\left((\Sigma^{X}-\Sigma^{Y})^{\sT}\; \nabla^{2}\varphi(X_t)\right)\right].
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem of arXiv:2606.09228, 'On topological indices of random caterpillar graphs'] We have
    \begin{align*}
        \Cov\left(\sum_{i<j} (j-i+2)I_iI_j,\sum_{k=1}^m I_k\left(I_k-1\right)\right)=-\frac{2n(n-1)(m-1)(m+7)}{6m^2}.
    \end{align*}

