\[
  \frac{L^{\star}_{D_{d,m}}\bigl((m+1)d-1;\mathrm{weighted}\bigr)}
       {L^{\star}_{D_{d,m}}}
  \;=\;1+\frac{m+1}{2md\,(m^2+m-1)}\;>\;1 .
\]

[Lemma pi=rho of arXiv:2507.08757, 'Strong existence and uniqueness of the tilt-indexed Busemann process in the planar corner '] Let $\widehat\pi^{\raisebox{1.3pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}}$ and $\widehat\gamma^{\raisebox{1.3pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}}$ be two shift-covariant non-crossing systems of geodesics such that $\widehat\mathbb{P}\{\widehat\pi^0\preceq\widehat\gamma^0\}=1$. Assume that either $\widehat\pi^{\raisebox{1.3pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}}\in{\widehat{\mathbbold\Pi}_c}$ or $\widehat\gamma^{\raisebox{1.3pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}}\in{\widehat{\mathbbold\Pi}_c}$. Assume also that there exists a cocycle ${\widehat B}\in\widehat{\mathcal{K}}$ such that both $\widehat\pi^u$ and $\widehat\gamma^u$ are ${\widehat B}$-geodesics for all $u\in\mathbb{Z}^2$. 
    That is, 
    \begin{align}
    \widehat\mathbb{P}\bigl\{{\widehat\omega}:\forall u\in\mathbb{Z}^2,\forall n\ge u\cdot(e_1+e_2):{\widehat B}({\widehat\omega},\widehat\pi_n^u({\widehat\omega}),\widehat\pi_{n+1}^u({\widehat\omega}))=\omega_{\widehat\pi_n^u({\widehat\omega})}({\widehat\omega})\bigr\}=1
    \end{align}
    and
    \begin{align}
    \widehat\mathbb{P}\bigl\{{\widehat\omega}:\forall u\in\mathbb{Z}^2,\forall n\ge u\cdot(e_1+e_2):{\widehat B}({\widehat\omega},\widehat\gamma_n^u({\widehat\omega}),\widehat\gamma_{n+1}^u({\widehat\omega}))=\omega_{\widehat\gamma_n^u({\widehat\omega})}({\widehat\omega})\bigr\}=1.
    \end{align}
    Then $\widehat\mathbb{P}\{\forall u\in\mathbb{Z}^2:\widehat\pi^u=\widehat\gamma^u\}=1$.

