body:
[Definition 42 (Balanced comparison structure) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] We say that $\xi$ is \textbf{balanced} with respect to $\lambda$ if there exists a one-species covariance function $\xi_\star:\R_+\to\R$ such that, for every $r\in\R_+$,
\begin{equation}

    \xi(r\lambda)=\xi_\star(r),
\end{equation}
and, for every $a=(a_s)_{s\in\sS}\in\R_+^\sS$,
\begin{equation}

    \xi(a)\leq \sum_{s\in\sS}\lambda_s\xi_\star\left(\frac{a_s}{\lambda_s}\right).
\end{equation}

[Lemma 27 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$, there exist $C,c>0$ such for any $T>0$, any distinct $v_1,v_2,w_1,w_2\in \widetilde{\mathbb{Z}}^d$ with $|v_1-w_1|\land |v_2-w_2|\ge d$, and any $z\in \{v_1,v_2,w_1,w_2\}$, 
 	 	\begin{equation}
 		\begin{split}
 			\mathbb{P}\big(  \widehat{\mathcal{L}}_{1/2}^{z} \ge T  \mid \{v_1\xleftrightarrow{} w_1\Vert v_2\xleftrightarrow{} w_2 \} \big)\le Ce^{-cT}. 
 		\end{split}
 	\end{equation}

[Lemma Bramson-converges-to-1 of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] \footnote{This claim can also be verified in the modern language of extremal point processes $\widetilde{\mathcal{E}}_\infty^\lambda$. Notably, the underlying reason for (equation other-main-input-from-Bramson of the paper) to hold is that the number of particles of $\widetilde{\mathcal{E}}_\infty^\lambda$ at a bounded distance from $x$ blows up as $x\to -\infty$: it grows like $ e^{-\mu x}$ for $\lambda >\sqrt{2}$ and $\approx (-x)e^{-\sqrt{2}x}$ for $\lambda = \sqrt{2}$.}
    Let $\phi:\mathbb{R}\to [0,1]$ be a measurable function such that $\phi(x) \geq \eta$ for all $x\in (a,b)$ \textcolor{black}{with} some $a,b \in \mathbb{R}$ and $\eta >0$. Let $u_\phi(t,x)$ be the solution to F-KPP equation with initial condition $\phi$. Then, for any $\delta >0$, as $t \to \infty$,
\begin{equation}
u_\phi\left(t, x\right) \to 1
\end{equation}
uniformly in $x$ such that $|x| \le \sqrt{2}t - \bigl(\frac{3}{2\sqrt{2}} + \delta\bigr)\log t$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 57 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Let $(H_s)_{s \ge 0}$ denote the height function at time $s$ for the Glauber dynamic on $\mX$, with floor constraint $\cH_{-q_0}$ and ceiling constraint $\cH_{q_0}$ (as in \Cref{def:constrained}), started from the maximal configuration compatible with these constraints (recall \Cref{def:partorder}). Then, for each $j \in [0, \mathfrak{j}]$ and $w \in \mathfrak{X}$, let 
\begin{flalign}

	H_{s,j} (w) = H_s (w) + (j-\mathfrak{j}) N^{M\delta-1}.
\end{flalign}

[Lemma lem:maximum principle trunc of arXiv:2607.02367, 'Flux solutions for stochastic chemical systems with sources and sinks'] Assume that the sequence of functions  $\psi^N (t)= (\psi_N(t, n ))_{n \in \mathbb N^M }  $ that are such that for every $n \in \mathbb N^M $ the function  $ t \mapsto \psi_N(t, n )$ is continuously differentiable and satisfies the following equation 
        \begin{align} 
 \partial_s  \psi^N(s, n)   -  
   \mathcal L^N_r[ \psi^N (s) ](n) - \bar{ \mathcal L}_s^N [ \psi^N (s) ](n) \leq 0 , \quad s \geq 0  \quad n \in \mathbb N^M     
\end{align}
    with initial datum $ \psi (0) = \psi_0 \in c_{00} (\mathbb N^M)$.
    Then 
    \begin{align*}
       \sup_{ t \in [0, \infty) } \max_{ n \in \mathbb N^M } \psi^N (t, n ) \leq    \sup_{ n \in \mathbb N^M } \psi_0 ( n ). 
    \end{align*}
    Moreover if $\psi^N $ attains a maximum at time $ t= \overline t  $, then $ \psi^N $ is constant. 

    Assume that the sequence of functions  $\psi^N (t)= (\psi_N(t, n ))_{n \in \mathbb N^M }  $ that are such that for every $n \in \mathbb N^M $ the function  $ t \mapsto \psi_N(t, n )$ is continuously differentiable and satisfies
        \begin{align} 
 \partial_s  \psi^N(s, n)   -  
   \mathcal L_r[ \psi^N (s) ](n) -  \mathcal L_s [ \psi^N (s) ](n) \geq 0 , \quad s\geq 0, \quad n \in \mathbb N^M     . 
\end{align}
    with initial datum $ \psi (0) = \psi_0 \in c_{00} (\mathbb N^M)$.
    Then 
    \begin{align*}
  \inf_{ t \in [0, \infty)   } \min_{ n \in \mathbb N^M } \psi^N (t, n ) \geq   \sup_{ n \in \mathbb N^M } \inf_0 ( n ) . 
    \end{align*}
    Moreover if $\psi^N $ attains a minimum at time $ t= \overline t  $, then $ \psi^N $ is constant.

