[Corollary 5 of arXiv:2512.19517, 'Spiking and Resetting'] For any $t>0$ and any $0<a\le b\le1$, the probability distribution $P^\varepsilon_c( \cdot \, : \, t,a,b)$ over $\mathbb N_0$ converges in law to a Poisson distribution with parameter 
\begin{equation}

\begin{split}
f(0) \, t\,  \lambda_* ( [a,b]) = f(0)\,  t \, \int_a^b \cfrac{dx}{x^2} = f(0) \, t \,  (a^{-1}- b^{-1}) \  . 
\end{split}
\end{equation}
Furthermore, we have that, for any $n\ge 0$, the function
\begin{equation}

\begin{split}
\Phi_n^\varepsilon: r \in[0,\infty) \mapsto \mathbb P ( e_1^\varepsilon \ge r, N^\varepsilon_{(0,r]} ([a,b]) = n) \in [0,1]
\end{split}
\end{equation}
converges uniformly on any compact interval $[0,t]$, $t>0$, as $\varepsilon$ vanishes to 
\begin{equation}

\begin{split}
\Phi_n: r \in [0,\infty) \mapsto e^{-r f(0)} e^{-r \lambda_* ([a,b]} \frac{(r \lambda_* ([a,b]))^n}{n!} \in [0,1] \ .
\end{split}
\end{equation}

[Lem overtake-bound of arXiv:2410.24170, 'Persistent hubs in CMJ branching processes with independent increments and preferential at'] Suppose that $(X_{i})_{i \in \mathbb{N}}$, $(X'_{i})_{i \in \mathbb{N}}$ and $Y$ are mutually independent random variables, with $(X_{i})_{i \in \mathbb{N}} \sim (X'_{i})_{i \in \mathbb{N}}$. Suppose that, for $k \in \mathbb{N}_{0}$, there exists $\lambda > 0$ such that
    \begin{equation} 
    \prod_{i=k}^{\infty}\E{e^{\lambda  (X'_{i} - X_{i})}} < \infty.  
    \end{equation}
    Then, for any $\ell \in \mathbb{N}$
    \begin{equation} 
        \Prob{\exists j \in \mathbb{N}\colon Y + \sum_{i=1}^{k + j} X_{i} \leq \sum_{i=k}^{k+j} X'_{i}} \leq \left(\prod_{i=k}^{\infty}\E{e^{\lambda  (X'_{i} - X_{i})}}\right) \E{e^{- \lambda \left(Y + \sum_{i=1}^{k-1} X_{i}\right)}}.
    \end{equation}

