[Proposition 1 of arXiv:2506.10522, 'On the Law of the Iterated Logarithm for $m$-dependent stationary random variables under s'] Let $\{X_n;n=1,2,\cdots\}$ be a sequence of independent random variables in a sub-linear space $\sles$ satisfying $|X_n|\leq\alpha_n\frac{s_n}{t_n}$ for some $\alpha_n\to0$ and $s_n^2\to\infty$. Denote $\underline{s}_n^2=\sum_{i=1}^n\mbe[X_i^2]$ and $V_n^2=\sum_{i=1}^nX_i^2$, and assume that there exists a real number $r$ such that
\begin{equation}
    \frac{\underline{s}_n^2}{s_n^2}\to r.
\end{equation}
Then 
\begin{equation}
    \mvstar\left(r\leq\liminf_{n\to\infty}{\frac{V_n^2}{s_n^2}}\leq\limsup_{n\to\infty}{\frac{V_n^2}{s_n^2}}\leq1\right)=1.
\end{equation}

[Lemma 6 of arXiv:2606.22656, 'Fluctuations of Point Vortex Ensembles\\ at Small Negative Inverse Temperature'] For every finite simple graph $\Gamma$ with $n$ vertices and every $\beta_*<8\pi$,
there exists $C_{\Gamma,\beta_*}<\infty$ such that, for all sufficiently
large $N$ and $\beta\leq \beta_*$,
\begin{equation*}
    |A_N(\Gamma)| \leq C_{\Gamma,\beta_*}
    \left(\frac{\beta}{N}\right)^{e(\Gamma)}.
\end{equation*}

