[Theorem 14 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $h\in Z\hat C(\Delta_T^3;B_\alpha)$. Then the map
\[
\mathcal T_h:\{R\in C(\Delta_T^2;B_\alpha) \mid \hat\delta R=h\}\to \{\text{compatible frozen increment families over }h\}
\]
defined by $\mathcal T_h(R):=(\Theta_\tau R)_{\tau\in[0,T]}$ is a bijection. Its inverse is given by
\begin{equation}

(r^\tau)_{\tau\in[0,T]}\mapsto R, \quad R_{ts}:=r^t_{ts}.
\end{equation}
In addition, if $\gamma\in(0,1)$ and $h\in Z\hat C^{\gamma}(\Delta_T^3;B_\alpha)$, then
$\mathcal T_h$ restricts to a bijection between $ \{R\in E^{\gamma}(\Delta_T^2; B_\alpha) \mid \hat\delta R=h\}$ and the compatible frozen increment families over $h$ satisfying
\begin{equation}

\sup_{\tau\in[0,T]}\|r^\tau\|_{\gamma-\varepsilon,\alpha+\varepsilon;\tau}<\infty, \quad \forall \varepsilon\in(0, \gamma).
\end{equation}
Likewise, if $h\in Z\hat C^{1}(\Delta_T^3;B_\alpha)$, then $\mathcal T_h$ restricts to a bijection between $\{R\in E_{\log}^{1}(\Delta_T^2; B_\alpha) \mid \hat\delta R=h\}$ and the compatible frozen increment families satisfying
\begin{equation}

\sup_{\tau\in[0,T]}\|r^\tau\|_{1,\log;\tau,\alpha}+\sup_{\tau\in[0,T]}\|r^\tau\|_{1-\varepsilon,\alpha+\varepsilon;\tau}<\infty, \quad \forall \varepsilon\in(0,1).
\end{equation}

[Corollary lema2 of arXiv:2609.03909, 'Conic Pseudo-Finslerian Mechanical Systems'] Let $L$ be a conic pseudo-Finslerian metric and let $	ilde L = fL$ be a metric conformally related to $L$ where $f:M	o \mathbb R$ is a positive smooth function. Then 
    $$ \widetilde{
abla}^V_VV= 
abla^V_VV+ rac{V(f)}{f}V- rac{g_v(V,V)}{2f}
abla^Vf.$$
    where $
abla$ and $\widetilde{
abla}$ are the Chern connections of $L$ and  $	ilde L$ respectively.

[Proposition 1 (Center accuracy after local calibration) of arXiv:2609.01319, 'Matched Queries for Curvature and Density at Branching Junctions'] Fix smooth localized score tests around a bounded reference offset. If the resulting exact tangent-model least-squares matrix has full column rank, then using the finite-noise score from \cref{thm:expansion} returns a physical center of the form
\begin{equation}
c_\sigma=x_0+\sigma^2b+O(\sigma^{2+\alpha})

\end{equation}
for some bounded $b\in\R^D$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 28 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] [\textbf{One-block estimate}] 
	Let $\gamma >0$, $0 \leq t \leq T$, $n \in \mathbb{N}_+$ and $ \widehat{b}_n \in \mathbb{R}$. Then
	\begin{align*}
		\mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ \widehat{b}_n \int_0^t \dd r \sum_{x}   \nabla H ( \tfrac{ \lfloor x - r v_n \rfloor }{n}  )    \big[  \bar{\xi} _x^{\alpha}( \eta_r^n ) \bar{\xi} _{x+1}^{\beta}( \eta_r^n ) - \Psi_{x, \ell_n}^{\alpha,\beta}(\eta_r^n) \big]  \Bigg\}^{2} \Bigg] \leq C t  \frac{ n (\widehat{b}_n \ell_n)^2  }{\Theta(n)}  \| \nabla H \|^{2}_{2,n},
	\end{align*}
	where $C$ is a constant independent of $H$, $n$ and $t$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 9 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb_{\leq n}$, $f:\cube^n\to \Rbb$ and $q\in [1,2)$,
\begin{equation}
    \left\|\left|\grad^k f\right|\right\|_{\Leb^2}^{2} \geq \Wop^{\geq k}(f) \left[1+ \frac{q}{2k(2-q)}\ln^+\left(\frac{\Wop^{\geq k}(f)}{\sum_{J:|J|=k} \left\|\Dop_J f\right\|_{\Leb^q}^2} \right)\right]^k,
\end{equation}
and further for $\left\|f\right\|_{\Leb^\infty}\leq 1$ and $q\leq p<2$,
\begin{equation}
    \left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p} \geq C^{\text{\rm\ref{thm:high-order-Eldan-Gross-Boolean}}}(p,q)^k\Wop^{\geq k}(f) \left[1 + \frac{q}{2k(2-q)}\ln^+\left(\frac{1}{\sum_{J:|J|=k} \left\|\Dop_J f\right\|_{\Leb^q}^2} \right)\right]^\frac{kp}{2},
\end{equation}
with $C^{\text{\rm\ref{thm:high-order-Eldan-Gross-Boolean}}}(p,q) = \left(\frac{2}{2-q}\,M(p)^{-\frac{2}{p}}+\frac{pq}{2\upe(2-p)(2-q)}\right)^{-\frac{p}{2}} \gtrsim \left(2-p\right)\left(2-q\right)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2603.28170, 'Stabilization time of finite configurations with a second class particle in discrete TASEP'] Let $p=\frac{1}{2}-\frac{\lambda}{2\sqrt{n}}$ for some $\lambda\in\R$ be fixed
and let $\omega\in\Omega_n$ be sampled according to the Bernoulli initial condition of parameter $p$ with a second class particle in uniform position.
Then we have that
\begin{equation}
E_n\stackrel\d\Longrightarrow X^{(\lambda)}
\end{equation}
as $n\to\infty$ where the distribution of $X^{(\lambda)}$ is given by
\begin{equation}
\P(X^{(\lambda)}=0)=1-\P(X^{(\lambda)}=1)=\E(\argmax_{s\in[0,1]}B_s^{(\lambda)})
\end{equation}
with a Brownian motion $B_s^{(\lambda)}$ with drift $\lambda$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 15 of arXiv:2604.02129, 'Realisation of constraints in underdamped Langevin dynamics'] The probability measure $\mu^\eps\in \mathcal P(\R^{2d})$ defined in~\eqref{eq:SpatPreLimSte} converges weakly to $\mu\in \mathcal P(\xi^{-1}(0)\times\R^d)$ given by 
\begin{align*}
    d\mu(q^2,p)\coloneqq \frac{1}{Z} \exp\biggl(-V(0,q^2) -\frac{|p|^2}{2}\biggr) dq^2 dp
\end{align*}
where $Z$ is the normalisation constant. 
In particular, for $f\in C_b(\R^d)$ with $f=f(q)$ we have
\begin{align*}
    \lim_{\eps\to 0} \int_{\R^{2d}}f(q)d\mu^\eps(q,p) = \int_{\R^{d-k}} f(0,q^2) \frac{1}{\hat Z} e^{-V(0,q^2)}dq^2,
\end{align*}
with $\hat Z\coloneqq \int_{\R^{d-k}}e^{-V(0,q^2)}dq^2$. 

Furthermore, the limit~\eqref{eq:limit-gen} of $(Q^2,P^2)$ with $\hat q=0$  admits the $(q^2,p^2)$-marginal of $\mu$, i.e.\ $\displaystyle\int_{\R^k}\mu\,dp^1$, as a steady state (cf.Proposition~\ref{prop:Behav-Q2P2}).

