body:
[Proposition 19 of arXiv:2605.17494, 'Generalized intersection exponents and local cut points for three-dimensional Brownian loo'] For all $\alpha \in I_0$, the following holds almost surely:
    \begin{equation}
        {\rm dim}_{\mathcal{H}}(G) \le \max \{2-\xi_{\alpha}(1,1),0 \},
    \end{equation}
    and the following holds with positive probability
    \begin{equation}
        {\rm dim}_{\mathcal{H}}(G) \ge \max \{2-\xi_{\alpha}(1,1),0 \}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] Let $L:C^{0,1}(\Omega_T)\to\mathbb{R}$ be any linear functional and recall 
    \begin{equation*}
    \mathfrak{M}(H):=\int_0^T\int_0^1\sigma(\rho_t)|\nabla H_t|^2\;dx\;dt+\int_0^T\Psi(t,H_t(0),H_t(1))\;dt.
\end{equation*}
Then 
\begin{equation*}
    \sup_{C^{0,1}(\Omega_T)}\{L_0(H)-\mathfrak{M}(H)\}=S_1+S_2,
\end{equation*}
where
\begin{equation*}
    S_1=\sup_{C^{0,1}_0(\Omega_T)}\{L_0(G)-\int_0^T\int_0^1\sigma(\rho_t)|\nabla G_t|^2\;dx\;dt\}
\end{equation*}
and 
\begin{equation*}
    S_2=\sup_{h,g\in C([0,T])}\{L(g_t[1-\Xi_t])+L(h_t\Xi_t)-\int_0^T\zeta_t[h_t-g_t]^2\;dt-\int_0^T\Psi(t,g_t,h_t)\;dt\}.
\end{equation*}
In the above formula, $\zeta_t=1/\langle 1/\sigma(\rho_t) \rangle$. (Proof in the paper; no proof environment follows the statement in the TeX.)

