body:
[Proposition pro: Quantile Coupling Lower Bound for SSQ of arXiv:2603.14163, '\LARGE \bf Tail Bounds for Queues with Abandonment: Constant, Moderate, Large Deviations, '] \textnormal{(Quantile Coupling Lower Bound for SSQ)} 
    With the same notations in this section, for all $p > 1$:
\begin{align*}
    W_p(\mathcal{L}(\tilde{q}), \mathcal{L}(Z)) &= \left[ \int_{0}^{1} \left| F_{\mathcal{L}(\tilde{q})}^{-1}(u) - F_{\mathcal{L}(Z)}^{-1}(u) \right|^p du \right]^{1/p} \geq C_{quantile, \lambda, \mu} \cdot \sqrt{\gamma} \cdot\mathbb{P}(q= 0)^{1/p},
\end{align*} 
where $C_{quantile, \lambda, \mu}$ is constant independent of $\gamma$ and $p$, defined in (equation eq: Gaussian Wasserstein-$p$ Lower bound, P_0 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:error_est of arXiv:2607.22291, 'Rare subtree patterns in size-conditioned Bienaymé trees: Poisson approximation and declum'] Let $(m_{n})$ be a sequence of positive integers such that $m_{n}=o(n)$. Let $H : (\mathbb{Z}_{\geq -1})^{m_n} \to \{0,1\}$ be a function and let $(z_{n})$ be a sequence of positive real numbers such that $z_{n}=o(a_{n})$. Then there exists a constant~$C > 0$ (independent of $n$ and of $H$) such that for every $n \geq 1$ sufficiently large we have
\begin{equation}
  \sup_{|k| \leq z_{n}}\mathbb{E}\bigl[H(X_1,\ldots,X_{m_n}) \mid S_n = k\bigr] \leq C\, \mathbb{E}\bigl[H(X_1,\ldots,X_{m_n})\bigr].
\end{equation}

[Lemma 19 of arXiv:2606.08115, '2606.08115'] Assume that a two-dimensional random walk $\left\{ \ov{S}_n\right\}$ satisfies condition (C). Let also the correlation coefficient of components of the random walk increments $\rho$ belongs to the interval $(0, 1)$.
Then for any $\varepsilon >0$ there exists a square $D = [\delta, A] \times [\delta, A]$ such that for any $\ov{x} \in \mathcal{X}_V$ the following inequality holds:
\begin{equation}

\varlimsup_{T \to \infty} \pr_{\bfx}^{+}\left(\ov{S}_T + \ov{x} \notin \sqrt{T}D \right) \le \varepsilon \frac{u\left( \ov{x}_0 + M\ov{x}\right)}{V\left(M\ov{x}\right)}.
\end{equation}

