body:
[Proposition prop:prn_integral of arXiv:2606.23547, 'The location of the largest exponential spacing and Euler’s generalized pentagonal numbers'] For $1\le r\le n$, the probability $p_{r,n}$ admits the integral representation
\begin{equation}
p_{r,n}
=\int_0^\infty r {\rm e}^{-r t}
\prod_{\substack{1\le k\le n\\k\neq r}}
\bigl(1-{\rm e}^{-k t}\bigr)\,{\rm d}t.
\end{equation}
Equivalently,
\begin{equation}
p_{r,n}
=\int_0^1 r\,u^{r-1}
\prod_{\substack{1\le k\le n\\k\neq r}}
(1-u^k)\,{\rm d}u.
\end{equation}

[Proposition 1 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Let $p=1$ and~\eqref{co:1} and~\eqref{co:2} be valid. Then pathwise uniqueness holds for~\eqref{eq:SIS epidemic model}, and any two solutions $I$ and $\tilde{I}$ to~\eqref{eq:SIS epidemic model} satisfy
\begin{equation}
\E\big[|I_{t} - \tilde{I}_{t}|\big] \leq e^{\int_{0}^{t}(\hat{b}_{k+1} + \hat{\lambda}_{k+1})(s,N(s))\,\mathrm{d}s}\E\big[|I_{0} - \tilde{I}_{0}|\big]
\end{equation}
for all $t\geq 0$. In particular, if $(\hat{b}_{k+1} + \hat{\lambda}_{k+1})^{+}(\cdot,N)$ is integrable, then $\sup_{t\geq 0} \E[|I_{t} -\tilde{I}_{t}|]$ is finite. If additionally
\begin{equation*}
\int_{0}^{\infty}(\hat{b}_{k+1}+\hat{\lambda}_{k+1})^{-}(s,N(s))\,\mathrm{d}s = \infty,\quad\text{then}\quad \lim_{t\uparrow\infty} \E\big[|I_{t}-\tilde{I}_{t}|\big] = 0.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 (Decision-boundary representation of the error-rate Hessian) of arXiv:2609.00774, 'Semi-Supervised Classification with Informative Missing Labels in Weibull Mixture Models'] Under \Cref{ass:boundaries}, with $p_Y$ continuous at the boundaries,
\begin{equation*}
 \left.\frac{\partial R(\widetilde\theta;\theta)}
 {\partial\widetilde\theta}\right|_{\widetilde\theta=\theta}=0,
\end{equation*}
and
\begin{equation}
 H_{R}(\theta)
 :=\left.\frac{\partial^2 R(\widetilde\theta;\theta)}
 {\partial\widetilde\theta\partial\widetilde\theta^\top}
 \right|_{\widetilde\theta=\theta}
 =\sum_{j=1}^K
 \frac{p_Y(y_j;\theta)}{2|\delta_y(y_j;\theta)|}
 g(y_j;\theta)g(y_j;\theta)^\top.

\end{equation}
Let $\widehat\theta$ satisfy
\begin{equation}
 \sqrt n(\widehat\theta-\theta)\xrightarrow{d}N(0,V),
 \qquad
 n\E\{(\widehat\theta-\theta)(\widehat\theta-\theta)^\top\}\longrightarrow V,

\end{equation}
and suppose that, for some $\epsilon>0$,
\begin{equation}
 \E\|\sqrt n(\widehat\theta-\theta)\|^{2+\epsilon}=O(1).

\end{equation}
Then
\begin{equation}
 \E\{R(\widehat\theta;\theta)\}-\err(\theta)
 =\frac{1}{4n}\sum_{j=1}^K
 \frac{p_Y(y_j;\theta)}{|\delta_y(y_j;\theta)|}
 g(y_j;\theta)^\top Vg(y_j;\theta)
 +o(n^{-1}).

\end{equation}
For a correctly specified regular maximum-likelihood estimator satisfying the stated moment conditions,
$V=\J(\theta)^{-1}$, so
\begin{equation}
 \E\{R(\widehat\theta;\theta)\}-\err(\theta)
 =\frac{1}{4n}\sum_{j=1}^K
 \frac{p_Y(y_j;\theta)}{|\delta_y(y_j;\theta)|}
 g(y_j;\theta)^\top\J(\theta)^{-1}g(y_j;\theta)
 +o(n^{-1}).

\end{equation}
For the estimator that ignores the missingness mechanism, the same specialisation holds with $\J=\J_{\mathrm{ig}}$ by \Cref{lem:ig-information}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:no_holes_in_waterfall_region of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] Let the parameters
	$T,S,N,t$ grow proportionally to $L$ as in (equation eq:limit_regime of the paper).
	Fix their scaled values $\mathsf{T},\mathsf{S},\mathsf{N},\mathsf{t}$.
	For any $\varepsilon>0$, there exists $c>0$ (depending on $\mathsf{T},\mathsf{S},\mathsf{N},\mathsf{t},\varepsilon$)
	such that
	\begin{equation*}
		\begin{split}
		&\operatorname{\mathbb{P}}
		\Bigl( \textnormal{there exists a hole }
			\begin{tikzpicture}[baseline = (current
			bounding box.south),scale=.25]
			\draw[thick] (0,0)--++(1,1)--++(1,0)--++(-1,-1)--cycle;
			\end{tikzpicture}
			\textnormal{ in the nonintersecting path ensemble at some point $(t,y)$,}
			\\&\hspace{140pt}
			\textnormal{where
			$
			\mathsf{t}_l+\varepsilon<
			\frac{t}{L}< \mathsf{t}_r-\varepsilon
			$
			and
				$\left|
				\frac{y}{L}-\frac{\mathsf{S}+\mathsf{t}}{2}
				\right|<\frac{\mathsf{N}-\varepsilon}{2}$
			}
		\Bigr)
		<e^{-cL},
		\end{split}
	\end{equation*}
	for all $L$ large enough.

