[Lem 121 (convergence of smoothed coefficients) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] The coefficients 
$(\tB,\tV,\tU,\trrr,\twww)^N$,
$(\Tbbb,\Tvvv,\Tuuu)^N$, and 
$(\iB,\iV,\iU,\ir,\iw)^N$
from Definitions~\ref{d:t.smooth} 
and \ref{d:t.smooth.variant}
converge pointwise as $N\to\infty$ to the coefficients
$(\tB,\tV,\tU,\trrr,\twww)$,
$(\Tbbb,\Tvvv,\Tuuu)$, and 
$(\iB,\iV,\iU,\ir,\iw)$
from Definition~\ref{d:cts.coeffs}. Since $\twww^N,\iw^N,\tF^N,\iF^N$ are all nonnegative, it follows that 
$\twww,\iw,\tF,\iF$ are also nonnegative.  Additionally, analogously  to \eqref{e:domain.plus.coarse} and the bounds from Lemmas \ref{l:sp.smooth.domain} and \ref{l:t.smooth.domain}, we have almost surely
	\[
	\Tvvv(t,y)
	\ge
	\Tuuu(t,y)^2 
	\]
for all 
$(t,y)\in [q_*,1]\times \bbR$. 

\begin{proof} 
From Definitions \ref{d:sp.smooth} and \ref{d:t.smooth},
	\begin{align*}
	\Tuuu^N(t,y)
	&= \int_{\R}\tphi(t-s) \suuu^N(s,y)\,ds
	=
	\int_{\R}
	\frac{\tphi(t-s)}{p^N(s) 
	\cdot s (p^N)'(s)}
	\frac{\overline{\varrho_{U,N,s}*\sphi}(y)}
	{\overline{\varrho_{\vY,N,s}*\sphi}(y)}
	\,ds \\
	&=\int_{H(y)} \int_{\R^4}
	\frac{\tphi(t-s)}{p^N(s) 
	\cdot s (p^N)'(s)}
	\frac{\sphi(\vy-\vx)}
	{\overline{\varrho_{\vY,N,s}*\sphi}(y)}
	\,\rho_{U,N}(ds\,d\vx)\,d\vy\,.
	\end{align*}
We will argue that the above converges pointwise to
	\[\Tuuu(t,y)
	= \int_{H(y)} \int_{\R^4}
	\frac{\tphi(t-s)}{p(s) 
	\cdot s p'(s)}
	\frac{\sphi(\vy-\vx)}
	{\overline{\varrho_{\vY,s}*\sphi}(y)}
	\,\rho_U(ds\,d\vx)\,d\vy\,.
	\]
In the above display for $\Tuuu^N(t,y)$, consider the rightmost expression in the first line. We will first argue that $\Tuuu^N(t,y)$ is close to
	\begin{align*}
	\Tuuu^{N,(1)}(t,y)
	&\equiv
	\int_{\R}
	\frac{\tphi(t-s)}{p(s) \cdot  s p'(s)}
	\frac{\overline{\varrho_{U,N,s}*\sphi}(y)}
	{\overline{\varrho_{\vY,N,s}*\sphi}(y)}
	\,ds\\
	&= \int_{H(y)} \int_{\R^4}
	\frac{\tphi(t-s)}{p(s) \cdot  s p'(s)}
	\frac{\sphi(\vy-\vx)}
	{\overline{\varrho_{\vY,N,s}*\sphi}(y)}
	\,\rho_{U,N}(ds\,d\vx)\,d\vy
	\,.
	\end{align*}
To this end, note it follows from 
Definition~\ref{d:sp.smooth} and Lemma~\ref{l:sp.smooth.reg}  that
	\[
	\|\sU^N\|_\infty
	= \sup_{s\in[q_0,1]} 
	\bigg\|
	\frac{\overline{\varrho_{U,N,s}*\sphi}}
	{\overline{\varrho_{\vY,N,s}*\sphi}}\bigg\|_\infty
	\le
	\bigg(
	\frac{\trK L}{\sep}\bigg)^{O(1)}
	(\MAX_N)^2
	\le
	\bigg(
	\frac{\trK L}{\sep}\bigg)^{O(1)}
	\,,
	\]
where the last bound holds for $N$ large enough by 
the bound \eqref{e.MAX.bound} from Proposition~\ref{p:Y.kolmogorov}.
The functions $p^N$ are concave and converge almost everywhere to $p$, and it is well-known that consequently $(p^N)'$ converges almost everywhere to $p'$. By the definition \eqref{e:qbar.and.qstar} of $\bar q$, both $1/p^N$ and $1/(p^N)'$ are uniformly bounded by $L^2$ on $[\bar q,1]$. For each $t\ge q_*$ and $s$ such that $t-s \in \mathsf{supp}(\tphi)$, we have $s\ge t-\tep \ge \bar q$. So, it follows by the bounded convergence theorem that
	\[\Big|
	\Tuuu^N(t,y)
	-\Tuuu^{N,(1)}(t,y)\Big|
	\le
	\bigg(
	\frac{\trK L}{\sep}\bigg)^{O(1)}
	\int_{\R}
	\bigg|\frac{\tphi(t-s)}
		{p^N(s) \cdot s (p^N)'(s)}
	-\frac{\tphi(t-s)}
		{p(s) \cdot s p'(s)}\bigg| \,ds
	\le o_N(1)\,.
	\]
Thus
$\Tuuu^N(t,y)$ is close to $\Tuuu^{N,(1)}(t,y)$, as claimed. We will next argue that $\Tuuu^{N,(1)}(t,y)$ is close to
	\[
	\Tuuu^{N,(2)}(t,y)
	\equiv
	\int_{H(y)} \int_{\R^4}
	\frac{\tphi(t-s)}{p(s) \cdot  s p'(s)}
	\frac{\sphi(\vy-\vx)}
	{\overline{\varrho_{\vY,s}*\sphi}(y)}
	\,\rho_{U,N}(ds\,d\vx)\,d\vy\,.
	\]
For this it suffices to note that the functions
$\overline{\varrho_{\vY,N,s}*\sphi}$ and 
$\overline{\varrho_{\vY,s}*\sphi}$ are bounded away from zero by the argument from Lemma~\ref{l:sp.smooth.reg} (cf.\ \eqref{e:denominator.lbd}), and are
uniformly close: 
	\begin{align*}
	&\sup_{s,y}\bigg\{ \Big|\overline{\varrho_{\vY,N,s}*\sphi}(y)
	-\overline{\varrho_{\vY,s}*\sphi}(y)\Big|\bigg\}\\
	&\qquad= \sup_{s,y}\bigg|
		\int_{H(y)} \bE\bigg\{ \sphi\Big(\vy-\vY^{\frozen,N}(s)\Big)
		-\sphi\Big(\vy-\vY^\frozen(s)\Big)\bigg\}\,d\vy\bigg| 
		\le o_N(1)\,,
	\end{align*}
where the last bou (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:Pn_moments of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let \(X=(H_N + A_N)(H_N + A_N)^*\) be the deformed inhomogeneous Wishart matrix of Definition~(def:wishart of the paper) with Gaussian entries, and let \(\{\mathcal P_n\}_{n\ge0}\) be a   family of polynomials defined by
\begin{equation}
    x^m \;=\;\sum_{n=0}^{m} C_{\mathrm{MP}}(m,n)\,\mathcal P_{n}(x), \quad m=0,1,\ldots,
\end{equation}
then for any nonnegative integers \(n_1,\dots,n_s\),
\begin{equation}
\mathbb{E}\Bigl[\prod_{j=1}^s \mathrm{Tr}\mathcal P_{n_j}(X)\Bigr]
=
\sum_{\Gamma\in\mathscr{D}_{s;\beta}}
\;\sum_{\eta:V(\Gamma)\to [M]\cup[N]}
\;\sum_{\substack{w_e \ge 1 \\ \sum_{e \in \partial D_j} w_e = n_j, \ \forall j}}
\;\prod_{e\in E_{\mathrm{int}}}p_{w_e}\bigl(\eta(x_e),\eta(y_e)\bigr)
\;\prod_{e\in E_b}(A^{w_e})_{\eta(z_e)\eta(w_e)}.
\end{equation}
Here
\begin{itemize}[leftmargin=2em]
  \item \(\mathscr{D}_{s;\beta}\) is the set of \(s\)-face ribbon graphs (orientable if \(\beta=2\)) (see Definition (def:diagram of the paper)),  
  \item \(E_{\mathrm{int}}\) denotes the interior edges of \(\Gamma\), and \(E_b\) its boundary edges (see Definition (def:diagram of the paper)),  
  \item for each interior edge \(e=(x_e,y_e)\),  \(p_{w_e}(\eta(x_e),\eta(y_e))\) denotes the \(n\)-step transition probability  (see (equation equ:transition_matrix of the paper) for the Markov chain),  
  \item for each boundary edge \(e=(z_e,w_e)\), \((A^{(w_e)})_{\eta(z_e)\eta(w_e)}\) is defined as in Proposition (prop:wishart_moment of the paper).  
\end{itemize}

[Proposition prop:first-counter-example-general of arXiv:2604.04882, 'On a Problem of M. Kac on Laplace Distributions'] Fix $\beta>0$ and $a_1,a_2>0$. Assume that either $0<\beta\le 2$ and $b\neq 0$ is arbitrary, or that $\beta>2$ and
    \begin{align}
        0<|b|<2\sqrt{\beta}\tan\!\left(\frac{\pi}{\beta}\right)\min\{\sqrt{a_1},\sqrt{a_2}\}.
    \end{align}
    Then the functions
    \begin{align}
        f_1(\xi)\coloneqq \left(1+\frac{a_1\xi^2-ib\xi}{\beta}\right)^{-\beta},
        \qquad
        f_2(\xi)\coloneqq \left(1+\frac{a_2\xi^2+ib\xi}{\beta}\right)^{-\beta}
    \end{align}
    are characteristic functions satisfying
    \begin{align}
        \Phi_\beta\bigl(f_1(\xi),f_2(\xi)\bigr)
        =
        \left(1+\frac{(a_1+a_2)\xi^2}{\beta}\right)^{-\beta}
        \in \cG_\beta,
    \end{align}
    but neither $f_1$ nor $f_2$ belongs to $\cG_\beta$.

