[Dfn 176 (approximate drift processes) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Define
$\barvD$ to be the process which starts from 
$\barvD(q_0)=\vY(q_0)$, is linear on each interval $q_d \le s \le q_{d+1}$, and has increments given by
	\beq
	\Delta\bar{D}^\sigma(q_d)
	\equiv \begin{cases}
	\displaystyle
	\Delta\bar{D}^\sigma\Big(q_d,B(q_d,a(q_d))\Big)
	\equiv
	\sum_{a\in B(q_d,a(q_d))}
	\frac{\Delta X^{\trunc,\sigma}(q_d,a)}
		{|B(q_d,a(q_d))|} 
	& \textup{for $\sigma\in\{\RomI,\RomII,\RomIII\}$,}\\
	\displaystyle
	\Delta\bar{D}^\sigma\Big(q_d,B^\Ising(q_d,i(q_d))\Big)
	\equiv \sum_{i\in B^\Ising(q_d,i(q_d))}
	\frac{\Delta X^{\trunc,\Ising}(q_d,i)}
		{|B^\Ising(q_d,i(q_d))|} 
	& \textup{for $\sigma=\Ising$.}\\
		\end{cases}
	\eeq
Similarly, we define $\barvD^\frozen$ to be the process which starts from 
$\barvD^\frozen(q_0)=\vY^\frozen(q_0)$, is linear on each interval $q_d \le s \le q_{d+1}$, and has increments given by
	\beq
	\Delta\bar{D}^{\frozen,\sigma}(q_d)
	\equiv \begin{cases}
	\displaystyle
	\sum_{a\in B^\frozen(q_d,a^\frozen(q_d))}
	\frac{\Delta X^{\frozen,\sigma}(q_d,a)}
		{|B^\frozen(q_d,a^\frozen(q_d))|}
	& \textup{for $\sigma\in\{\RomI,\RomII,\RomIII\}$,}\\
	\displaystyle
	\sum_{i\in B^{\Isplus}(q_d,i^\frozen(q_d))}
	\frac{\Delta X^{\Isplus}(q_d,i)}
		{|B^\Isplus(q_d,i^\frozen(q_d))|} 
	& \textup{for $\sigma=\Ising$.}\\
		\end{cases}
	\eeq
Write $B^\frozen=B^\frozen(q_d,a^\frozen(q_d))$, and note that 
if $B^\frozen\cap[M]=\emptyset$ then $
\Delta\bar{D}^{\frozen,\sigma}(q_d)=0$ for all $\sigma\in\{\RomI,\RomII,\RomIII\}$. Otherwise,
if $B^\frozen\cap[M]=B\ne\emptyset$, then we have
	\beq
	\Delta\bar{D}^{\frozen,\sigma}(q_d,B^\frozen)
	=
	\frac{|B|}{|B^\frozen|}
	\Delta\bar{D}^\sigma(q_d,B)
	\eeq
for all $\sigma\in\{\RomI,\RomII,\RomIII\}$. A similar relation holds for $\sigma=\Ising$.

[Lemma lem:alive-tree-supercritical-support-witness of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Assume the minimal Kahane--Peyri\`ere regime. Then \(\mathbb{P}(W>0)>1/2\). Hence
\begin{equation*}
\mathcal T^{+}:=\{v\in\mathcal T:Q_v>0\}
\end{equation*}
is a supercritical Galton--Watson tree with offspring law \(\operatorname{Binomial}(2,\mathbb{P}(W>0))\). Moreover, with
\begin{equation*}
A_n:=\#\{v\in\{0,1\}^{n}:Q_v>0\},
\end{equation*}
one has \(A_n\to\infty\) almost surely on \(\{\mu_\circ(\mathbb S^1)>0\}\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm Semicircular system asymptotics of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] For each $n$, let $(M_1,\dots,M_k)$ be a jointly Gaussian family of GOE random matrices such that
    \begin{equation}
        \begin{split}
            \mathbb{E}\left[(M_i)_{\ell_1,\ell_2} (M_j)_{\ell_1',\ell_2'}\right]= \left(\delta_{(\ell_1,\ell_2),(\ell_1',\ell_2')}+\delta_{(\ell_1,\ell_2),(\ell_2',\ell_1')}\right) \varphi_{i,j}.
        \end{split}
    \end{equation}
    Then,
    \begin{equation}
        \begin{split}
            \frac{1}{n^{1+\ell/2}}\mathbb{E}\left[\mathrm{Tr}(M_{i_1}\dots M_{i_{\ell}})\right] = \sum_{\pi \in NC_2[\alpha]} \prod_{(j,j') \in \pi} \varphi_{i_j,i_{j'}}+O(n^{-1}),
        \end{split}
    \end{equation}
    as $n \to \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 3 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Let $p\geq 2$ and~\eqref{co:1} and~\eqref{co:5} hold. Then pathwise uniqueness holds for~\eqref{eq:SIS epidemic model}, and any two solutions $I$ and $\tilde{I}$ to~\eqref{eq:SIS epidemic model} satisfy
\begin{equation*}
\E\big[|I_{t} - \tilde{I}_{t}|^{p}\big] \leq e^{\int_{0}^{t}\overline{\lambda}_{p}(s,N(s))\,\mathrm{d}s}\E\big[|I_{0} - \tilde{I}_{0}|^{p}\big]
\end{equation*}
for all $t\geq 0$ with $\overline{\lambda}_{p} := p(\hat{b}_{k+1} + \hat{\lambda}_{k+1} + c_{p}\lambda^{2})$. In particular, the integrability of $\overline{\lambda}_{p}^{+}(\cdot,N)$ entails that $\sup_{t\geq 0}\E[|I_{t} - \tilde{I}_{t}|^{p}] < \infty$. In this case,
\begin{equation*}
\int_{0}^{\infty}\overline{\lambda}_{p}^{-}(s,N(s))\,\mathrm{d}s = \infty\quad\text{implies}\quad \lim_{t\uparrow\infty} \E\big[|I_{t} - \tilde{I}_{t}|^{p}\big] = 0.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 of arXiv:2605.15931, '2605.15931'] For each $n \in \mathbb{N}$ and $1\leq k \leq \ell$, the processes
		$$
		F^{n,k}_{a}:=n^{1/2}\int_0^{\tilde{\tau}^n(X)\wedge a}\nabla f_k(X_s)\cdot \sigma(X_s)dW_s\,{\stackrel{\textnormal{a.s. and }L^1}{\to}}\, V^{n,k}
		$$
		as $a \to \infty$. We denote $F^n_a=(F^{n,1}_a,...,F^{n,\ell}_a)$ and $V^n=(V^{n,1},...,V^{n,\ell})$. We have
		$$
		V^{n}\,{\stackrel{\textnormal{w}}{\to}}\,  J_f(x)\sigma(x)W_{\tau^1(\sigma(x)W)}
		$$
		{as $n\to \infty$.}

