[Thm def:interac of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] {georgii2}}]
   For every $\mathsf{P}\in \mathcal P_{s,1}(\Gamma)$, the limit
   \begin{align}
    \mathcal W^{int}(\mathsf{P}):=\lim_{n\to \infty}\frac{1}{n}\int H_n(\xi)\mathsf{P}(d\xi)
\end{align}  
exists. For   $\mathsf{P}\in \mathcal P_{s,1}(\Gamma)$ with $\int \xi(\Lambda_1)^2\mathsf{P}(d\xi)<\infty$ the interaction energy admits the  representation 
\begin{align}
     \mathcal{W}^{int}(\mathsf{P})=\frac{1}{2}\int \sum_{0 \neq x\in \xi}\varphi(x)\mathsf{P}^0(d\xi).
\end{align}
For $\mathsf{P}\in \mathcal P_{s,1}(\Gamma)$ with $\int \xi(\Lambda_1)^2\mathsf{P}(d\xi)=\infty$ the limit is given by $\mathcal{W}^{int}(\mathsf{P})=\infty$.
For $\beta>0$ the free energy  $\mathcal F_{\beta}(\mathsf{P}):=\beta \mathcal{W}^{int}(\mathsf{P})+\mathcal E(\mathsf{P})$
is lower semicontinuous w.r.t.\ the topology $\mathcal T_{\mathcal L}$. Moreover, by assumption (assumption0 of the paper), the functional $\mathcal F_{\beta}$ is bounded from below by a finite constant. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:Schervish estimates of arXiv:2412.06420, 'Accuracy, Estimates, and Representation Results'] Assume $\mathsf{acc}_k:\mathsf{ConvHull}(\mathsf{Values}(V))\to\mathbb{R}$ is absolutely continuous for each $k\in\mathsf{range}(V)$.

		If $\mathsf{acc}$ is (strictly) proper for $V$ (we need: for finitely supported probabilities, $p$, $\mathrm{Exp}_p[\mathsf{acc}_V(x)]$ is maximised (uniquely) at $x=\mathrm{Exp}_p[V]$\footnote{In fact, we just need it for the $p_{k,r,t}$ constructed; these assign all their weight to two possibilities, where $V$ takes value $k$ and $r$}); then there is a (strictly) positive function $m$ such that for every $k\in\mathsf{range}(V)$ and $x\in\mathsf{ConvHull}(\mathsf{range}(V))$
			\begin{equation}
			\mathsf{acc}_k(x)=\mathsf{acc}_k(k)-\int_x^k(k-t)m(t)\dd{t}
		\end{equation}
		Moreover, $$m(t)=\frac{\mathsf{acc}_k'(t)}{k-t}$$ for all $k\in\mathsf{range}(V)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2608.22636, 'Q-Learning with Stable Infinite-Dimensional \\Linear Function Approximation'] Suppose Assumption \ref{assump:mix} holds with mixing time in Definition \ref{def:mixing_time}. Let $m:\mbb Z\to\R$ be bounded and centered; i.e, $\norm{m}\le b$ and $\int_\Z md\mu_b =0.$ Then
\begin{equation}
        v(z)
        :=
        \sum_{t=0}^{\infty}\int_\Z m(y)P_b^t(dy\mid z)

\end{equation}
is the unique bounded centered solution of
\begin{equation}
        v(z)-\int_\Z v(y)P_b(dy\mid z)=m(z),
        \quad \forall z\in\mbb Z,\quad \text{and}\quad \int_\Z v(z)\mu_b(dz)=0

\end{equation}
where the sum converges absolutely and uniformly. Moreover, $\norm{v}\le2\tmix b.$

[Cor 11 of arXiv:2609.03268, 'Poincare Polynomials of Heavy-Light Hassett Spaces'] Let $p_n(x)$ be as defined in \cref{thm:LM-ppoly-deg2-recursion}. Then for $n\ge 1$, 
                \begin{equation}

                    p_n(x)=\sum_{i=1}^n {n\choose i} (x-1)^{i-1}p_{n-i}(x).
                \end{equation}

[Lemma 12 of arXiv:2608.27569, 'Laplace and Dolbeault operators on Sasakian manifolds'] On $\Omega^m$, we have 
\begin{eqnarray*}
\lbrack L,\delta ] &=&d^{c}-(2n-m) \eta \wedge  \\
\text{ }[\Lambda ,d] &=&-\delta ^{c}+(2n-m+1) \xi \lrcorner. 
\end{eqnarray*}

