[Definition 4 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] {\em((Power) spectral density)}
  Let $(\mathbf{x}_t)_{t\geq 0}$  be a stationary process. Then 
  \begin{align}
    S_\mathbf{x}(\omega)=\lim_{T\to\infty} \E\left[\frac{|G_T(\omega)|^2}{2T}\right]
\end{align}
is called (power) spectral density.

[Lem SymAd of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] One has 
\begin{align*}
 & A_{1}\partial_{{\rm e}_{1}}\hat{\otimes}_{{\rm s}}\cdots\hat{\otimes}_{{\rm s}}A_{r}\partial_{{\rm e}_{1}}({\rm ad}_{{\rm e}_{1}}^{l}(v))\\
 & =\sum_{\sigma\in{\cal S}_{r}}\sum_{\substack{\substack{\xi_{1}+\cdots+\xi_{r+1}}
=l-r}
}{\rm ad}_{{\rm e}_{1}}^{\xi_{1}}\circ{\rm ad}_{A_{\sigma(1)}}\circ{\rm ad}_{{\rm e}_{1}}^{\xi_{2}}\circ\cdots\circ{\rm ad}_{{\rm e}_{1}}^{\xi_{r}}\circ{\rm ad}_{A_{\sigma(r)}}\circ{\rm ad}_{{\rm e}_{1}}^{\xi_{r+1}}(v)
\end{align*}
for any $l\geqslant r\geqslant1$.

[Prop 3 of arXiv:2609.02392, 'Large values of cubic and quartic Dirichlet $L$-functions of prime moduli'] With the notation as above, let $j=3$, $4$ and $\psi$ be any ray class character modulo $9$ (resp. $16$) when $j=3$ (resp. $j=4$) and let $r$ be any primary element in $\mathcal O_K$. Then we have for real $Z>1$ and $\varepsilon>0$, we have
\begin{align*}

\begin{split}
  H_Z(r;\psi) := \sum_{\substack {c \odd \\ (c, r)=1 \\ N(c) \leq Z}} \frac {\Lambda_K(c)\psi(c) g_{K,j}(r, c) }{\sqrt{N(c)}}  \ll &
\begin{cases}
   \min (Z^{1+\varepsilon},  N(r)^{1/10+\varepsilon}Z^{4/5+\varepsilon}), & j=3, \\ \\
   \min (Z^{1+\varepsilon},  N(r)^{1/16+\varepsilon}Z^{7/8+\varepsilon}), & j=4.
\end{cases}
\end{split}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm discrete-conv of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] Let $\tau_\delta$ be a critical XOR-Ising model in the setup of Theorem (thm:ES-XOR of the paper). As $\delta\to 0$, 
    \begin{equation}
        \big(\delta^{-1/4}\tau_\delta,\ (\delta^{-1/4}\mu_k^\delta)_{k\geq1},\ (C_k^\delta)_{k\geq1},\ (\xi_k^\delta)_{k\geq1}\big) \overset{(d)}{\longrightarrow} \big(\tau,\ (\mu_k)_{k\geq1},\ (C_k)_{k\geq1},\ (\xi_k)_{k\geq1}\big),
    \end{equation}
    where the limiting law is that of Theorem (thm:cont-XOR of the paper). Under the obvious modifications, the same statement holds for $+/+$ boundary conditions. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma apx_lemma: random_walk_expected_hitting_size of arXiv:2512.06640, 'Existence and sharpness of the phase transition for the frog model on transitive graphs'] Let $G$ be a quasi-transitive graph of superlinear polynomial growth.

    For any $K_1, K_2 \ge 1$, there exist constants $c = c(G, K_1, K_2)$ and $C = C(G)$, such that for any $a \ge 2$, $x \in V$, and $D \subseteq B_x(K_1 a)$ with $|D| \ge |B_x(a)|/K_2$, we have



    \begin{align}
        c \cdot \theta(a) \leq \sum_{y \in D} \mathbb P_x \left( \tau_y \le a^2 \right) \leq C \cdot \theta(a) \, ,
    \end{align}
    where $\theta(a)$ is defined as 
    \begin{align*}
        \theta(a) := \begin{cases}
            a^2 & \text{if } d \geq 3, \\
            a^2 / \log a & \text{if } d = 2.
        \end{cases}
    \end{align*}

