[Prop LT-1 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Given $\eta \in (0,\frac{1}{2}-\gamma)$, for each $\theta \geq 0$ there exists a constant $C=C(\theta,\gamma) > 0$ such~that, if $k$ is sufficiently large, given any integer $j > 1$, $n \geq k$ and $\widetilde{x} \in {\rm D}_n$ with $\overline{{\rm B}^+[\widetilde{x};j]}\subseteq {\rm D}_n$, we have that 
	\begin{equation}

 {\rm e}^{-2\sqrt{2}\widehat{v}-\frac{\widehat{v}^2}{k+jk^\gamma}-Ck^\gamma} \leq \mathbb{P} \bigg( \min_{x \in {\rm B}^-[\widetilde{x};j-1]}L_t(x) \leq \theta \,\Big|\, \sqrt{\widehat{N}_t[\widetilde{x};j]} \geq v \,; 
\mathcal F[\widetilde{x};j]\bigg) \leq  {\rm e}^{- 2\sqrt{2}\widehat{v}+Ck^\gamma}
\end{equation} uniformly over all $t >0$ and $v \in \mathcal R^\eta_k(j)$, where above we abbreviate $\widehat{v}:=v-\sqrt{2}(k+(j-1)k^\gamma)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:negative-potential-results of arXiv:2608.18320, 'Asymptotics for Beta-Splitting Trees via Homogeneous Fragmentations and Meromorphic Potent'] For $-2<\beta<0$,
    \begin{equation}
            U_\beta(\mathrm{d} x)
            =\eta_\beta\delta_0(\mathrm{d} x)
            +\left[
            \frac1{\mu_\beta}
            +\sum_{k\ge1}
            \frac{e^{s_{\beta,k}x}}{\phi_\beta'(s_{\beta,k})}
            \right]\mathrm{d} x.
    \end{equation}
    The residues $1/\phi_\beta'(s_{\beta,k})$ are positive, and the series
    converges locally uniformly for $x>0$.  Equivalently, for $\textnormal{Re} z>0$,
    \begin{equation}
            \frac1{\phi_\beta(z)}
            =\eta_\beta+\frac1{\mu_\beta z}
            +\sum_{k\ge1}
            \frac1{\phi_\beta'(s_{\beta,k})(z-s_{\beta,k})}.
    \end{equation}
    In particular,
    \begin{equation}
            \eta_\beta
            -\sum_{k\ge1}
            \frac1{s_{\beta,k}\phi_\beta'(s_{\beta,k})}
            =-\frac{\phi_\beta''(0)}{2\mu_\beta^2}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 3 of arXiv:2608.20980, 'A Critical Audit of Spatiotemporal Forecasting Benchmark Datasets and Baselines'] The SARIMA$(p,d,q)(P,D,Q)_s$ model is defined as the model that satisfies the following equation:
  \begin{equation}

    \Phi(B_s) \phi(B) \nabla^d \nabla_s^D y_t = \Theta(B_s) \theta(B) \epsilon_t.
  \end{equation}

[Proposition 16 (Uniform coalescence) of arXiv:2608.30211, '2608.30211'] One has
\begin{equation}
 \lim_{\kappa\to\infty}
 \sup_{\varrho\in[0,1]}
 \sup_{u\in\cU_{\kappa,\varrho}}
 \|u-\Phi_{\kappa,\varrho}\|_{L^\infty(D_\kappa)}=0.
\end{equation}
The supremum over an empty solution set is understood as zero.

[Lemma lem:iidmax of arXiv:2601.20502, 'Optimal matching under size priority'] Let $G$ be a finite graph. Consider $M_{\mathrm{opt}}$ to be the maximum weight maximum size matching on $G$ when we pick a family $w(e)_{e \in E(G)}$ of weights. Formally, define $W^{\mathrm{bad}}\subseteq \mathbb{R}_+^{E(G)}$ to be the set of weights such that there are ties, and $\mathcal{M}_{\mathrm{max}}$ to be the set of maximal matchings on $G$. Then $M_{\mathrm{opt}}$ is the map defined as
    \begin{align*}
        \mathbb{R}_+^{E(G)} \setminus W^{\mathrm{bad}} &\to \mathcal{M}_{\max} \\
        w(e)_{e \in E(G)} &\mapsto M_{\mathrm{opt}}(w(e)_{e \in E(G)}).
    \end{align*}
     The range of $M_{\mathrm{opt}}$ is precisely $\mathcal{M}_{\max}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 36 of arXiv:2608.29872, 'Local Laws and Outlier Eigenvalues for Spiked Separable Covariance Matrices'] Under the assumptions of Theorem \ref{distribution of outliers}, set $z=\theta_i^a+\ii n^{-2}$ for some $1\le i \le r$. Then, for $\mathcal{P}_i^a\equiv \mathcal{P}_i^a(z)$ and any fixed $\ell\geq 2$, we have 
\begin{equation}
\begin{aligned}
\expect[(\mathcal{P}_i^a)^\ell]=&~(\ell-1)\pbb{\frac{d_i^a+1}{d_i^a}}^4(\sigma_i^a)^2\pB{2m_{2a}(\theta_i^a)+k_4b(\theta_i^a)s_4(\vv_i^a)}\expect[(\mathcal{P}_i^a)^{\ell-2}] +\OO_\prec(n^{-1/6}).
\end{aligned}
\end{equation} 
Moreover, for $\ell=1$, we have $\expect[\mathcal{P}_i^a]=\OO_\prec(n^{-\e})$ for some constant $\e>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Conj maps pairs of arXiv:2609.02409, 'Membranes and Maps'] The stable pair series lifts to a rational function in $q$ satisfying
    \begin{equation}
        \ch[\mathsf{T}] \, \PTargs{X}{Z}{\mathsf{T}'}{\beta}
        =
        \GWdiscargs{Z}{\mathsf{T}}{\beta} 
    \end{equation}
    under the change of variables induced by the Chern character $\ch[\mathsf{T}] \colon \mathrm{Rep}(\mathsf{T}) \to \widehat{\mathsf{R}}$. (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Theorem theorem 1 of arXiv:2411.14350, 'Randomized Geodesic Flow on Hyperbolic Groups'] There exists a measure $\Theta$ on $\partial^2 G$ satisfying 
\begin{equation}
\frac{{\rm{d}}\Theta}{{\rm{d}} (\nu_o\otimes\nu_o)} (\xi,\eta)\asymp {\rm e} ^{2(\xi,\eta)_o^{{\mathcal G}}} \qquad\forall (\xi,\eta)\in \partial^2 G, 
\end{equation}
which can be constructed explicitly in the following three measure-equivalent ways:
\begin{enumerate}
\item As the measure $\Theta_1$ given by
\begin{equation}
\Theta_1(A) = \int_{A} \lim_{n\to\infty} \sum_{z=-n}^n\bigg[\frac{1}{2n+1} \, \frac{{\rm{d}}(\nu_{p_z}\otimes \nu_{p_z})}{{\rm{d}}(\nu_{o}\otimes \nu_{o})}(\xi,\eta)\bigg]\;{\rm{d}}(\nu_{o}\otimes \nu_{o})(\xi,\eta)
\end{equation}
for $A\subset \partial^2 G$, where $(p_z)_{z\in\mathbb{Z}}=(p_z(\xi,\eta))_{z\in\mathbb{Z}}$ is a fixed quasi-geodesic between $\xi$ and $\eta$. 
\vspace{2mm}
\item As a disintegrated version $\Theta_2$ of $\Theta_1$, defined by
\begin{equation}
\Theta_2(A) = \int_{A} \lim_{n\to\infty} \sum_{z=-n}^n \bigg[\frac{1}{2n+1} \,\frac{{\rm{d}}(\nu_{x_z}\otimes \nu_{x_z})}{{\rm{d}}(\nu_{o}\otimes \nu_{o})}(\xi,\eta)\bigg]\;{\rm{d}}\bar\mathbb{P}_o\big((x_n)_{n\in\mathbb{N}}\big),
\end{equation}
for all $A\subset\partial^2 G$, where $\xi={\rm bd} (x_n)_{n\in\mathbb{N}}$ and $\eta={\rm bd} (x_{-n})_{n\in\mathbb{N}}$.
\vspace{2mm}
\item  As the push forward $\Theta_3(\cdot)= \widehat\mathbb{Q}({\rm bd} ^{-1}(\cdot))$ of the measure $\widehat\mathbb{Q}$ (defined in (equation def QZ int of the paper)) under the boundary map ${\rm bd} : G^{\mathbb{Z}}\to \partial^2 G$. The measure $\Theta_3$ is invariant under the action of $G$ on $\partial^2G$. 
\end{enumerate}
Finally, the measure $\Theta$ on $\partial^2 G$ is 
\begin{itemize}
    \item quasi-invariant under the $G$-action with uniformly bounded Radon-Nikodym derivatives $\frac{{\rm{d}} g_{\ast}\Theta}{d\Theta}$, and
    \item ergodic under the action of $G$ on $\partial^2 G$. 
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

