[Theorem 36 of arXiv:2608.27307, '2608.27307'] Under Assumptions~\ref{ass:basic} and~\ref{ass:rand_ent}, fix $\tau>0$ sufficiently small. Let $z=E+\ii\eta$ satisfy
        \begin{align}
                z\in\mb D(\tau,\eta_0), \qquad \eta\geq N^{-1+\tau}, 
        \end{align}
        and suppose that $\|\Pi(z)\|\lesssim1$. Let $\phi\in[N^{-1},N^{\tau/10}]$ and $\vphi>0$ be deterministic, with
        \begin{align}
                0<\vphi\lesssim\|\Im\Pi(z)\|+\phi, 
        \end{align}
        and assume that $ G(z)-\Pi(z)=O_\prec(\phi)$ and $ \Im G(z)=O_\prec(\vphi)$.
        Then, we have
        \begin{align}
                \Om(G(z),z) = O_\prec \left((1+\phi)^3\sqrt{\frac{\vphi+\eta}{N\eta}}\right). 
        \end{align}
        Moreover, for every deterministic matrix $B\in\C^{L\times L}$ with $\|B\| = O(1)$, we have
        \begin{align}
                \avg{B\Om(G(z),z)}_L = O_\prec \left((1+\phi)^6\frac{\vphi+\eta}{N\eta}\right). 
        \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem Lem6.2-replacement of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] Let $R_l, R_r$ be left and right halves of $R$. There exist $c_5, c_6$ (independent of $\beta$) such that for all $\beta>\beta_0$ and $\ell \ge \beta e^{2\beta}$, and $\sqrt{C \log \ell} \le\bar \alpha \le (1/s)\sqrt{\ell}$ for $C$ large independent of $\beta$,
    \begin{align*}
        \pi_R^\eta(\lambda_1 \subset R_l, \lambda_2 \subset R_r \mid \partial \lambda_1 = \{x,u\}\,,\,\partial\lambda_2 = \{y,v\}) \ge 1- \ell^{c_5} e^{ - c_6 s \bar \alpha^2}
    \end{align*}

