[Lemma hitting_immediate_neighbours_whp of arXiv:2411.10113, 'Long-range one-dimensional\\ internal diffusion-limited aggregation'] Suppose that~(equation ass:irreducible of the paper) holds. For $1 < \alpha \leq 2$, suppose in addition that (if $\alpha = 2$) $\Exp ( X^2 ) < \infty$ and $\Exp X =0$, or (if $1<\alpha<2$) that~(equation ass:stable-alpha of the paper) holds. 
Then the following hold.
\begin{thmenumi}[label=(\roman*)]
\item For any $\varepsilon>0$, there exist $\delta >0$ and $N_0 \in {\mathbb N}$, such that, for all $N \geq N_0$ and every $k \in {\mathbb Z}$ with $| k | \le \delta  N$,
\begin{equation}

\bP_k \left( T_0 <  \eta_{(-\infty, N]} \right) \ge 1-\varepsilon.
\end{equation}
\item For any $\varepsilon >0$ and $c>0$, 
there exist $\delta >0$ and $N_0 \in {\mathbb N}$, such that, for all $N \geq N_0$ and every $k \in {\mathbb Z}$ with $|k| \le \delta N$,
\begin{equation}

\bP_k \left( T_0 < \eta_{[-cN, N]} \right) \ge 1-\varepsilon.
\end{equation}
\end{thmenumi}

