[Proposition 4 (Posterior expectations of the complete-data sufficient statistics) of arXiv:2608.21551, '\bf Sparse Separable Factor Analysis in the Complex Domain with an Application to Local Fi'] At iteration $t$, define
\begin{align*}
  \widetilde{\Sigmab}^{(t)}
  =
  \tilde{\Lambdab}^{(t)}
  \Gammab^{(t)}
  \tilde{\Lambdab}^{(t)\star}
  +
  \Psib^{(t)},\quad
  \widetilde{\Ab}^{(t)}
  =
  \Gammab^{(t)}
  \tilde{\Lambdab}^{(t)\star}
  \left(\widetilde{\Sigmab}^{(t)}\right)^{-1},\quad
  \widetilde{\Cb}^{(t)}
  =
  \Gammab^{(t)}
  -
  \widetilde{\Ab}^{(t)}
  \tilde{\Lambdab}^{(t)}
  \Gammab^{(t)}.
\end{align*}
Then, the conditional distribution of the latent factor matrix is
\begin{align*}
  \tilde{\Zb}\mid\Xb,\tilde{\thetab}^{(t)}
  \sim
  \mathbb{C}\Ncal_{k\times n}
  \left(
    \widetilde{\Ab}^{(t)}\Xb,
    \widetilde{\Cb}^{(t)},
    \Ib_n
  \right),
\end{align*}
and the posterior expectations of the complete-data sufficient statistics in \eqref{eq:sufficient_stat_defs} are
\begin{align}

  \tilde{\Zb}^{(t)}
  =
  \widetilde{\Ab}^{(t)}\Xb, \qquad
  \widetilde{\Sbb}_{zz}^{(t)}
  =
  n\widetilde{\Cb}^{(t)}
  +
  \tilde{\Zb}^{(t)}
  \tilde{\Zb}^{(t)\star}.
\end{align}

[Lemma eq:N(B/eta) of arXiv:2609.01825, 'On everywhere locally soluble varieties \\ in families over toric bases'] If $B_d>1$ and $\eta_d\ge 1$, then
 \begin{equation}
	N_d\!\left(\frac{B_d}{\eta_d}\right) = 
	c_d\left(\frac{B_d}{\eta_d}\right)^{a_d} (1+\log B_d)^{-\Delta_d} (1 + O((1+ \log \eta_d)(1+\log B_d)^{-\delta})).
 \end{equation}

