for some  $c_1,C_1>0$ that do not depend on $\varepsilon$, $n$, $i$ or $j$. For $(x,s;y,t) \in ...","release_manifest_digest":"sha256:f00e0708bfb477ac969dcacf5baa9a6c269b8e1bd205a7efb064f5c236efbfe5","revision_digest":"sha256:f32facc8715ada876c5c6e69eaeb505bc26e7542159cf72e13d8f31ea1a1062b","source_id":"arxiv:2607.18104","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

