body:
[Proposition prop:F_upper_bound of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] With the same notation and assumptions (itm:B1 of the paper)-(itm:B2 of the paper) in Definition (mixingdef of the paper), with $\|A_N\|_{\mathrm{op}}=a$, the following upper bounds hold.
\begin{enumerate}[label=(\roman*)] 
    \item  
        If $\Gamma\in \mathscr{D}_{s;\beta}^*$  is a diagram without any open edge,  then 
         \begin{equation}
        \left|F_{\Gamma}(\{n_j\})\right|\le\frac{n^{|V|-1}}{(|V|-1)!}\Big(\frac{(\gamma t_N)\lor n}{N}\Big)^{|E|-|V|+1} N,
    \end{equation}
        while particularly 
        for $|E|\le \frac{n}{t_N}$, 
    \begin{equation}
         \left|F_{\Gamma}(\{n_j\})\right|\le \frac{(5 \gamma n)^{|E|}}{(|E|-1)!}N^{|V|-|E|}.
    \end{equation}


    \item  If   $\Gamma\in\mathscr{D}_{s;\beta}^{*}$ is a diagram with at least one open edge,  then  \begin{equation}
         \left|F_{\Gamma}(\{n_j\})\right|\le (1+a^n)r^{|V_{\mathrm{b}}|}\Big(\frac{(\gamma t_N)\lor n}{N}\Big)^{|E_{\mathrm{int}}|-|V_{\mathrm{int}}|}\frac{n^{|V|}}{(|V|)!},
    \end{equation}
    while particularly 
    for $|E_{\mathrm{int}}|\le \frac{n}{t_N}$, 
    \begin{equation}
         \left|F_{\Gamma}(\{n_j\})\right|\le 10^{|E|}\gamma^{|E_{\mathrm{int}}|}(1+a^n)r^{|V_{\mathrm{b}}|}\frac{n^{|E|}}{(|E|-1)!}N^{|V_{\mathrm{int}}|-|E_{\mathrm{int}}|}.
    \end{equation}
\end{enumerate}

