[Definition def:solution of arXiv:2412.01381, 'Ergodicity and mixing for locally monotone stochastic evolution equations'] An $H$-valued continuous $({\mathcal F}_t)_{t\in [0,T]}$-adapted process $(X_t)_{t\in [0,T]}$ is called a \emph{solution} to~(equation eq:model of the paper) if for its $\mathrm{d} t\otimes\mathbb{P}$-equivalence class $\widehat{X}$, we have
\begin{enumerate}
\item For some $\tilde{\alpha}>1$, $\widehat{X}\in L^{\tilde{\alpha}}([0,T];V)\cap L^2([0,T];H)$, $\mathbb{P}$-a.s.
\item For any $V$-valued $({\mathcal F}_t)_{t\in [0,T]}$-progressively measurable $\mathrm{d} t\otimes \mathbb{P}$-version $\overline{X}$ of $\widehat{X}$ it holds that
\begin{equation*}
X_t=x+\int_0^t A(\overline{X}_s)\,\mathrm{d} s+B \,W_t,\quad t\in [0,T],\quad\mathbb{P}\text{-a.s.}
\end{equation*}
\end{enumerate}

