body:
[Definition 9 of arXiv:2607.18104, '2607.18104'] Assume, as above, the directed landscapes $\big\{(\mathcal{L}^{i,1},\mathcal{L}^{i,2}):i\in  \lbr n\rbr\big\}$ are coupled via the law $\mathbf{P}_n$ described above \eqref{eq:GoodCoupling}, and recall the notation $ \mathcal{L}^{\mathcal{R}}$ from \eqref{eq:LReqn}.

We define the scale $n\in \N$ \textbf{unwrapped patched directed landscape} as the random function $\Lpat:\SetR\to\R \cup \{-\infty\}$ given as follows. For all $(x,s;y,t) \in \SetR \cap \mathcal{V}_{n}$ we set 
\begin{equation}
\Lpat(x,s;y,t) := \begin{cases}  \mathcal{L}^{\mathcal{R}}(x,s;y,t) &\text{ if } \pi^{\mathcal{R},+}_{x,s;y,t}\text{ and }\pi^{\mathcal{R},-}_{x,s;y,t} \subseteq \mathcal{R}, \\
-\infty &\text{ else}. 
\end{cases}
\end{equation} 
For such $(x,s;y,t)\in \SetR \cap \mathcal{V}_{n}$ we say that a continuous path $\bar\pi:[s,t]\to \R$ is an \textbf{unwrapped inherited geodesic} for the scale $n$ unwrapped patched directed landscape if $\Lpat(x,s;y,t)\neq -\infty$ and $\bar\pi$ is a geodesic for $\mathcal{L}^{\mathcal{R}}$.

For all other $(x,s;y,t) \in \SetR \setminus \mathcal{V}_{n}$, either 
$s,t\in \big[\frac{i-1}{n},\frac{i}{n}\big]$ for some $i\in \lbr n\rbr$, or not. 
In the case when $s,t\in \big[\frac{i-1}{n},\frac{i}{n}\big]$, we set $\Lpat(x,s;y,t):=-\infty$ and say that  no unwrapped inherited geodesic exists between $(x,s)$ and $(y,t)$.
In the other case, where $s\in \big[\frac{i-1}{n},\frac{i}{n}\big]$ and $t\notin \big[\frac{i-1}{n},\frac{i}{n}\big]$ for some $i\in \lbr n\rbr$, we define $\Lpat(x,s;y,t)$ as follows. Assuming, inductively, that $\Lpa(x,s;y,t)$ is defined for $t\in \big(s,\frac{k}{n}\big]$ for some $k\geq i$ (the base case $k=i$ is above) then for $t\in \big(\frac{k}{n},\frac{k+1}{n}\big]$, 
\begin{equation}
\Lpat(x,s;y,t) := \sup_{(\tilde{x},\tilde{s}) \in \partial \mathcal{R}^{k}_n} \Lpat(x,s;\tilde{x},\tilde{s}) +  \Lpat(\tilde{x},\tilde{s};y,t). 
\end{equation}
The unwrapped inherited geodesic is similarly inductively defined. Assume that we have specified the definition of the unwrapped inherited geodesics for $t\in \big(s,\frac{k}{n}\big]$ for some $k\geq i$ (the base case $k=i$ definition is above). Then, for $t\in \big(\frac{k}{n},\frac{k+1}{n}\big]$, we say that a path $\bar\pi:[s,t]\to\R$ is an unwrapped inherited geodesic if its restriction to $[s,\frac{k}{n}]$ and $[\frac{k}{n},t]$ are both unwrapped inherited geodesic and if the pair $\big(\bar\pi(\frac{k}{n}),\frac{k}{n}\big)$, realizes the supremum in \eqref{eq:RecursionDL}. In all cases above, if no path satisfies the condition of being an unwrapped inherited geodesic between $(x,s)$ and $(y,t)$ then we say that no such geodesic exists.

By construction, the unwrapped patched directed landscape $\Lpat$ is $1$-periodic in the horizontal coordinates, i.e., $\Lpat(x,s;y,t)=\Lpat(x+\ell,s;y+\ell,t)$ for all $\ell\in \Z$. We can now define the  scale $n\in \N$ \textbf{wrapped patched directed landscape} by setting for all $(x,s;y,t) \in \SetT$
\begin{equation}
\Lpa(x,s;y,t):= \sup_{\ell\in \Z}\Lpat(x+\ell,s;y,t). 
\end{equation}
A path $\pi:[s,t]\to \mathbb{T}$ on the torus is called a \textbf{wrapped inherited geodesic} if there exists an unwrapped inherited geodesic $\bar\pi:[s,t]\to \R$ such that $\bar\pi(s) = x+\ell$ where $\ell$ achieves the supremum in \eqref{eq:ExtendPatched}, and such that $\pi(\tilde s)= \bar\pi(\tilde s) \mod 1$ for all $\tilde{s}\in[s,t]$. Since we assume all inherited geodesics are continuous paths, $\bar\pi$ is uniquely determined from $\pi$ and we call it the unwrapping of $\pi$. 
We call an unwrapped inherited geodesic $\pi$ between $(x,s)$ and $(y,t)$ leftmost if for all other unwrapped inherited geodesics $\tilde\pi$, $\pi(\tilde s)\leq \pi(\tilde s)$ for all $\tilde s\in[s,t]$ (and rightmost if $\leq $ is replaced with $\geq$). We call a wrapped inherited geodesic leftmost (or rightmost) if its unwrapping is the leftmost (or rightmost) unwrapped inherited geodesic.

[Definition 63 of arXiv:2607.18104, '2607.18104'] Fix $\delta>0$ and $M\in \N$, and assume that the Bernoulli paths $(h_0^{i,1,1})_{i \in \lbr M \rbr}$ and $(h_0^{i,2,1})_{i \in \lbr M \rbr}$ are all $(N,k)$-periodic and satisfy  $h_0^{i}:=h_0^{i,1,1}=h_0^{i,2,1}$ for all $i \in \lbr M \rbr$. We define for all $t\in [0,\delta N^{3/2}]$ and $i \in \lbr M \rbr$ the $\boldsymbol{(\delta,N)}$\textbf{-patched ASEP height function} 
\begin{equation}
h^{\textup{patch},\delta}(h^{i}_0;y,t) := \begin{cases} \hA_{1,1}\big(h_0^{i,1,1},0;y,t\big) & \text{ if } (y,t) \in \mathcal{I}_{\delta,N}^{\rho}\big(0,\frac{1}{2}\big) ,   \\
\hA_{2,1}(h_0^{i,2,1},0;y,t) & \text{ if } (y,t) \in \mathcal{I}_{\delta,N}^{\rho}\big(\frac{1}{2},1\big) . 
\end{cases}
\end{equation} For all $t\geq 0$ and $i\in \lbr M \rbr$, recall $f(t)$ from \eqref{def:Functionf}, and let the number of particles between $f(t)+\frac{1}{4}N$ and $f(t)+\frac{5}{4}N$ for the patched ASEP with initial conditions $h_0^{i}$ be defined as
\begin{equation}
    K^{i}_t := h^{\textup{patch},\delta}\Big(h^{i}_0;f(t),t\Big) -  h^{\textup{patch},\delta}\Big(h^{i}_0;f(t)+N-1,t\Big) . 
\end{equation}
We now obtain $h^{\textup{patch},\delta}$ for all $(y,t) \notin \mathcal{I}_{\delta,N}^{\rho}\big(0,1\big)$ by extension so that $h^{\textup{patch},\delta}(h^{i}_0;\cdot,t)$ is an $(N,K_t^{i})$-periodic Bernoulli path. Now suppose that we have constructed the $(\delta,N)$-patched ASEP height function until time $j\delta N^{3/2}$ (the base case $j=1$ is covered above). Then we set 
\begin{equation}
h^{\textup{patch},\delta}(h^{i}_0;y,t) := \begin{cases} \hA_{1,j}\big(h_{j\delta N^{3/2}}^{i,1,j},0;y,t\big) & \text{ if } (y,t) \in \mathcal{I}_{\delta,N}^{\rho}\big(0,\frac{1}{2}\big) ,   \\
\hA_{2,j}(h_{j\delta N^{3/2}}^{i,2,j},0;y,t) & \text{ if } (y,t) \in \mathcal{I}_{\delta,N}^{\rho}\big(\frac{1}{2},1\big) , 
\end{cases}
\end{equation}
for all $(y,t) \in \mathcal{I}_{\delta,N}^{\rho}\big(0,1\big)$ with $t \in [j\delta N^{3/2},(j+1) \delta N^{3/2}]$, and define $h^{\textup{patch},\delta}(h^{i}_0;y,t)$ outside of $\mathcal{I}_{\delta,N}^{\rho}\big(0,1\big)$ by extension to a periodic path as for the base case $j=1$.

[Thm Inverse3 of arXiv:2609.01350, 'New classes of trace-form permutation polynomials and their compositional inverses'] Let $q=2^m$, $f_2(x)=x+\gamma {\rm Tr}_{q}^{q^2} (c_1 x+ c_2 x^2+ c_3x^3+c_3x^{q+2}+x^{2q-1}),$ where $c_1 \in \mathbb F_{q^2}$, $c_2, c_3  \in \mathbb F_{q}$ and $\gamma \in \mathbb F_{q}^*$ such that $1+\gamma{\rm Tr}_q^{q^2}(c_1)=\gamma$. Then the compositional inverse of $f_2(x)$ is
\begin{equation}
  f_2^{-1}(x)=
  \begin{cases}
    \gamma^{-1}x
      & \text{if } x\in\mathbb F_q,\\[0.8em]
    x+h_2(x)+\dfrac{x^3+x^{3q}}{x^{q+1}}
      & \text{if } x\notin\mathbb F_q,\ \beta=0,\\[0.8em]
    x+h_2(x)+\dfrac{x^3+x^{3q}}{x^{q+1}}+R+\dfrac{\beta}{R}
      & \text{if } x\notin\mathbb F_q,\ \beta\neq0,\ m \text{ odd},\\[0.8em]
    x+h_2(x)+\dfrac{x^3+x^{3q}}{x^{q+1}}
      +\dfrac{\theta^{(q+2)/3}+\theta^{(2q+1)/3}}{\beta}
      & \text{if } x\notin\mathbb F_q,\ m \text{ even},
  \end{cases}
\end{equation}
where
\[
  \beta=h_2(x)^2+(x+x^q)\,h_2(x)
        +\frac{(x+x^q)^6}{x^{2q+2}}
        +\frac{(x+x^q)^4}{x^{q+1}}
        +(x+x^q)^2+x^{q+1},
\]
\[
  R=\bigg(\beta\,(x+x^q)\sum_{i=0}^{(m-1)/2}
      \Big(\frac{\beta}{(x+x^q)^2}\Big)^{4^i}\bigg)^{1/3},
\]
and, in the last case, $\theta\in\mathbb F_{q^2}\setminus\mathbb F_q$ is either
root of $\theta^2+\beta(x+x^q)\theta+\beta^3=0$ (both roots give
the same value). For $m$ even one always has $\beta\neq0$, so the
four cases are exhaustive.

[Definition 220 (Functions of the second kind, type II and III) of arXiv:2601.16377, '2601.16377'] For each $g \in [H]$, let $\gamma(\alpha_g)$ (respectively $\gamma(\beta_g)$) be a small positively oriented circular loop around $\alpha_g$ (respectively $\beta_g$). If $f_g(z)$ is a meromorphic function in a complex neighborhood $\amsmathbb{M}_g$ of $[\alpha_g,\beta_g]$ with possible poles only at $\alpha_g,\beta_g$, then we define for any $h \in [H]$
\begin{equation}

\begin{split}
\mathfrak{F}_h^{\textnormal{II}}[\boldsymbol{f}](z) & = \sum_{g = 1}^H \left[\oint_{\gamma(\alpha_g)} + \oint_{\gamma(\beta_g)}\right] \frac{\dd \zeta}{2\ii\pi}\left(\frac{\delta_{g,h}}{2(z - \zeta)^2} + \big \langle \bth_g \cdot \mathcal{F}_{h,\bullet}(z,\zeta)\big \rangle\right) \sigma_g(\zeta) f_g(\zeta), \\
\mathfrak{F}_h^{\textnormal{III}}[\boldsymbol{f}](z) & = \sum_{g = 1}^H \left[\oint_{\gamma(\alpha_g)} + \oint_{\gamma(\beta_g)}\right] \frac{\dd\zeta}{2\ii\pi} \left(\frac{1}{2(z - \zeta)^2} + \sum_{g' \neq g} \theta_{g,g'} \mathcal{F}_{h,g'}(z,\zeta) \right)\frac{f_g(\zeta)}{\theta_{g,g}},
\end{split}
\end{equation}
where $z$ is outside the contours of integration.

[Lemme 60 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] Let $\mu \in \mathcal{M}_1(\mathbb{R})$ be compactly supported and such that

\begin{align}

1 + \frac{2}{\ell} \Int{\mathbb{R}}{} \ln|x-y| \, \mathrm{d}\mu(y) \geq \kappa > 0 \qquad \dd \mu(x)\;\;  \e{a.e.} \; x \in \mathbb{R} \;.

\end{align}

Given  $\tau > 0$ set $\mu_\tau = \frac{1}{2\tau} \mathbbm{1}_{[-\tau;\tau]} \ast \mu$. Then,

\begin{align*}

1 + \frac{2}{\ell} \Int{\mathbb{R}}{} \ln|x-y| \, \mathrm{d}\mu_\tau(y) \geq \kappa  & & \forall x \in \mathbb{R} \, .

\end{align*}

