[Theorem 5 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb$, $f\in \Sob^k(\Rbb^n,\gamma_n)$ with $\left\|f\right\|_{\Leb^\infty}\leq 1$, and $1\leq q\leq p\leq 2$,
\begin{equation}
    \frac{\left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p}}{\big[1+\frac{q}{2k(2-q)} \ln^{+}(\left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p}/\left\|\left|\grad^k f\right|\right\|_{\Leb^q}^{2})\big]^{kp/2}} \geq C^{\text{\rm\ref{thm:high-order-Lp-Lq-Gaussian}}}(p,q)^k \Wop^{\geq k}(f),
\end{equation}
and further,
\begin{equation}
    \sum_{\kappa\in \Nbb^n:|\kappa|=k}\frac{\left\|\Dop^\kappa f\right\|_{\Leb^p}^{p}}{\big[1+\frac{q}{2k(2-q)} \ln^{+}(\left\|\Dop^\kappa f\right\|_{\Leb^p}^{p}/\left\|\Dop^\kappa f\right\|_{\Leb^q}^{2})\big]^{kp/2}} \geq C^{\text{\rm\ref{thm:high-order-Lp-Lq-Gaussian}}}(p,q)^k \Wop^{\geq k}(f),
\end{equation}
with $C^{\text{\rm\ref{thm:high-order-Lp-Lq-Gaussian}}}(p,q) = C^{\text{\rm\ref{thm:high-order-Lp-Lq-energy-Boolean}}}(p,q) \gtrsim 2-q$. (Proof in the paper; no proof environment follows the statement in the TeX.)

