body:
[Lemma 7 (Markov property) of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] Suppose that~$x_1,\dots,x_m\in\T_n$ are vertices such that the subtrees $\T^{(1)},\dots,\T^{(m)}$ of~$\T_n$ rooted at these vertices are vertex-disjoint. Write~$n_i$ for the depth of~$\T^{(i)}$ and denote
\begin{equation}

\V(x_1,\dots,x_m):=\{x_1,\dots,x_m\}\cup\Bigl(\T_n\smallsetminus\bigcup_{i=1}^m\T^{(i)}\Bigr).
\end{equation}
Then, for   all   $t>0$, conditional on $\{L_t(x)\colon x\in\V(x_1,\dots,x_m)\}$, the families
\begin{equation}

\{L_t(x)\colon x\in\T^{(i)}\}_{i=1}^m
\end{equation}
are independent with the~$i$-th family distributed as $\{L_u(x)\colon x\in\T_{n_i}\}$ for~$u:=L_t(x_i)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 10 of arXiv:2607.08242, 'Convergence of random sums in non-commutative probability'] Suppose the assumptions of Theorem \ref{thm31}(ii) hold. 
    Suppose $\frac{N_n}{\eta_n}$ has a limiting probability measure $\mu$. Then, 
    \begin{equation*}
        \lim_{n\rightarrow\infty}\tilde{\varphi}(\tilde{\mathcal{S}}_{N_n}^m)=\varphi(s^m)\int_{0}^\infty x^{m/2}\,\mu(\mathrm{d}x),\ m\in\mathbb{N}.
        \end{equation*}
        In other words, $\tilde{\mathcal{S}}_{N_n}\stackrel{*}{\to}
        sy$ where $s$ and $y$ are independent variables, 

        and the $m$th moment of $y$ is given by $\int_0^\infty x^{m/2}\,\mu(\mathrm{d}x)$. If further $y$ has a probability measure $\mu_y$, and
        $\tilde{\mathcal{S}}_{N_n}$ has a probability measure $\mu_n$, then $\mu_n$ converges weakly to $\mu_s \star \mu_y$ where $\star$ denotes product convolution of two probability measures.

[Lem fluctuating-sum of arXiv:2410.24170, 'Persistent hubs in CMJ branching processes with independent increments and preferential at'] {leadership}}] 
    Suppose~$(S_{j})_{j \in \mathbb{N}}$ is a sequence of mutually independent, symmetric random variables. If $\sum_{j=1}^{\infty} S_{j}$ diverges almost surely, then 
        \begin{equation} 
        \limsup_{n \to \infty} \sum_{j=1}^{n} S_j = \infty \quad \text{and} \quad \liminf_{n \to \infty} \sum_{j=1}^{n} S_{j} = -\infty \quad \text{almost surely.}
        \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:dcm-matrix-form of arXiv:2606.10257, 'Downward conditional monotonicity gives survival and extinction for contact processes in r'] An MMPP is DCM if and only if $v^*\preceq x\preceq y$ implies that, for all $t>0$, 
	\begin{equation}
		v^*\preceq \frac{xe^{t(T-D_\alpha)}}{xe^{t(T-D_\alpha)}\boldsymbol1}\preceq \frac{ye^{t(T-D_\alpha)}}{ye^{t(T-D_\alpha)}\boldsymbol1}.
	\end{equation}

[Thm eq:modifzakai of arXiv:2411.16366, 'Connections between sequential Bayesian inference and evolutionary dynamics'] \textbf{(Informal Theorem (theo:limitcrowkimura of the paper):) Limiting process of (equation eq:repmutlin of the paper)} Consider a time discretisation of the interval $[0,T]$ with step size $\delta_d$ such that $d \times \delta_d = T$.  Denote by $\{Z_t^d\}_{0 < t \leq T}$ a piecewise linear approximation with step size $\delta_d$ of an observation path generated by (equation eq:obs of the paper).  Finally, let $\mu_t^d \propto \rho_t^d$ denote the unnormalised form of $\rho_t^d$ satisfying (equation eq:repmutlin of the paper).  Then under some conditions, 
		\begin{align*}
			\mu_t^d \rightarrow q_t \quad \text{as} \quad d \rightarrow \infty, \enskip \forall \enskip  t \in [0, T],
		\end{align*}
		where $q_t$ satisfies the modified Zakai equation,
		\begin{align}

			d q_t(x) = \mathcal{L}^\ast q_t(x) -\frac{s}{2}h(x)^\top \Xi^{-1} h(x) q_t(x)  + (r-s)q_t(x) h(x)^\top \Xi^{-1} dZ_t, 
			\tag{$\textbf{ZK}$}
		\end{align}
		with $\mathcal{L}^\ast$ is as defined in (equation eq:repmutlin of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm vector-main of arXiv:2608.29018, 'Sharp Restricted Isometry Thresholds for\\ Global Minima of Rank-Restricted Matrix LASSO'] Fix integers $r_{\star}\ge1,$ $k\ge2$, and
set $t\coloneqq k/r_{\star}$. Suppose $\normzero{x_{\star}}\le r_{\star}$
and that $A\in\operatorname{rip}(\delta,k)$. If $\delta<\delta_{\mathrm{sharp}}(t)$ and the
regularization parameter $\lambda>0$ satisfies
\begin{equation}
\lambda\ge2\frac{1+\rho_{\delta,t}}{1-\rho_{\delta,t}}\norminf{A^{T}\xi},
\end{equation}
then for any sparsity level $r\ger_{\star}$, the solution $x_{\lambda,r}$
in ((eq:vector-lasso of the paper)) satisfies \begin{subequations}
\begin{align}
\normtwo{A(x_{\lambda,r}-x_{\star})} & \le\frac{4\tau_{\delta,t}}{1-\rho_{\delta,t}}\sqrt{r_{\star}}\,\lambda,\\
\normtwo{x_{\lambda,r}-x_{\star}} & \le\frac{16\tau_{\delta,t}^{2}}{(1-\rho_{\delta,t})^{2}}\sqrt{r_{\star}}\,\lambda.
\end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:hoelder_sets_def of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] For $n \in \mathbb{N}$, let
    \begin{equation*}
        \mathrm{HC}_n \coloneqq \Big\{ \psi \in C_0[0,1] \,\Big|\, \forall \, x,y \in [0,1]: \; | \psi(x)-\psi(y) | \leq n\, |x-y|^{1/n} \Big\},
    \end{equation*}
    and let $\mathrm{HC} \coloneqq \bigcup_{n>0} \mathrm{HC}_n$.

[Theorem 59 (All-degree intrinsic primitive--Fock unitary) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] The direct sum
\begin{equation}
 \mathbb U=\bigoplus_{q\ge1}\mathbb U_q

\end{equation}
is a unitary
\begin{equation}
 \mathbb U:
 \bigoplus_{q\ge1}
 \cW_q\left(\bigoplus_{s\le q}\cK_s\right)
 \xrightarrow{\ \simeq\ }
 \bigoplus_{q\ge1}\cH_q,
 \qquad P_{\le Q}\mathbb U=\mathbb U P_{\le Q}.

\end{equation}
It is an isometry at every level of the compact Hilbert scale for which the corresponding
weighted norm is finite.  Condition $\mathrm{QT}_2$ is used only to ensure that the represented
packet belongs to the grade-wise direct sum on the right-hand side.

[Lemma 16 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$, there exist $C,c>0$ such that for any $T>0$, $D\subset \widetilde{\mathbb{Z}}^d$ and $v,w\in \widetilde{\mathbb{Z}}^d\setminus D$ with $|v-w|\ge d$, 
	\begin{equation}
		\mathbb{P}\big( \widehat{\mathcal{L}}_{1/2}^{D,v}\ge T \mid  v\xleftrightarrow{(D)} w \big) \le Ce^{-cT}. 
	\end{equation}

