[Proposition 30 of arXiv:2609.02064, 'Coalescence and fluctuations of O'Connell--Yor polymers\\ via the free-energy correlation '] For every $x,\wt x\in\R$ with $x\neq\wt x$,
  \begin{align}
    \frac{\partial}{\partial x}
    \EE\bigl[
      F_{\wt x}^{\al,\be}F_{x}^{\al,\be}
    \bigr]
    =\lim_{\eps\downarrow0}
    \EE\left[
      \frac1\be\log \cZ_{\wt x}^\eps
      \frac{\partial}{\partial x}
      \frac1\be\log \cZ_x^\eps
    \right].
  \end{align}

[Corollary coro:chromatic-signed of arXiv:2609.03959, 'The combinatorial Hopf algebra of signed graphs'] Let $\Sigma$ be a signed graph, then 
\begin{equation}
\chi_\Sigma ^b (2t) = \phi_t\circ \Psi (\Sigma) = \zeta^{\ast t}(\Sigma).
\end{equation}

[Lemma 34 (Exact positive ledger) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] For every common-module split,
\begin{align}
 0\le\mathcal N_q&\le a_QR^2\Id,
 \\
 \mathfrak H_Q(A,r)
 &=\sum_{b=1}^{d}\sum_{q=1}^{Q}
   \ip{r_{b,q}}{\mathcal N_qr_{b,q}}.

\end{align}
Moreover the coherent residual and mixed Malliavin--Stein defects satisfy
\begin{equation}
 \Delta_{\mathrm{res}}(r)+\Delta_{\mathrm{mix}}(A,r)
 \le\mu_Q\mathfrak H_Q(A,r).

\end{equation}

[Theorem 28 of arXiv:2609.02197, '2609.02197'] Let $\theta \in \left]-\infty,2-\frac{d}{2}\right[.$
\begin{enumerate}
\item
There exists a stochastic process $\left(\widetilde{X}_{r,1}\right)_{r \in \mathbb{R}_+}$ with state space $\left(\mathscr{C}^\theta,\mathcal{B}\left(\mathscr{C}^\theta\right)\right)$ such that the sample paths of $\left(\widetilde{X}_{q,1}\right)_{q \in \mathbb{R}_+}$ are continuous and for $\mathds{P}$-almost every $\omega \in \Omega,\left(\widetilde{X}_{r,1}\left(\omega\right)\right)\left(\varphi\right)=\left(X_{r,1}\left(\varphi\right)\right)\left(\omega\right).$
\item For all $\left(r,q\right) \in \mathbb{R}_+\times \mathbb{R}_+^*,$ let \gls{sto3}$:=\zeta_q*\widetilde{X}_{r,1}.$ For every $\left(U,\varsigma\right) \in \mathbb{R}_+\times \mathbb{R}_+^*,$ $$\lim_{\epsilon\downarrow 0}\mathds{P}\left(\sup_{r \in \left[0,U\right]}\left\Vert \widetilde{X}_{r,\epsilon,1}-\widetilde{X}_{r,1}\right\Vert_{\mathscr{C}^\theta}>\varsigma\right)=0.$$
\end{enumerate}

[Definition notation:BCset1 of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] For each $(R,\alpha)$ atom of  $\tilde{\Phi}$, let 

\begin{equation}
C_{(R,\alpha)}:=\left\{(t, f((R,\alpha), t)): t\in \mathbb{R}\right\}.

\end{equation} 

We call the infinite closed set $C_{(R,\alpha)}\subset\mathbb{H}^+$ a \textbf{radial bird closed set} or
a \textbf{radial bird particle} or simply a \textbf{radial bird}.

[Lemma lem_new_c_star of arXiv:2411.02046, 'Speed of Convergence and Moderate Deviations of FPP on Random Geometric Graphs'] Under the assumptions of Theorem~(thm:speed.FPP of the paper), there exists~$C^* > 0$ such that almost surely, for every~$x \in \mathbb R^d$ with~$\|x\|$ large enough, we have
    \begin{equation}
    \left| T(x) - \frac{\|x\|}{\upvarphi}\right| \le C^* \sqrt{\|x\|}\log\big(\|x\|\big).
    \end{equation}

