[Proposition prop:global_hajek_intro of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Define
\begin{equation}

    \widehat{\mathsf{N}}_G(x) \coloneqq \mathsf{N}_G(x) - 2 \mathsf{e} p^{\mathsf{e}-1} n^{\mathsf{v}-2} \mathsf{E}(x).
\end{equation}
Then, for all $\zeta \in (0,1)$, there is some $c > 0$ such that 
\begin{equation}
    \mathbb{P} \mleft[
        \mleft|
            \widehat{\mathsf{N}}_G(X) - \mathbb{E}\mleft[\widehat{\mathsf{N}}_G(X)\mright]
        \mright| > n^{\mathsf{v}-1.5+\zeta}
    \mright] \leq \exp\mleft(-cn^\zeta\mright).
\end{equation}
In particular, for all $\xi > 0$, we have
\begin{equation}
    \operatorname{Var}\mleft[\widehat{\mathsf{N}}_G(X)\mright] \lesssim n^{2\mathsf{v}-3+\xi}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:pole-short-time-calibration of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] Assume (equation eq:pole-coefficient-class of the paper), take
$K=K_\theta^\star(a)$, and let
$0\leq\alpha<1/2$ and $0<\theta<1-4/(C_\alpha^{\mathrm{Br}})^2$, with
$\Delta_{\mathrm{hi}}$ as in Theorem~(thm:pole-calibration of the paper).  There are
\begin{equation*}
 \begin{aligned}
 N_{\mathrm H}&=N_{\mathrm H}
   (\lambda,\Lambda,\alpha,\Delta_{\mathrm{hi}}^{-1})\in\mathbb N,\qquad
 r_{\mathrm{loc}}=r_{\mathrm{loc}}
   \bigl(T,\lambda,\Lambda,\alpha,\theta,\Delta_{\mathrm{hi}}^{-1},
                  \mathcal M_d(a)\bigr)\in(0,T],
 \end{aligned}
\end{equation*}
and $C=C\bigl(T,\lambda,\Lambda,\alpha,\theta,\Delta_{\mathrm{hi}}^{-1}\bigr)>0$
such that the following holds.

Let $0<r<r_{\mathrm{loc}}$, $I_r=(0,r)$, and
$F\in\mathfrak D(I_r,\overline w_{\alpha,K})$.  Put $u=S_{I_r}F$ and
\begin{equation*}
 G(s,\xi)=rF(rs,\sqrt{rs}\,\xi),\qquad
 q(s,\xi)=u(rs,\sqrt{rs}\,\xi).
\end{equation*}
Then $\mathcal P_rq=G$ and
\begin{equation}
 \left\lVert \mathcal J_rq\right\rVert_{\mathscr Y_{\alpha,K,r}}
 \leq\bigl(C_\alpha^{\mathrm{Br}}+C\mathcal M_d(a)r\bigr)
       \left\lVert G\right\rVert_{\mathscr X_{\alpha,K,r}}.

\end{equation}
The exact scaling identities are
\begin{equation}
 \left\lVert G\right\rVert_{\mathscr X_{\alpha,K,r}}^2
 =r^{1-\alpha}\left\lVert F\right\rVert_{\overline w_{\alpha,K};I_r}^2,
 \qquad
 \left\lVert \mathcal J_rq\right\rVert_{\mathscr Y_{\alpha,K,r}}^2
 =r^{1-\alpha}\norm{\operatorname{Hess}_gu}_{\overline w_{\alpha,K},g;I_r}^2.

\end{equation}
Consequently, Theorems~(thm:bochner-source-density of the paper)
and~(thm:causal-reweighting of the paper) give
\begin{equation}
 C_{w_{\alpha,K;\kappa},I_r}(X^a)
 \leq C_\alpha^{\mathrm{Br}}+C\mathcal M_d(a)r,
 \qquad 0<r<r_{\mathrm{loc}},\quad \kappa\geq0.

\end{equation}

[Proposition 39 (Unimodularity of the embedded Delaunay graph) of arXiv:2504.02435, 'Poisson-Voronoi percolation in higher rank'] Let $G$ be a non-compact connected semisimple real Lie group and $(X,d_X)$ be its symmetric space. Let $\mathbf Y$ be a Poisson point process $Y$ on $X$ with intensity $c \, {\rm vol}$ for some $c>0$ and with iid ${\rm Unif}[0,1]$-marks. Let $Y_0=Y\cup\{o\}$ and $\mathbf Y_0=\mathbf Y \cup \{\mathbf o\}$, where $\mathbf o$ is the origin equipped with an independent ${\rm Unif}[0,1]$-mark. Let $\mathcal G$ denote the Delaunay graph associated to ${\rm Vor}(Y_0)$ and let $\rho$ denote the vertex corresponding to the cell of the origin. Then the following hold:
\begin{itemize}
\item[{\rm(1)}] The Delaunay graph $(\mathcal G,\rho)$ defines a unimodular random graph. 
\item[{\rm(2)}] Let $\psi$ denote the marking of the embedded Delaunay graph. Then $(\mathcal G,\rho,\psi)$ satisfies 
\begin{equation}
\mathbb E \bigg[ \sum_{x\in V(\mathcal G)} f(\mathcal G,\rho,x,\psi) \bigg] = \mathbb E \bigg[ \sum_{x\in V(\mathcal G)} f(\mathcal G,x,\rho,\psi) \bigg]
\end{equation}
for every non-negative measurable function $f$ of bi-rooted embedded graphs $(H,u,v,\varphi)$ with the additional property that
\begin{equation} 
f(H,u,v,\tau \circ \varphi)= f(H,u,v,\varphi)
\end{equation}
for every isometry $\tau$ of $X$ which interchanges $\varphi(u)$ and $\varphi(v)$. 
\item[{\rm(3)}] Let $\Psi$ denote the marking of the embedded Delaunay graph with labels. Then $(\mathcal G,\rho,\Psi)$ satisfies 
\begin{equation}
\mathbb E \bigg[ \sum_{x\in V(\mathcal G)} f(\mathcal G,\rho,x,\Psi) \bigg] = \mathbb E \bigg[ \sum_{x\in V(\mathcal G)} f(\mathcal G,x,\rho,\Psi) \bigg]
\end{equation}
for every non-negative measurable function $f$ of bi-rooted embedded labeled graphs $(H,u,v,\Phi=(\varphi,\varphi'))$ with the additional property that 
\begin{equation} 
f(H,u,v,\tau \circ \Phi)= f(H,u,v,\Phi)
\end{equation} 
for every isometry $\tau$ of $X$ which interchanges $\varphi(u)$ and $\varphi(v)$. 
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:large_jump_comono_coup of arXiv:2411.03609, 'Asymptotically optimal Wasserstein couplings for the small-time stable domain of attractio'] Let $\alpha \in (0,2)\setminus\{1\}$ and $q \in (0,\alpha)\cap(0,1]$ satisfy $\int_{\mathbb{R}^d\setminus B_{\bm{0}}(1)}|\bm{w}|^q\nu_{\bm{X}}(\mathrm{d}\bm{w})<\infty$, where $q\ne\alpha/(p+1)$ and $q\ne\alpha/(\alpha\delta+1)$. Then, under Assumptions~(\nameref{asm:S}) \& (\nameref{asm:C}) we have, as $t \downarrow 0$,
\begin{align*}
\mathcal{W}_q\big(\bm{L}^{\bm{S}^t}, \bm{L}^{\bm{Z}}\big) 
&= \mathcal{O}\big(G_2(t)^q 
    +(1+G_1(t))^qt^{\min\{1-q/\alpha,q\delta\}}     
    +G(t)^{pq}(1+G_1(t))^{q(1+p)}t^{\min\{1-q/\alpha,pq/\alpha\}}\big).
\end{align*}

