body:
[Theorem thm:E[sl] of arXiv:2604.05921, 'Simplicity of random hypergraphs'] Let $R(\cdot)$ be as in (equation def:B of the paper) and let $E^* = \{e \in E: \delta_e^{\textnormal{tail}} = \delta_e^{\textnormal{head}}\}$. We denote $\delta_e = \delta_e^{\textnormal{tail}}=\delta_e^{\textnormal{head}}$ for $e \in E^*$. Then, for a uniformly random directed hypergraph with degree sequence $\vb*{d}$,
    \begin{align}

         \mathds{E}[S_n] &= \sum_{e \in E^*} \frac{(n\mathds{E}[d_U^{\textnormal{in}}]-\delta_e)!(n\mathds{E}[d_U^{\textnormal{out}}]-\delta_e)!}{(n\mathds{E}[d_U^{\textnormal{in}}])!(n\mathds{E}[d_U^{\textnormal{out}}])!} \sum_{\substack{\vb*{a} \in \mathds{N}^{\delta_e}:\\\sum_{i=1}^{\delta_e} ia_i = \delta_e}}  \frac{\delta_e!^2}{\prod_{k=1}^{\delta_e} k!^{2a_k} } \sum_{\alpha(\cdot) \in R(\vb*{a})} (-1)^{\sum_{\vb*{x} \in \mathds{N}^{\delta_e}} (\sum_{i=1}^{\delta_e} x_i - 1)\alpha(\vb*{x})}\nonumber\\
     &\hspace{1cm}
    \times\prod_{\vb*{y} \in \mathds{N}^{\delta_e}} \Bigg( \frac{1}{\alpha(\vb*{y})!} \Big(\frac{n\mathds{E}\big[\prod_{i=1}^{\delta_e} (\mathds{1}_{\{d_U^{\textnormal{out}},d_U^{\textnormal{in}} \geq i\}}\frac{d_U^{\textnormal{out}}!}{(d_U^{\textnormal{out}}-i)!}\frac{d_U^{\textnormal{in}}!}{(d_U^{\textnormal{in}}-i)!})^{y_i} \big] \big(\sum_{i=1}^{\delta_e} y_i-1 \big)!}{\prod_{i=1}^{\delta_e} y_i!} \Big)^{\alpha(\vb*{y})} \Bigg).
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm: main of arXiv:2411.04157, 'Stochastic homogenization of dynamical discrete optimal transport'] Let $(\mathcal X_\omega,\mathcal E_\omega)_{\omega\in\Omega}$ be a random graph in $\mathbb{R}^n$ with random weights $(\sigma_\omega\colon \mathcal E_\omega\to[\lambda,\Lambda])_{\omega\in\Omega}$ and random means $(\theta^\omega)_{\omega\in\Omega}$ with $0<\lambda<\Lambda$, satisfying the graph Assumption (ass: graph of the paper) almost surely, such that $(\mathcal X_\omega,\mathcal E_\omega,\sigma_\omega,\theta_\omega)$ is stationary.

For every $\varepsilon>0$ let $({\mathcal X_{\omega,\varepsilon}},\mathcal E_{\omega,\varepsilon})$ be the rescaled random graph and $\mathcal{A}_{\omega,\varepsilon}$ be the rescaled action functional defined in Section (sec: rescaled graph of the paper). Let $A_\omega$ be the homogenized action functional given in (equation eq: hom action of the paper).
Then we have almost surely $\mathcal{A}_{\omega,\varepsilon}\stackrel{\Gamma}{\longrightarrow}_{\varepsilon\to 0} A_\omega$ in the sense that the following two conditions hold almost surely:
\begin{enumerate}
    \item Lower bound: For every $m^\varepsilon \stackrel{*}{\rightharpoonup} \rho$ narrowly in $\mathcal{M}_+((0,T)\times \mathbb{R}^n)$ and $\iota J^\varepsilon \stackrel{*}{\rightharpoonup} j$ narrowly in $\mathcal{M}((0,T)\times \mathbb{R}^n;\mathbb{R}^n)$,
\begin{equation*}
    \liminf_{\varepsilon\to 0}  \mathcal{A}_{\omega,\varepsilon}(m^\varepsilon,J^\varepsilon) \geq  A_\omega(\rho,j).
\end{equation*}
    \item Upper bound:
    For every curve $(\rho,j)$ there exist sequences $m^\varepsilon \stackrel{*}{\rightharpoonup} \rho$ narrowly in $\mathcal{M}_+((0,T)\times \mathbb{R}^n)$ \text{ and } $\iota J^\varepsilon \stackrel{*}{\rightharpoonup} j$  narrowly in $\mathcal{M}((0,T)\times \mathbb{R}^n;\mathbb{R}^n)$ such that
\begin{equation*}
    \limsup_{\varepsilon\to 0}  \mathcal{A}_{\omega,\varepsilon}(m^\varepsilon,J^\varepsilon) \leq  A_\omega(\rho,j).
\end{equation*}
In addition, $\max_{t\in[0,1]}W_2(m^\varepsilon_t,\rho_t) \to 0$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem theo:1Gllaw of arXiv:2605.21265, 'The non-Hermitian minor process'] Let $X$ satisfy Assumption~(ass:chi of the paper)(i). Fix a (large) $L>0$ and a (small) $c_0>0$. There exists an $N$-independent constant $\tau>0$ such that
\begin{align}
\left\vert\left\langle \big(G^{(k),z}_x(w)-M^{(k),z}_x(w)\big)B\right\rangle\right\vert &\prec\frac{\|B\|}{N\eta},\\
\left\vert\left\langle \bm{x}, \big(G^{(k),z}_x(w)-M^{(k),z}_x(w)\big)\bm{y}\right\rangle\right\vert &\prec\|\bm{x}\|\|\bm{y}\|\left(\sqrt{\frac{\rho_x^{z}(w)}{N\eta}}+\frac{1}{N\eta}\right),
\end{align}
uniformly in deterministic matrix $B\in\mathbf{C}^{(2k)\times (2k)}$, deterministic vectors $\bm{x},\bm{y}\in\mathbf{C}^{2k}$, $x:=k/N\in [c_0,1]$, $|\Re w|\le \tau$, $\eta:=|\Im w|\in (N^{-L}, N^L)$ and $|z|\le L$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 33 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] For every \(\lambda>0\), there is \(C_{H,\lambda}<\infty\) such that, for
every finite \(F\subset\mathbb D\), every \(e\in F\cup\{0\}\), and either
\(I=[0,1]\) or \(I=[-1,0]\),
\begin{equation}
  \EE_{\widehat Q_{F,e}}
  \exp\left(\lambda\sup_{t\in I}G_t\right)
  \leq C_{H,\lambda},

\end{equation}
uniformly in \(F\), \(e\), and the side.

[Definition 35 of arXiv:2608.05931, 'Effective Lagrangian regularity and the uniqueness threshold for random H\"older velocity '] For each $N \in \N$, we let $U^N : [0,1] \times \T^d \to \R^d$ denote the truncated sum
    \[U^N(t,x) := \sum_{j=0}^N u^j(t,x).\]
    We then let $\Phi^N: [0,1]  \times \T^d \to \T^d$ denote the (uniquely defined) flow solution of the ODE
    \begin{equation}\begin{cases}
        \dot \Phi^{N}_t(y) = U^N(t,\Phi^{N}_t(y)),\\ \Phi^{N}_0(y) = y.
    \end{cases}
    \end{equation}
    For any $v : [0,1] \times \T^d \to \R^d$ with $v \in \mathcal{C}^0([0,1]\times \T^d)$, we let $\iop^{N} v : \T^d \times [0,1] \times \T^d \to \R^d$ be defined by
    \[\iop^{N} v(y,t,x) := \int_0^t v\big(s, \Phi^N_s(y) + x\big)\,ds.\]

[Theorem cor:pointwise of arXiv:2608.24731, 'Optimal Alternating Regret for Online Learning and Games\thanks{Authors are alphabetically'] For every horizon $T \ge 1$, (alg:main of the paper) with the uniform probability measure $\mu \in \Delta_{\+X}$ guarantees
\begin{equation}
  \max_{\boldsymbol{u} \in \+X}\operatorname{Reg}_{\mathrm{Alt}}^T(\boldsymbol{u})
  \le
  8d\left(1+\log_{+}\frac{T}{2d}\right) + \frac{1}{4},
\end{equation}
where $\log_{+} z:=\max\{0,\log z\}$. Since $\max_{\boldsymbol{u} \in \+X}\operatorname{Reg}_{\mathrm{Alt}}^T(\boldsymbol{u}) \le 4T$ trivially, we have
\begin{align*}
    \max_{\boldsymbol{u} \in \+X}\operatorname{Reg}_{\mathrm{Alt}}^T(\boldsymbol{u}) = O\left( \min\left\{T, d\left (1+\log_{+} \frac{T}{2d}\right) \right\} \right) = O(d \log(1+T/d))
\end{align*}

