body:
[Lemma 6 of arXiv:2608.01516, 'Nondegeneracy and regularity of polynomial pushforwards'] Let $\alpha\in(0,1]$ and let $\nu$ be a probability Borel measure on $\mathbb R^k$.
Then the estimate
\begin{equation}
\nu(A)\le C\bigl(\lambda_k(A)\bigr)^\alpha
\end{equation}
for every Borel set $A\subset \mathbb R^k$ is equivalent to the estimate
\begin{equation}
\int_{\mathbb R^k}\psi\,d\nu\le C\|\psi\|_{L^1(\mathbb R^k)}^\alpha
\end{equation}
for every $\psi\in C_0^\infty(\mathbb R^k)$ with $0\le\psi\le 1$.

[Lemma 35 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] There exist a sequence $\{\varepsilon_n\}_{n \in \mathbb{N}} \subset (0,1)$ and a nonnegative function
$v_{\text{{\tiny $\delta$}}} \in W^{1,2}(0,T\,;L^2(\Omega)) \cap L^\infty (0,T\,;H^1(\Omega))$ such that the following convergences hold as $n \to \infty$\,:

\begin{gather}

\varepsilon_n \downarrow 0,\\

z_{\text{{\tiny $\delta,\!\varepsilon_n$}}} \longrightarrow v_{\text{{\tiny $\delta$}}} \quad \text{in} \quad C([0,T]\,;L^2(\Omega)),\\

v_{\text{{\tiny $\delta,\!\varepsilon_n$}}} \longrightarrow v_{\text{{\tiny $\delta$}}} \quad \left\{
\begin{array}{l}
\text{in} \quad C([0,T]\,;L^2(\Omega)),\\[0.1cm]
\text{weakly in} \quad W^{1,2}(0,T\,;L^2(\Omega)),\\[0.1cm]
\text{weakly$^*$ in} \quad L^\infty (0,T\,;H^1(\Omega)).
\end{array}
\right.
\end{gather}

[Lemma cuttimes of arXiv:2411.13505, 'Capacity of loop-erased random walk'] We have
\begin{equation}
	\begin{split}
		\lim_{n\rightarrow\infty}\mathbb{E}\left[|n-\rho_{n(\log n)^{-1/3}}|\right]=\lim_{n\rightarrow\infty}\mathbb{E}\left[|(\log n)^{1/3}n-\ell_n|\right]=0.
	\end{split}
\end{equation}
Furthermore, there exists $C>0$ such that for all $n$ and all $m$ such that $|n-m|\geq (\log m)^{-6}m$,
\begin{equation}
	\mathbb{P}(\text{there are no cut times between $n$ and $m$})\leq C\frac{\log\log m}{\log m}.
\end{equation}

[Lem 1 of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] For any simple path $\gamma = (x_t,y_t)$, if $\gamma|_{[0,1]}$ has infinite radius of convergence for its log-signature and $x_t\in[-1,1]$ for all $t\in[0,1]$, then looking at any fixed horizontal level $y=a$ of the image $\gamma([0,1])$, we only have the following two cases: 
\begin{itemize}
       \item The right street copies the left street. In the sense that for any $x\in(0,1)$, $(x,a)\in\gamma([0,1])$, we have $(x-1,a)\in\gamma([0,1])$. For any $x\in(-1,0)$, $(x,a)\in\gamma([0,1])$ we have $(x+1,a)\in\gamma([0,1])$.

       \item Both capture the missing points of the other. In the sense that for any $x\in(0,1)$, $(x,a)\notin\gamma([0,1])$, we have $(x-1,a)\in\gamma([0,1])$. For any $x\in(-1,0)$, $(x,a)\notin\gamma([0,1])$, we have $(x+1,a)\in\gamma([0,1])$.
\end{itemize}

[Lm Expectation G almost Expectation  tilde G of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] We have 
    \begin{equation}
        \sup_{t \in [0,T]}|\mathbb{E}\Tilde{G}(M(t)/\sqrt{n},\theta(t))-\mathbb{E} G(M(t)/\sqrt{n},\theta(t))| \lesssim e^{-c\frac{n}{\log(n)}},
    \end{equation}
    for sufficiently large $n$.

